__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"lorePack",{enumerable:!0,get:function(){return z}});var t=r(d[0]),n=r(d[1]),s=r(d[2]),c=r(d[3]),o=r(d[4]),l=r(d[5]),w=r(d[6]),h=r(d[7]),f=r(d[8]),u=r(d[9]);const z={entries:{...t.chapters1,...n.chapters2,...s.classes,...c.races,...o.zones1,...l.zones2,...w.instances1,...h.instances2,...f.items,...u.terms},eras:{creation:{title:"\ud2f0\ud0c4\uacfc \uace0\ub300 \uc2e0",when:"\uae30\ub85d\ub41c \uc5ed\uc0ac \uc774\uc804"},"ancient-kalimdor":{title:"\uce7c\ub3c4\ub808\uc774 \uc81c\uad6d",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 1\ub9cc \ub144 \uc774\uc0c1 \uc804"},"elder-kingdoms":{title:"\uc61b \uc655\uad6d\ub4e4",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 7,000~200\ub144 \uc804"},draenor:{title:"\ub4dc\ub808\ub178\uc5b4\uc758 \uc624\ud06c",when:"\uc5b4\ub460\uc758 \ubb38 \uc774\uc804\uc758 \uc218\uc2ed \ub144"},"first-war":{title:"\uc81c1\ucc28 \ub300\uc804\uc7c1",when:"\uc5b4\ub460\uc758 \ubb38\uc774 \uc5f4\ub9ac\ub2e4 (0\ub144)"},"second-war":{title:"\uc81c2\ucc28 \ub300\uc804\uc7c1",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uba87 \ub144 \ud6c4"},interwar:{title:"\uc804\uc7c1\uacfc \uc804\uc7c1 \uc0ac\uc774",when:"\uc81c2\ucc28 \ub300\uc804\uc7c1 \uc774\ud6c4\uc758 \uba87 \ud574"},"third-war":{title:"\uc81c3\ucc28 \ub300\uc804\uc7c1",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 20\ub144 \ud6c4"},"new-homes":{title:"\uce7c\ub9bc\ub3c4\uc5b4\uc758 \uc0c8 \ubcf4\uae08\uc790\ub9ac",when:"\uc81c3\ucc28 \ub300\uc804\uc7c1 \uc774\ud6c4\uc758 \uba87 \ud574"},classic:{title:"\uc6d4\ub4dc \uc624\ube0c \uc6cc\ud06c\ub798\ud504\ud2b8\uc758 \uc2dc\ub300",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 25\ub144 \ud6c4, Forever\uc758 \ubc30\uacbd"},beyond:{title:"\ud074\ub798\uc2dd \uc774\ud6c4",when:"\uc774\ud6c4\uc758 \ud655\uc7a5\ud329 (Forever\uc5d0\ub294 \uc5c6\uc74c)"}},categories:{chapter:"\uc6cc\ud06c\ub798\ud504\ud2b8 \uc774\uc57c\uae30",class:"\uc9c1\uc5c5",race:"\uc885\uc871",zone:"\uc9c0\uc5ed",instance:"\ub358\uc804 \ubc0f \uacf5\uaca9\ub300",item:"\uc804\uc124 \uc544\uc774\ud15c",term:"\uc6a9\uc5b4\uc9d1"},notice:"WoW Forever Path\ub97c \uc704\ud574 \uc0c8\ub85c \uc4f4 \uae00\uc785\ub2c8\ub2e4. \uc0ac\uc2e4\uad00\uacc4\ub294 \ud45c\uc2dc\ub41c \uc790\ub8cc\uc640 \ub300\uc870\ud588\uc73c\uba70, warcraft.wiki.gg \ubb38\uc11c(CC BY-SA 4.0)\uc640 \ube14\ub9ac\uc790\ub4dc \uac8c\uc2dc\ubb3c\uc740 \ucc38\uace0 \uc790\ub8cc\ub85c\ub9cc \uc37c\uc744 \ubfd0 \ubb38\uc7a5\uc744 \uc62e\uaca8 \uc624\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. World of Warcraft\uc640 Blizzard\ub294 Blizzard Entertainment, Inc.\uc758 \uc0c1\ud45c\uc785\ub2c8\ub2e4."}},1723,[1790,1791,1792,1793,1794,1795,1796,1797,1798,1799]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters1",{enumerable:!0,get:function(){return t}});const t={"chapter:titans-and-old-gods":{title:"\ud2f0\ud0c4\uacfc \uace0\ub300 \uc2e0",summary:"\ud544\uba78\uc790\uc758 \uc655\uad6d\uc774 \uc0dd\uaca8\ub098\uae30 \uc804, \ud310\ud14c\uc628\uc758 \ud2f0\ud0c4\ub4e4\uc740 \uc80a\uc740 \uc138\uacc4\uc758 \uc601\ud63c\uc744 \ub450\uace0 \uace0\ub300 \uc2e0\ub4e4\uacfc \uc2f8\uc6e0\uace0, \uc544\uc81c\ub85c\uc2a4\uc5d0\ub294 \uc9c0\uae08\ub3c4 \uadf8 \uc0c1\ucc98\uac00 \ub0a8\uc544 \uc788\ub2e4.",when:"\uae30\ub85d\ub41c \uc5ed\uc0ac \uc774\uc804",body:["\ud544\uba78\uc790\ub4e4\uc774 \uae30\ub85d\uc744 \ub0a8\uae30\uae30 \ud6e8\uc52c \uc804, \ud2f0\ud0c4\ub4e4\uc740 \uc6b0\uc8fc\uc758 \ub05d\uc5c6\ub294 \uc5b4\ub460\uc744 \uac70\ub2d0\uc5c8\ub2e4. \uadf8\ub4e4\uc740 \uc0b4\uc544 \uc788\ub294 \uac70\uc778\uc73c\ub85c \uc790\ub77c\ub09c \uc138\uacc4\ud63c\uc774\uc5c8\ub2e4. \uadf8\uc911 \uac00\uc7a5 \uace0\uadc0\ud55c \uc774\ub4e4\uc774 \ud310\ud14c\uc628\uc73c\ub85c \ubaa8\uc5ec, \uc790\uc2e0\ub4e4\uacfc \uac19\uc740 \uc7a0\ub4e0 \uc138\uacc4\ud63c\uc744 \ucc3e\uc544 \ubcc4\ub4e4\uc744 \ub4a4\uc84c\ub2e4. \uadf8\ub4e4\uc740 \uc544\uc81c\ub85c\uc2a4 \uae4a\uc219\ud55c \uacf3\uc5d0\uc11c \ub180\ub77c\uc6b4 \uac00\ub2a5\uc131\uc744 \uc9c0\ub2cc \uc138\uacc4\ud63c\uc744 \uac10\uc9c0\ud588\uc9c0\ub9cc, \ub354 \uc5b4\ub450\uc6b4 \uc138\ub825\uc774 \uba3c\uc800 \uadf8\uacf3\uc744 \ucc3e\uc544\ub0b8 \ub4a4\uc600\ub2e4.","\uacf5\ud5c8\uc758 \uad70\uc8fc\ub4e4\uc740 \uc790\uc2e0\ub4e4\uc758 \ud558\uc218\uc778\uc778 \uace0\ub300 \uc2e0\ub4e4\uc744 \uc80a\uc740 \uc138\uacc4\uc5d0 \ub0b4\ub358\uc84c\ub2e4. \uc774\uc0e4\ub77c\uc988, \ud06c\ud230, \uc694\uadf8\uc0ac\ub860, \ub290\uc870\uc2a4\ub294 \uc9c0\uac01 \uc18d\uc5d0 \ubab8\uc744 \ubb3b\uace0 \uac80\uc740 \uc81c\uad6d\uc744 \uc138\uc6e0\uc73c\uba70, \ubd88\uacfc \ub300\uc9c0\uc640 \ubc14\ub78c\uacfc \ubb3c\uc758 \uc815\ub839 \uad70\uc8fc\ub4e4\uc744 \uc7a5\uad70\uc73c\ub85c \uac70\ub290\ub838\ub2e4. \ud310\ud14c\uc628\uc774 \ub3c4\ucc29\ud558\uc790 \ud2f0\ud0c4\uc774 \ubcbc\ub824\ub0b8 \uad70\ub300\uac00 \uc81c\uad6d\uc758 \uc131\ucc44\ub4e4\uc744 \ubb34\ub108\ub728\ub838\ub2e4. \ucd5c\uace0\uc2e0 \uc544\ub9cc\ud234\uc774 \uc774\uc0e4\ub77c\uc988\ub97c \ub545\uc5d0\uc11c \ub72f\uc5b4\ub0c8\uc9c0\ub9cc, \uadf8 \uc77c\uaca9\uc740 \uc138\uacc4\uc758 \ube44\uc804 \uc0dd\uba85\ub825\uc774 \ud758\ub7ec\ub098\uc624\ub294 \uc0c1\ucc98\ub97c \ub0a8\uacbc\ub2e4. \ud2f0\ud0c4\ub4e4\uc740 \ub098\uba38\uc9c0\ub97c \uc8fd\uc774\uba74 \uc544\uc81c\ub85c\uc2a4 \uc790\uccb4\uac00 \uc8fd\uc744 \uc218\ub3c4 \uc788\ub2e4\ub294 \uac83\uc744 \uae68\ub2ec\uc558\ub2e4.","\uadf8\ub798\uc11c \uad00\ub9ac\uc790\ub4e4\uc740 \uac10\uc625\uc744 \ud0dd\ud588\ub2e4. \ud06c\ud230, \uc694\uadf8\uc0ac\ub860, \ub290\uc870\uc2a4\ub294 \ub545\uc18d \uae4a\uc740 \uacf3\uc5d0 \uc0ac\uc2ac\ub85c \ubb36\uc600\uace0, \uc815\ub839 \uad70\uc8fc\ub4e4\uc740 Skywall\uacfc \ubd88\uc758 \ub545 \uac19\uc740 \uc601\uc5ed\uc774 \uc788\ub294 \uc815\ub839\uacc4\ub85c \ucd94\ubc29\ub418\uc5c8\ub2e4. \uad00\ub9ac\uc790\ub4e4\uc740 \ud53c \ud758\ub9ac\ub294 \uc0c1\ucc98\ub97c \uac00\ub77c\uc549\ud600 \ube5b\ub098\ub294 \ud638\uc218, \uc601\uc6d0\uc758 \uc0d8\uc73c\ub85c \ub9cc\ub4e4\uc5c8\uace0, \uc0b0\uacfc \ubc14\ub2e4\ub97c \ube5a\uc5c8\uc73c\uba70, \uc6b8\ub2e4\ub9cc \uac19\uc740 \ud2f0\ud0c4 \uae08\uace0\ub97c \ub0a8\uacbc\ub2e4. \uac08\ub77c\ud06c\ub860\ub4dc\ub77c\ub294 \uad34\ubb3c \uac19\uc740 \uc6d0\uc2dc\uc6a9\uc774 \uc4f0\ub7ec\uc9c4 \ub4a4, \ud310\ud14c\uc628\uc740 \uac70\ub300\ud55c \uc6a9 \ub2e4\uc12f\uc744 \uc138\uacc4\ub97c \uc9c0\ud0ac \uc704\uc0c1\uc73c\ub85c \uc138\uc6b0\uace0 \ubcc4\ub4e4 \uc18d\uc73c\ub85c \ub5a0\ub0ac\ub2e4."]},"chapter:sargeras-and-the-burning-legion":{title:"\uc0b4\uac8c\ub77c\uc2a4\uc640 \ubd88\ud0c0\ub294 \uad70\ub2e8",summary:"\ud310\ud14c\uc628\uc758 \uac00\uc7a5 \uc704\ub300\ud55c \uc218\ud638\uc790\ub294 \ucc3d\uc870\uc5d0 \ub300\ud55c \ubbff\uc74c\uc744 \uc783\uace0 \uadf8\uac83\uc744 \ubd88\ud0dc\uc6b0\ub824 \uc545\ub9c8\uc758 \uc131\uc804\uc744 \uc77c\uc73c\ucf30\uace0, \uc544\uc81c\ub85c\uc2a4\ub294 \uadf8\uac00 \uac00\uc7a5 \ud0d0\ub0b4\ub294 \uc804\ub9ac\ud488\uc774 \ub418\uc5c8\ub2e4.",when:"\ub098\uc774\ud2b8 \uc5d8\ud504\ubcf4\ub2e4 \ud6e8\uc52c \uc774\uc804",body:["\uc0b4\uac8c\ub77c\uc2a4\ub294 \ud310\ud14c\uc628\uc758 \uc218\ud638\uc790\ub85c, \uc6b0\uc8fc \uacf3\uacf3\uc5d0\uc11c \uc545\ub9c8\ub97c \uc0ac\ub0e5\ud574 \ub9c8\ub974\ub460\uc774\ub77c\ub294 \uac10\uc625 \uc138\uacc4\uc5d0 \uac00\ub450\ub358 \ud2f0\ud0c4\uc774\uc5c8\ub2e4. \uae30\ub098\uae34 \uc804\uc7c1 \uc18d\uc5d0\uc11c \uadf8\ub294 \uacf5\ud5c8\uc758 \uad70\uc8fc\ub4e4\uc774 \uc9c4\uc815 \uc6d0\ud558\ub294 \uac83\uc744 \uc54c\uac8c \ub418\uc5c8\ub2e4. \uc138\uacc4\ud63c\uc744 \ud0c0\ub77d\uc2dc\ucf1c \uc790\uc2e0\ub4e4\ub9cc\uc758 \uc5b4\ub460\uc758 \ud2f0\ud0c4\uc744 \ub0b3\ub294 \uac83\uc774\uc5c8\ub2e4. \ucc3d\uc870\uac00 \uad6c\uc81c\ud560 \uc218 \uc5c6\uc744 \ub9cc\ud07c \uacb0\ud568\ud22c\uc131\uc774\ub77c\uace0 \ud655\uc2e0\ud55c \uadf8\ub294 \ubaa8\ub4e0 \uac83\uc744 \ubd88\ud0dc\uc6b0\ub294 \ud3b8\uc774 \ucc28\ub77c\ub9ac \uc790\ube44\ub86d\ub2e4\uace0 \uacb0\ub860\uc9c0\uc5c8\ub2e4.","\uadf8\ub294 \ub9c8\ub974\ub460\uc758 \uac10\uc625\uc744 \ubd80\uc218\uace0 \uadf8 \uc548\uc758 \uc545\ub9c8\ub4e4\uc744 \ud480\uc5b4 \ubd88\ud0c0\ub294 \uad70\ub2e8\uc758 \uccab \ub300\uc5f4\ub85c \uc0bc\uc558\ub2e4. \uc544\ub974\uac70\uc2a4 \ud589\uc131\uc5d0\uc11c \uadf8\ub294 \uc5d0\ub808\ub2e4\ub974\uc5d0\uac8c \uc9c0\uc2dd\uacfc \ud798\uc744 \ub0b4\ubc00\uc5c8\ub2e4. \uadf8\ub4e4\uc758 \uc9c0\ub3c4\uc790 \ud0ac\uc81c\ub374\uacfc \uc544\ud0a4\ubaac\ub4dc\ub294 \uc774\ub97c \ubc1b\uc544\ub4e4\uc600\uace0, \uc608\uc5b8\uc790 \ubca8\ub80c\uc740 \uac70\uc808\ud55c \uc774\ub4e4\uacfc \ud568\uaed8 \ub2ec\uc544\ub0ac\ub2e4. \ud6d7\ub0a0 \ub4dc\ub808\ub098\uc774\ub77c \ubd88\ub9ac\uac8c \ub420 \uc774\ub4e4\uc774\uc5c8\ub2e4. \ud310\ud14c\uc628\uc740 \uc61b \uc218\ud638\uc790\ub97c \ub9c9\uc73c\ub824 \ud588\uc73c\ub098 \uadf8\uc758 \uc190\uc5d0 \uc4f0\ub7ec\uc84c\ub2e4.","\uadf8 \ub4a4\ub85c \uad70\ub2e8\uc740 \uc0b4\uac8c\ub77c\uc2a4\uc758 \uc9c0\ud718 \uc544\ub798 \uc138\uacc4\uc5d0\uc11c \uc138\uacc4\ub85c \uc62e\uaca8 \ub2e4\ub154\uace0, \uc5d0\ub808\ub2e4\ub974\uc640 \ub098\uc2a4\ub808\uc9d0\uc774\ub77c \ubd88\ub9ac\ub294 \uacf5\ud3ec\uc758 \uad70\uc8fc\ub4e4, \uadf8\ub9ac\uace0 \uc218\ub9ce\uc740 \ud558\uae09 \uc545\ub9c8\uac00 \uadf8\ub97c \uc12c\uacbc\ub2e4. \uc544\uc81c\ub85c\uc2a4\ub294 \ub2e4\ub978 \uc5b4\ub5a4 \uc138\uacc4\ubcf4\ub2e4 \uc911\uc694\ud588\ub2e4. \uc544\uc9c1 \uc7a0\ub4e4\uc5b4 \uc788\ub294 \uc138\uacc4\ud63c\uc774\uc5c8\uace0, \uc774\ubbf8 \uace0\ub300 \uc2e0\ub4e4\uc758 \ud754\uc801\uc774 \uc0c8\uaca8\uc838 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc6d4\ub4dc \uc624\ube0c \uc6cc\ud06c\ub798\ud504\ud2b8\uc758 \uc2dc\ub300\uc5d0 \uc774\ub974\uae30\uae4c\uc9c0 \uad70\ub2e8\uc740 \uc544\uc81c\ub85c\uc2a4\ub97c \ub450 \ubc88 \uce68\uacf5\ud588\uace0, \uadf8\ub4e4\uc758 \uc18d\uc0ad\uc784\uc740 \uc5d8\ud504\uc640 \uc624\ud06c\uc640 \uc778\uac04\uc758 \uc5ed\uc0ac\ub97c \ubaa8\ub450 \ube5a\uc5b4\ub0c8\ub2e4."]},"chapter:rise-of-the-kaldorei":{title:"\uce7c\ub3c4\ub808\uc774\uc758 \ubd80\ud765",summary:"\uace0\ub300 \uce7c\ub9bc\ub3c4\uc5b4\ub294 \ud2b8\ub864\uc774 \uc9c0\ubc30\ud588\uc9c0\ub9cc, \uc601\uc6d0\uc758 \uc0d8\uc5d0 \uc774\ub04c\ub9b0 \ud55c \ubd80\uc871\uc774 \ub098\uc774\ud2b8 \uc5d8\ud504\uac00 \ub418\uc5c8\uace0, \uadf8\ub4e4\uc758 \uc5ec\uc655 \uc544\uc988\uc0e4\ub77c\ub294 \uc228 \ub9c9\ud790 \ub4ef\ud55c \ub9c8\ubc95\uc758 \uc81c\uad6d\uc744 \uc138\uc6e0\ub2e4.",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 15,000~10,000\ub144 \uc804",body:["\ud2f0\ud0c4\ub4e4\uc774 \ub5a0\ub09c \ub4a4\uc758 \uc2dc\ub300\uc5d0 \uce7c\ub9bc\ub3c4\uc5b4\ub294 \ud558\ub098\uc758 \uac70\ub300\ud55c \ub300\ub959\uc774\uc5c8\ub2e4. \uc794\ub2ec\ub77c\uac00 \uc774\ub044\ub294 \ud2b8\ub864\ub4e4\uc740 \uace0\ub300 \uc2e0\uc758 \ud558\uc218\uc778\uc774 \ub0a8\uae34 \uace4\ucda9 \uac19\uc740 \uc885\uc871 \uc544\ud034\ub974\uc640 \uc624\ub79c \uc804\uc7c1\uc744 \ubc8c\uc5ec, \uadf8\ub4e4\uc744 \ub545\uc758 \ubd81\ucabd\uacfc \ub0a8\ucabd \ub05d\uc73c\ub85c \ubab0\uc544\ub0c8\ub2e4. \uadf8\uacf3\uc5d0\uc11c \uadf8 \ud6c4\uc190\ub4e4\uc740 \ud6d7\ub0a0 \ub124\ub8e8\ube44\uc548\uacfc \ud034\ub77c\uc9c0\uac00 \ub41c\ub2e4. \uc2b9\ub9ac\ud55c \ud2b8\ub864\ub4e4\uc740 \uad6c\ub8e8\ubc14\uc2dc\uc640 \uc544\ub9c8\ub2c8 \uac19\uc740 \uacbd\uc7c1 \uc81c\uad6d\uc73c\ub85c \uac08\ub77c\uc84c\ub2e4.","\ud55c \ud2b8\ub864 \ubd80\uc871\uc740 \ub354 \uc870\uc6a9\ud55c \uae38\uc744 \ud0dd\ud588\ub2e4. \uadf8\ub4e4\uc740 \uc601\uc6d0\uc758 \uc0d8 \uae30\uc2ad\uc5d0 \uc815\ucc29\ud588\uace0, \uc5ec\ub7ec \uc138\ub300\uc5d0 \uac78\uccd0 \uc0d8\uc758 \ud798\uc774 \uadf8\ub4e4\uc744 \ubc14\uafb8\uc5b4 \ub193\uc558\ub2e4. \uadf8\ub4e4\uc740 \ub354 \ud06c\uace0 \uc624\ub798 \uc0b4\uac8c \ub418\uc5c8\uc73c\uba70, \ub2ec\uc758 \uc5ec\uc2e0 \uc5d8\ub8ec\uc744 \uc12c\uae30\uace0 \uc2a4\uc2a4\ub85c\ub97c '\ubcc4\uc758 \uc790\uc190', \uce7c\ub3c4\ub808\uc774\ub77c \ubd88\ub800\ub2e4. \ubc18\uc2e0 \uc138\ub098\ub9ac\uc6b0\uc2a4\uc640 \ub2e4\ub978 \uace0\ub300 \uc790\uc5f0\uc758 \uc815\ub839\ub4e4\uc758 \uc778\ub3c4\ub97c \ubc1b\uc544, \uadf8\ub4e4\uc740 \uace7 \ud2b8\ub864 \uce5c\ucc99\ub4e4\uc744 \ub2a5\uac00\ud588\ub2e4.","\uadf8\ub4e4\uc758 \uac00\uc7a5 \uc704\ub300\ud55c \ud1b5\uce58\uc790\ub294 \ubc31\uc131\uc758 \uc0ac\ub791\uc744 \ubc1b\uc740 \uc544\uc988\uc0e4\ub77c \uc5ec\uc655\uc774\uc5c8\ub2e4. \uadf8\ub140\ub97c \uc12c\uae34 \uba85\uac00\ub294 \uc0d8\uc5d0\uc11c \uc810\uc810 \ub354 \ub9ce\uc740 \ud798\uc744 \ub04c\uc5b4\ub0b4\ub294 \ub9c8\ubc95\uc0ac \uadc0\uc871\uc774\uc5c8\ub2e4. \uadf8\ub140\uc758 \uad81\uc804\uc740 \uc0d8 \uae30\uc2ad\uc758 \uc9c4\uc544\uc988\uc0e4\ub9ac\uc5d0 \uc11c \uc788\uc5c8\uace0, \uc81c\uad6d\uc740 \uce7c\ub9bc\ub3c4\uc5b4 \uc804\uc5ed\uc73c\ub85c \ubed7\uc5b4 \ub098\uac14\ub2e4. \uadf8\ub7ec\ub098 \ub9c8\ubc95\uc744 \ud5a5\ud55c \uba85\uac00\uc758 \uac08\ub9dd\uc740 \uc138\uacc4 \ub108\uba38 \uba40\ub9ac\uae4c\uc9c0 \ud30c\ubb38\uc744 \uc77c\uc73c\ucf30\uace0, \ub4a4\ud2c0\ub9b0 \ud669\ucc9c\uc758 \uac70\ub300\ud55c \ubb34\uc5b8\uac00\uac00 \uadf8\uac83\uc744 \ub290\uaf08\ub2e4."]},"chapter:war-of-the-ancients":{title:"\uace0\ub300\uc758 \uc804\uc7c1",summary:"\uc544\uc988\uc0e4\ub77c\uac00 \ubd88\ud0c0\ub294 \uad70\ub2e8\uc5d0\uac8c \uae38\uc744 \uc5f4\uc5c8\uace0, \uc601\uc6d0\uc758 \uc0d8\uc774 \uc2a4\uc2a4\ub85c \ubb34\ub108\uc9c0\uae30 \uc804\uae4c\uc9c0 \uc138\uacc4\ub294 \uac70\uc758 \uc885\ub9d0\uc744 \ub9de\uc744 \ubed4\ud588\ub2e4.",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 10,000\ub144 \uc804",body:["\uc0b4\uac8c\ub77c\uc2a4\ub294 \uc544\uc988\uc0e4\ub77c\uc640 \uba85\uac00\uc5d0\uac8c \uc18d\uc0ad\uc774\uba70 \uadf8\ub4e4\uc758 \ubaa8\uc2b5\ub300\ub85c \ub2e4\uc2dc \ube5a\uc5b4\uc9c4 \uc138\uacc4\ub97c \uc57d\uc18d\ud588\ub2e4. \uadf8\ub4e4\uc740 \uadf8\ub97c \ubbff\uace0 \uc601\uc6d0\uc758 \uc0d8\uc744 \ud1b5\ud574 \ubd88\ud0c0\ub294 \uad70\ub2e8\uc744 \uc704\ud55c \uad00\ubb38\uc744 \uc5f4\uc5c8\ub2e4. \uc544\ud0a4\ubaac\ub4dc\uc640 \ub9cc\ub178\ub85c\uc2a4\uac00 \uc774\ub044\ub294 \uc545\ub9c8\ub4e4\uc774 \uce7c\ub9bc\ub3c4\uc5b4\ub85c \uc3df\uc544\uc838 \ub4e4\uc5b4\uc640, \uc5ec\uc655\uc774 \ub2e4\uc2a4\ub9ac\ub358 \ubc14\ub85c \uadf8 \uce7c\ub3c4\ub808\uc774\ub97c \ud559\uc0b4\ud558\uae30 \uc2dc\uc791\ud588\ub2e4.","\uc800\ud56d\uad70\uc740 \ub73b\ubc16\uc758 \uc9c0\ub3c4\uc790\ub4e4\uc744 \uc911\uc2ec\uc73c\ub85c \ubaa8\uc600\ub2e4. \uc138\ub098\ub9ac\uc6b0\uc2a4\uc5d0\uac8c \ub4dc\ub8e8\uc774\ub4dc\uc758 \uae38\uc744 \ubc30\uc6b4 \ucd5c\ucd08\uc758 \ub098\uc774\ud2b8 \uc5d8\ud504 \ub9d0\ud4e8\ub9ac\uc628 \uc2a4\ud1b0\ub808\uc774\uc9c0, \uc7ac\ub2a5 \uc788\ub294 \ub9c8\ubc95\uc0ac\uc600\ub358 \uadf8\uc758 \uc30d\ub465\uc774 \ub3d9\uc0dd \uc77c\ub9ac\ub2e8, \uadf8\ub9ac\uace0 \uc5d8\ub8ec\uc758 \uc0ac\uc81c \ud2f0\ub780\ub370 \uc704\uc2a4\ud37c\uc708\ub4dc\uc600\ub2e4. \uc790\uc5f0\uc758 \ubc18\uc2e0\ub4e4\uacfc \ub300\ubd80\ubd84\uc758 \uc6a9\uad70\ub2e8\uc774 \uadf8\ub4e4 \uacc1\uc5d0\uc11c \uc2f8\uc6e0\ub2e4. \uac80\uc740 \uc704\uc0c1 \ub12c\ud0c0\ub9ac\uc628\uc740 \uc6a9\uc758 \uc601\ud63c\uc774\ub77c\ub294 \ubb34\uae30\ub97c \ub0b4\ub193\uc558\uc9c0\ub9cc, \uadf8\uac83\uc744 \ub3d9\ub9f9\ub4e4\uc5d0\uac8c \uaca8\ub204\uc5c8\ub2e4. \uc774 \ubc30\uc2e0\uc73c\ub85c \uadf8\ub294 \ub370\uc2a4\uc719\uc774\ub77c\ub294 \uc774\ub984\uc744 \uc5bb\uac8c \ub41c\ub2e4.","\uc0b4\uac8c\ub77c\uc2a4\uac00 \uc9c1\uc811 \uad00\ubb38\uc744 \ub118\uc5b4\uc624\ub824 \ud558\uc790, \ub9d0\ud4e8\ub9ac\uc628\uacfc \ub3d9\ub8cc\ub4e4\uc740 \uba85\uac00\uc758 \uc8fc\ubb38\uc744 \ubb34\ub108\ub728\ub838\ub2e4. \ubd88\uc548\uc815\ud574\uc9c4 \uc0d8\uc740 \uc548\uc73c\ub85c \ubd95\uad34\ud588\uace0, \uc138\uacc4\uc758 \ubd84\ub9ac\uac00 \ub4a4\ub530\ub790\ub2e4. \ubc14\ub2e4\uac00 \uc9c4\uc544\uc988\uc0e4\ub9ac\ub97c \uc0bc\ud0a4\uace0 \uce7c\ub9bc\ub3c4\uc5b4\uac00 \ucabc\uac1c\uc84c\uc73c\uba70, \uc0d8\uc774 \uc788\ub358 \uc790\ub9ac\uc5d0\uc11c\ub294 \ud63c\ub3c8\uc758 \uc18c\uc6a9\ub3cc\uc774\ub77c \ubd88\ub9ac\ub294 \ud3ed\ud48d\uc774 \ub3cc\uae30 \uc2dc\uc791\ud588\ub2e4. \uc544\uc988\uc0e4\ub77c\uc640 \uadf8\ub140\uc758 \uad81\uc815\uc740 \ud30c\ub3c4 \uc544\ub798\ub85c \uc0ac\ub77c\uc84c\uace0, \ud6d7\ub0a0 \ub098\uac00\uac00 \ub418\uc5b4 \ub3cc\uc544\uc628\ub2e4. \ud558\ub098\uc600\ub358 \ub300\ub959\uc5d0\uc11c \uc624\ub298\ub0a0 \uce7c\ub9bc\ub3c4\uc5b4, \ub3d9\ubd80 \uc655\uad6d, \ub178\uc2a4\ub80c\ub4dc\ub85c \uc54c\ub824\uc9c4 \ub545\ub4e4\uc774 \uc0dd\uaca8\ub0ac\ub2e4."]},"chapter:the-long-watch-of-hyjal":{title:"\ud558\uc774\uc798\uc758 \uae30\ub098\uae34 \ud30c\uc218",summary:"\uc0dd\uc874\uc790\ub4e4\uc740 \ub450 \ubc88\uc9f8 \uc0d8 \uc704\uc5d0 \uc138\uacc4\uc218\ub97c \ud0a4\uc6b0\uace0, \uc77c\ub9ac\ub2e8\uc744 \ub545\uc18d\uc5d0 \uac00\ub450\uc5c8\uc73c\uba70, \ub9cc \ub144 \ub3d9\uc548 \ud30c\uc218\ub97c \uc130\ub2e4.",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 10,000\ub144 \uc804\ubd80\ud130",body:["\uc138\uacc4\uc758 \ubd84\ub9ac\uc5d0\uc11c \uc0b4\uc544\ub0a8\uc740 \ub098\uc774\ud2b8 \uc5d8\ud504\ub4e4\uc740 \ud558\uc774\uc798 \uc0b0\uc5d0 \ubaa8\uc600\ub2e4. \uadf8\uacf3\uc5d0\uc11c \uadf8\ub4e4\uc740 \uc77c\ub9ac\ub2e8\uc774 \uc61b \uc0d8\uc758 \ubb3c\uc744 \ub2f4\uc740 \uc57d\ubcd1\ub4e4\uc744 \uac00\uc9c0\uace0 \ub098\uc640 \uadf8\uc911 \uc77c\ubd80\ub97c \uc0b0\uc18d \ud638\uc218\uc5d0 \ubd80\uc5b4 \uc0c8\ub85c\uc6b4 \uc601\uc6d0\uc758 \uc0d8\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uac8c \ub418\uc5c8\ub2e4. \uadf8\uac83\uc774 \uc5b8\uc820\uac00 \uad70\ub2e8\uc744 \ub2e4\uc2dc \ubd88\ub7ec\ub4e4\uc77c\uae4c \ub450\ub824\uc6cc\ud55c \ub9d0\ud4e8\ub9ac\uc628\uacfc \uc138\ub098\ub9ac\uc6b0\uc2a4\ub294 \uc77c\ub9ac\ub2e8\uc744 \ub545\uc18d \uac10\uc625\uc778 Barrow Deeps\uc5d0 \uac00\ub450\uc5c8\uace0, \uac04\uc218 \ub9c8\uc774\uc5d0\ube0c \uc100\ub3c4\uc1a1\uc774 \ub9cc \ub144 \ub3d9\uc548 \uadf8\ub97c \uc9c0\ud0a4\uac8c \ub418\uc5c8\ub2e4.","\uc138 \uc704\uc0c1, \uc54c\ub809\uc2a4\ud2b8\ub77c\uc790\uc640 \uc774\uc138\ub77c\uc640 \ub178\uc988\ub3c4\ub974\ubb34\ub294 \uc0c8\ub85c\uc6b4 \uc0d8 \uc704\uc5d0 \uc138\uacc4\uc218 \ub180\ub4dc\ub78f\uc2e4\uc744 \ud0a4\uc6cc \uc751\ub2f5\ud588\ub2e4. \uadf8 \ubfcc\ub9ac\ub294 \uc0d8\ubb3c\uc744 \ubd09\uc778\ud588\uace0, \uadf8 \ucd95\ubcf5\uc740 \ub098\uc774\ud2b8 \uc5d8\ud504\uc5d0\uac8c \ubd88\uba78\uc744, \ub4dc\ub8e8\uc774\ub4dc\uc5d0\uac8c\ub294 \uc5d0\uba54\ub784\ub4dc\uc758 \uafc8\uacfc\uc758 \uc720\ub300\ub97c \uc8fc\uc5c8\ub2e4. \ub9ce\uc740 \ub4dc\ub8e8\uc774\ub4dc\uac00 \uadf8\uacf3\uc5d0\uc11c \uc218\ubc31 \ub144\uc529 \uc7a0\ub4e4\uc5c8\ub2e4. \ud2f0\ub780\ub370\ub294 \uc5d8\ub8ec\uc758 \uc790\ub9e4\ud68c\uc640 \ud30c\uc218\uafbc\uc744 \uc774\ub04c\uba70 \ub4dc\ub8e8\uc774\ub4dc\ub4e4\uc774 \uafc8\uafb8\ub294 \ub3d9\uc548 \uc232\uc744 \uc9c0\ucf30\ub2e4. \uce7c\ub3c4\ub808\uc774 \uc0ac\uc774\uc5d0\uc11c \ube44\uc804 \ub9c8\ubc95\uc740 \uae08\uc9c0\ub418\uc5c8\ub2e4.","\ubaa8\ub4e0 \uba85\uac00\uac00 \ub530\ub978 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc77c\ubd80\ub294 \ubc14\ub2e4 \uac74\ub108\ub85c \ucd94\ubc29\ub418\uc5b4 \ucfe0\uc5d8\ud0c8\ub77c\uc2a4\ub97c \uc138\uc6e0\uace0, \uc174\ub4dc\ub784\ub77c\ub77c \ubd88\ub9ac\ub294 \ub2e4\ub978 \uc774\ub4e4\uc740 \uc9c0\uae08\uc758 \ud398\ub784\ub77c\uc2a4\uc5d0 \uc788\ub294 \ub3c4\uc2dc \uc5d8\ub4dc\ub808\ud0c8\ub77c\uc2a4\uc5d0 \uc228\uc5b4\ub4e4\uc5c8\ub2e4. \uadf8 \ud3d0\ud5c8\ub294 \uc624\ub298\ub0a0 \ud608\ud22c\uc758 \uc804\uc7a5\uc774\ub77c \ubd88\ub9b0\ub2e4."]},"chapter:exiles-of-quelthalas":{title:"\ucfe0\uc5d8\ud0c8\ub77c\uc2a4\uc758 \ucd94\ubc29\uc790\ub4e4",summary:"\ucd94\ubc29\ub2f9\ud55c \uba85\uac00\ub294 \ubc14\ub2e4\ub97c \uac74\ub108 \ud0dc\uc591\uc0d8\uc744 \ubc1d\ud788\uace0, \ub85c\ub370\ub860 \ubd81\ubd80\uc758 \uc232\uc5d0 \uc5d8\ud504 \uc655\uad6d\uc744 \uc138\uc6e0\ub2e4.",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 6,800\ub144 \uc804",body:["\uc138\uacc4\uc758 \ubd84\ub9ac\uac00 \uc788\uace0 \uc624\ub79c \uc138\uc6d4\uc774 \ud750\ub978 \ub4a4\uc5d0\ub3c4, \ud55c \ubb34\ub9ac\uc758 \uba85\uac00\ub294 \uc5ec\uc804\ud788 \ube44\uc804 \ub9c8\ubc95\uc744 \ud3ec\uae30\ud558\uc9c0 \ubabb\ud588\ub2e4. \uadf8\ub4e4\uc758 \ubb34\ubaa8\ud55c \uc8fc\ubb38\uc740 \uc7bf\ube5b \uace8\uc9dc\uae30 \uc704\uc5d0 \ud3ed\ud48d\uc744 \uc77c\uc73c\ucf30\uace0, \ub098\uc774\ud2b8 \uc5d8\ud504\ub4e4\uc740 \uacb0\uad6d \uadf8\ub4e4\uc744 \ucd94\ubc29\ud588\ub2e4. \ub2e4\uc2a4\ub808\ub9c8\ub974 \uc120\uc2a4\ud2b8\ub77c\uc774\ub354\uac00 \uc774\ub044\ub294 \ucd94\ubc29\uc790\ub4e4\uc740 \ub300\ud574\ub97c \uac74\ub108 \ub3d9\ucabd\uc73c\ub85c \ud56d\ud574\ud588\uace0, \ub9c8\ubc95\uc774 \uac15\ud558\uac8c \ud750\ub974\ub294 \ub545\uc744 \ucc3e\uc544 \uc5ec\ub7ec \ud574 \ub3d9\uc548 \uc0c8 \ub300\ub959\uc744 \ub5a0\ub3cc\uc558\ub2e4.","\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 6,800\ub144 \uc804, \uadf8\ub4e4\uc740 \ub85c\ub370\ub860 \ubd81\ubd80\uc5d0\uc11c \uadf8\ub7f0 \ub545\uc744 \ucc3e\uc544\ub0c8\ub2e4. \ub2e4\uc2a4\ub808\ub9c8\ub974\ub294 \ud6d4\uccd0 \uc628 \uc601\uc6d0\uc758 \uc0d8 \ubb3c \ud55c \ubcd1\uc744 \uc9c0\ub9e5\uc774 \uad50\ucc28\ud558\ub294 \uacf3\uc758 \ud638\uc218\uc5d0 \ubd80\uc5c8\uace0, \ud0dc\uc591\uc0d8\uc774 \ud0c0\uc624\ub974\uba70 \uc0dd\uaca8\ub0ac\ub2e4. \uadf8 \uc8fc\uc704\uc5d0 \ucfe0\uc5d8\ud0c8\ub77c\uc2a4\uc640 \uc218\ub3c4 \uc2e4\ubc84\ubb38\uc774 \uc138\uc6cc\uc84c\ub2e4. \ub2ec\uc774 \uc544\ub2cc \ud0dc\uc591 \uc544\ub798\uc5d0\uc11c \uc0b4\uac8c \ub41c \ucd94\ubc29\uc790\ub4e4\uc740 \uc218\ubc31 \ub144\uc5d0 \uac78\uccd0 \ubcc0\ud574 \ud558\uc774 \uc5d8\ud504, \uace7 \ucfe0\uc5d8\ub3c4\ub808\uc774\uac00 \ub418\uc5c8\ub2e4.","\uadf8 \ub545\uc740 \ube44\uc5b4 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uadf8\uacf3\uc5d0\ub294 \uc544\ub9c8\ub2c8 \ud2b8\ub864\uc5d0\uac8c \uc2e0\uc131\ud55c \uace0\ub300 \uc720\uc801\uc774 \uc788\uc5c8\uace0, \ud2b8\ub864\ub4e4\uc740 \uc555\ub3c4\uc801\uc778 \uc218\ub85c \uc0c8\ub85c \uc628 \uc774\ub4e4\uc744 \uacf5\uaca9\ud588\ub2e4. \uc5d8\ud504\ub4e4\uc740 \ub9c8\ubc95\uc73c\ub85c \uadf8\ub4e4\uc744 \ub9c9\uc544 \ub0b4\uace0, \uc544\ub9c8\ub2c8\ub97c \ub9c9\ub294 \ub8ec\uc11d \uc7a5\ubcbd \ubc18\ub514\ub178\ub9ac\uc5d8\uc744 \uc138\uc6e0\ub2e4. \uc57d \uc0ac\ucc9c \ub144 \ub3d9\uc548 \ucfe0\uc5d8\ud0c8\ub77c\uc2a4\ub294 \uadf8 \ub4a4\uc5d0\uc11c \ubc88\uc601\ud588\uace0, \ud2b8\ub864\ub4e4\uc740 \ubcf5\uc218\ub97c \uae30\ub2e4\ub838\ub2e4."]},"chapter:arathor-and-the-troll-wars":{title:"\uc544\ub77c\uc18c\ub974\uc640 \ud2b8\ub864 \uc804\uc7c1",summary:"\ud769\uc5b4\uc838 \uc788\ub358 \uc778\uac04 \ubd80\uc871\ub4e4\uc740 \uc18c\ub77c\ub518 \uc655 \uc544\ub798 \ud558\ub098\uac00 \ub418\uc5c8\uace0, \uc5d8\ud504\uc640\uc758 \ub3d9\ub9f9\uc740 \uc54c\ud130\ub799 \uc0b0\ub9e5 \uae30\uc2ad\uc5d0\uc11c \uc544\ub9c8\ub2c8 \uc81c\uad6d\uc744 \ubb34\ub108\ub728\ub838\ub2e4.",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 2,800\ub144 \uc804",body:["\uc218\ucc9c \ub144 \ub3d9\uc548 \ub3d9\ubd80 \uc655\uad6d\uc758 \uc778\uac04 \ubd80\uc871\ub4e4\uc740 \uc11c\ub85c \uc2f8\uc6e0\uace0, \ubd81\ucabd\uc5d0\uc11c\ub294 \uc544\ub9c8\ub2c8 \uc57d\ud0c8\uc790\ub4e4\uc774 \uccd0\ub4e4\uc5b4\uc654\ub2e4. \uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 2,800\ub144 \uc804, \uc544\ub77c\uc2dc \ubd80\uc871\uc758 \uc18c\ub77c\ub518\uc740 \ubd84\uc5f4\ub41c \uc778\ub958\uac00 \uba78\ub9dd\ud558\ub9ac\ub77c\ub294 \uac83\uc744 \uae68\ub2ec\uc558\ub2e4. \uadf8\ub294 \ud63c\uc778\uacfc \uc57d\uc18d\uacfc \uc815\ubcf5\uc73c\ub85c \ubd80\uc871\ub4e4\uc744 \uc544\ub77c\uc18c\ub974 \uc655\uad6d\uc73c\ub85c \ud1b5\ud569\ud588\uace0, \uc624\ub298\ub0a0\uc758 \uc544\ub77c\uc2dc \uace0\uc6d0\uc5d0 \uc218\ub3c4\uc778 \uc694\uc0c8 \ub3c4\uc2dc \uc2a4\ud2b8\ub86c\uc744 \uc138\uc6e0\ub2e4.","\uc794\ub2ec\ub77c\uc758 \ub3c4\uc6c0\uc73c\ub85c \ub2e4\uc2dc \uae30\uc138\ub97c \uc62c\ub9b0 \uc544\ub9c8\ub2c8\ub294 \uc5c4\uccad\ub09c \uc218\ub85c \ucfe0\uc5d8\ud0c8\ub77c\uc2a4\ub97c \uacf5\uaca9\ud588\ub2e4. \uc5d8\ud504\ub4e4\uc740 \uc544\ub77c\uc18c\ub974\uc5d0 \uc190\uc744 \ub0b4\ubc00\uc5c8\ub2e4. \uc778\uac04 \ubcd1\uc0ac\ub4e4\uc744 \uc5bb\ub294 \ub300\uac00\ub85c, \uadf8\ub4e4\uc740 \uc120\ud0dd\ub41c \uc778\uac04 \ubc31 \uba85\uc5d0\uac8c \ub9c8\ubc95\uc744 \uac00\ub974\uce58\uae30\ub85c \ud588\uace0, \uc774\ub4e4\uc774 \ucd5c\ucd08\uc758 \uc778\uac04 \ub9c8\ubc95\uc0ac\uac00 \ub418\uc5c8\ub2e4. \uc5d8\ud504\uc640 \uc778\uac04\uc740 \ud568\uaed8 \uc54c\ud130\ub799 \uc0b0\ub9e5 \uae30\uc2ad\uc5d0\uc11c \uc544\ub9c8\ub2c8 \uad70\ub300\ub97c \uada4\uba78\uc2dc\ucf30\uace0, \ub9c8\ubc95\uc0ac\ub4e4\uc758 \ubd88\uae38\uc740 \ud2b8\ub864\ub4e4\uc744 \ucca0\uc800\ud788 \ud769\uc5b4 \ub193\uc544 \uadf8\ub4e4\uc758 \uc81c\uad6d\uc740 \ub05d\ub0b4 \ud68c\ubcf5\ud558\uc9c0 \ubabb\ud588\ub2e4.","\uac10\uc0ac\uc758 \ub73b\uc73c\ub85c \ucfe0\uc5d8\ud0c8\ub77c\uc2a4\uc758 \uc5d8\ud504\ub4e4\uc740 \uc544\ub77c\uc18c\ub974 \uc655\uac00\uc758 \ud608\ud1b5\uc5d0 \ucda9\uc131\uc744 \ub9f9\uc138\ud588\ub2e4. \uc2a4\ud2b8\ub86c\uc740 \ubc88\uc601\ud588\uace0 \uadf8 \ubc31\uc131\uc740 \ubd81\ucabd \uacf3\uacf3\uc73c\ub85c \ud37c\uc838 \ub098\uac14\ub2e4. \uc544\ub9c8\ub2c8\ub294 \uadf8 \ub4a4\ub85c\ub3c4 \uc5ec\ub7ec \ubc88 \ub2e4\uc2dc \uc77c\uc5b4\uc11c\uac8c \ub418\uba70, \ub3d9\ubd80 \ub0b4\ub959\uc9c0\uc640 \uc544\ub77c\uc2dc \uace0\uc6d0\uc5d0\uc11c\ub294 \uc9c0\uae08\ub3c4 \uc232\ud2b8\ub864 \ubd80\uc871\ub4e4\uc774 \uadf8 \uc61b \uc804\uc7c1\uc758 \ud3d0\ud5c8\ub97c \ub5a0\ub3c8\ub2e4."]},"chapter:guardians-and-the-seven-kingdoms":{title:"\uc218\ud638\uc790\uc640 \uc77c\uacf1 \uc655\uad6d",summary:"\uc778\uac04\uc758 \ub9c8\ubc95\uc774 \uc545\ub9c8\ub97c \ub04c\uc5b4\ub4e4\uc774\uc790 \ub9c8\ubc95\uc0ac\ub4e4\uc740 \ub2ec\ub77c\ub780\uc744 \uc138\uc6b0\uace0 \ub0a8\ubab0\ub798 \uc2f8\uc6b8 \uc218\ud638\uc790\ub97c \ubf51\uc558\uc73c\uba70, \uadf8\uc0ac\uc774 \uc544\ub77c\uc18c\ub974\ub294 \uc77c\uacf1 \uc655\uad6d\uc73c\ub85c \uac08\ub77c\uc84c\ub2e4.",when:"\ud2b8\ub864 \uc804\uc7c1 \uc774\ud6c4\uc758 \uc218\ucc9c \ub144",body:["\ub9c8\ubc95\uc740 \uc9c0\ud61c\ubcf4\ub2e4 \ube60\ub974\uac8c \uc544\ub77c\uc18c\ub974\uc5d0 \ud37c\uc84c\ub2e4. \ub9c8\ubc95\uc0ac\ub4e4\uc758 \uc8fc\ubb38\uc740 \uc138\uacc4\uc758 \ubcbd\uc744 \uc587\uac8c \ub9cc\ub4e4\uace0 \uc545\ub9c8\ub4e4\uc758 \uc8fc\uc758\ub97c \ub04c\uc5c8\uace0, \uadf8\ub798\uc11c \ud558\uc774 \uc5d8\ud504\uc640 \uc778\uac04 \ub9c8\ubc95\uc0ac\ub4e4\uc740 \ud2f0\ub9ac\uc2a4\ud314 \uc758\ud68c\ub97c \uacb0\uc131\ud588\ub2e4. \uc758\ud68c\ub294 \ube44\ubc00\ub9ac\uc5d0 \ub2e8 \ud55c \uba85\uc758 \uc218\ud638\uc790\ub97c \ubf51\uc544 \uadf8\ub4e4\uc758 \ud798\uc744 \ubaa8\uc544 \ub9e1\uae30\uace0, \ubd88\ud0c0\ub294 \uad70\ub2e8\uc758 \ud558\uc218\uc778\ub4e4\uc744 \uc0ac\ub0e5\ud558\uac8c \ud588\ub2e4.","\ub9c8\ubc95\uc0ac\ub4e4\uc740 \ud0a4\ub9b0 \ud1a0\uac00 \ub2e4\uc2a4\ub9b4 \uadf8\ub4e4\ub9cc\uc758 \ub3c4\uc2dc \ub2ec\ub77c\ub780\ub3c4 \uc138\uc6e0\ub2e4. \ud55c\ud3b8 \uc544\ub77c\uc18c\ub974\uc758 \ud6c4\uacc4\uc790\ub4e4\uc740 \uc2a4\ud2b8\ub86c\uc744 \ub5a0\ub0ac\uace0, \uc218\ubc31 \ub144\uc5d0 \uac78\uccd0 \uc81c\uad6d\uc740 \uc77c\uacf1 \uc778\uac04 \uc655\uad6d\uc73c\ub85c \ub098\ub258\uc5c8\ub2e4. \ub85c\ub370\ub860, \uc2a4\ud2b8\ub86c\uac00\ub4dc, \uae38\ub2c8\uc544\uc2a4, \uc54c\ud130\ub799, \ucfe8 \ud2f0\ub77c\uc2a4, \ub2ec\ub77c\ub780, \uadf8\ub9ac\uace0 \ub0a8\ucabd\uc758 \uc2a4\ud1b0\uc708\ub4dc\uc600\ub2e4. \uc2a4\ud1b0\uc708\ub4dc\ub294 \uc624\ub7ab\ub3d9\uc548 \uc544\uc81c\ub85c\uc2a4 \uc655\uad6d\uc774\ub77c \ubd88\ub838\ub2e4.","\uac00\uc7a5 \uc720\uba85\ud55c \uc218\ud638\uc790\ub294 \uc560\uadf8\uc708\uc774\uc5c8\ub2e4. \uadf8\ub140\ub294 \ub178\uc2a4\ub80c\ub4dc\uc5d0\uc11c \uc0b4\uac8c\ub77c\uc2a4\uc758 \ud654\uc2e0\uc744 \uc4f0\ub7ec\ub728\ub9ac\uace0 \uadf8 \ubab8\uc744 \ubc14\ub2e4 \ubc11 \ubb34\ub364\uc5d0 \ubd09\uc778\ud588\ub2e4. \uadf8\ub140\ub294 \uc5b4\ub460\uc758 \ud2f0\ud0c4\uc758 \uc601\ud63c\uc774 \uc790\uc2e0\uc5d0\uac8c \uc228\uc5b4\ub4e0 \uac83\uc744 \ub05d\ub0b4 \uc54c\uc9c0 \ubabb\ud588\ub2e4. \uadf8\ub140\uac00 \uc544\ub4e4 \uba54\ub514\ube0c\ub97c \ub0b3\uc790 \uadf8 \uc601\ud63c\uc740 \uc544\ub4e4\uc5d0\uac8c \uc62e\uaca8 \uac14\uace0, \ub9c8\uc9c0\ub9c9 \uc218\ud638\uc790\ub294 \uc601\ud63c \uc18d\uc5d0 \ubc30\uc2e0\uc790\ub97c \uc228\uae34 \ucc44 \uc790\ub77c\ub0ac\ub2e4. \ud6d7\ub0a0 \uadf8\ub294 \uc790\uc2e0\uc758 \ud0d1 \uce74\ub77c\uc794\uc5d0\uc11c \uc624\ud06c\ub4e4\uc5d0\uac8c \ubb38\uc744 \uc5f4\uc5b4 \uc8fc\uac8c \ub41c\ub2e4."]},"chapter:war-of-the-three-hammers":{title:"\uc138 \ub9dd\uce58\uc758 \uc804\uc7c1",summary:"\uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \uc138 \ub4dc\uc6cc\ud504 \ud074\ub79c\uc774 \uc655\uc88c\ub97c \ub450\uace0 \uc2f8\uc6e0\uace0, \ud328\ubc30\ud55c \ub9c8\ubc95\uc0ac \uc601\uc8fc\uac00 \ub77c\uadf8\ub098\ub85c\uc2a4\ub97c \uc18c\ud658\ud574 \ub545\uc744 \ubd88\ud0dc\uc6b0\uba70 \uac80\uc740\ubc14\uc704 \uc0b0\uc744 \uc19f\uc544\uc624\ub974\uac8c \ud588\ub2e4.",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 230\ub144 \uc804",body:["\ub358 \ubaa8\ub85c\uc758 \ub208 \uc544\ub798, \ub4dc\uc6cc\ud504\ub4e4\uc740 \ud2f0\ud0c4\uc758 \ub300\uc9c0\uc778\uc5d0\uac8c\uc11c \ubfcc\ub9ac\ub97c \ucc3e\ub294 \ub3cc\uacfc \uc7a5\uc778\uc758 \uc655\uad6d \uc544\uc774\uc5b8\ud3ec\uc9c0\ub97c \uae4e\uc544 \ub0c8\ub2e4. \uc138 \ud074\ub79c\uc774 \ubd88\ud3b8\ud558\uac8c \uadf8\uacf3\uc744 \ub098\ub204\uc5b4 \uc37c\ub2e4. \ube0c\ub860\uc988\ube44\uc5b4\ub4dc, \uc640\uc77c\ub4dc\ud574\uba38, \uadf8\ub9ac\uace0 \ub9c8\ubc95\uc744 \uc0ac\ub791\ud558\ub294 \uac80\uc740\ubb34\uc1e0\uc600\ub2e4. \uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 230\ub144 \uc804, \ub300\uc655 \ubaa8\ub514\ubb34\uc2a4 \uc564\ube4c\ub9c8\uac00 \uc8fd\uc790 \uadf8\ub4e4\uc758 \uacbd\uc7c1\uc740 \ub0b4\uc804\uc73c\ub85c \ud3ed\ubc1c\ud588\ub2e4.","\ube0c\ub860\uc988\ube44\uc5b4\ub4dc\uac00 \uc2b9\ub9ac\ud574 \ub2e4\ub978 \ud074\ub79c\ub4e4\uc744 \ubab0\uc544\ub0c8\ub2e4. \uc640\uc77c\ub4dc\ud574\uba38\ub294 \ub3d9\ucabd\uc5d0 \uadf8\ub9bc \ubc14\ud1a8\uc744 \uc138\uc6e0\uace0, \uac80\uc740\ubb34\uc1e0\ub294 \ub0a8\ucabd \ubd89\uc740\ub9c8\ub8e8 \uc0b0\ub9e5\uc5d0 \uadf8\ub4e4\ub9cc\uc758 \uc655\uad6d\uc744 \uc138\uc6e0\ub2e4. \ub9c8\ubc95\uc0ac \uc601\uc8fc \ud0c0\uc6b0\ub9bf\uc0b0\uc740 \ud328\ubc30\ub97c \ubc1b\uc544\ub4e4\uc774\uc9c0 \ubabb\ud588\ub2e4. \uadf8\ub294 \ub450 \uacbd\uc7c1\uc790\ub97c \ub3d9\uc2dc\uc5d0 \uacf5\uaca9\ud588\uc9c0\ub9cc \uadf8\uc758 \uad70\ub300\ub294 \ubb34\ub108\uc84c\uace0, \uc544\ub0b4 \ubaa8\ub4dc\uad6c\ub4dc\ub294 \uadf8\ub9bc \ubc14\ud1a8\uc5d0\uc11c \uc4f0\ub7ec\uc84c\ub2e4.","\uc808\ub9dd\ud55c \ud0c0\uc6b0\ub9bf\uc0b0\uc740 \ub354 \ud070 \ud798\uc5d0 \uc190\uc744 \ubed7\uc5b4, \ud2f0\ud0c4\uc774 \uac00\ub450\uc5b4 \ub454 \uc815\ub839 \uad70\uc8fc\uc778 \ubd88\uc758 \uad70\uc8fc \ub77c\uadf8\ub098\ub85c\uc2a4\ub97c \uc18c\ud658\ud588\ub2e4. \ubd88\uc758 \uad70\uc8fc\uc758 \ucd9c\ud604\uc740 \uc601\uc8fc\ub97c \uc8fd\uc774\uace0, \ub545\uc744 \ucc22\uc5b4 \uc774\uae00\uac70\ub9ac\ub294 \ud611\uace1\uacfc \ubd88\ud0c0\ub294 \ud3c9\uc6d0\uc744 \ub9cc\ub4e4\uc5c8\uc73c\uba70, \uac80\uc740\ubc14\uc704 \uc0b0\uc744 \uc19f\uc544\uc624\ub974\uac8c \ud588\ub2e4. \uc0b4\uc544\ub0a8\uc740 \uac80\uc740\ubb34\uc1e0 \ub4dc\uc6cc\ud504\ub4e4\uc740 \uadf8\uacf3\uc5d0\uc11c \uadf8\uc758 \ub178\uc608\uac00 \ub418\uc5c8\ub2e4. \uc640\uc77c\ub4dc\ud574\uba38\ub294 \uc800\uc8fc\ubc1b\uc740 \uadf8\ub9bc \ubc14\ud1a8\uc744 \ubc84\ub9ac\uace0 \ub3d9\ubd80 \ub0b4\ub959\uc9c0\ub85c \ub5a0\ub0ac\ub2e4. \uac00\uae4c\uc6b4 \uacf3\uc5d0 \ub3c4\uc2dc \ub188\ub9ac\uac74\uc744 \ub450\uace0 \uc788\ub358 \uc774\uc6c3 \ub178\uc6c0\ub4e4\uc740 \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \uad73\uac74\ud55c \uce5c\uad6c\uac00 \ub418\uc5c8\ub2e4."]},"chapter:corruption-of-the-orcs":{title:"\uc624\ud06c\uc758 \ud0c0\ub77d",summary:"\uba38\ub098\uba3c \ub4dc\ub808\ub178\uc5b4\uc5d0\uc11c \ud0ac\uc81c\ub374\uc740 \uc8fc\uc220\uc744 \ub530\ub974\ub358 \uc624\ud06c \ubd80\uc871\ub4e4\uc744 \uc545\ub9c8\uc758 \ud53c\ub85c \ubb36\uc778 \ud53c\uc5d0 \uad76\uc8fc\ub9b0 \ud638\ub4dc\ub85c \ubc14\uafb8\uc5b4 \ub193\uc558\ub2e4.",when:"\uc5b4\ub460\uc758 \ubb38 \uc774\uc804\uc758 \uc218\uc2ed \ub144",body:["\ub4dc\ub808\ub178\uc5b4\uc5d0\uc11c \uc624\ud06c\ub4e4\uc740 \uc0ac\ub0e5\uafbc\uacfc \uc8fc\uc220\uc0ac\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc790\uae0d\uc2ec \ub192\uc740 \ubd80\uc871\uc744 \uc774\ub8e8\uc5b4, \uc870\uc0c1\uacfc \uc815\ub839\ub4e4\uc744 \uc12c\uae30\uba70 \uc0b4\uc558\ub2e4. \uadf8\ub4e4\uc740 \ubca8\ub80c\uacfc \ud568\uaed8 \uc544\ub974\uac70\uc2a4\uc5d0\uc11c \ub2ec\uc544\ub09c \uc5d0\ub808\ub2e4\ub974, \uace7 \ub4dc\ub808\ub098\uc774\uc640 \ubd88\ud3b8\ud558\uac8c \uc138\uacc4\ub97c \ub098\ub204\uc5b4 \uc37c\ub2e4. \ud0ac\uc81c\ub374\uc740 \uc774 \ucd94\ubc29\uc790\ub4e4\uc744 \ucad3\ub294 \uc77c\uc744 \ud55c \ubc88\ub3c4 \uba48\ucd98 \uc801\uc774 \uc5c6\uc5c8\uace0, \uc624\ud06c\ub4e4\uc5d0\uac8c\uc11c \ubb34\uae30\ub97c \ubcf4\uc558\ub2e4.","\ub12c\uc974\uc758 \uc8fd\uc740 \uc544\ub0b4\uc758 \uc601\ud63c\uc73c\ub85c \ubcc0\uc7a5\ud55c \uc545\ub9c8 \uad70\uc8fc\ub294 \ub299\uc740 \uc8fc\uc220\uc0ac\uc5d0\uac8c \uc18d\uc0ad\uc5ec \uadf8\ub97c \ub4dc\ub808\ub098\uc774\uc5d0\uac8c \ub4f1\uc744 \ub3cc\ub9ac\uac8c \ud588\ub2e4. \ub12c\uc974\uc774 \ub9dd\uc124\uc774\uc790 \ud0ac\uc81c\ub374\uc740 \ub354 \uace0\ubd84\uace0\ubd84\ud55c \uc81c\uc790 \uad74\ub2e8\uc744 \ucc3e\uc544\ub0c8\ub2e4. \uad74\ub2e8\uc740 \ube44\ubc00 \uc870\uc9c1\uc778 \uc5b4\ub460\uc758 \uc758\ud68c\ub97c \uc138\uc6b0\uace0 \uc624\ud06c\ub4e4\uc5d0\uac8c \uc9c0\uc625 \ub9c8\ubc95\uc744 \uac00\ub974\ucce4\uc73c\ub2c8, \uadf8\ub4e4\uc774 \ucd5c\ucd08\uc758 \ud751\ub9c8\ubc95\uc0ac\uc600\ub2e4. \uc815\ub839\ub4e4\uc740 \uce68\ubb35\ud588\uace0, \uc624\ud06c\ub4e4\uc758 \ud478\ub978 \ub545\uc740 \uc8fd\uc5b4 \uac00\uae30 \uc2dc\uc791\ud588\ub2e4.","\ub300\uaddc\ubaa8 \uc9d1\ud68c\uc5d0\uc11c \ubd80\uc871\uc7a5\ub4e4\uc740 \uad6c\ub369\uc774 \uad70\uc8fc \ub9cc\ub178\ub85c\uc2a4\uc758 \ud53c\ub97c \ub9c8\uc168\uace0, \uc804\uc7c1\ub178\ub798 \ubd80\uc871\uc758 \uadf8\ub86c \ud5ec\uc2a4\ud06c\ub9bc\uc774 \uac00\uc7a5 \uba3c\uc800 \ub9c8\uc168\ub2e4. \uc545\ub9c8\uc758 \ubd84\ub178\ub85c \uac00\ub4dd \ucc2c \ud1b5\ud569 \ud638\ub4dc\ub294 \ub4dc\ub808\ub098\uc774\ub97c \ub36e\uccd0 \uac70\uc758 \ubab0\uc0b4\uc2dc\ucf30\ub2e4. \ub4c0\ub85c\ud0c4\uc758 \uc11c\ub9ac\ub291\ub300 \ubd80\uc871\ub9cc\uc774 \uc77c\ubd80\ub098\ub9c8 \uac70\ub9ac\ub97c \ub450\uc5c8\ub2e4. \ud559\uc0b4\uc774 \ub05d\ub098\uc790 \uad74\ub2e8\uc5d0\uac8c\ub294 \uc0c8\ub85c\uc6b4 \uc804\uc7c1\uc774 \ud544\uc694\ud588\uace0, \ud0ac\uc81c\ub374\uc758 \uc8fc\uc778\uc740 \uc774\ubbf8 \uc544\uc81c\ub85c\uc2a4\uc5d0 \ud558\ub098\ub97c \uc900\ube44\ud574 \ub450\uace0 \uc788\uc5c8\ub2e4."]},"chapter:the-first-war":{title:"\uc5b4\ub460\uc758 \ubb38\uacfc \uc81c1\ucc28 \ub300\uc804\uc7c1",summary:"\uba54\ub514\ube0c\ub294 \uc624\ud06c\ub4e4\uc774 \uc5b4\ub460\uc758 \ubb38\uc744 \uc5ec\ub294 \uac83\uc744 \ub3c4\uc654\uace0, \ud638\ub4dc\ub294 \uc2a4\ud1b0\uc708\ub4dc \uc655\uad6d\uc744 \ud729\uc4f8\uc5c8\ub2e4.",when:"0\ub144: \uc5b4\ub460\uc758 \ubb38\uc774 \uc5f4\ub9ac\ub2e4",body:["\ube59\uc758\ub41c \uba54\ub514\ube0c\uc758 \uc778\ub3c4\ub85c \uad74\ub2e8\uc758 \ud751\ub9c8\ubc95\uc0ac\ub4e4\uacfc \uc218\ud638\uc790\ub294 \ud6d7\ub0a0 \ub9d0\ub77c\ubd99\uc5b4 \uc800\uc8fc\ubc1b\uc740 \ub545\uc774 \ub418\ub294 \ub2aa, \uac80\uc740\ub2aa\uc5d0\uc11c \ub4dc\ub808\ub178\uc5b4\uc640 \uc544\uc81c\ub85c\uc2a4 \uc0ac\uc774\uc5d0 \uade0\uc5f4\uc744 \uc5f4\uc5c8\ub2e4. \uc624\ud06c\ub4e4\uc740 \uc5b4\ub460\uc758 \ubb38\uc73c\ub85c \uc54c\ub824\uc9c0\uac8c \ub41c \uadf8 \uade0\uc5f4\ub85c \uc3df\uc544\uc838 \ub4e4\uc5b4\uc654\uace0, \uadf8\ub4e4\uc758 \uc815\ucc30\ubcd1\uc740 \uace7 \uc624\ub298\ub0a0\uc758 \uc2a4\ud1b0\uc708\ub4dc\uc778 \uc544\uc81c\ub85c\uc2a4 \uc655\uad6d\uc758 \uae30\ub984\uc9c4 \ub4e4\ud310\uc744 \ucc3e\uc544\ub0c8\ub2e4.","\ub808\uc778 \ub9b0 \uad6d\uc655\uacfc \uadf8\uc758 \uc6a9\uc0ac \uc548\ub450\uc778 \ub85c\ud0c0\ub294 \uc5ec\ub7ec \ud574 \ub3d9\uc548 \ub9de\uc11c \uc2f8\uc6e0\ub2e4. \uba54\ub514\ube0c\uc758 \uc81c\uc790 \uce74\ub4dc\uac00\ub294 \uc2a4\uc2b9\uc758 \ubc30\uc2e0\uc744 \uc54c\uc544\ub0c8\uace0, \ub85c\ud0c0\uc640 \ud558\ud504\uc624\ud06c \uac00\ub85c\ub098\uc640 \ud568\uaed8 \uce74\ub77c\uc794\uc5d0\uc11c \uc218\ud638\uc790\uc640 \ub9de\uc11c \uadf8\ub97c \uc8fd\uc600\ub2e4. \uadf8\ub7ec\ub098 \uc2b9\ub9ac\ub294 \ub108\ubb34 \ub2a6\uac8c \ucc3e\uc544\uc654\ub2e4. \ud638\ub4dc\uc758 \uc804\ud22c\ubd80\ub300\ub294 \uc655\uad6d\uc744 \ubd88\ud0dc\uc6b0\uba70 \ub098\uc544\uac14\uace0, \ud638\ub4dc \uc548\uc5d0\uc11c\ub294 \uad50\ud65c\ud55c \uc624\uadf8\ub9bc \ub460\ud574\uba38\uac00 \uac80\uc740\uc190\uc744 \uc4f0\ub7ec\ub728\ub9ac\uace0 \ub300\uc871\uc7a5\uc774 \ub418\uc5c8\ub2e4.","\uad74\ub2e8\uc758 \uc8fc\ubb38\uc5d0 \ubb36\uc778 \uac00\ub85c\ub098\ub294 \ub808\uc778 \uad6d\uc655\uc744 \uc554\uc0b4\ud588\uace0, \uc2a4\ud1b0\uc708\ub4dc\ub294 \ud568\ub77d\ub418\uc5b4 \ubd88\ud0d4\ub2e4. \ub85c\ud0c0\ub294 \ub808\uc778\uc758 \uc5b4\ub9b0 \uc544\ub4e4 \ubc14\ub9ac\uc548\uc744 \ube44\ub86f\ud55c \uc0dd\uc874\uc790\ub4e4\uc744 \ubaa8\uc544 \ubc14\ub2e4 \uac74\ub108 \ub85c\ub370\ub860\uc73c\ub85c \uc774\ub04c\uc5c8\ub2e4. \uba40\ub9ac \ub3d9\ucabd, Forever\uc5d0\ub9cc \uc788\ub294 \uc9c0\uc5ed\uc778 Riverglades\uc5d0\uc11c\ub294 \ud638\ub4dc\uac00 Sunnyglade \ub9c8\uc744\uc744 \uc7bf\ub354\ubbf8\ub85c \ub9cc\ub4e4\uace0 \uc0dd\uc874\uc790\ub4e4\uc744 \ub178\uc608\ub85c \ub04c\uace0 \uac14\ub2e4."]},"chapter:the-second-war":{title:"\uc81c2\ucc28 \ub300\uc804\uc7c1",summary:"\uc778\uac04 \uc655\uad6d\ub4e4\uacfc \uc5d8\ud504, \ub4dc\uc6cc\ud504, \ub178\uc6c0\uc740 \ub85c\ub370\ub860 \uc5bc\ub77c\uc774\uc5b8\uc2a4\ub85c \ubb49\uccd0 \uac80\uc740\ubc14\uc704 \ucca8\ud0d1\uc5d0\uc11c \ub460\ud574\uba38\uc758 \ud638\ub4dc\ub97c \ubb34\ub108\ub728\ub838\ub2e4.",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 5~6\ub144 \ud6c4",body:["\ub85c\ud0c0\uc758 \uacbd\uace0\uc5d0 \ub85c\ub370\ub860\uc758 \ud14c\ub808\ub098\uc2a4 \uba54\ub124\uc2e4 \uad6d\uc655\uc740 \uc778\uac04 \uc655\uad6d\ub4e4\uc744 \ubd88\ub7ec \ubaa8\uc558\ub2e4. \uadf8\ub4e4\uc740 \ub85c\ud0c0\ub97c \ucd5c\uace0 \uc0ac\ub839\uad00\uc73c\ub85c \uc0bc\uc544 \ub85c\ub370\ub860 \uc5bc\ub77c\uc774\uc5b8\uc2a4\ub97c \uacb0\uc131\ud588\uace0, \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \ub4dc\uc6cc\ud504\uc640 \ub178\uc6c0, \uadf8\ub9ac\uace0 \uc544\ub77c\uc18c\ub974 \ud608\ud1b5\uc5d0 \ub300\ud55c \uc61b \ub9f9\uc138\ub97c \uc9c0\ud0a8 \ucfe0\uc5d8\ud0c8\ub77c\uc2a4\uc758 \ud558\uc774 \uc5d8\ud504\uac00 \ud569\ub958\ud588\ub2e4. \ubcd1\uc0ac\ub4e4\uc5d0\uac8c \ud76c\ub9dd\uc744 \uc8fc\uae30 \uc704\ud574 \ub300\uc8fc\uad50 \uc54c\ub860\uc11c\uc2a4 \ud30c\uc62c\uc740 \ucd5c\ucd08\uc758 \uc131\uae30\uc0ac\ub4e4\uc778 \ubc31\uc740\uc758 \uc190 \uae30\uc0ac\ub2e8\uc744 \ucc3d\uc124\ud588\uace0, \ube5b\uc758 \uc218\ud638\uc790 \uc6b0\uc11c\uac00 \uadf8 \uc120\ub450\uc5d0 \uc130\ub2e4.","\ub460\ud574\uba38\uc758 \ud638\ub4dc\ub3c4 \ucee4\uc838 \uc788\uc5c8\ub2e4. \uc624\uc6b0\uac70, \uc904\uc9c4\uc774 \uc774\ub044\ub294 \uc544\ub9c8\ub2c8 \ud2b8\ub864, \uace0\ube14\ub9b0 \uacf5\ubcd1\uc774 \uc624\ud06c\uc640 \ub098\ub780\ud788 \uc2f8\uc6e0\ub2e4. \uc6a9\uc544\uadc0 \ubd80\uc871\uc740 \ub370\uc2a4\uc719\uc758 \uc6a9\uc758 \uc601\ud63c\uc744 \uc774\uc6a9\ud574 \uadf8\ub9bc \ubc14\ud1a8\uc5d0\uc11c \ubd89\uc740 \uc6a9\ub4e4\uc744 \ub178\uc608\ub85c \uc0bc\uc558\uace0, \uad74\ub2e8\uc740 \ucd5c\ucd08\uc758 \uc8fd\uc74c\uc758 \uae30\uc0ac\ub4e4\uc744 \ub9cc\ub4e4\uc5b4 \ub0c8\ub2e4. \ud638\ub4dc\ub294 \uce74\uc988 \ubaa8\ub2e8\uc744 \ud729\uc4f8\uace0 \ucfe0\uc5d8\ud0c8\ub77c\uc2a4 \uc77c\ubd80\ub97c \ubd88\ud0dc\uc6e0\uc73c\uba70 \ub85c\ub370\ub860\uc758 \uc218\ub3c4\ub97c \ud3ec\uc704\ud588\ub2e4.","\uacb0\uc815\uc801\uc778 \uc21c\uac04\uc5d0 \uad74\ub2e8\uc740 \ub460\ud574\uba38\ub97c \ubc30\uc2e0\ud558\uace0 \uc0b4\uac8c\ub77c\uc2a4\uc758 \ubb34\ub364\uc744 \ub04c\uc5b4\uc62c\ub9ac\uae30 \uc704\ud574 \ubc14\ub2e4\ub85c \ub5a0\ub0ac\uc73c\uba70, Stormreaver \ubd80\uc871\uacfc \ud669\ud63c\uc758 \ub9dd\uce58 \ubd80\uc871\uc744 \ub370\ub9ac\uace0 \uac14\ub2e4. \uc57d\ud574\uc9c4 \ud638\ub4dc\ub294 \uac80\uc740\ubc14\uc704 \uc0b0\uc73c\ub85c \ubb3c\ub7ec\ub0ac\ub2e4. \uac80\uc740\ubc14\uc704 \ucca8\ud0d1 \uc804\ud22c\uc5d0\uc11c \ub460\ud574\uba38\ub294 \ub85c\ud0c0\ub97c \uc8fd\uc600\uc9c0\ub9cc, \ub85c\ud0c0\uc758 \ubd80\uad00 \ud22c\ub784\ub9ac\uc628\uc774 \ud638\ub4dc\ub97c \ubb34\ub108\ub728\ub838\uace0 \uce74\ub4dc\uac00\ub294 \uc5b4\ub460\uc758 \ubb38\uc744 \ud30c\uad34\ud588\ub2e4. \uc0b4\uc544\ub0a8\uc740 \uc624\ud06c\ub4e4\uc740 \uc218\uc6a9\uc18c\ub85c \ub04c\ub824\uac14\ub2e4. Forever\uc758 Riverglades\uc5d0\uc11c\ub294 \ubb34\ub364\uc5d0\uc11c \ub3c4\ub9dd\uce5c \ud669\ud63c\uc758 \ub9dd\uce58 \uc624\uc6b0\uac70\ub4e4\uacfc Stormreaver \uc624\ud06c\ub4e4\uc774 \uc0c8 \ubcf4\uae08\uc790\ub9ac\ub97c \ub9c8\ub828\ud588\ub2e4."]}}},1790,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters2",{enumerable:!0,get:function(){return t}});const t={"chapter:beyond-the-dark-portal":{title:"\uc5b4\ub460\uc758 \ubb38 \ub108\uba38",summary:"\ub12c\uc974\uc740 \ubb38\uc744 \ub2e4\uc2dc \uc5f4\uc5b4 \ub4dc\ub808\ub178\uc5b4\ub97c \uac08\uac00\ub9ac \ucc22\uc5c8\uace0, \ud0ac\uc81c\ub374\uc740 \ub299\uc740 \uc8fc\uc220\uc0ac\ub97c \ub9ac\uce58 \uc655\uc73c\ub85c \ub2e4\uc2dc \ube5a\uc5b4\ub0c8\ub2e4.",when:"\uc81c2\ucc28 \ub300\uc804\uc7c1 \uc9c1\ud6c4",body:["\uad74\ub2e8\uc774 \uc8fd\uace0 \ud638\ub4dc\uac00 \uac07\ud78c \ub4a4, \ub299\uc740 \ub12c\uc974\uc740 \ub4dc\ub808\ub178\uc5b4\uc5d0 \ub0a8\uc544 \uc788\ub358 \uc624\ud06c\ub4e4\uc744 \ubaa8\uc558\ub2e4. \uadf8\ub294 \uc5b4\ub460\uc758 \ubb38\uc744 \ub2e4\uc2dc \uc5f4\uace0 \uc544\uc81c\ub85c\uc2a4\ub85c \uc57d\ud0c8\ub300\ub97c \ubcf4\ub0b4 \uac15\ub825\ud55c \uc720\ubb3c\ub4e4\uc744 \ud6d4\uce58\uac8c \ud588\ub2e4. \uc790\uc2e0\uc758 \ubc31\uc131\uc774 \ub2ec\uc544\ub0a0 \uc218 \uc788\ub294 \uc0c8\ub85c\uc6b4 \uc138\uacc4\ub85c \uac00\ub294 \uad00\ubb38\uc744 \uc5f4\uae30 \uc704\ud574\uc11c\uc600\ub2e4.","\uc5bc\ub77c\uc774\uc5b8\uc2a4\ub294 \ud22c\ub784\ub9ac\uc628\uacfc \uce74\ub4dc\uac00\uac00 \uc774\ub044\ub294 \uc6d0\uc815\ub300\ub97c \ubb38 \ub108\uba38\ub85c \ubcf4\ub0b4 \ub9de\uc130\uace0, \uc21c\ucc30\uc790 \uc54c\ub808\ub9ac\uc544 \uc708\ub4dc\ub7ec\ub108, \ub4dc\uc6cc\ud504 \ucfe0\ub974\ub4dc\ub780 \uc640\uc77c\ub4dc\ud574\uba38, \uc804\uc0ac \ub2e4\ub098\uc2a4 \ud2b8\ub864\ubca0\uc778\uc774 \ud569\ub958\ud588\ub2e4. \uadf8\ub4e4\uc740 \ub4dc\ub808\ub178\uc5b4 \uc804\uc5ed\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \ud638\ub4dc\uc640 \uc2f8\uc6e0\uc9c0\ub9cc, \ub12c\uc974\uc758 \uad00\ubb38\ub4e4\uc740 \uc774\ubbf8 \uc138\uacc4\ub97c \ucc22\uc5b4 \ub193\uace0 \uc788\uc5c8\ub2e4. \uc544\uc81c\ub85c\uc2a4\ub97c \uad6c\ud558\uae30 \uc704\ud574 \uc6d0\uc815\ub300\ub294 \ubc18\ub300\ud3b8\uc5d0\uc11c \uc5b4\ub460\uc758 \ubb38\uc744 \ud30c\uad34\ud588\uace0, \ud6d7\ub0a0 \uc544\uc6c3\ub79c\ub4dc\uac00 \ub420 \ubd80\uc11c\uc9c4 \uc794\ud574 \uc18d\uc5d0 \uc2a4\uc2a4\ub85c \uac07\ud788\uace0 \ub9d0\uc558\ub2e4.","\ub12c\uc974\uc740 \uc790\uc2e0\uc774 \uc5f0 \uade0\uc5f4 \ud558\ub098\ub85c \ub2ec\uc544\ub0ac\uc9c0\ub9cc, \uace7\uc7a5 \ud0ac\uc81c\ub374\uc758 \uc190\uc544\uadc0\uc5d0 \ub5a8\uc5b4\uc84c\ub2e4. \uc545\ub9c8\ub294 \uadf8\uc758 \uc721\uc2e0\uc744 \ube7c\uc557\uace0 \uc601\ud63c\ub9cc \ub0a8\uaca8 \ub9c8\ubc95\uc774 \uae43\ub4e0 \uac11\uc637\uc5d0 \ubb36\uc740 \ub4a4, \ub8ec\uac80 \uc11c\ub9ac\ud55c\uacfc \ud568\uaed8 \uc5bc\uc74c\ub369\uc774 \uc18d\uc5d0 \ubd09\uc778\ud588\ub2e4. \ub178\uc2a4\ub80c\ub4dc\uc758 \uc5bc\uc5b4\ubd99\uc740 \ud669\ubb34\uc9c0\uc5d0 \ub0b4\ub358\uc838\uc9c4 \uc5bc\uc5b4\ubd99\uc740 \uc655\uc88c\ub294 \uc0c8\ub85c\uc6b4 \uad8c\ub825\uc758 \uc790\ub9ac\uac00 \ub418\uc5c8\ub2e4. \uc5b8\ub370\ub4dc\uc758 \uc5ed\ubcd1\uc744 \ud37c\ub728\ub824 \uad70\ub2e8\uc758 \uadc0\ud658\uc744 \uc704\ud574 \uc544\uc81c\ub85c\uc2a4\ub97c \uc57d\ud558\uac8c \ub9cc\ub4dc\ub294 \uc784\ubb34\ub97c \ub9e1\uc740 \ub9ac\uce58 \uc655\uc774\uc5c8\ub2e4."]},"chapter:thrall-and-the-new-horde":{title:"\uc2a4\ub784\uacfc \uc0c8\ub85c\uc6b4 \ud638\ub4dc",summary:"\ub178\uc608\ub85c \uae38\ub7ec\uc9c4 \uc624\ud06c\uac00 \ub358\ud640\ub4dc\uc5d0\uc11c \ud0c8\ucd9c\ud574 \uc8fc\uc220\uc744 \ub2e4\uc2dc \ucc3e\uc544\ub0c8\uace0, \uc790\uae30 \ubc31\uc131\uc744 \uc218\uc6a9\uc18c\uc5d0\uc11c \ud574\ubc29\uc2dc\ucf30\ub2e4.",when:"\uc81c3\ucc28 \ub300\uc804\uc7c1 \uc774\uc804\uc758 \uba87 \ud574",body:["\uc218\uc6a9\uc18c\uc758 \uc624\ud06c\ub4e4\uc740 \uc545\ub9c8\uc758 \ubd84\ub178\uac00 \ube60\uc838\ub098\uac00\uba74\uc11c \uc774\uc0c1\ud55c \ubb34\uae30\ub825\uc5d0 \ube60\uc838\ub4e4\uc5c8\ub2e4. \ud790\uc2a4\ube0c\ub798\ub4dc \uad6c\ub989\uc9c0\uc5d0 \uc788\ub294 \ub358\ud640\ub4dc \uc694\uc0c8\uc758 \uc5d0\ub378\ub77c\uc2a4 \ube14\ub799\ubb34\uc5b4 \uacbd\uc740 \uc5ec\ub7ec \ud574 \uc804\uc5d0 \uace0\uc544\uac00 \ub41c \uc624\ud06c \uc544\uae30\ub97c \ubc1c\uacac\ud574 \uac80\ud22c\uc0ac\uc774\uc790 \uc7a5\ucc28 \uc4f8 \ubb34\uae30\ub85c \uae38\ub800\ub2e4. \uadf8\ub294 \uc544\uc774\uc5d0\uac8c \ub178\uc608\ub97c \ub73b\ud558\ub294 \ub9d0\uc778 \uc2a4\ub784\uc774\ub77c\ub294 \uc774\ub984\uc744 \ubd99\uc600\ub2e4. \ud558\ub140 \ud0c0\ub808\uc0ac \ud3ed\uc2a4\ud134\ub9cc\uc774 \uadf8\ub97c \uce5c\uc808\ud558\uac8c \ub300\ud588\uace0, \uadf8\ub140\uc758 \ub3c4\uc6c0\uc73c\ub85c \uc2a4\ub784\uc740 \ub9c8\uce68\ub0b4 \ud0c8\ucd9c\ud588\ub2e4.","\ucc98\uc74c\uc73c\ub85c \uc790\uc720\ub97c \uc5bb\uc740 \uc2a4\ub784\uc740 \uc790\uae30 \uc885\uc871\uc758 \uc804\uc124\uc744 \ucc3e\uc544 \ub098\uc130\ub2e4. \uadf8\ub86c \ud5ec\uc2a4\ud06c\ub9bc\uc740 \uc624\ud06c\uac00 \uc5b4\ub5a4 \uc874\uc7ac\uc77c \uc218 \uc788\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\uc5c8\uace0, \ub299\uc740 \uc624\uadf8\ub9bc \ub460\ud574\uba38\ub294 \uadf8\ub97c \ubd80\uad00\uc73c\ub85c \uc0bc\uc558\uc73c\uba70, \uc54c\ud130\ub799 \uc0b0\ub9e5\uc758 \uc11c\ub9ac\ub291\ub300 \ubd80\uc871\uc5d0\uc11c\ub294 \uc8fc\uc220\uc0ac \ub4dc\ub809\ud0c0\ub974\uac00 \uc815\ub839\uacfc \ub300\ud654\ud558\ub294 \ubc95\uc744 \uac00\ub974\ucce4\ub2e4. \uadf8\uacf3\uc5d0\uc11c \uadf8\ub294 \uc790\uc2e0\uc774 \uc11c\ub9ac\ub291\ub300 \uc871\uc7a5 \ub4c0\ub85c\ud0c4\uc758 \uc544\ub4e4\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc54c\uac8c \ub418\uc5c8\ub2e4.","\uc2a4\ub784\uacfc \uadf8\ub86c\uacfc \ub460\ud574\uba38\ub294 \uc218\uc6a9\uc18c\ub97c \ud558\ub098\uc529 \ud574\ubc29\uc2dc\ucf30\ub2e4. \ub460\ud574\uba38\ub294 \uc804\ud22c\uc5d0\uc11c \uc4f0\ub7ec\uc9c0\uba70 \uc790\uc2e0\uc758 \uac80\uc740 \uac11\uc637\uacfc \ub9dd\uce58\ub97c \uc2a4\ub784\uc5d0\uac8c \ub118\uacbc\uace0, \uc2a4\ub784\uc740 \uc545\ub9c8\uc758 \ud53c\uac00 \uc544\ub2cc \uba85\uc608\uc640 \uc8fc\uc220 \uc704\uc5d0 \uc138\uc6b4 \uc0c8\ub85c\uc6b4 \ud638\ub4dc\uc758 \ub300\uc871\uc7a5\uc774 \ub418\uc5c8\ub2e4. \ub358\ud640\ub4dc\uc5d0\uc11c \uadf8\ub294 \ube14\ub799\ubb34\uc5b4\ub97c \ubb3c\ub9ac\ucce4\uc9c0\ub9cc, \ud0c0\ub808\uc0ac\ub294 \uc0b4\uc544\ub0a8\uc9c0 \ubabb\ud588\ub2e4. \uc774\uc81c \uc2a4\ub784\uc774 \ubc14\ub77c\ub294 \uac83\uc740 \ubc31\uc131\uc774 \ud3c9\ud654\ub86d\uac8c \uc0b4 \uc218 \uc788\ub294 \uace0\ud5a5\ubfd0\uc774\uc5c8\ub2e4."]},"chapter:the-lich-king-and-the-plague":{title:"\ub9ac\uce58 \uc655\uacfc \uc5ed\ubcd1",summary:"\ub178\uc2a4\ub80c\ub4dc\uc758 \ub9ac\uce58 \uc655\uc740 \ub0a8\ucabd\uc73c\ub85c \uc190\uc744 \ubed7\uc5c8\uace0, \ub300\ub9c8\ubc95\uc0ac \ucf08\ud22c\uc790\ub4dc\ub294 \ub85c\ub370\ub860\uc758 \uace1\ubb3c\uc744 \ud1b5\ud574 \uc5b8\ub370\ub4dc\uc758 \uc5ed\ubcd1\uc744 \ud37c\ub728\ub838\ub2e4.",when:"\uc81c3\ucc28 \ub300\uc804\uc7c1\uc758 \uc11c\ub9c9",body:["\uc5bc\uc5b4\ubd99\uc740 \uc655\uc88c\uc5d0 \uac07\ud600 \uc788\uc73c\uba74\uc11c\ub3c4 \ub9ac\uce58 \uc655\uc758 \uc815\uc2e0\uc740 \ub178\uc2a4\ub80c\ub4dc \uc804\uc5ed\uc5d0 \ubbf8\ucce4\ub2e4. \uadf8\ub294 \uac70\ubbf8 \uc655\uad6d \uc544\uc878\ub124\ub8f9\uc744 \uc815\ubcf5\ud574 \uadf8 \ubc31\uc131\uc744 \ud558\uc218\uc778\uc73c\ub85c \uc77c\uc73c\ucf30\uace0, \uc5bc\uc74c\uc655\uad00\uc5d0 \uc788\ub294 \uc790\uc2e0\uc758 \uc655\uc88c \uc8fc\uc704\uc5d0 \uc694\uc0c8\ub97c \uc313\uc558\ub2e4. \uadf8\ub7f0 \ub2e4\uc74c \uadf8\ub294 \uc804\uc7c1\uc5d0 \uc9c0\uce5c \ub0a8\ucabd\uc758 \uc778\uac04 \uc655\uad6d\ub4e4\ub85c \ub208\uc744 \ub3cc\ub838\ub2e4.","\ub2ec\ub77c\ub780\uc5d0\uc11c\ub294 \uc874\uacbd\ubc1b\ub358 \ub300\ub9c8\ubc95\uc0ac \ucf08\ud22c\uc790\ub4dc\uac00 \uac15\ub839\uc220\uc5d0 \uc0ac\ub85c\uc7a1\ud600 \uc788\uc5c8\ub2e4. \ud0a4\ub9b0 \ud1a0\uac00 \uadf8\uc758 \uc5f0\uad6c\ub97c \uac70\ubd80\ud558\uc790 \uadf8\ub294 \ub9ac\uce58 \uc655\uc758 \ubd80\ub984\uc5d0 \uc751\ud574 \ub178\uc2a4\ub80c\ub4dc\ub85c \uac14\ub2e4\uac00 \uadf8\uc758 \uc608\uc5b8\uc790\uac00 \ub418\uc5b4 \ub3cc\uc544\uc654\ub2e4. \uadf8\ub294 \ub85c\ub370\ub860\uc758 \uac00\ub09c\ud55c \uc774\ub4e4\uc5d0\uac8c \ud3c9\ub4f1\uacfc \uc601\uc0dd\uc744 \uc57d\uc18d\ud558\ub294 \uc800\uc8fc\ubc1b\uc740 \uc790\uc758 \uad50\ub2e8\uc744 \uc138\uc6e0\uace0, \uadf8 \uc2e0\ub3c4\ub4e4\uc744 \uc774\uc6a9\ud574 \uace1\ubb3c \uc218\uc1a1\ud488\uc5d0 \uc228\uae34 \uc5ed\ubcd1\uc744 \ud37c\ub728\ub838\ub2e4.","\uc5ed\ubcd1\uc740 \ud76c\uc0dd\uc790\ub97c \uc8fd\uc778 \ub4a4 \uc0dd\uac01 \uc5c6\ub294 \uc5b8\ub370\ub4dc, \uace7 \uc2a4\uceec\uc9c0\ub85c \ub418\uc0b4\ub824 \ub0c8\ub2e4. \uc655\uad6d\ub4e4\uc774 \uc138\uae08\uacfc \uc218\uc6a9\uc18c \ube44\uc6a9\uc744 \ub450\uace0 \ub2e4\ud22c\ub294 \uc0ac\uc774, \ub85c\ub370\ub860 \ubd81\ubd80\uc758 \ub9c8\uc744\ub4e4\uc774 \ucc28\ub840\ub85c \ubb34\ub108\uc84c\ub2e4. \ud0a4\ub9b0 \ud1a0\uc640 \ubc31\uc740\uc758 \uc190\uc774 \uc704\ud5d8\uc744 \uae68\ub2ec\uc558\uc744 \ub54c\ub294 \uc774\ubbf8 \uc5ed\ubcd1\uc774 \ub85c\ub370\ub860\uc758 \ubd81\ubd80 \uc9c0\ubc29 \uc804\uc5ed\uc5d0 \ud37c\uc9c4 \ub4a4\uc600\ub2e4. \ubd88\ud0c0\ub294 \uad70\ub2e8\uc758 \uacf5\ud3ec\uc758 \uad70\uc8fc\ub4e4\uc774 \ub9ac\uce58 \uc655\uc758 \uc77c\uc744 \uc9c0\ucf1c\ubcf4\uace0 \uc788\uc5c8\ub2e4. \uadf8 \uc77c\uc740 \uadf8\ub4e4\uc758 \uc8fc\uc778\uc774 \ub3cc\uc544\uc62c \uae38\uc744 \ub2e6\uae30 \uc704\ud55c \uac83\uc774\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4."]},"chapter:fall-of-lordaeron":{title:"\ub85c\ub370\ub860\uc758 \ubab0\ub77d",summary:"\uc544\uc11c\uc2a4 \uc655\uc790\ub294 \uc5ed\ubcd1\uc758 \uadfc\uc6d0\uc744 \ucd94\uc801\ud574 \uc11c\ub9ac\ud55c\uc744 \uc190\uc5d0 \ub123\uc5c8\uace0, \ub3cc\uc544\uc640 \uc790\uc2e0\uc758 \uc655\uad6d\uacfc \ucfe0\uc5d8\ud0c8\ub77c\uc2a4, \ub2ec\ub77c\ub780\uc744 \ud30c\uad34\ud588\ub2e4.",when:"\uc81c3\ucc28 \ub300\uc804\uc7c1, \uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uc57d 20\ub144 \ud6c4",body:["\ubc31\uc740\uc758 \uc190\uc758 \uc80a\uc740 \uc131\uae30\uc0ac \uc544\uc11c\uc2a4 \uba54\ub124\uc2e4 \uc655\uc790\ub294 \ub9c8\ubc95\uc0ac \uc81c\uc774\ub098 \ud504\ub77c\uc6b0\ub4dc\ubb34\uc5b4\uc640 \ud568\uaed8 \uc5ed\ubcd1\uc744 \ub9c9\uc73c\ub7ec \ub098\uc130\ub2e4. \uc2a4\ud2b8\ub77c\uc194\ub984\uc5d0\uc11c \uadf8\ub294 \ub3c4\uc2dc\uc758 \uace1\ubb3c\uc774 \uc774\ubbf8 \uc624\uc5fc\ub418\uc5c8\ub2e4\ub294 \uac83\uc744 \uc54c\uace0, \uc8fc\ubbfc\ub4e4\uc774 \uc5b8\ub370\ub4dc\ub85c \uc77c\uc5b4\ub098\uae30 \uc804\uc5d0 \ubaa8\ub450 \uc8fd\uc774\ub77c\uace0 \uba85\ub839\ud588\ub2e4. \uc6b0\uc11c\uc640 \uc81c\uc774\ub098\ub294 \uadf8\ub97c \ub530\ub974\uae30\ub97c \uac70\ubd80\ud588\ub2e4. \uc544\uc11c\uc2a4\ub294 \uacf5\ud3ec\uc758 \uad70\uc8fc \ub9d0\uac00\ub2c8\uc2a4\ub97c \ucad3\uc544 \ub178\uc2a4\ub80c\ub4dc\uae4c\uc9c0 \uac14\uace0, \ubd80\ud558\ub4e4\uc774 \ub5a0\ub098\uc9c0 \ubabb\ud558\ub3c4\ub85d \uc790\uae30 \ubc30\ub97c \ubd88\ud0dc\uc6b4 \ub4a4 \ub8ec\uac80 \uc11c\ub9ac\ud55c\uc744 \uc190\uc5d0 \ub123\uc5c8\ub2e4. \uadf8 \uac80\uc740 \uadf8\uc758 \uc601\ud63c\uc744 \uc557\uc544 \uac14\ub2e4.","\uc544\uc11c\uc2a4\ub294 \ub9ac\uce58 \uc655\uc758 \uc8fd\uc74c\uc758 \uae30\uc0ac\uac00 \ub418\uc5b4 \ub3cc\uc544\uc640 \uc544\ubc84\uc9c0 \ud14c\ub808\ub098\uc2a4 \uad6d\uc655\uc744 \uadf8\uc758 \uc655\uc88c\uc758 \ubc29\uc5d0\uc11c \uc0b4\ud574\ud588\ub2e4. \uc2a4\uceec\uc9c0\uac00 \ub85c\ub370\ub860\uc744 \ud729\uc4f8\uc5c8\ub2e4. \uc6b0\uc11c\ub294 \ud14c\ub808\ub098\uc2a4\uc758 \uc720\uace8\uc744 \ub2f4\uc740 \uc720\uace8\ud568\uc744 \uc9c0\ud0a4\ub2e4 \uc4f0\ub7ec\uc84c\uace0, \uc544\uc11c\uc2a4\ub294 \uad70\ub300\ub97c \uc774\ub04c\uace0 \ucfe0\uc5d8\ud0c8\ub77c\uc2a4\ub85c \ub4e4\uc5b4\uac00 \uc5d8\ud504\uc758 \ubc29\uc5b4\ub97c \ubb34\ub108\ub728\ub9b0 \ub4a4 \ud0dc\uc591\uc0d8\uc744 \uc774\uc6a9\ud574 \ucf08\ud22c\uc790\ub4dc\ub97c \ub9ac\uce58\ub85c \ub418\uc0b4\ub838\ub2e4. \uc2e4\ubc84\ubb38\uc758 \uc21c\ucc30\ub300\uc7a5\uad70 \uc2e4\ubc14\ub098\uc2a4 \uc708\ub4dc\ub7ec\ub108\ub294 \uadf8\uc640 \uc2f8\uc6b0\ub2e4 \uc8fd\uc5c8\uace0, \ubc34\uc2dc\ub85c \ub418\uc0b4\uc544\ub0ac\ub2e4.","\uc774\uc5b4 \ucf08\ud22c\uc790\ub4dc\ub294 \ub2ec\ub77c\ub780\uc5d0\uc11c \uc545\ub9c8 \uad70\uc8fc \uc544\ud0a4\ubaac\ub4dc\ub97c \uc18c\ud658\ud588\uace0, \ubd88\ud0c0\ub294 \uad70\ub2e8\uc774 \uc544\uc81c\ub85c\uc2a4\ub85c \ub3cc\uc544\uc654\ub2e4. \ub2ec\ub77c\ub780\uc740 \uc0b0\uc0b0\uc870\uac01 \ub0ac\uace0, \uac00\uc7a5 \uc704\ub300\ud55c \uc778\uac04 \uc655\uad6d\uc774\ub358 \ub85c\ub370\ub860\uc740 \uc0ac\ub77c\uc84c\ub2e4. \ubd81\ubd80\uc5d0\ub294 \ud769\uc5b4\uc9c4 \uc0dd\uc874\uc790\uc640 \ud53c\ub09c\ubbfc, \uad11\uc2e0\ub3c4\ub9cc\uc774 \ub0a8\uc558\uace0, \ub545\uc740 \uc544\uc11c\uc2a4\uc758 \uc5b8\ub370\ub4dc\uac00 \ucc28\uc9c0\ud588\ub2e4."]},"chapter:battle-for-mount-hyjal":{title:"\ud558\uc774\uc798 \uc0b0 \uc804\ud22c",summary:"\uc608\uc5b8\uc790\uc758 \uacbd\uace0\ub97c \ubc1b\uc740 \uc624\ud06c\uc640 \uc778\uac04\uc740 \uce7c\ub9bc\ub3c4\uc5b4\ub85c \ud56d\ud574\ud574, \ub098\uc774\ud2b8 \uc5d8\ud504\uc640 \ud798\uc744 \ud569\uccd0 \uc138\uacc4\uc218 \uc55e\uc5d0\uc11c \uc544\ud0a4\ubaac\ub4dc\ub97c \ub9c9\uc544 \ub0c8\ub2e4.",when:"\uc81c3\ucc28 \ub300\uc804\uc7c1\uc758 \ub05d",body:["\uc8fd\uc74c\uc5d0\uc11c \ub3cc\uc544\uc628 \uba54\ub514\ube0c, \uace7 \uc218\uc218\uaed8\ub07c\uc758 \uc608\uc5b8\uc790\uac00 \uc2a4\ub784\uacfc \uc81c\uc774\ub098\uc5d0\uac8c \uc11c\ucabd \uce7c\ub9bc\ub3c4\uc5b4\ub85c \ud56d\ud574\ud558\ub77c\uace0 \uc7ac\ucd09\ud588\ub2e4. \uc2a4\ub784\uc758 \ud638\ub4dc\ub294 \uadf8 \ud574\uc548\uc5d0 \uc0c1\ub959\ud574 \ucf00\ub978 \ube14\ub7ec\ub4dc\ud6c4\ud504\uc758 \ud0c0\uc6b0\ub80c\uacfc \uce5c\uad6c\uac00 \ub418\uc5c8\uace0 \ubd88\ubaa8\uc758 \ub545\uc744 \uac00\ub85c\uc9c8\ub7ec \uc2f8\uc6cc \ub098\uac14\uc73c\uba70, \uc81c\uc774\ub098\ub294 \ub85c\ub370\ub860\uc758 \ud53c\ub09c\ubbfc\ub4e4\uc744 \uac19\uc740 \ub300\ub959\uc73c\ub85c \uc774\ub04c\uc5c8\ub2e4. \uc7bf\ube5b \uace8\uc9dc\uae30\uc758 \uc232\uc5d0\uc11c \uadf8\ub86c \ud5ec\uc2a4\ud06c\ub9bc\uacfc \uc804\uc7c1\ub178\ub798 \ubd80\uc871\uc740 \ub2e4\uc2dc \uc545\ub9c8\uc758 \ud53c\ub97c \ub9c8\uc2dc\uace0 \ubc18\uc2e0 \uc138\ub098\ub9ac\uc6b0\uc2a4\ub97c \uc8fd\uc600\ub2e4.","\uc2a4\ub784\uacfc \uc81c\uc774\ub098\ub294 \ucc98\uc74c\uc73c\ub85c \ud798\uc744 \ud569\uccd0 \uadf8\ub86c\uc744 \uad6c\ud588\ub2e4. \ub9c8\uc9c0\ub9c9 \uacb0\ud22c\uc5d0\uc11c \uadf8\ub86c\uc740 \ub9cc\ub178\ub85c\uc2a4\ub97c \uc4f0\ub7ec\ub728\ub838\uace0, \uc790\uae30 \ubaa9\uc228\uc744 \ub300\uac00\ub85c \uc624\ud06c\ub4e4\uc744 \ud53c\uc758 \uc800\uc8fc\uc5d0\uc11c \ud480\uc5b4 \uc8fc\uc5c8\ub2e4. \uadf8\uc0ac\uc774 \ud2f0\ub780\ub370 \uc704\uc2a4\ud37c\uc708\ub4dc\ub294 \ub4dc\ub8e8\uc774\ub4dc\ub4e4\uc744 \uae68\uc6b0\uace0, \uc77c\ub9ac\ub2e8\uc758 \ud798\uc774 \ub3c4\uc6c0\uc774 \ub418\ub9ac\ub77c \uae30\ub300\ud558\uba70 \uadf8\ub97c Barrow Deeps\uc5d0\uc11c \ud480\uc5b4 \uc8fc\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \uadf8\ub294 \uad74\ub2e8\uc758 \ud574\uace8\uc744 \uc9d1\uc5b4\uc0bc\ucf1c \ubc18\ucbe4 \uc545\ub9c8\uac00 \ub418\uc5c8\uace0, \uce5c\ud615\uc5d0\uac8c \ucd94\ubc29\ub2f9\ud588\ub2e4.","\uc544\ud0a4\ubaac\ub4dc\ub294 \ub180\ub4dc\ub78f\uc2e4\uc758 \ud798\uc744 \ube68\uc544\ub4e4\uc774\ub824 \uc9c4\uad70\ud588\ub2e4. \ub098\uc774\ud2b8 \uc5d8\ud504\uc640 \uc778\uac04\uacfc \uc624\ud06c\uac00 \ud568\uaed8 \ud558\uc774\uc798 \uc0b0\uc758 \ube44\ud0c8\uc744 \uc9c0\ud0a4\uba70 \uc2dc\uac04\uc744 \ubc8c\uc5c8\uace0, \uadf8\ub3d9\uc548 \ub9d0\ud4e8\ub9ac\uc628\uc774 \ud568\uc815\uc744 \uc900\ube44\ud588\ub2e4. \uc545\ub9c8\uac00 \ub098\ubb34\uc5d0 \ub2e4\ub2e4\ub974\uc790 \uc218\ucc9c\uc758 \uc704\uc2b5\uc774 \uadf8\uc5d0\uac8c \ubab0\ub824\ub4e4\uc5c8\uace0, \ub180\ub4dc\ub78f\uc2e4\uc758 \ud798\uc774 \uadf8\ub97c \uac08\uac00\ub9ac \ucc22\uc5c8\ub2e4. \uad70\ub2e8\uc758 \uad70\ub300\ub294 \ubb34\ub108\uc84c\uc9c0\ub9cc \uc138\uacc4\uc218\ub294 \ud06c\uac8c \uc0c1\ucc98 \uc785\uc5c8\uace0, \ub098\uc774\ud2b8 \uc5d8\ud504\ub294 \uc138\uacc4\uc218\uac00 \ub0b4\ub824 \uc900 \ubd88\uba78\uc744 \uc783\uc5c8\ub2e4."]},"chapter:rise-of-the-forsaken":{title:"\ud3ec\uc138\uc774\ud070\uc758 \ubd09\uae30",summary:"\ub9ac\uce58 \uc655\uc774 \uc57d\ud574\uc9c0\uc790 \uc2e4\ubc14\ub098\uc2a4 \uc708\ub4dc\ub7ec\ub108\ub294 \ub2e4\ub978 \uc5b8\ub370\ub4dc\uc640 \ud568\uaed8 \uc18d\ubc15\uc5d0\uc11c \ubc97\uc5b4\ub098 \ud3ec\uc138\uc774\ud070\uc73c\ub85c\uc11c \ub85c\ub370\ub860\uc758 \ud3d0\ud5c8\ub97c \ucc28\uc9c0\ud588\ub2e4.",when:"\uc81c3\ucc28 \ub300\uc804\uc7c1 \uc9c1\ud6c4",body:["\uc544\ud0a4\ubaac\ub4dc\uac00 \uc4f0\ub7ec\uc9c4 \ub4a4 \ub9ac\uce58 \uc655\uc758 \uc7a5\uc545\ub825\uc740 \ud754\ub4e4\ub9ac\uae30 \uc2dc\uc791\ud588\ub2e4. \uc774\uc81c \ud0ac\uc81c\ub374\uc744 \uc12c\uae30\uac8c \ub41c \uc77c\ub9ac\ub2e8\uc774 \uc5bc\uc5b4\ubd99\uc740 \uc655\uc88c\ub97c \uacf5\uaca9\ud558\uc790, \uc544\uc11c\uc2a4\ub294 \uc8fc\uc778\uc744 \uc9c0\ud0a4\ub7ec \ubd81\ucabd\uc73c\ub85c \ub2ec\ub824\uac14\ub2e4. \ub85c\ub370\ub860\uc5d0\uc11c\ub294 \uacf5\ud3ec\uc758 \uad70\uc8fc\ub4e4\uc774 \uc2a4\uceec\uc9c0\ub97c \ucc28\uc9c0\ud558\ub824 \ud588\uace0, \uadf8 \ud63c\ub780 \uc18d\uc5d0\uc11c \ub9ce\uc740 \uc5b8\ub370\ub4dc\uac00 \uc790\uc720 \uc758\uc9c0\ub97c \ub418\ucc3e\uc558\ub2e4.","\uc2e4\ubc14\ub098\uc2a4 \uc708\ub4dc\ub7ec\ub108\uac00 \uadf8 \uccab \ubc88\uc9f8\uc600\ub2e4. \uadf8\ub140\ub294 \ubc34\uc2dc\ub4e4\uacfc \ub2e4\ub978 \uc790\uc720\ub85c\uc6b4 \uc5b8\ub370\ub4dc, \uadf8\ub9ac\uace0 \uc5b5\uc9c0\ub85c \ubd80\ub9ac\uac8c \ub41c \uacf5\ud3ec\uc758 \uad70\uc8fc \ubc14\ub9ac\ub9c8\ud2b8\ub77c\uc2a4\uc640 \ud568\uaed8 \uacbd\uc7c1\uc790\ub4e4\uc744 \ubb3c\ub9ac\uce58\uace0 \ub85c\ub370\ub860\uc758 \ud3d0\ud5c8\uac00 \ub41c \uc218\ub3c4\ub97c \ucc28\uc9c0\ud588\ub2e4. \uadf8 \uc544\ub798\uc5d0\ub294 \uc61b \uc655\uc2e4 \ubb18\uc9c0\uc640 \ud558\uc218\ub3c4\uac00 \uc788\uc5c8\uace0, \uadf8\uacf3\uc774 \uc5b8\ub354\uc2dc\ud2f0\uac00 \ub418\uc5c8\ub2e4. \uadf8\ub140\uc758 \ubc31\uc131\uc740 \uc2a4\uc2a4\ub85c\ub97c \ud3ec\uc138\uc774\ud070\uc774\ub77c \ubd88\ub800\ub2e4. \ub354\ub294 \uc778\uac04\uc774 \uc544\ub2c8\uace0, \uc0b0 \uc790\ub4e4\uc5d0\uac8c \ubc84\ub9bc\ubc1b\uc558\uc73c\uba70, \ub9ac\uce58 \uc655\uc5d0\uac8c\uc11c \uc790\uc720\ub85c\uc6b4 \uc774\ub4e4\uc774\ub77c\ub294 \ub73b\uc774\uc5c8\ub2e4.","\uc544\uc11c\uc2a4\ub294 \uc5bc\uc74c\uc655\uad00\uc5d0 \uc774\ub974\ub7ec \ub9ac\uce58 \uc655\uc758 \ud22c\uad6c\ub97c \uc4f0\uace0 \uc5bc\uc5b4\ubd99\uc740 \uc655\uc88c \uc704\uc5d0\uc11c \uadf8\uc640 \ud558\ub098\uac00 \ub418\uc5c8\uc73c\uba70, \uc774\ud6c4 \uc5bc\uc74c \ub4a4\uc5d0\uc11c \uce68\ubb35\ud588\ub2e4. \uc801\ub4e4\uc5d0\uac8c \ub458\ub7ec\uc2f8\uc778 \ud3ec\uc138\uc774\ud070\uc740 \ubd88\uc548\ud55c \ub3d9\ub9f9\uc73c\ub85c\uc11c \uc2a4\ub784\uc758 \ud638\ub4dc\uc5d0 \ud569\ub958\ud588\uace0, \uc2a4\uceec\uc9c0\uc640 \ubd89\uc740\uc2ed\uc790\uad70, \ub85c\ub370\ub860 \uadc0\uc871\uc758 \ub0a8\uc740 \uc138\ub825\uc740 \uc5ed\ubcd1\uc9c0\ub300\ub97c \ub450\uace0 \uc2f8\uc6e0\ub2e4. Forever\uc758 \uc774\uc57c\uae30\ub294 \uc6cc\ud06c\ub798\ud504\ud2b8 III: \ub9ac\ud3ec\uc9c0\ub4dc\uc758 'Forsaken Kingdom' \ucea0\ud398\uc778 \uc774\ud6c4\uc5d0 \uc774\uc5b4\uc9c0\uba70, \uc774 \uc548\ub0b4\uc11c\ub294 \uadf8 \ucea0\ud398\uc778\uc758 \uc0ac\uac74\uc744 \uc544\uc9c1 \ub2e4\ub8e8\uc9c0 \uc54a\ub294\ub2e4."],unknowns:["Forever\uac00 \uc774\uc5b4\ubc1b\ub294 \uc6cc\ud06c\ub798\ud504\ud2b8 III: \ub9ac\ud3ec\uc9c0\ub4dc\uc758 'Forsaken Kingdom' \ucea0\ud398\uc778\uc5d0\uc11c \uc5b4\ub5a4 \uc77c\uc774 \uc77c\uc5b4\ub098\ub294\uc9c0\ub294 \uc774 \uc548\ub0b4\uc11c\uac00 \uc4f0\ub294 \uc790\ub8cc\uc5d0 \ub098\uc624\uc9c0 \uc54a\ub294\ub2e4."]},"chapter:durotar-and-theramore":{title:"\ub4c0\ub85c\ud0c0\uc640 \ud14c\ub77c\ubaa8\uc5b4",summary:"\uc2a4\ub784\uc740 \ub4c0\ub85c\ud0c0\uc640 \uc624\uadf8\ub9ac\ub9c8\ub97c \uc138\uc6b0\uace0 \uc81c\uc774\ub098\ub294 \ud14c\ub77c\ubaa8\uc5b4\ub97c \uc138\uc6e0\uc73c\uba70, \ub450 \uc9c0\ub3c4\uc790\ub294 \uc81c\uc774\ub098\uc758 \uc544\ubc84\uc9c0\uac00 \uc804\uc7c1\uc744 \ud558\ub7ec \uc654\uc744 \ub54c\uc870\ucc28 \uc704\ud0dc\ub85c\uc6b4 \ud3c9\ud654\ub97c \uc9c0\ucf30\ub2e4.",when:"\uc81c3\ucc28 \ub300\uc804\uc7c1 \uc774\ud6c4\uc758 \uba87 \ud574",body:["\ud558\uc774\uc798 \uc774\ud6c4 \uc2a4\ub784\uc740 \uc624\ud06c\ub4e4\uc744 \uce7c\ub9bc\ub3c4\uc5b4 \ub3d9\ucabd \ud574\uc548\uc758 \uac70\uce5c \ubd89\uc740 \ub545\uc73c\ub85c \uc774\ub04c\uace0, \uc544\ubc84\uc9c0\uc758 \uc774\ub984\uc744 \ub530 \uadf8\uacf3\uc744 \ub4c0\ub85c\ud0c0\ub77c \ubd88\ub800\ub2e4. \uc218\ub3c4 \uc624\uadf8\ub9ac\ub9c8\ub294 \uc624\uadf8\ub9bc \ub460\ud574\uba38\ub97c \uae30\ub9ac\ub294 \uc774\ub984\uc774\uc5c8\ub2e4. \ucf00\ub978 \ube14\ub7ec\ub4dc\ud6c4\ud504\uc758 \ud0c0\uc6b0\ub80c\uc740 \uc36c\ub354 \ube14\ub7ec\ud504\uc758 \uace0\uc6d0 \uc8fc\ubcc0 \uba40\uace0\uc5b4 \ucd08\uc6d0\uc5d0 \uc790\ub9ac \uc7a1\uc558\uace0, \uc2a4\ub784\uc774 \uc11c\ucabd\uc73c\ub85c \ud56d\ud574\ud558\ub358 \uc911 \uad6c\ud574 \uc900 \ubcfc\uc9c4\uc758 \uac80\uc740\ucc3d \ud2b8\ub864\ub4e4\uc740 \ub4c0\ub85c\ud0c0 \uc55e\ubc14\ub2e4\uc758 \uba54\uc544\ub9ac \uc12c\uc5d0 \ud130\uc804\uc744 \uc7a1\uc558\ub2e4.","\uc81c\uc774\ub098 \ud504\ub77c\uc6b0\ub4dc\ubb34\uc5b4\ub294 \ub85c\ub370\ub860\uc5d0\uc11c \ub370\ub824\uc628 \uc778\uac04 \uc0dd\uc874\uc790\ub4e4\uc744 \uc704\ud574 \uba3c\uc9c0\uc9c4\ud759 \uc2b5\uc9c0\ub300\uc758 \ud55c \uc12c\uc5d0 \ud14c\ub77c\ubaa8\uc5b4\ub97c \uc138\uc6e0\ub2e4. \uadf8\ub140\uc640 \uc2a4\ub784\uc740 \ud558\uc774\uc798\uc5d0\uc11c \ud568\uaed8 \uc2f8\uc6e0\uace0, \ud3c9\ud654\ub97c \uc9c0\ud0a4\uae30\ub85c \uc57d\uc18d\ud588\ub2e4. \uadf8 \ud3c9\ud654\ub294 \uadf8\ub140\uc758 \uc544\ubc84\uc9c0\uc778 \ucfe8 \ud2f0\ub77c\uc2a4\uc758 \ub300\uc81c\ub3c5 \ub370\uc77c\ub9b0 \ud504\ub77c\uc6b0\ub4dc\ubb34\uc5b4\uac00 \uc624\ud06c\ub97c \uba78\ub9dd\uc2dc\ud0a4\uaca0\ub2e4\uba70 \ud568\ub300\ub97c \uc774\ub04c\uace0 \uc624\uba74\uc11c \uc2dc\ud5d8\ub300\uc5d0 \uc62c\ub790\ub2e4.","\ub370\uc77c\ub9b0\uc740 \ub4c0\ub85c\ud0c0 \ud574\uc548\uc744 \uacf5\uaca9\ud588\ub2e4. \ud638\ub4dc\uc758 \uc6a9\uc0ac\uac00 \ub41c \ubaa9\ub098\ud0c8 \ucd9c\uc2e0\uc758 \ubc18\uc624\uc6b0\uac70 \ubc29\ub791\uc790 \ub809\uc0ac\ub974\uac00 \uc624\ud06c\uc640 \ud2b8\ub864\uacfc \ud0c0\uc6b0\ub80c\uc744 \ud558\ub098\ub85c \ubb36\uc5b4 \uadf8\uc5d0\uac8c \ub9de\uc130\uace0, \ubc31\uc131\uacfc \uc544\ubc84\uc9c0 \uc0ac\uc774\uc5d0\uc11c \uac08\ub4f1\ud558\ub358 \uc81c\uc774\ub098\ub294 \ud638\ub4dc\uac00 \ud14c\ub77c\ubaa8\uc5b4\uc5d0\uc11c \uadf8\uc758 \uad70\ub300\ub97c \uce58\ub3c4\ub85d \ud5c8\ub77d\ud588\ub2e4. \ub370\uc77c\ub9b0\uc740 \uadf8 \uc804\ud22c\uc5d0\uc11c \uc8fd\uc5c8\ub2e4. \uc81c\uc774\ub098\ub294 \uadf8\ub97c \uc560\ub3c4\ud588\uc9c0\ub9cc \uc57d\uc18d\uc744 \uc9c0\ucf30\uace0, \ud14c\ub77c\ubaa8\uc5b4\uc640 \uc624\uadf8\ub9ac\ub9c8 \uc0ac\uc774\uc758 \ubd88\uc548\ud55c \ud734\uc804\uc740 \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc640 \ud638\ub4dc\ub97c \uc787\ub294 \uba87 \uc548 \ub418\ub294 \ub2e4\ub9ac\uac00 \ub418\uc5c8\ub2e4."]},"chapter:stormwind-in-shadow":{title:"\uadf8\ub9bc\uc790 \uc18d\uc758 \uc2a4\ud1b0\uc708\ub4dc",summary:"\uc7ac\uac74\ub41c \uc2a4\ud1b0\uc708\ub4dc\ub294 \ubc30\uc2e0\ub2f9\ud55c \uc11d\uacf5 \uae38\ub4dc, \uc0ac\ub77c\uc9c4 \uc655, \uad81\uc815\uc5d0 \uc228\uc740 \uc6a9\uacfc \ub9c8\uc8fc\ud558\uace0 \uc788\uc73c\uba70, \ub178\uc6c0\ub4e4\uc740 \uc790\uc2e0\ub4e4\uc758 \ub3c4\uc2dc\ub97c \uc783\uc5c8\ub2e4.",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 25\ub144 \ud6c4",body:["\uc81c2\ucc28 \ub300\uc804\uc7c1\uc774 \ub05d\ub09c \ub4a4, \uc5d0\ub4dc\uc708 \ubc34\ud074\ub9ac\ud504\uac00 \uc774\ub044\ub294 \uc11d\uacf5 \uae38\ub4dc\ub294 \uc7bf\ub354\ubbf8\uac00 \ub41c \uc2a4\ud1b0\uc708\ub4dc\ub97c \ub2e4\uc2dc \uc138\uc6e0\ub2e4. \uc77c\uc774 \ub05d\ub098\uc790 \uadc0\uc871\uc6d0\uc740 \ub300\uac00\ub97c \uce58\ub974\uae30\ub97c \uac70\ubd80\ud588\ub2e4. \uc11d\uacf5\ub4e4\uc740 \ud3ed\ub3d9\uc744 \uc77c\uc73c\ucf30\ub2e4\uac00 \ucad3\uaca8\ub0ac\uace0, \ub370\ud53c\uc544\uc988 \ub2e8\uc774 \ub418\uc5c8\ub2e4. \uadf8\ub4e4\uc740 \uc9c0\uae08 \uc228\uaca8\uc9c4 \uad11\uc0b0\uc744 \uac70\uc810 \uc0bc\uc544 \uc11c\ubd80 \ubab0\ub77d\uc9c0\ub300\ub97c \uc57d\ud0c8\ud558\uba70 \uc655\uc2e4\uc744 \ub178\ub9b0 \uc74c\ubaa8\ub97c \uafb8\ubbf8\uace0 \uc788\ub2e4.","\ub85c\ud0c0\uac00 \ud55c\ub54c \uad6c\ud574 \ub0c8\ub358 \uc18c\ub144, \ubc14\ub9ac\uc548 \ub9b0 \uad6d\uc655\uc740 \ud14c\ub77c\ubaa8\uc5b4\uc5d0\uc11c \uc5f4\ub9ac\ub294 \uc678\uad50 \ud68c\ub2f4\uc5d0 \uac00\ub358 \uc911 \uc0ac\ub77c\uc84c\ub2e4. \uc18c\ubb38\uc5d0 \ub530\ub974\uba74 \ub370\ud53c\uc544\uc988\uac00 \uadf8\ub97c \ub0a9\uce58\ud574 \uc54c\uce74\uc988 \uc12c\uc5d0 \uac00\ub450\uace0 \uc788\ub2e4\uace0 \ud55c\ub2e4. \uc5b4\ub9b0 \uc544\ub4e4 \uc548\ub450\uc778\uc774 \uc655\uc704\uc5d0 \uc62c\ub790\uace0, \ub300\uc601\uc8fc \ubcfc\ubc14\ub974 \ud3f4\ub4dc\ub77c\uace4\uc774 \uc12d\uc815\uc744 \ub9e1\uc558\ub2e4. \uad81\uc815\uc5d0\uc11c\ub294 \uc6b0\uc544\ud55c \uadc0\ubd80\uc778 \uce74\ud2b8\ub77c\ub098 \ud504\ub808\uc2a4\ud1a8\uc774 \ud070 \uc601\ud5a5\ub825\uc744 \uc5bb\uc5c8\ub2e4. \uadf8\ub140\uc758 \uc815\uccb4\ub294 \ub370\uc2a4\uc719\uc758 \ub538 \uc624\ub2c9\uc2dc\uc544\ub85c, \uc655\uad6d\uc744 \uc870\uc6a9\ud788 \ud30c\uba78\ub85c \uc774\ub04c\uace0 \uc788\uc5c8\ub2e4.","\uc5bc\ub77c\uc774\uc5b8\uc2a4\ub294 \ub2ec\ub77c\uc84c\ub2e4. \ub85c\ub370\ub860\uc740 \ubb34\ub108\uc84c\uace0, \ub098\uc774\ud2b8 \uc5d8\ud504\ub294 \ud558\uc774\uc798 \uc774\ud6c4 \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc5d0 \ud569\ub958\ud588\ub2e4. \ub358 \ubaa8\ub85c\uc5d0\uc11c\ub294 \ud2b8\ub85c\uadf8\ub4e4\uc774 \ub545\uc18d\uc5d0\uc11c \uc19f\uad6c\uccd0 \ub188\ub9ac\uac74\uc744 \uc810\ub839\ud588\ub2e4. \uadf8\ub4e4\uc744 \ubc29\uc0ac\ub2a5\uc73c\ub85c \ubab0\uc544\ub0b4\ub824\ub358 \ub178\uc6c0\ub4e4\uc758 \ud544\uc0ac\uc801\uc778 \uc2dc\ub3c4\ub294 \uc624\ud788\ub824 \uc790\uc2e0\ub4e4\uc758 \ub3c4\uc2dc\ub97c \uc624\uc5fc\uc2dc\ucf30\uace0, \ub55c\uc7a5\uc774\uc655 \uba55\uce74\ud1a0\ud06c\ub294 \uc0dd\uc874\uc790\ub4e4\uc744 \uc774\ub04c\uace0 \uc544\uc774\uc5b8\ud3ec\uc9c0\ub85c \ud53c\uc2e0\ud588\ub2e4. \uadf8\uacf3\uc740 \ub9c8\uadf8\ub2c8 \ube0c\ub860\uc988\ube44\uc5b4\ub4dc \uc655\uc774 \ub2e4\uc2a4\ub9ac\uba70, \uadf8\uc758 \ud0d0\ud5d8\uac00 \uc5f0\ub9f9\uc740 \uc628 \uc138\uc0c1\uc744 \ud30c\ud5e4\uce58\uba70 \ud2f0\ud0c4\uc758 \ube44\ubc00\uc744 \ucc3e\uace0 \uc788\ub2e4."]},"chapter:fire-beneath-blackrock":{title:"\uac80\uc740\ubc14\uc704 \uc544\ub798\uc758 \ubd88\uae38",summary:"\uac80\uc740\ubc14\uc704 \uc0b0\uc5d0\uc11c\ub294 \uac80\uc740\ubb34\uc1e0 \ub4dc\uc6cc\ud504\uac00 \ub77c\uadf8\ub098\ub85c\uc2a4\ub97c \uc12c\uae30\uace0 \ub124\ud30c\ub9ac\uc548\uc758 \uc624\ud06c\ub4e4\uc774 \uadf8 \uc704\uc758 \ucca8\ud0d1\uc744 \uc9c0\ud0a4\uba70, \uc624\ub2c9\uc2dc\uc544\ub294 \uba3c\uc9c0\uc9c4\ud759 \uc2b5\uc9c0\ub300\uc5d0\uc11c \uc0c8\ub07c\ub4e4\uc744 \uc9c0\ud0a8\ub2e4.",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 25\ub144 \ud6c4",body:["\ud0c0\uc6b0\ub9bf\uc0b0\uc758 \uc2e4\uc218\ub85c\ubd80\ud130 \ub450 \uc138\uae30\uac00 \uc9c0\ub0ac\uc9c0\ub9cc, \uadf8\uc758 \ud6c4\uc190\ub4e4\uc740 \uc5ec\uc804\ud788 \uac80\uc740\ubc14\uc704 \uc0b0 \uc544\ub798\ub97c \ub2e4\uc2a4\ub9b0\ub2e4. \uc81c\uc655 \ub2e4\uadf8\ub780 \ud0c0\uc6b0\ub9bf\uc0b0\uc740 \uac80\uc740\ubc14\uc704 \ub098\ub77d \uae4a\uc740 \uacf3\uc5d0 \uc788\ub294 \uac80\uc740\ubb34\uc1e0\uc758 \ub3c4\uc2dc \uc5b4\ub460\uad34\ucca0\ub85c\uc5d0\uc11c \uad81\uc815\uc744 \uc5f4\uace0, \uadf8 \uc544\ub798 \ud654\uc0b0 \uc2ec\uc7a5\ubd80\uc5d0\uc11c\ub294 \ub77c\uadf8\ub098\ub85c\uc2a4\uac00 \ubd88\ud0c0\uba70 \ub4dc\uc6cc\ud504\ub4e4\uc774 \uadf8\ub97c \uc704\ud574 \uc77c\ud55c\ub2e4. \ub9c8\uadf8\ub2c8 \uc655\uc758 \ub538 \ubaa8\uc774\ub77c \ube0c\ub860\uc988\ube44\uc5b4\ub4dc \uacf5\uc8fc\ub294 \ud3ec\ub85c\ub85c \uc0b0\uc5d0 \uc654\ub2e4\uac00 \uc81c\uc655\uc758 \uc544\ub0b4\ub85c \ub0a8\uc558\uace0, \uc774\uc5d0 \uc544\ubc84\uc9c0\ub294 \ubd84\ub178\ud588\ub2e4.","\uc704\ucabd \uc804\ub2f9\uc740 \uac80\uc740\uc6a9\uad70\ub2e8\uc758 \uac83\uc774\ub2e4. \ub370\uc2a4\uc719\uc758 \uc544\ub4e4 \ub124\ud30c\ub9ac\uc548\uc740 \ube45\ud130 \ub124\ud30c\ub9ac\uc6b0\uc2a4 \uacbd\uc758 \ubaa8\uc2b5\uc73c\ub85c \uac80\uc740\ub0a0\uac1c \ub465\uc9c0\ub97c \ub2e4\uc2a4\ub9ac\uba70, \uc2a4\ub784\uc5d0\uac8c \ub05d\ub0b4 \ud569\ub958\ud558\uc9c0 \uc54a\uc740 \uac80\uc740\ubc14\uc704 \uc624\ud06c\ub4e4\uc744 \uc9c0\ud718\ud55c\ub2e4. \uc774\ub4e4\uc744 \uc774\ub044\ub294 \uac83\uc740 \uac80\uc740\ubc14\uc704 \ucca8\ud0d1\uc758 \ub300\uc871\uc7a5 \ub80c\ub4dc \ube14\ub799\ud578\ub4dc\ub2e4. \ubd88\uacfc \uadf8\ub9bc\uc790\ub294 \uac19\uc740 \uc0b0 \uc548\uc5d0\uc11c \ub0c9\uc804\uc744 \ubc8c\uc774\uace0 \uc788\uc73c\uba70, \ubd88\ud0c0\ub294 \ud3c9\uc6d0\uacfc \uc774\uae00\uac70\ub9ac\ub294 \ud611\uace1\uc774 \uadf8 \ub300\uac00\ub97c \uce58\ub974\uace0 \uc788\ub2e4.","\ub124\ud30c\ub9ac\uc548\uc758 \ub204\uc774\uc774\uc790 \uac00\uc9dc \ud504\ub808\uc2a4\ud1a8 \ubd80\uc778\uc778 \uc624\ub2c9\uc2dc\uc544\ub294 \uba3c\uc9c0\uc9c4\ud759 \uc2b5\uc9c0\ub300\uc5d0 \ub465\uc9c0\ub97c \ud2c0\uace0 \uc0c8\ub07c\ub4e4\uc744 \uc9c0\ud0a8\ub2e4. \uadf8\ub140\uc5d0\uac8c \uac00\ub824\uba74 Drakefire Amulet\uc774 \ud544\uc694\ud558\uba70, \uc774\ub294 \uc9c4\uc601\ub9c8\ub2e4 \uac80\uc740\ubc14\uc704 \ucca8\ud0d1\uc744 \uac70\uccd0 \uac00\ub294 \uae34 \ud018\uc2a4\ud2b8 \ub77c\uc778\uc73c\ub85c \uc5bb\ub294\ub2e4. Forever\uc5d0\uc11c \uc624\ub2c9\uc2dc\uc544\uc758 \ub465\uc9c0\ub294 12\uc6d4 9\uc77c\uc5d0 \uc5f4\ub9ac\ub294 \uacf5\uaca9\ub300 \uc138 \uacf3 \uc911 \ud558\ub098\uc774\uba70, \ud558\uc774\uc798 \uc0b0\uc758 \uc0c8 \uacf5\uaca9\ub300 \ub450 \uacf3\uacfc \ud568\uaed8 \uc5f4\ub9b0\ub2e4."]},"chapter:plaguelands-and-the-scarlet-crusade":{title:"\uc5ed\ubcd1\uc9c0\ub300\uc640 \ubd89\uc740\uc2ed\uc790\uad70",summary:"\ucf08\ud22c\uc790\ub4dc\uc758 \uc2a4\uceec\uc9c0\uac00 \ubd81\ubd80\ub97c \uc7a5\uc545\ud558\uace0 \ubd89\uc740\uc2ed\uc790\uad70\uc758 \uad11\uc2e0\ub3c4\ub4e4\uc740 \uc5b8\ub370\ub4dc\uc640 \uc0b0 \uc790\ub97c \uac00\ub9ac\uc9c0 \uc54a\uace0 \uc2f8\uc6b0\uba70, \uba87\uba87 \uad73\uac74\ud55c \ub2e8\uccb4\uac00 \uc804\uc120\uc744 \uc9c0\ud0a8\ub2e4.",when:"\uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 25\ub144 \ud6c4",body:["\ub85c\ub370\ub860\uc758 \uc2ec\uc7a5\ubd80\ub294 \uc774\uc81c \uc5ed\ubcd1\uc9c0\ub300\uac00 \ub418\uc5c8\ub2e4. \ucf08\ud22c\uc790\ub4dc\ub294 \ub5a0\ub2e4\ub2c8\ub294 \uac15\ub839\uc220\uc0ac\uc758 \uc131\ucc44 \ub099\uc2a4\ub77c\ub9c8\uc2a4\uc5d0\uc11c \uadf8\uacf3\uc758 \uc2a4\uceec\uc9c0\ub97c \uc9c0\ud718\ud558\uace0, \ub0a8\uc791 \ub9ac\ube10\ub370\uc5b4\ub294 \ud3d0\ud5c8\uac00 \ub41c \uc2a4\ud2b8\ub77c\uc194\ub984\uc758 \uc5b8\ub370\ub4dc\ub97c \ub2e4\uc2a4\ub9ac\uba70, \ubc14\ub85c\ube0c \uac00\ubb38\uc758 \uc61b \ud559\uad50 \uc2a4\uce7c\ub85c\ub9e8\uc2a4\uc5d0\uc11c\ub294 \uc800\uc8fc\ubc1b\uc740 \uc790\uc758 \uad50\ub2e8\uc774 \uc0c8 \uac15\ub839\uc220\uc0ac\ub4e4\uc744 \uae38\ub7ec \ub0b8\ub2e4.","\ubc31\uc740\uc758 \uc190\uc758 \uc0dd\uc874\uc790\ub4e4\uc740 \ub545\uc5d0\uc11c \uc5ed\ubcd1\uc744 \ubd88\ud0dc\uc6cc \uc5c6\uc560\uaca0\ub2e4\uace0 \ub9f9\uc138\ud558\uba70 \ubd89\uc740\uc2ed\uc790\uad70\uc73c\ub85c \ub2e4\uc2dc \ubaa8\uc600\ub2e4. \uc2ed\uc790\uad70\uc758 \uc218\uc7a5 \uc0ac\uc774\ub2e8 \ub2e4\uc2a4\ub85c\ud55c\uc758 \uc815\uccb4\ub294 \uacf5\ud3ec\uc758 \uad70\uc8fc \ubc1c\ub098\uc790\ub974\uc774\uba70, \uc2ed\uc790\uad70\uc740 \ub108\ubb34\ub098 \uad11\uc2e0\uc801\uc774 \ub418\uc5b4 \uc624\uc5fc\uc774 \uc758\uc2ec\ub418\ub294 \uc678\ubd80\uc778\uc740 \ub204\uad6c\ub4e0 \uc8fd\uc778\ub2e4. \uadf8 \uac70\uc810\uc73c\ub85c\ub294 \ud2f0\ub9ac\uc2a4\ud314 \uc232\uc758 \ubd89\uc740\uc2ed\uc790\uad70 \uc218\ub3c4\uc6d0, \ud558\uc2a4\uae00\ub80c, \ud2f0\ub974\uc758 \uc190, \uadf8\ub9ac\uace0 \uc2a4\ud2b8\ub77c\uc194\ub984\uc758 \uc694\uc0c8\uac00 \uc788\ub2e4. \uadf8 \uc601\uc6c5\ub4e4\uc870\ucc28 \ub354 \uc5b4\ub450\uc6b4 \uc0ac\uc5f0\uc744 \uc9c0\ub154\ub2e4. \ub974\ub178 \ubaa8\uadf8\ub808\uc778\uc740 '\ud30c\uba78\uc758 \uc778\ub3c4\uc790'\ub77c \ubd88\ub9b0 \uc544\ubc84\uc9c0 \uc54c\ub809\uc0b0\ub4dc\ub85c\uc2a4\ub97c \ubc30\uc2e0\ud574 \uc8fd\uc74c\uc73c\ub85c \ubab0\uc544\ub123\uc5c8\ub2e4.","\ubaa8\ub4e0 \uc131\uae30\uc0ac\uac00 \uad11\uc2e0\ub3c4\uac00 \ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2ed\uc790\uad70\uc758 \uc794\ud639\ud568\uc744 \uac70\ubd80\ud55c \uc774\ub4e4\uc740 \uc740\ube5b \uc5ec\uba85\ud68c\ub97c \uacb0\uc131\ud588\uace0, \ud76c\ub9dd\uc758 \ube5b \uc608\ubc30\ub2f9\uc744 \uac70\uc810\uc73c\ub85c \uc2a4\uceec\uc9c0\uc640 \uc2f8\uc6b0\ub294 \ub204\uad6c\uc640\ub3c4 \uc190\uc744 \uc7a1\ub294\ub2e4. \ucd94\ubc29\ub2f9\ud55c \uc131\uae30\uc0ac \ud2f0\ub9ac\uc628 \ud3f4\ub4dc\ub9c1\uc740 \ud558\uc2a4\uae00\ub80c \uadfc\ucc98\uc5d0\uc11c \uc740\ub454\uc790\ub85c \uc0b4\uace0 \uc788\uc73c\uba70, \ud3ec\uc138\uc774\ud070\uc740 \ud2f0\ub9ac\uc2a4\ud314\uc5d0\uc11c \ubd81\ucabd\uc73c\ub85c \ubc00\uace0 \uc62c\ub77c\uc628\ub2e4. \ub85c\ub370\ub860\uc758 \uc6b4\uba85\uc740 \uc544\uc9c1 \uc815\ud574\uc9c0\uc9c0 \uc54a\uc558\ub2e4."]},"chapter:azeroth-in-year-twenty-five":{title:"25\ub144\uc758 \uc544\uc81c\ub85c\uc2a4",summary:"Forever\uc758 \uc774\uc57c\uae30\uac00 \ud3bc\uccd0\uc9c0\ub294 \uc6d4\ub4dc \uc624\ube0c \uc6cc\ud06c\ub798\ud504\ud2b8 \uccab\ud574\uc758 \uc138\uacc4: \uc704\ud0dc\ub85c\uc6b4 \ud3c9\ud654, \uafc8\ud2c0\ub300\ub294 \uc61b \uc704\ud611, \uc9c0\ub3c4 \uc704\uc758 \uc0c8\ub85c\uc6b4 \uc7a5\uc18c\ub4e4.",when:"25\ub144: Forever\uc758 \ubc30\uacbd",body:["\uc5b4\ub460\uc758 \ubb38\uc774 \ucc98\uc74c \uc5f4\ub9b0 \uc9c0 25\ub144, \uc544\uc81c\ub85c\uc2a4\ub294 \uc0b4\uc544\ub0a8\uc740 \uc790\ub4e4\uc758 \uc138\uacc4\ub2e4. \uc2a4\ud1b0\uc708\ub4dc\uc640 \uc544\uc774\uc5b8\ud3ec\uc9c0, \ub178\uc6c0\uacfc \ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \uc5bc\ub77c\uc774\uc5b8\uc2a4\ub294 \uc624\ud06c\uc640 \ud2b8\ub864, \ud0c0\uc6b0\ub80c\uacfc \ud3ec\uc138\uc774\ud070\uc758 \ud638\ub4dc\uc640 \ub9de\uc11c\uace0 \uc788\uc73c\uba70, \uc5b4\ub290 \ucabd\ub3c4 \uc0c1\ub300\ub97c \ubbff\uc9c0 \uc54a\ub294\ub2e4. \uc9c0\ub3c4\uc758 \uac00\uc7a5\uc790\ub9ac\uc5d0\uc11c\ub294 \uc61b \uc801\ub4e4\uc774 \uae68\uc5b4\ub09c\ub2e4. \uc2e4\ub9ac\ub354\uc2a4\uc758 \uace0\ub300 \uc2e0 \ud06c\ud230\uc758 \ud558\uc218\uc778\ub4e4, \ub0a8\ucabd \ud2b8\ub864 \uc720\uc801\uc758 \ud53c\uc758 \uc2e0 \ud559\uce74\ub974\uc758 \uc0ac\uc81c\ub4e4, \uadf8\ub9ac\uace0 \ub4dc\ub8e8\uc774\ub4dc\ub4e4\uc758 \uafc8\uc18d\uc73c\ub85c \uc2a4\uba70\ub4dc\ub294 \uc5d0\uba54\ub784\ub4dc\uc758 \uc545\ubabd\uc758 \ud0c0\ub77d\uc774\ub2e4.","\uc6d4\ub4dc \uc624\ube0c \uc6cc\ud06c\ub798\ud504\ud2b8: Forever\ub294 \ubc14\ub85c \uc774 \uc21c\uac04\uc744 \ubc30\uacbd\uc73c\ub85c \ud55c\ub2e4. \ube14\ub9ac\uc790\ub4dc\ub294 \uc6cc\ud06c\ub798\ud504\ud2b8 III: \ub9ac\ud3ec\uc9c0\ub4dc\uc758 'Forsaken Kingdom' \ucea0\ud398\uc778 \uc774\ud6c4, \ubd88\ud0c0\ub294 \uc131\uc804 \uc774\uc804\uc778 \uc774 \uc2dc\uc810\uc5d0 \uac8c\uc784\uc744 \ubb34\uae30\ud55c \uba38\ubb3c\uac8c \ud558\uba70, \uadf8 \uc774\uc57c\uae30\uac00 \ud604\uc7ac \uc6d4\ub4dc \uc624\ube0c \uc6cc\ud06c\ub798\ud504\ud2b8\uc758 \uc5f0\uc18d\uc131\uc744 \uacf5\uc720\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubc1d\ud614\ub2e4. Forever\ub294 \uc6d0\uc791\uc5d0 \uc5c6\ub358 \uc7a5\uc18c\ub4e4\uc744 \ub354\ud55c\ub2e4. \ud669\uc57c\uc758 \ub545 \ub3d9\ucabd\uc5d0 \uc788\uc73c\uba70 Farholde Keep\uc774 \ud669\ud63c\uc758 \ub9dd\uce58\uc5d0 \ub9de\uc11c \ubc84\ud2f0\ub294 Riverglades, \uc740\ud3d0 \uc7a5\ubcbd\uc774 \ubb34\ub108\uc9c4 \ucc44 \ubcf5\uad6c \uc911\uc778 \ub2ec\ub77c\ub780, \uadf8\ub9ac\uace0 Hall of Thanes\uc758 \uc655\uc2e4 \ubb34\ub364\ubd80\ud130 \ud2f0\ud0c4 \uc2dc\uc124 Shaper's Terrace\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294 \ub358\uc804\ub4e4\uc774\ub2e4.","Forever\ub294 \ud50c\ub808\uc774\uc5b4\uc5d0\uac8c \uc0c8\ub85c\uc6b4 \uc885\uc871\ub3c4 \uc5f4\uc5b4 \uc900\ub2e4. \ubc14\ub78c\uc758 \uc815\ub839\uacc4 Skywall\uc5d0 \ub5a0 \uc788\ub294 \uc12c Zephras Isle\uc758 Skyborne\uc774\ub2e4. \uc12c\uc758 \ubc14\ub78c \uc815\ub839\ub4e4\uc740 \uc218\ubc31 \ub144 \uc804\uc5d0 \uc0ac\ub77c\uc84c\uace0 \uc12c\uc744 \ud558\ub298\uc5d0 \ub744\uc6b0\ub294 \ub9c8\ubc95\uc740 \uc57d\ud574\uc9c0\uace0 \uc788\ub2e4. \uadf8\ub4e4\uc758 High Order\ub294 \uc5bc\ub77c\uc774\uc5b8\uc2a4\ub97c, Windshaper\ub294 \ud638\ub4dc\ub97c \uc12c\uae34\ub2e4. \uc774 \uc774\uc57c\uae30\ub4e4\uc774 \uc5b4\ub5bb\uac8c \ub05d\ub0a0\uc9c0\ub294 \uc544\uc9c1 \uc4f0\uc774\ub294 \uc911\uc774\ub2e4. \ube14\ub9ac\uc790\ub4dc\ub294 2027\ub144\uc5d0 \uc120\ubcf4\uc77c \uc0c8 \uacf5\uaca9\ub300\uc640 \ub358\uc804, \uc804\uc124 \ud018\uc2a4\ud2b8 \ub77c\uc778\uc744 \ubc1c\ud45c\ud588\uc73c\uba70, \ud558\uc774\uc798 \uc0b0\uc758 \uacf5\uaca9\ub300\ub294 12\uc6d4 9\uc77c\uc5d0 \uc5f4\ub9b0\ub2e4."]},"chapter:after-classic":{title:"\uc5d0\ud544\ub85c\uadf8: \ud074\ub798\uc2dd \uc774\ud6c4",summary:"\uc6d0\ub798\uc758 \uc2dc\uac04\uc120\uc5d0\uc11c \uc774\uc57c\uae30\ub294 \uc544\uc6c3\ub79c\ub4dc\uc640 \ub178\uc2a4\ub80c\ub4dc, \uadf8 \ub108\uba38\ub85c \uc774\uc5b4\uc84c\uc9c0\ub9cc, Forever\ub294 25\ub144\uc5d0 \uba38\ubb3c\uba70 \uc790\uc2e0\ub9cc\uc758 \uc774\uc57c\uae30\ub97c \ub4e4\ub824\uc900\ub2e4.",when:"\uc774\ud6c4\uc758 \ud655\uc7a5\ud329 (Forever\uc5d0\ub294 \uc5c6\uc74c)",body:["\uc6d4\ub4dc \uc624\ube0c \uc6cc\ud06c\ub798\ud504\ud2b8\uc758 \uc6d0\ub798 \uc2dc\uac04\uc120\uc5d0\uc11c \uc774\uc57c\uae30\ub294 \uacc4\uc18d \ub098\uc544\uac14\ub2e4. \uc5b4\ub460\uc758 \ubb38\uc774 \ub2e4\uc2dc \uc5f4\ub838\uace0, \ubd88\ud0c0\ub294 \uc131\uc804\ub294 \ubaa8\ud5d8\uac00\ub4e4\uc744 \uc544\uc6c3\ub79c\ub4dc\ub85c \ub370\ub824\uac14\uc73c\uba70, \uadf8\uacf3\uc5d0\uc11c \uc77c\ub9ac\ub2e8\uacfc \uce98\ud0c0\uc2a4 \uc120\uc2a4\ud2b8\ub77c\uc774\ub354\uac00 \uc4f0\ub7ec\uc84c\ub2e4. \ub9ac\uce58 \uc655\uc758 \ubd84\ub178\uc5d0\uc11c\ub294 \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc640 \ud638\ub4dc\uac00 \ub178\uc2a4\ub80c\ub4dc\ub85c \uc9c4\uad70\ud588\uace0, \uc544\uc11c\uc2a4\ub294 \uc5bc\uc74c\uc655\uad00 \uc131\ucc44 \uaf2d\ub300\uae30\uc5d0\uc11c \ud328\ubc30\ud588\ub2e4. \ub300\uaca9\ubcc0\uc5d0\uc11c\ub294 \ub370\uc2a4\uc719\uc774 \uae4a\uc740 \uacf3\uc5d0\uc11c \ud130\uc838 \ub098\uc640 \uc138\uacc4\uc758 \ubaa8\uc2b5\uc744 \ubd80\uc218\uc5b4 \ub193\uc558\uace0, \uacb0\uad6d \uc704\uc0c1\ub4e4\uacfc \ud544\uba78\uc758 \ub3d9\ub9f9\ub4e4\uc774 \uadf8\ub97c \uc4f0\ub7ec\ub728\ub838\ub2e4.","\uc774\ud6c4\uc758 \ud655\uc7a5\ud329\ub4e4\uc740 \uc774\uc57c\uae30\ub97c \ud310\ub2e4\ub9ac\uc544, \ub610 \ub2e4\ub978 \ub4dc\ub808\ub178\uc5b4, \uc544\ub974\uac70\uc2a4\uc5d0\uc11c\uc758 \ubd88\ud0c0\ub294 \uad70\ub2e8\uc758 \ucd5c\ud6c4, \uc9c4\uc601 \uac04\uc758 \uc804\uba74\uc804, \uc8fd\uc740 \uc790\ub4e4\uc758 \uc601\uc5ed, \uc6a9\uc758 \uc12c, \uadf8\ub9ac\uace0 \uc544\uc81c\ub85c\uc2a4 \uc790\uc2e0\uc758 \uc138\uacc4\ud63c\uc744 \ub458\ub7ec\uc2fc \uae34 \uc2f8\uc6c0\uc73c\ub85c \uc774\ub04c\uc5c8\ub2e4. \uc774 \uc548\ub0b4\uc11c\uc5d0 \ub098\uc624\ub294 \ub9ce\uc740 \uc7a5\uc18c\uac00 \uadf8 \uacfc\uc815\uc5d0\uc11c \uc54c\uc544\ubcfc \uc218 \uc5c6\uc744 \ub9cc\ud07c \ubc14\ub00c\uc5c8\ub2e4.","\uc6d4\ub4dc \uc624\ube0c \uc6cc\ud06c\ub798\ud504\ud2b8: Forever\ub294 \uadf8 \uc5b4\ub5a4 \uae38\ub3c4 \ud0dd\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud604\uc7ac \uac8c\uc784\uc758 \uc5f0\uc18d\uc131 \ubc16\uc5d0 \uc788\ub294 '\uc2dc\uac04\uc758 \uac70\ud488' \uc18d\uc5d0\uc11c 25\ub144\uc5d0 \uba38\ubb3c\uba70, \uc6d0\ub798 \uc138\uacc4\uc758 \ud1a0\ub300 \uc704\uc5d0 \uc790\uc2e0\uc758 \ubbf8\ub798\ub97c \uc313\uc544 \uac04\ub2e4. \ube14\ub9ac\uc790\ub4dc\uc758 \ub85c\ub4dc\ub9f5\uc740 2027\ub144\uc5d0 \uc0c8 \uacf5\uaca9\ub300\uc640 \ub358\uc804, \ud018\uc2a4\ud2b8, \uadf8\ub9ac\uace0 \uc0c8\ub86d\uac8c \uc190\ubcf8 \uc0c1\uc9d5\uc801\uc778 \uacf5\uaca9\ub300\ub97c \uc57d\uc18d\ud558\uace0 \uc788\uc73c\ub2c8, \uc774 \uc774\uc57c\uae30\uc758 \ub2e4\uc74c \uc7a5\ub4e4\uc740 \uc624\ub86f\uc774 Forever\uc758 \uac83\uc774 \ub420 \uac83\uc774\ub2e4."]}}},1791,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"classes",{enumerable:!0,get:function(){return s}});const s={"class:mage":{title:"\ub9c8\ubc95\uc0ac",summary:"\uba85\uac00\uc640 \ucd5c\ucd08\uc758 \uc778\uac04 \ub9c8\ubc95\uc0ac\ub4e4\uc758 \ud6c4\uc608\uc778 \ub9c8\ubc95\uc0ac\ub294 \ub0a0\uac83 \uadf8\ub300\ub85c\uc758 \ube44\uc804 \ub9c8\ub825\uc744 \ub2e4\ub8e8\uba70, \uc774\uc57c\uae30\uc758 \ubaa8\ub4e0 \uc2dc\ub300\ub294 \uadf8\ub4e4 \uc911 \ub204\uad70\uac00\ub97c \uc911\uc2ec\uc73c\ub85c \ub3cc\uc544\uac04\ub2e4.",body:["\ub9c8\ubc95\uc0ac\ub294 \ud55c\ub54c \uc601\uc6d0\uc758 \uc0d8\uc5d0\uc11c \uc19f\uc544\ub098\ub358 \uc9c8\uc11c\uc758 \uc21c\uc218\ud55c \ub9c8\ubc95, \ube44\uc804\uc744 \ub2e4\ub8ec\ub2e4. \ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \uba85\uac00\ub294 \ucd5c\ucd08\uc758 \uc704\ub300\ud55c \ub9c8\ubc95\uc0ac\ub4e4\uc774\uc5c8\uace0, \ucd94\ubc29\ub2f9\ud55c \uadf8\ub4e4\uc758 \ud6c4\uc190\uc778 \ucfe0\uc5d8\ud0c8\ub77c\uc2a4\uc758 \ud558\uc774 \uc5d8\ud504\ub294 \ud2b8\ub864 \uc804\uc7c1 \ub3d9\uc548 \uc778\uac04 \ubc31 \uba85\uc5d0\uac8c \uadf8 \uae30\uc220\uc744 \uac00\ub974\ucce4\ub2e4. \uadf8 \ucd5c\ucd08\uc758 \uc778\uac04 \ub9c8\ubc95\uc0ac\ub4e4\uc740 \ud6d7\ub0a0 \ub2ec\ub77c\ub780\uc744 \uc138\uc6e0\uace0, \uadf8\uacf3\uc5d0\uc11c \ud0a4\ub9b0 \ud1a0\ub294 \uc9c0\uae08\ub3c4 \ub9c8\ubc95\uc758 \ube44\ubc00\uc744 \uc9c0\ud0a4\uace0 \uc788\ub2e4.","\uc774\uc57c\uae30\uc758 \ubaa8\ub4e0 \uc2dc\ub300\ub294 \ud55c \uba85\uc758 \ub9c8\ubc95\uc0ac\ub97c \uc911\uc2ec\uc73c\ub85c \ub3cc\uc544\uac04\ub2e4. \ub9c8\uc9c0\ub9c9 \uc218\ud638\uc790 \uba54\ub514\ube0c, \uc5b4\ub460\uc758 \ubb38\uc744 \ud30c\uad34\ud55c \uadf8\uc758 \uc81c\uc790 \uce74\ub4dc\uac00, \ub2ec\ub77c\ub780\uc744 \uc9c0\ud0a4\ub2e4 \uc228\uc9c4 \ub300\ub9c8\ubc95\uc0ac \uc548\ud1a0\ub2c8\ub2e4\uc2a4, \uadf8\ub9ac\uace0 \uc9c0\uae08 \ud14c\ub77c\ubaa8\uc5b4\ub97c \ub2e4\uc2a4\ub9ac\ub294 \uc81c\uc774\ub098 \ud504\ub77c\uc6b0\ub4dc\ubb34\uc5b4\uac00 \uadf8\ub807\ub2e4. 25\ub144\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \ud559\uc0dd\ub4e4\uc774 \uc2a4\ud1b0\uc708\ub4dc\uc758 \ub9c8\ubc95\uc0ac \uc9c0\uad6c\uc640 \uc5b8\ub354\uc2dc\ud2f0\uc758 \ub9c8\ubc95 \uc9c0\uad6c\uc5d0\uc11c \uc218\ub828\ud558\uba70, \ub178\uc6c0\uacfc \ud2b8\ub864 \ub9c8\ubc95\uc0ac\ub4e4\uc740 \uc624\ub798\uc804\ubd80\ud130 \uc778\uac04\uacfc \ud3ec\uc138\uc774\ud070 \uacc1\uc5d0 \uc11c \uc654\ub2e4. Forever\ub294 \ud55c\ub54c \uc8fc\uc220\uacfc \uc9c0\uc625 \ub9c8\ubc95\ubc16\uc5d0 \ubab0\ub790\ub358 \uc624\ud06c, \uadf8\ub9ac\uace0 \ub9c8\ubc95\uc0ac\uac00 \ub420 \uc218 \uc788\ub294 \uc720\uc77c\ud55c Skyborne\uc778 High Order\uc5d0\uac8c \uc774 \uae38\uc744 \uc5f4\uc5b4 \uc900\ub2e4."]},"class:warrior":{title:"\uc804\uc0ac",summary:"\uc544\uc81c\ub85c\uc2a4\uc758 \ubaa8\ub4e0 \uc885\uc871\uc5d0\uac8c\ub294 \uc804\uc0ac\uac00 \uc788\uc73c\uba70, \uc138\uacc4 \uc5ed\uc0ac\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc740 \uadf8\ub4e4\uc758 \uac15\ucca0\ub85c \uc4f0\uc600\ub2e4.",body:["\uc544\uc81c\ub85c\uc2a4\uc758 \ubaa8\ub4e0 \uc885\uc871\uc5d0\uac8c\ub294 \uc804\uc0ac\uac00 \uc788\uc73c\uba70, \uadf8 \uc5ed\uc0ac\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc740 \uadf8\ub4e4\uc758 \uac15\ucca0\ub85c \uc4f0\uc600\ub2e4. \uc544\ub77c\uc18c\ub974\uc758 \ubcd1\uc0ac\ub4e4\uc740 \uc18c\ub77c\ub518\uc758 \uc131\ubcbd\uc5d0\uc11c \uc544\ub9c8\ub2c8\ub97c \ub9c9\uc544 \ub0c8\uace0, \ub4dc\uc6cc\ud504 \uc601\uc8fc\ub4e4\uc740 \uc138 \ub9dd\uce58\uc758 \uc804\uc7c1\uc5d0\uc11c \uc544\uc774\uc5b8\ud3ec\uc9c0\ub97c \uc704\ud574 \uc2f8\uc6e0\uc73c\uba70, \uc624\ud06c \ubd80\uc871\ub4e4\uc740 \ud638\ub4dc\uac00 \ub9cc\ub4e4\uc5b4\uc9c0\uae30 \ud6e8\uc52c \uc804\ubd80\ud130 \uc6a9\uc0ac\ub4e4\uc758 \ud798\uc73c\ub85c \uc0b4\uc544\uc654\ub2e4. \uc804\uc0ac\ub294 \uc8fc\ubb38\uc774 \uc544\ub2c8\ub77c \ud6c8\ub828\uacfc \uac11\uc637, \uadf8\ub9ac\uace0 \uc804\ud22c\uc758 \ubd84\ub178\ub97c \ubbff\ub294\ub2e4.","\uadf8\ub4e4\uc758 \uc601\uc6c5\uc740 \uc5f0\ub300\uae30\ub97c \uac00\ub4dd \ucc44\uc6b4\ub2e4. \uac80\uc740\ubc14\uc704 \ucca8\ud0d1\uc5d0\uc11c \uc4f0\ub7ec\uc9c8 \ub54c\uae4c\uc9c0 \uc5bc\ub77c\uc774\uc5b8\uc2a4\ub97c \uc774\ub048 \uc544\uc81c\ub85c\uc2a4\uc758 \uc0ac\uc790 \uc548\ub450\uc778 \ub85c\ud0c0, \ud558\uc774\uc798 \uc0b0\uc5d0\uc11c \uc790\uc2e0\uc744 \ud76c\uc0dd\ud574 \uc624\ud06c\ub97c \uc545\ub9c8\uc758 \ud53c\uc5d0\uc11c \ud574\ubc29\ud55c \uadf8\ub86c \ud5ec\uc2a4\ud06c\ub9bc, \uadf8\ub9ac\uace0 \uc5bc\ub77c\uc774\uc5b8\uc2a4 \uc6d0\uc815\ub300\uc640 \ud568\uaed8 \ub4dc\ub808\ub178\uc5b4\uc5d0 \ub0a8\uc740 \ub2e4\ub098\uc2a4 \ud2b8\ub864\ubca0\uc778\uc774 \uadf8\ub807\ub2e4. 25\ub144\uc5d0 \uc804\uc0ac\ub4e4\uc740 \uc2a4\ud1b0\uc708\ub4dc\uc758 \uacbd\ube44\ubcd1\ubd80\ud130 \uc624\uadf8\ub9ac\ub9c8\uc758 \uadf8\ub7f0\ud2b8\uae4c\uc9c0 \ubaa8\ub4e0 \uae43\ubc1c \uc544\ub798\uc5d0\uc11c \uc2f8\uc6b0\uba70, \ud50c\ub808\uc774\ud560 \uc218 \uc788\ub294 \ubaa8\ub4e0 \uc885\uc871\uc774 \ubb34\uae30\ub97c \ub4e4 \uc218 \uc788\ub2e4. Forever\ub294 \ub450 \ubd84\ud30c\uc758 Skyborne\uc744 \uadf8\ub4e4\uc758 \ub300\uc5f4\uc5d0 \ub354\ud55c\ub2e4."]},"class:paladin":{title:"\uc131\uae30\uc0ac",summary:"\uc81c2\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \ud0dc\uc5b4\ub09c \uac70\ub8e9\ud55c \uc804\uc0ac\ub4e4, \ubc31\uc740\uc758 \uc190 \uc131\uae30\uc0ac\ub2e8\uc740 \uc790\uc2e0\ub4e4 \uac00\uc6b4\ub370 \ud55c \uba85\uc5d0\uac8c \ubb34\ub108\uc84c\uc9c0\ub9cc \uc9c0\uae08\uc740 \uc0c8\ub85c\uc6b4 \uae43\ubc1c \uc544\ub798 \uc2f8\uc6b0\uace0 \uc788\ub2e4.",body:["\uc131\uae30\uc0ac\ub294 \uc131\uc2a4\ub7ec\uc6b4 \ube5b\uc758 \uc804\uc0ac\uc774\uc790 \uc0ac\uc81c\ub2e4. \ub300\uc8fc\uad50 \uc54c\ub860\uc11c\uc2a4 \ud30c\uc62c\uc740 \uc81c2\ucc28 \ub300\uc804\uc7c1 \uc911\uc5d0 \uadf8\ub4e4\uc758 \uae30\uc0ac\ub2e8\uc778 \ubc31\uc740\uc758 \uc190 \uae30\uc0ac\ub2e8\uc744 \uc138\uc6cc, \uc2f8\uc6b0\ub294 \uac83\ub9cc\ud07c \uce58\uc720\ub3c4 \ud560 \uc218 \uc788\ub294 \uc6a9\uc0ac\ub4e4\uc744 \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc5d0 \uc8fc\uc5c8\ub2e4. \ube5b\uc758 \uc218\ud638\uc790 \uc6b0\uc11c\uac00 \uadf8 \uccab \ubc88\uc9f8\uc600\uace0, \ud22c\ub784\ub9ac\uc628\uacfc \ud2f0\ub9ac\uc628 \ud3f4\ub4dc\ub9c1, \uc544\uc11c\uc2a4 \uba54\ub124\uc2e4 \uc655\uc790\ub3c4 \ubaa8\ub450 \ub9f9\uc138\ub97c \ud588\ub2e4.","\uae30\uc0ac\ub2e8\uc740 \uc790\uc2e0\ub4e4 \uac00\uc6b4\ub370 \ud55c \uba85\uc5d0\uac8c \ubb34\ub108\uc84c\ub2e4. \uc544\uc11c\uc2a4\ub294 \uc6b0\uc11c\ub97c \uc0b4\ud574\ud558\uace0 \ub85c\ub370\ub860\uc758 \ud30c\uad34\uc5d0 \uc55e\uc7a5\uc130\uc73c\uba70, \ubc31\uc740\uc758 \uc190\uc758 \uc0dd\uc874\uc790\ub4e4\uc740 \ud769\uc5b4\uc84c\ub2e4. \ud55c\ucabd\uc5d0\ub294 \ubd89\uc740\uc2ed\uc790\uad70\uc758 \uad11\uc2e0\ub3c4\ub4e4\uc774, \ub2e4\ub978 \ucabd\uc5d0\ub294 \uc740\ube5b \uc5ec\uba85\ud68c\uc640 \ucd94\ubc29\ub41c \ud2f0\ub9ac\uc628\uc774 \uc130\ub2e4. \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \ub4dc\uc6cc\ud504\ub3c4 \ube5b\uc744 \uc804\uc7a5\uc73c\ub85c \uac00\uc838\uac04\ub2e4. Forever\uc758 \uac00\uc7a5 \ub180\ub77c\uc6b4 \ubcc0\ud654\ub294 \uc774\uc81c \ud3ec\uc138\uc774\ud070\ub3c4 \uc131\uae30\uc0ac\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\uc9c0\ub9cc, \uc774 \uc548\ub0b4\uc11c\uac00 \uc4f4 \uc790\ub8cc\ub294 \uc5b8\ub370\ub4dc\uac00 \uc5b4\ub5bb\uac8c \ube5b\uc744 \ub2e4\ub8e8\uac8c \ub418\uc5c8\ub294\uc9c0 \uc544\uc9c1 \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4."],unknowns:["Forever\uc5d0\uc11c \ud3ec\uc138\uc774\ud070 \uc131\uae30\uc0ac\uac00 \uc5b4\ub5bb\uac8c \ube5b\uc744 \ub2e4\ub8e8\uac8c \ub418\uc5c8\ub294\uc9c0\ub294 \uc774 \uc548\ub0b4\uc11c\uac00 \uc4f0\ub294 \uc790\ub8cc\uc5d0\uc11c \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4."]},"class:hunter":{title:"\uc0ac\ub0e5\uafbc",summary:"\uc21c\ucc30\uc790, \uc18c\ucd1d\uc218, \uc57c\uc218\uc870\ub828\uc0ac\uc778 \uc0ac\ub0e5\uafbc\uc740 \ud65c\uacfc \ucd1d, \uadf8\ub9ac\uace0 \ucda9\uc9c1\ud55c \ub3d9\ubb3c\uacfc\uc758 \uc720\ub300\ub85c \uc0b4\uc544\uac04\ub2e4.",body:["\uc0ac\ub0e5\uafbc\uc740 \ud65c\uacfc \ucd1d, \uadf8\ub9ac\uace0 \uc57c\uc218\uc640\uc758 \uc720\ub300\ub85c \uc0b4\uc544\uac04\ub2e4. \uc5ec\ub7ec \uc138\ub300\uc5d0 \uac78\uccd0 \uc708\ub4dc\ub7ec\ub108 \uac00\ubb38\uc774 \uc774\ub048 \ucfe0\uc5d8\ud0c8\ub77c\uc2a4\uc758 \uc21c\ucc30\uc790\ub4e4\uc740 \uc5d8\ud504\uc758 \uc232\uc744 \uc9c0\ucf30\uace0, \ub4dc\uc6cc\ud504 \uc18c\ucd1d\uc218\uc640 \uc640\uc77c\ub4dc\ud574\uba38\uc758 \uadf8\ub9ac\ud3f0 \uae30\uc218\ub4e4\uc740 \uc81c2\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \uc2f8\uc6e0\uc73c\uba70, \ub098\uc774\ud2b8 \uc5d8\ud504 \ud30c\uc218\uafbc\uacfc \ud2b8\ub864 \ud5e4\ub4dc\ud5cc\ud130\ub4e4\uc740 \uce7c\ub9bc\ub3c4\uc5b4\uc640 \uac00\uc2dc\ub364\ubd88 \uace8\uc9dc\uae30\uc758 \uc232\uc744 \ub204\ube48\ub2e4.","\uc774\uc57c\uae30 \uc18d\uc5d0\uc11c \uac00\uc7a5 \ub048\uc9c8\uae34 \uc0dd\uc874\uc790\ub4e4 \uac00\uc6b4\ub370 \uba87\uba87\uc740 \uc0ac\ub0e5\uafbc\uc774\ub2e4. \uc54c\ub808\ub9ac\uc544 \uc708\ub4dc\ub7ec\ub108\ub294 \uc5b4\ub460\uc758 \ubb38 \ub108\uba38\ub85c \uc9c4\uad70\ud574 \ub05d\ub0b4 \ub3cc\uc544\uc624\uc9c0 \uc54a\uc558\uace0, \uadf8\ub140\uc758 \ub3d9\uc0dd \uc2e4\ubc14\ub098\uc2a4\ub294 \ub9c8\uc9c0\ub9c9 \uc228\uc744 \uac70\ub458 \ub54c\uae4c\uc9c0 \uc544\uc11c\uc2a4\uc640 \uc2f8\uc6e0\uc73c\uba70, \uc57c\uc218\uc870\ub828\uc0ac \ub809\uc0ac\ub974\ub294 \ub370\uc77c\ub9b0 \ud504\ub77c\uc6b0\ub4dc\ubb34\uc5b4\uc5d0 \ub9de\uc120 \ud638\ub4dc\uc758 \uc6a9\uc0ac\uac00 \ub418\uc5c8\ub2e4. Forever\uc5d0\uc11c\ub294 \uc778\uac04\ub3c4 \uc774 \uae38\uc744 \uac78\uc744 \uc218 \uc788\uace0, \ub450 Skyborne \ubd84\ud30c \ubaa8\ub450 \uc0ac\ub0e5\uafbc\uc744 \ud488\uace0 \uc788\ub2e4."]},"class:rogue":{title:"\ub3c4\uc801",summary:"\ucca9\uc790, \ub3c4\ub451, \uc554\uc0b4\uc790\uc778 \ub3c4\uc801\uc740 \uba85\uc608\uac00 \ub9dd\uc124\uc774\ub294 \uacf3\uc5d0\uc11c \uc6c0\uc9c1\uc774\uba70, \uadf8\ub4e4\uc758 \uae38\ub4dc \uac00\uc6b4\ub370 \uba87\uba87\uc740 \uc870\uc6a9\ud788 \uc5ed\uc0ac\ub97c \ube5a\uc5b4 \uc654\ub2e4.",body:["\ub3c4\uc801\uc740 \uba85\uc608\uac00 \ub9dd\uc124\uc774\ub294 \uacf3\uc5d0\uc11c \uc6c0\uc9c1\uc778\ub2e4. \ub3c4\ub451\uacfc \ucca9\uc790\uc640 \uc554\uc0b4\uc790\ub294 \uc5b4\ub290 \ub3c4\uc2dc\uc5d0\ub098 \uc788\uc9c0\ub9cc, \uadf8\ub4e4\uc758 \uc870\uc9c1 \uac00\uc6b4\ub370 \uba87\uba87\uc740 \uc5ed\uc0ac\ub97c \ube5a\ub294\ub2e4. \ub9c8\ud2f0\uc544\uc2a4 \uc1fc\uac00 \uc774\ub044\ub294 \uc2a4\ud1b0\uc708\ub4dc\uc758 \uc815\ubcf4\ubd80 SI:7, \uc54c\ud130\ub799 \uc0b0\ub9e5\uc5d0 \uc228\uc740 \ub808\uc774\ube10\ud640\ud2b8\uc758 \uc554\uc0b4\uc790\ub4e4, \ubab0\ub77d\ud55c \uc54c\ud130\ub799 \uadc0\uc871\uc5d0\uac8c\uc11c \uc0dd\uaca8\ub09c \uc2e0\ub514\ucf00\uc774\ud2b8, \uadf8\ub9ac\uace0 \uc11c\ubd80 \ubab0\ub77d\uc9c0\ub300\ub97c \ub5a0\ub3c4\ub294 \ub370\ud53c\uc544\uc988 \ub2e8\uc774 \uadf8\ub807\ub2e4.","\ucd08\uae30 \uc804\uc7c1\uc5d0\uc11c \uac00\uc7a5 \uc720\uba85\ud55c \ub3c4\uc801\uc740 \ub808\uc778 \uad6d\uc655\uc744 \uce7c\ub85c \uc8fd\uc778 \ud558\ud504\uc624\ud06c \ucca9\uc790 \uac00\ub85c\ub098 \ud558\ud504\uc624\ub974\uc13c\uc774\uc5c8\ub2e4. 25\ub144\uc5d0\ub294 \ub3c4\uc801 \uad50\uad00\ub4e4\uc774 \uc2a4\ud1b0\uc708\ub4dc\uc758 \uad6c \uc2dc\uac00\uc9c0\uc640 \uc5b8\ub354\uc2dc\ud2f0\uc758 \ub3c4\uc801 \uc9c0\uad6c\uc5d0\uc11c \uac00\ub974\uce58\uba70, \ud0c0\uc6b0\ub80c\uc744 \uc81c\uc678\ud55c \ud50c\ub808\uc774\ud560 \uc218 \uc788\ub294 \ubaa8\ub4e0 \uc885\uc871\uc774 \uc774 \uc77c\uc744 \ubc30\uc6b8 \uc218 \uc788\ub2e4. Forever\ub294 \ub450 \ubd84\ud30c\uc758 Skyborne\uc744 \uadf8\ub9bc\uc790 \uc18d\uc5d0 \ub354\ud55c\ub2e4."]},"class:priest":{title:"\uc0ac\uc81c",summary:"\uc0ac\uc81c\ub294 \uc131\uc2a4\ub7ec\uc6b4 \ube5b\uc774\ub098 \ub2ec\uc758 \uc5ec\uc2e0 \uc5d8\ub8ec, \ud639\uc740 \ub354 \uc624\ub798\ub418\uace0 \uc5b4\ub450\uc6b4 \ud798\uc744 \uc12c\uae30\uba70, \ub3d9\ub8cc\ub97c \uce58\uc720\ud558\uace0 \ud544\uc694\ud560 \ub54c\ub294 \uc801\uc744 \ubb34\ub108\ub728\ub9b0\ub2e4.",body:["\uc0ac\uc81c\ub294 \uc5ec\ub7ec \ud615\ud0dc\uc758 \ubbff\uc74c\uc744 \uc12c\uae34\ub2e4. \uc2a4\ud1b0\uc708\ub4dc\uc758 \ube5b\uc758 \ub300\uc131\ub2f9\uc744 \uc911\uc2ec\uc73c\ub85c \ud558\uba70 \ud55c\ub54c \ub300\uc8fc\uad50 \uc54c\ub860\uc11c\uc2a4 \ud30c\uc62c\uc774 \uc774\ub04c\uc5c8\ub358 \uc778\uac04\uc758 \uc131\uc2a4\ub7ec\uc6b4 \ube5b\uc758 \uad50\ud68c\ub294, \ube5b\uc774 \uc5b4\ub290 \ud55c \uc2e0\uc774 \uc544\ub2c8\ub77c \ub355 \uc18d\uc5d0 \uae43\ub4e0\ub2e4\uace0 \uac00\ub974\uce58\uba70, \ub4dc\uc6cc\ud504\ub3c4 \uadf8 \uac00\ub974\uce68\uc744 \ubc1b\uc544\ub4e4\uc600\ub2e4. \ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \uc5ec\uc0ac\uc81c\ub4e4\uc740 \uace0\ub300\uc758 \uc804\uc7c1 \uc774\ub798 \ud2f0\ub780\ub370 \uc704\uc2a4\ud37c\uc708\ub4dc\uac00 \uc774\ub04c\uc5b4 \uc628 \uc790\ub9e4\ud68c\uc5d0\uc11c \ub2ec\uc758 \uc5ec\uc2e0 \uc5d8\ub8ec\uc744 \uc12c\uae34\ub2e4.","\ub2e4\ub978 \uc774\ub4e4\uc740 \ub354 \uc5b4\ub450\uc6b4 \uae38\uc744 \uac77\ub294\ub2e4. \ud3ec\uc138\uc774\ud070 \uc0ac\uc81c\ub4e4\uc740 \uadf8\ub4e4\ub9cc\uc758 \uc74c\uc6b8\ud55c \uc2e0\uc559\uc744 \uc9c0\ud0a4\uace0, \ud2b8\ub864 \uc0ac\uc81c\ub4e4\uc740 \uc870\uc0c1\uc758 \ub85c\uc544\ub97c \uc12c\uae30\uba70, \uc554\ud751 \ub9c8\ubc95\uc740 \ub9ce\uc740 \uc0ac\uc81c\uc758 \uae30\uc220 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. Forever\uc5d0\uc11c\ub294 \uc624\ub7ab\ub3d9\uc548 \uae30\uc220\uc790\uc758 \uc885\uc871\uc73c\ub85c \uc54c\ub824\uc9c4 \ub178\uc6c0\uc774 \ucc98\uc74c\uc73c\ub85c \uc0ac\uc81c\uac00 \ub420 \uc218 \uc788\uc73c\uba70, \ube14\ub9ac\uc790\ub4dc\ub294 \uadf8\ub4e4\uc5d0\uac8c \uace0\uc720\ud55c \uc885\uc871 \uc0ac\uc81c \uc8fc\ubb38\uc744 \uc8fc\uc5c8\ub2e4."]},"class:shaman":{title:"\uc8fc\uc220\uc0ac",summary:"\uc8fc\uc220\uc0ac\ub294 \ub300\uc9c0, \ubd88, \ubb3c, \ubc14\ub78c\uc758 \uc815\ub839\uc5d0\uac8c \ub3c4\uc6c0\uc744 \uccad\ud55c\ub2e4. \ud55c \uc138\ub300 \ub3d9\uc548 \uc624\ud06c\uc5d0\uac8c\uc11c \ub04a\uacbc\ub358 \uc804\ud1b5\uc744 \uc2a4\ub784\uc774 \ub418\uc0b4\ub838\ub2e4.",body:["\uc8fc\uc220\uc0ac\ub294 \ub300\uc9c0\uc640 \ubd88\uacfc \ubb3c\uacfc \ubc14\ub78c\uc758 \uc815\ub839\uacfc \ub300\ud654\ud558\uba70, \uba85\ub839\ud558\uc9c0 \uc54a\uace0 \ubd80\ud0c1\ud55c\ub2e4. \ub4dc\ub808\ub178\uc5b4\uc5d0\uc11c \uc624\ud06c \uc8fc\uc220\uc0ac\ub4e4\uc740 \ubc31\uc131\uc758 \uae38\uc7a1\uc774\uc600\uc9c0\ub9cc, \ub12c\uc974\uc758 \ud0c0\ub77d\uc774 \uadf8\ub4e4\uc744 \ud751\ub9c8\ubc95\uc0ac\ub85c \ubc14\uafb8\uc5b4 \ub193\uc558\uace0, \ud55c \uc138\ub300 \ub3d9\uc548 \uc815\ub839\ub4e4\uc740 \uc624\ud06c\uc5d0\uac8c \uc804\ud600 \uc751\ub2f5\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc2a4\ub784\uc740 \uc11c\ub9ac\ub291\ub300 \ubd80\uc871\uc758 \ub4dc\ub809\ud0c0\ub974\uc5d0\uac8c \ubc30\uc6cc \uadf8 \uc804\ud1b5\uc744 \ub418\uc0b4\ub838\uace0, \uadf8\uac83\uc744 \uc911\uc2ec\uc73c\ub85c \ud638\ub4dc\ub97c \ub2e4\uc2dc \uc138\uc6e0\ub2e4.","\uba40\uace0\uc5b4\uc758 \ud0c0\uc6b0\ub80c\uacfc \uac80\uc740\ucc3d \ud2b8\ub864\ub3c4 \uadf8\ub4e4 \ub098\ub984\uc758 \uc8fc\uc220 \ud48d\uc2b5\uc744 \uc9c0\ud0a4\uace0 \uc788\uc73c\uba70, \uc2a4\ub784\uc740 \uc5ec\uc804\ud788 \uc624\uadf8\ub9ac\ub9c8\uc758 \uc8fc\uc220\uc0ac\ub4e4\uc744 \uc774\ub048\ub2e4. Forever\ub294 \ub450 \uc0c8 \uc5bc\uad74\uc744 \ub354\ud55c\ub2e4. \uc6d0\uc791\uc5d0\uc11c\ub294 \uc8fc\uc220\uc0ac\uac00 \uc5c6\ub358 \ub4dc\uc6cc\ud504, \uadf8\ub9ac\uace0 \ubc14\ub78c\uc758 \uc815\ub839\uacc4 Skywall\uc5d0 \ub5a0 \uc788\ub294 \uc12c Zephras Isle\uc5d0\uc11c \uc628 Windshaper Skyborne\uc774\ub2e4."],unknowns:["Forever\uc5d0\uc11c \ub4dc\uc6cc\ud504\uac00 \uc5b4\ub5bb\uac8c \uc8fc\uc220\uc744 \ubc1b\uc544\ub4e4\uc600\ub294\uc9c0\ub294 \uc774 \uc548\ub0b4\uc11c\uac00 \uc4f0\ub294 \uc790\ub8cc\uc5d0\uc11c \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4."]},"class:warlock":{title:"\ud751\ub9c8\ubc95\uc0ac",summary:"\uc9c0\uc625 \ub9c8\ubc95\uacfc \uc18d\ubc15\ub41c \uc545\ub9c8\uc758 \uc8fc\uc778\uc778 \ud751\ub9c8\ubc95\uc0ac\ub294 \ud638\ub4dc\uc640 \ud568\uaed8 \uc544\uc81c\ub85c\uc2a4\uc5d0 \uc654\uc73c\uba70, \ud798\uacfc \ud30c\uba78 \uc0ac\uc774\uc758 \uc881\uc740 \uae38\uc744 \uac77\ub294\ub2e4.",body:["\ud751\ub9c8\ubc95\uc0ac\ub294 \uc9c0\uc625 \ub9c8\ubc95\uc5d0\uc11c \ud798\uc744 \ub04c\uc5b4\ub0b4\uace0 \uc545\ub9c8\ub97c \uc790\uc2e0\uc758 \uc758\uc9c0\uc5d0 \ubb36\ub294\ub2e4. \uc774 \uae30\uc220\uc740 \ud638\ub4dc\uc640 \ud568\uaed8 \uc544\uc81c\ub85c\uc2a4\uc5d0 \uc654\ub2e4. \ud0ac\uc81c\ub374\uc774 \uc774\ub97c \uad74\ub2e8\uc5d0\uac8c \uac00\ub974\ucce4\uace0, \uad74\ub2e8\uc758 \uc5b4\ub460\uc758 \uc758\ud68c\ub294 \uc624\ud06c \uc8fc\uc220\uc0ac\ub4e4\uc744 \ud751\ub9c8\ubc95\uc0ac\ub85c \ubc14\uafb8\uc5b4 \uadf8\ub4e4\uc758 \uc8fc\ubb38\uc744 \uc704\ud574 \ub4dc\ub808\ub178\uc5b4\uc758 \uc0dd\uba85\ub825\uc744 \ube68\uc544\ub4e4\uc600\ub2e4. \uc8fd\uc74c\uc758 \uae30\uc0ac\uc640 \uc545\ub9c8\uc758 \ud53c\uc758 \uc800\uc8fc\ub294 \uadf8 \uac00\uc7a5 \uc5b4\ub450\uc6b4 \uc5f4\ub9e4\uc600\ub2e4.","\ubaa8\ub4e0 \ud751\ub9c8\ubc95\uc0ac\uac00 \uad70\ub2e8\uc744 \uc12c\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc778\uac04 \ud751\ub9c8\ubc95\uc0ac\ub4e4\uc740 \uc2a4\ud1b0\uc708\ub4dc\uc758 \uc120\uc220\uc9d1 Slaughtered Lamb \uc544\ub798\uc5d0\uc11c \ubab0\ub798 \ubaa8\uc774\uace0, \ub178\uc6c0\uacfc \ud3ec\uc138\uc774\ud070\ub3c4 \uc774 \uae30\uc220\uc744 \uc5f0\uad6c\ud558\uba70, \uc2a4\ub784\uc758 \ud638\ub4dc\ub294 \uc624\ud06c \ud751\ub9c8\ubc95\uc0ac\ub4e4\uc744 \uacbd\uacc4\ud558\uba70 \ubc1b\uc544\ub4e4\uc778\ub2e4. \ubaa8\ub4e0 \ud751\ub9c8\ubc95\uc0ac\ub294 \uac19\uc740 \uc904 \uc704\ub97c \uac77\ub294\ub2e4. \ud798\uc740 \uc9c4\uc9dc\uc774\uace0, \uadf8 \ud798\uc5d0 \uc0bc\ucf1c\uc9c8 \uc704\ud5d8\ub3c4 \uc9c4\uc9dc\ub2e4. Forever\uc5d0\uc11c\ub294 \ud2b8\ub864\ub3c4 \ud751\ub9c8\ubc95\uc0ac\uac00 \ub420 \uc218 \uc788\ub2e4."]},"class:druid":{title:"\ub4dc\ub8e8\uc774\ub4dc",summary:"\ubc18\uc2e0 \uc138\ub098\ub9ac\uc6b0\uc2a4\uc5d0\uac8c\uc11c \ucc98\uc74c \ubc30\uc6b4, \ubaa8\uc2b5\uc744 \ubc14\uafb8\ub294 \uc790\uc5f0\uc758 \uc218\ud638\uc790\uc778 \ub4dc\ub8e8\uc774\ub4dc\ub294 \ub2ec\uc758 \uc232\uc5d0\uc11c \uc5d0\uba54\ub784\ub4dc\uc758 \uafc8\uae4c\uc9c0 \uc138\uacc4\uc758 \uade0\ud615\uc744 \uc9c0\ud0a8\ub2e4.",body:["\ub4dc\ub8e8\uc774\ub4dc\ub294 \uc790\uc5f0\uc758 \uade0\ud615\uc744 \uc9c0\ud0a4\uba70 \uc57c\uc218\uc758 \ubaa8\uc2b5\uc744 \ucde8\ud560 \uc218 \uc788\ub2e4. \ub9d0\ud4e8\ub9ac\uc628 \uc2a4\ud1b0\ub808\uc774\uc9c0\ub294 \ubc18\uc2e0 \uc138\ub098\ub9ac\uc6b0\uc2a4\uc5d0\uac8c\uc11c \uadf8 \uae30\uc220\uc744 \ubc30\uc6cc \ucd5c\ucd08\uc758 \ub4dc\ub8e8\uc774\ub4dc\uac00 \ub418\uc5c8\uace0, \uadf8\uc758 \ucd94\uc885\uc790\ub4e4\uc740 \ud30c\uc218\uafbc\uc774 \ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \uc232\uc744 \uc9c0\ud0a4\ub294 \ub3d9\uc548 \uc5d0\uba54\ub784\ub4dc\uc758 \uafc8\uc5d0\uc11c \uc218\ubc31 \ub144\uc529 \uc7a0\ub4e4\uc5c8\ub2e4. \uc131\uc2a4\ub7ec\uc6b4 \uc232\uc778 \ub2ec\uc758 \uc232\uc5d0 \ud130\ub97c \ub454 \uc138\ub098\ub9ac\uc628 \uc758\ud68c\ub294 \uc774\uc81c \ubaa8\ub4e0 \uc885\uc871\uc758 \ub4dc\ub8e8\uc774\ub4dc\ub97c \ud558\ub098\ub85c \ubaa8\uc740\ub2e4.","\uc81c3\ucc28 \ub300\uc804\uc7c1 \uc774\ud6c4 \ub9d0\ud4e8\ub9ac\uc628\uc740 \ud0c0\uc6b0\ub80c\uc5d0\uac8c \ub4dc\ub8e8\uc774\ub4dc\uc758 \uae30\uc220\uc744 \uac00\ub974\ucce4\uace0, \ud558\ubb3c \ub8ec\ud1a0\ud15c\uc774 \ucd5c\ucd08\uc758 \ud0c0\uc6b0\ub80c \ub4dc\ub8e8\uc774\ub4dc\uac00 \ub418\uc5c8\ub2e4. 25\ub144\uc5d0 \ub4dc\ub8e8\uc774\ub4dc\ub4e4\uc740 \uae4a\uc740 \uadfc\uc2ec\uc5d0 \ube60\uc838 \uc788\ub2e4. \uc138\uacc4\uc218 \ub180\ub4dc\ub78f\uc2e4\uc740 \uc0c1\ucc98\ub97c \uc785\uc5c8\uace0, \ud154\ub4dc\ub78f\uc2e4\uc740 \uc704\uc0c1\ub4e4\uc758 \ucd95\ubcf5 \uc5c6\uc774 \uc790\ub77c\ub0ac\uc73c\uba70, \uc545\ubabd\uc774 \uc5d0\uba54\ub784\ub4dc\uc758 \uafc8 \uc18d\uc73c\ub85c \ud37c\uc9c0\uace0 \uc788\ub2e4. Forever\uc5d0\uc11c\ub294 \ub450 Skyborne \ubd84\ud30c \ubaa8\ub450 \ub4dc\ub8e8\uc774\ub4dc\ub97c \ud488\uace0 \uc788\ub2e4."]}}},1792,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"races",{enumerable:!0,get:function(){return o}});const o={"race:human":{title:"\uc778\uac04",summary:"\uc544\ub77c\uc18c\ub974\uc758 \ud6c4\uc608\uc774\uc790 \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc758 \uc911\ucd94\uc778 \uc778\uac04\uc740 \uc544\uc81c\ub85c\uc2a4 \uc5ed\uc0ac\uc758 \ubaa8\ub4e0 \uc804\uc7c1\uc5d0\uc11c \ub300\uac00\ub97c \uce58\ub800\uc9c0\ub9cc, \uc5ec\uc804\ud788 \ub2e4\uc2dc \uc77c\uc5b4\uc120\ub2e4.",body:["\uc778\uac04\uc740 \uc5b4\ub460\uc758 \ubb38\uc73c\ub85c\ubd80\ud130 \uac70\uc758 \uc0bc\ucc9c \ub144 \uc804\uc5d0 \uc18c\ub77c\ub518 \uc655\uc774 \uc544\ub77c\uc18c\ub974\ub85c \ud1b5\ud569\ud55c \ubd80\uc871\ub4e4\uc758 \ud6c4\uc190\uc774\ub2e4. \uc544\ub77c\uc18c\ub974\uc758 \ud6c4\uacc4\uc790\ub4e4\uc740 \uc77c\uacf1 \uc778\uac04 \uc655\uad6d\uc744 \uc138\uc6e0\uace0, \uc5d8\ud504\ub4e4\uc740 \uadf8\ub4e4\uc758 \uccab \ub9c8\ubc95\uc0ac\ub97c \uac00\ub974\ucce4\uc73c\uba70, \uc131\uc2a4\ub7ec\uc6b4 \ube5b\uc5d0 \ub300\ud55c \ubbff\uc74c\uc740 \ud6d7\ub0a0 \uc131\uae30\uc0ac\ub97c \ub0b3\uc558\ub2e4. \uc778\ub958\ub294 \uc81c1\ucc28, \uc81c2\ucc28, \uc81c3\ucc28 \ub300\uc804\uc7c1 \ub0b4\ub0b4 \uc5bc\ub77c\uc774\uc5b8\uc2a4\ub97c \ub5a0\ubc1b\ucce4\uace0, \uadf8 \ub300\uac00\ub294 \ucef8\ub2e4. \uc2a4\ud1b0\uc708\ub4dc\ub294 \ud55c \ubc88 \ubd88\ud0d4\uace0, \ub85c\ub370\ub860\uc740 \uc2a4\uceec\uc9c0\uc5d0\uac8c \ubb34\ub108\uc84c\ub2e4.","25\ub144\uc758 \uc2a4\ud1b0\uc708\ub4dc\ub294 \uc778\uac04 \uc138\ub825\uc758 \uc2ec\uc7a5\uc774\ub2e4. \ud770 \ub3cc\ub85c \uc7ac\uac74\ub418\uc5c8\uc9c0\ub9cc \ub370\ud53c\uc544\uc988, \ud589\ubc29\ubd88\uba85\ub41c \ubc14\ub9ac\uc548 \uad6d\uc655, \uadf8\ub9ac\uace0 \ud504\ub808\uc2a4\ud1a8 \ubd80\uc778\uc758 \ub9c8\ubc95\uc5d0 \uac78\ub9b0 \uad81\uc815 \ub54c\ubb38\uc5d0 \ud3b8\ud560 \ub0a0\uc774 \uc5c6\ub2e4. \uc0c8\ub85c\uc6b4 \uc778\uac04\uc740 \uc5d8\uc708 \uc232\uc758 \ubd81\ub158\uace8 \uc218\ub3c4\uc6d0\uc5d0\uc11c \ubaa8\ud5d8\uc744 \uc2dc\uc791\ud55c\ub2e4. Forever\uc5d0\uc11c\ub294 \uc6d0\uc791\uc774 \ub2e4\ub978 \uc885\uc871\uc5d0\uac8c\ub9cc \ud5c8\ub77d\ud588\ub358 \uc0ac\ub0e5\uafbc\uc758 \uae38\uc744 \uc778\uac04\ub3c4 \uac78\uc744 \uc218 \uc788\ub2e4."]},"race:gnome":{title:"\ub178\uc6c0",summary:"\uc870\uc0c1\uc774 \ud2f0\ud0c4\uc758 \uae30\uacc4\uc600\ub358 \ub6f0\uc5b4\ub09c \ubc1c\uba85\uac00 \ub178\uc6c0\uc740 \ub3c4\uc2dc \ub188\ub9ac\uac74\uc744 \uc783\uace0 \uc544\uc774\uc5b8\ud3ec\uc9c0\uc5d0\uc11c \ub9dd\uba85 \uc0dd\ud65c\uc744 \ud558\uace0 \uc788\ub2e4.",body:["\ub178\uc6c0\uc740 \ubab8\uc9d1\uc740 \uc791\uc9c0\ub9cc \uc7ac\uc8fc\ub294 \uac70\ub300\ud558\ub2e4. \uadf8\ub4e4\uc758 \uc870\uc0c1\uc778 \uae30\uacc4\ub178\uc6c0\uc740 \ud2f0\ud0c4\uc774 \ub9cc\ub4e0 \uae30\uacc4\uc600\ub294\ub370, \ud6d7\ub0a0 \uc0b4\ub369\uc774\uc758 \uc800\uc8fc\uc5d0 \uac78\ub824 \uc0b4\uc544 \uc788\ub294 \uc874\uc7ac\uac00 \ub418\uc5c8\ub2e4. \uadf8\ub4e4\uc740 \ub358 \ubaa8\ub85c\uc5d0 \ud1b1\ub2c8\ubc14\ud034\uc640 \uc99d\uae30\uc758 \ub3c4\uc2dc \ub188\ub9ac\uac74\uc744 \uc138\uc6e0\uace0, \uc774\uc6c3\ud55c \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \ub4dc\uc6cc\ud504\uc640 \uad73\uac74\ud55c \ub3d9\ub9f9\uc744 \ub9fa\uc5b4 \uc81c2\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \ud568\uaed8 \uc2f8\uc6e0\ub2e4.","\uadf8 \ub3c4\uc2dc\ub294 \uc774\uc81c \uc783\uc5b4\ubc84\ub9b0 \uacf3\uc774\ub2e4. \ud2b8\ub85c\uadf8\ub4e4\uc774 \ub545\uc18d\uc5d0\uc11c \ubc00\ub824 \uc62c\ub77c\uc624\uc790, \ub188\ub9ac\uac74\uc744 \ubc29\uc0ac\ub2a5\uc73c\ub85c \uac00\ub4dd \ucc44\uc6b0\uc790\ub294 \uba55\uae30\ub2c8\uc5b4 \uc2dc\ucf54 \ud154\ub9c8\ud50c\ub7ec\uadf8\uc758 \uc870\uc5b8\uc740 \uc624\ud788\ub824 \ub3c4\uc2dc\ub97c \uc624\uc5fc\uc2dc\ucf30\ub2e4. \ub9ce\uc740 \ub178\uc6c0\uc774 \uc8fd\uc5c8\uace0, \uc0b4\uc544\ub0a8\uc740 \uc774\ub4e4 \uc911 \uc77c\ubd80\ub294 \ub4a4\ud2c0\ub9b0 \ub098\ubcd1 \ub178\uc6c0\uc774 \ub418\uc5c8\ub2e4. \ub55c\uc7a5\uc774\uc655 \uac94\ube48 \uba55\uce74\ud1a0\ud06c\ub294 \ub098\uba38\uc9c0\ub97c \uc774\ub04c\uace0 \uc544\uc774\uc5b8\ud3ec\uc9c0\ub85c \ub9dd\uba85\ud588\uace0, \ud154\ub9c8\ud50c\ub7ec\uadf8\ub294 \ud3d0\ud5c8\ub97c \ub2e4\uc2a4\ub9ac\uace0 \uc788\ub2e4. Forever\ub294 \ucc98\uc74c\uc73c\ub85c \ub178\uc6c0\uc5d0\uac8c \uc0ac\uc81c\uc758 \uae38\uc744 \uc5f4\uc5b4 \uc900\ub2e4."]},"race:night-elf":{title:"\ub098\uc774\ud2b8 \uc5d8\ud504",summary:"\uace0\ub300\uc758 \uce7c\ub3c4\ub808\uc774\ub294 \ub9cc \ub144 \ub3d9\uc548 \uce7c\ub9bc\ub3c4\uc5b4\ub97c \uc9c0\ucf1c \uc654\ub2e4. \uc774\uc81c \ud544\uba78\uc790\uac00 \ub41c \uadf8\ub4e4\uc740 \uc0c8\ub85c\uc6b4 \uc138\uacc4\uc218\ub97c \uc2ec\uace0 \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc5d0 \ud569\ub958\ud588\ub2e4.",body:["\ub098\uc774\ud2b8 \uc5d8\ud504, \uace7 \uce7c\ub3c4\ub808\uc774\ub294 \ud50c\ub808\uc774\ud560 \uc218 \uc788\ub294 \uc885\uc871 \uac00\uc6b4\ub370 \uac00\uc7a5 \uc624\ub798\ub418\uc5c8\ub2e4. \uc601\uc6d0\uc758 \uc0d8\uc5d0 \uc758\ud574 \ubcc0\ud55c \ud2b8\ub864\uc758 \ud6c4\uc190\uc778 \uadf8\ub4e4\uc740 \ub9c8\ubc95\uc758 \uc81c\uad6d\uc744 \uc138\uc6e0\uace0, \uace0\ub300\uc758 \uc804\uc7c1\uc5d0\uc11c \uc0b4\uc544\ub0a8\uc558\uc73c\uba70, \ud558\uc774\uc798 \uc0b0\uc758 \uadf8\ub298\uc5d0\uc11c \ub4dc\ub8e8\uc774\ub4dc\uc640 \ud30c\uc218\uafbc\uc758 \uc740\ub454 \ubbfc\uc871\uc73c\ub85c \ub9cc \ub144\uc744 \ubcf4\ub0c8\ub2e4. \uadf8\ub4e4 \uc0ac\uc774\uc5d0\uc11c \ube44\uc804 \ub9c8\ubc95\uc740 \uc5ec\uc804\ud788 \uae08\uc9c0\ub418\uc5b4 \uc788\ub2e4.","\uc81c3\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \uc544\ud0a4\ubaac\ub4dc\ub97c \ucc98\uce58\ud558\uae30 \uc704\ud574 \ub180\ub4dc\ub78f\uc2e4\uc774 \uc0c1\ucc98\ub97c \uc785\uc73c\uba74\uc11c \uadf8\ub4e4\uc740 \ubd88\uba78\uc744 \uc783\uc5c8\ub2e4. \ub9d0\ud4e8\ub9ac\uc628\uc774 \uc5d0\uba54\ub784\ub4dc\uc758 \uafc8\uc5d0\uc11c \uae38\uc744 \uc783\uc740 \uc0ac\uc774, \ub300\ub4dc\ub8e8\uc774\ub4dc \ud310\ub4dc\ub784 \uc2a4\ud0dc\uadf8\ud5ec\ub984\uc740 \uc5b4\ub460\ud574\uc548 \uc55e\ubc14\ub2e4\uc5d0 \uc0c8\ub85c\uc6b4 \uc138\uacc4\uc218 \ud154\ub4dc\ub78f\uc2e4\uc744 \ud0a4\uc6e0\uace0, \uadf8 \uac00\uc9c0 \uc704\uc5d0 \uc218\ub3c4 \ub2e4\ub974\ub098\uc11c\uc2a4\uac00 \uc138\uc6cc\uc84c\ub2e4. \ud2f0\ub780\ub370 \uc704\uc2a4\ud37c\uc708\ub4dc\uc758 \uc9c0\ub3c4 \uc544\ub798 \ub098\uc774\ud2b8 \uc5d8\ud504\ub294 \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc5d0 \ud569\ub958\ud588\ub2e4. \uc0c8\ub85c\uc6b4 \ub098\uc774\ud2b8 \uc5d8\ud504\ub294 \ud154\ub4dc\ub78f\uc2e4\uc758 \uc232\uc18d \uacf5\ud130\uc5d0\uc11c \ubaa8\ud5d8\uc744 \uc2dc\uc791\ud55c\ub2e4."]},"race:dwarf":{title:"\ub4dc\uc6cc\ud504",summary:"\ud2f0\ud0c4\uc758 \ub300\uc9c0\uc778\uc758 \uc790\uc190\uc778 \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \ub4dc\uc6cc\ud504\ub294 \uace0\uc9d1 \uc13c \ub3d9\ub9f9\uc774\uc790 \uc9c0\uce60 \uc904 \ubaa8\ub974\ub294 \ud0d0\ud5d8\uac00\uc774\uba70, \ubd84\uc5f4\ub41c \uc720\uc0b0\uc758 \uc218\ud638\uc790\ub2e4.",body:["\ub4dc\uc6cc\ud504\ub294 \uace0\uc9d1\uc774 \uc138\uace0 \ub9c8\uc74c\uc774 \ub530\ub73b\ud558\uba70 \ub3cc\uc5d0\uc11c \ud0dc\uc5b4\ub0ac\ub2e4. \uadf8\ub4e4\uc758 \uc870\uc0c1\uc740 \uc0b4\ub369\uc774\uc758 \uc800\uc8fc\ub85c \ubcc0\ud55c \ud2f0\ud0c4\uc758 \uc218\ud638\uc790, \ub300\uc9c0\uc778\uc774\uc5c8\ub2e4. \ub358 \ubaa8\ub85c\uc758 \uc0b0\uc744 \uae4e\uc544 \ub9cc\ub4e0 \uc544\uc774\uc5b8\ud3ec\uc9c0\ub294 \uc624\ub79c \uc138\uc6d4 \uadf8\ub4e4\uc758 \uc218\ub3c4\uc600\ub2e4. \uc138 \ub9dd\uce58\uc758 \uc804\uc7c1\uc740 \ud074\ub79c\ub4e4\uc744 \uac08\ub77c\ub193\uc558\ub2e4. \ube0c\ub860\uc988\ube44\uc5b4\ub4dc\ub294 \ub3c4\uc2dc\ub97c \uc9c0\ucf30\uace0, \uc640\uc77c\ub4dc\ud574\uba38\ub294 \ub3d9\ubd80 \ub0b4\ub959\uc9c0\uc5d0 \uc790\ub9ac \uc7a1\uc558\uc73c\uba70, \uac80\uc740\ubb34\uc1e0\ub294 \ub77c\uadf8\ub098\ub85c\uc2a4\ub97c \uc12c\uae30\ub294 \uc2e0\uc138\uac00 \ub418\uc5c8\ub2e4.","\ub9c8\uadf8\ub2c8 \ube0c\ub860\uc988\ube44\uc5b4\ub4dc \uc655 \uc544\ub798\uc5d0\uc11c \ub4dc\uc6cc\ud504\ub294 \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc758 \ubaa8\ub4e0 \uc804\uc7c1\uc5d0\uc11c \uc2f8\uc6e0\uace0, \uadf8\uc758 \ub3d9\uc0dd \ube0c\ub780\uc774 \uc8fc\uc694 \uc778\ubb3c\ub85c \ud65c\uc57d\ud558\ub294 \ud0d0\ud5d8\uac00 \uc5f0\ub9f9\uc740 \ub4dc\uc6cc\ud504\uc758 \uae30\uc6d0\uc744 \ucc3e\uc544 \uc6b8\ub2e4\ub9cc \uac19\uc740 \ud2f0\ud0c4 \uc720\uc801\uc744 \ud30c\ud5e4\uce5c\ub2e4. \ub9c8\uadf8\ub2c8\uc758 \ub538 \ubaa8\uc774\ub77c\ub294 \uac80\uc740\ubb34\uc1e0 \uc81c\uc655\uc758 \uc544\ub0b4\uac00 \ub418\uc5c8\uace0, \uc655\uc740 \uc774\ub97c \uac1c\uc778\uc801\uc778 \uc0c1\ucc98\ub85c \uc5ec\uae34\ub2e4. Forever\ub294 \ub4dc\uc6cc\ud504 \uad70\uc8fc\ub4e4\uc758 \uc548\uc2dd\ucc98\uc778 \uc544\uc774\uc5b8\ud3ec\uc9c0 \uc9c0\ud558\uc758 Hall of Thanes\ub97c \ub354\ud55c\ub2e4. \uadf8\uacf3\uc740 \uc9c0\uae08 \uac80\uc740\ubb34\uc1e0\ub85c \uc5ec\uaca8\uc9c0\ub294 \uce68\uc785\uc790\ub4e4\uc5d0\uac8c \ub6ab\ub838\uc73c\uba70, \ub4dc\uc6cc\ud504\ub294 \uc8fc\uc220\uc0ac\uc758 \uae38\ub3c4 \uac78\uc744 \uc218 \uc788\ub2e4."]},"race:skyborne-high-order":{title:"Skyborne: High Order",body:["Skyborne\uc740 \uc6d4\ub4dc \uc624\ube0c \uc6cc\ud06c\ub798\ud504\ud2b8: Forever\uc758 \uc0c8\ub85c\uc6b4 \ud50c\ub808\uc774 \uac00\ub2a5 \uc885\uc871\uc774\uba70, High Order\ub294 \uadf8\uc911 \uc5bc\ub77c\uc774\uc5b8\uc2a4 \ud3b8\uc5d0 \uc120 \ubd84\ud30c\ub2e4. \uadf8\ub4e4\uc758 \uace0\ud5a5\uc740 \ubc14\ub78c\uc758 \uc815\ub839\uacc4 Skywall\uc5d0 \ub5a0 \uc788\ub294 \uc12c Zephras Isle\ub85c, \ub300\uc7a5\ub85c Talaanis Shadowsong\uc774 \ub2e4\uc2a4\ub9ac\uba70 \uc8fc\uc694 \uc815\ucc29\uc9c0\ub294 Valanaar \ub9c8\uc744\uc774\ub2e4. \ud55c\ub54c \uc12c\uc5d0\uc11c Skyborne\uacfc \ud568\uaed8 \uc0b4\ub358 \ubc14\ub78c \uc815\ub839\ub4e4\uc740 \uc218\ubc31 \ub144 \uc804\uc5d0 \uc0ac\ub77c\uc84c\uace0, \uc12c\uc744 \uc9c0\ud0f1\ud558\ub294 \ub9c8\ubc95\uc740 \uc57d\ud574\uc9c0\uace0 \uc788\uc73c\uba70, \ud53c\ub09c\ubbfc\ub4e4\uc774 Zephras\ub85c \ubab0\ub824\ub4dc\ub294 \uac00\uc6b4\ub370 \uc790\ub9e4 \uc12c\uc778 Anvilas\uc640 Siroccas\uc640\uc758 \uc5f0\ub77d\uc740 \ub04a\uacbc\ub2e4.","High Order\uc758 \ubaa8\ud5d8\uac00\ub4e4\uc740 Valanaar\uc5d0\uc11c \uc54c\ud130\ub799 \uc0b0\ub9e5\uc758 \ub2ec\ub77c\ub780\uc73c\ub85c \uac00\ub294 \ube44\ud589\uc120\uc744 \ud0c0\uace0 \uc12c\uc744 \ub5a0\ub09c\ub2e4. \uadf8\ub4e4\uc740 \uc804\uc0ac, \uc0ac\ub0e5\uafbc, \ub3c4\uc801, \ub4dc\ub8e8\uc774\ub4dc, \ub9c8\ubc95\uc0ac\uac00 \ub420 \uc218 \uc788\uc73c\uba70, \ube44\uc804\uc744 \uc5f0\uad6c\ud558\ub294 \uc720\uc77c\ud55c Skyborne\uc774\ub2e4. \uadf8\ub4e4\uc758 \uc7ac\ub2a5\uc740 \uace0\ud5a5\uc744 \ub2ee\uc558\ub2e4. \ubc14\ub78c\uc744 \ud0c0\uace0 \ud65c\uac15\ud574 \ub0b4\ub824\uc624\uace0, \ube68\ub77c\uc9c4 \uac00\uc18d\uc73c\ub85c \uc6c0\uc9c1\uc774\uba70, \uc815\ub839\uc5d0\uac8c \ub354 \uac15\ud55c \ud53c\ud574\ub97c \uc8fc\uace0, \uadfc\ucc98\uc758 \uc9c0\ub9e5\uc744 \uc77d\uc5b4 \uc0dd\uba85\ub825\uacfc \ub9c8\ub098\ub97c \ud68c\ubcf5\ud55c\ub2e4. \uc774\ub4e4\uc744 \ud50c\ub808\uc774\ud558\ub824\uba74 \uc120\ud0dd \uc0c1\ud488\uc778 Skyborne Heroic \ub610\ub294 Epic Pack\uc774 \ud544\uc694\ud558\ub2e4."]},"race:skyborne-windshaper":{title:"Skyborne: Windshaper",body:["Windshaper\ub294 \ud638\ub4dc \ud3b8\uc5d0 \uc120 Skyborne\uc774\ub2e4. High Order\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uadf8\ub4e4\uc740 \ubc14\ub78c\uc758 \uc815\ub839\uacc4 Skywall\uc758 Zephras Isle \ucd9c\uc2e0\uc774\ub2e4. \uc774 \uc12c\uc758 \ubc14\ub78c \uc815\ub839\ub4e4\uc740 \uc218\ubc31 \ub144 \uc804\uc5d0 \uc0ac\ub77c\uc84c\uace0, \uc12c\uc744 \uc9c0\ud0f1\ud558\ub294 \ub9c8\ubc95\ub3c4 \uc11c\uc11c\ud788 \ud798\uc744 \uc783\uace0 \uc788\ub2e4. Anvilas\uc640 Siroccas \uac19\uc740 \uc12c\ub4e4\uc774 \uce68\ubb35\uc5d0 \ube60\uc9c0\uba74\uc11c \ud53c\ub09c\ubbfc\ub4e4\uc774 Zephras\ub85c \ubab0\ub824\ub4e4\uace0 \uc788\uc73c\uba70, Zephras\ub9c8\uc800 \ubb34\ub108\uc9c0\uae30 \uc2dc\uc791\ud588\ub2e4.","Windshaper\ub294 Valanaar\uc5d0\uc11c \ube44\ud589\uc120\uc744 \ud0c0\uace0 \uba40\uace0\uc5b4\uc758 Skywatcher Plateau\ub85c \ud5a5\ud55c\ub2e4. \uadf8\ub4e4\uc740 \uc804\uc0ac, \uc0ac\ub0e5\uafbc, \ub3c4\uc801, \ub4dc\ub8e8\uc774\ub4dc, \uc8fc\uc220\uc0ac\uac00 \ub420 \uc218 \uc788\uc73c\uba70, \uc8fc\uc220\uc0ac\uc758 \uae38\uc744 \uac77\ub294 \uc720\uc77c\ud55c Skyborne\uc774\ub2e4. \uadf8\ub4e4\uc740 \ubc14\ub78c\uc744 \ud0c0\uace0 \ud65c\uac15\ud558\uace0, \ube68\ub77c\uc9c4 \uac00\uc18d\uc73c\ub85c \uc2f8\uc6b0\uba70, \uc815\ub839\uc5d0\uac8c \ub354 \uac15\ud55c \ud53c\ud574\ub97c \uc900\ub2e4. \uadf8\ub4e4\ub9cc\uc758 \uc7ac\ub2a5\uc778 Skysight\ub294 \uc774\ub3d9 \uc18d\ub3c4\ub97c \ub192\uc5ec \uc8fc\uba70, \uc815\ub839\uc758 \ud569\ub958 \uc9c0\uc810 \uadfc\ucc98\uc5d0\uc11c\ub294 \ud6e8\uc52c \uc624\ub798 \uc9c0\uc18d\ub41c\ub2e4. High Order\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc120\ud0dd \uc0c1\ud488\uc778 Skyborne Heroic \ub610\ub294 Epic Pack\uc774 \ud544\uc694\ud558\ub2e4."]},"race:orc":{title:"\uc624\ud06c",summary:"\ud55c\ub54c \uc545\ub9c8\uc758 \ud53c\uc5d0 \uc608\uc18d\ub418\uc5c8\ub358 \uc624\ud06c\ub294 \uc2a4\ub784\uc5d0 \uc758\ud574 \ud574\ubc29\ub418\uc5c8\uace0, \uc774\uc81c \ubd89\uc740 \ub545 \ub4c0\ub85c\ud0c0\uc5d0\uc11c \uba85\uc608\ub97c \ub418\ucc3e\uace0 \uc788\ub2e4.",body:["\uc624\ud06c\ub294 \uc545\ub9c8\uc758 \ud53c\uc640 \uad74\ub2e8\uc758 \ud751\ub9c8\ubc95\uc0ac\ub4e4\uc5d0\uac8c \ub5a0\ubc00\ub824 \ud638\ub4dc\ub85c\uc11c \ub4dc\ub808\ub178\uc5b4\uc5d0\uc11c \uc544\uc81c\ub85c\uc2a4\ub85c \uac74\ub108\uc654\ub2e4. \uc81c2\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \ud328\ubc30\ud55c \ub4a4 \uadf8\ub4e4\uc740 \uc218\uc6a9\uc18c\uc5d0\uc11c \uc2dc\ub4e4\uc5b4 \uac14\ub294\ub370, \uc11c\ub9ac\ub291\ub300 \uc871\uc7a5 \ub4c0\ub85c\ud0c4\uc758 \uc544\ub4e4 \uc2a4\ub784\uc774 \uadf8\ub4e4\uc744 \ud574\ubc29\ud558\uace0 \uc870\uc0c1\uc758 \uc8fc\uc220 \uc804\ud1b5\uc744 \ub418\uc0b4\ub838\ub2e4.","\uc81c3\ucc28 \ub300\uc804\uc7c1 \uc774\ud6c4 \uc2a4\ub784\uc740 \ubc31\uc131\uc744 \uc774\ub04c\uace0 \uce7c\ub9bc\ub3c4\uc5b4\ub85c \uac00\uc11c \ub4c0\ub85c\ud0c0\uc640 \uadf8 \uc218\ub3c4 \uc624\uadf8\ub9ac\ub9c8\ub97c \uc138\uc6e0\ub2e4. \ub300\uc871\uc7a5\uc740 \uc9c0\uae08 \uadf8\uacf3\uc5d0\uc11c \ud0c0\uc6b0\ub80c, \uac80\uc740\ucc3d \ud2b8\ub864, \ud3ec\uc138\uc774\ud070\uacfc \ud568\uaed8\ud558\ub294 \ud638\ub4dc\ub97c \ub2e4\uc2a4\ub9b0\ub2e4. \uc624\ud06c\ub294 \uc790\ubd80\uc2ec\uc774 \uac15\ud558\uace0 \uc194\uc9c1\ud558\uba70 \ucda9\uc131\uc2a4\ub7fd\uc9c0\ub9cc, \uadf8\ub4e4\uc758 \ud53c\ub85c \uc5bc\ub8e9\uc9c4 \uacfc\uac70\ub294 \ub4c0\ub85c\ud0c0\uc758 \ubd88\ud0c0\ub294 \uce7c\ub0a0 \uad11\uc2e0\ub3c4\ub4e4\uacfc, \ub05d\ub0b4 \uc2a4\ub784\uc5d0\uac8c \ud569\ub958\ud558\uc9c0 \uc54a\uc740 \uac80\uc740\ubc14\uc704 \ubd80\uc871 \uc18d\uc5d0 \uc5ec\uc804\ud788 \ub0a8\uc544 \uc788\ub2e4. \uc0c8\ub85c\uc6b4 \uc624\ud06c\ub294 \uc2dc\ud5d8\uc758 \uace8\uc9dc\uae30\uc5d0\uc11c \ubaa8\ud5d8\uc744 \uc2dc\uc791\ud55c\ub2e4. Forever\uc5d0\uc11c\ub294 \uc624\ud06c\ub3c4 \ub9c8\ubc95\uc0ac\uac00 \ub420 \uc218 \uc788\ub2e4."]},"race:tauren":{title:"\ud0c0\uc6b0\ub80c",summary:"\ub300\uc9c0\ubaa8\uc2e0\uc744 \uc12c\uae30\ub294 \ucd08\uc6d0\uc758 \uc628\ud654\ud55c \uac70\uc778 \ud0c0\uc6b0\ub80c\uc740 \uba40\uace0\uc5b4\uc5d0 \ubcf4\uae08\uc790\ub9ac\ub97c \ucc3e\uc558\uace0, \uac10\uc0ac\ud558\ub294 \ub9c8\uc74c\uc73c\ub85c \ud638\ub4dc\uc5d0 \ud569\ub958\ud588\ub2e4.",body:["\ud0c0\uc6b0\ub80c\uc740 \ub300\uc9c0\ubaa8\uc2e0\uc744 \uc12c\uae30\uba70 \uc624\ub79c \uc138\uc6d4 \uce7c\ub9bc\ub3c4\uc5b4\uc758 \ud3c9\uc6d0\uc744 \ub5a0\ub3cc\uc544 \uc628 \uac70\ub300\ud558\uace0 \ud3c9\ud654\ub85c\uc6b4 \uc720\ubaa9\ubbfc\uc774\ub2e4. \uc81c3\ucc28 \ub300\uc804\uc7c1 \ubb34\ub835 \uadf8\ub4e4\uc740 \ucf04\ud0c0\uc6b0\ub85c\uc2a4\uc5d0\uac8c \ucad3\uacbc\ub294\ub370, \ub9c9 \ub3c4\ucc29\ud55c \uc2a4\ub784\uc758 \ud638\ub4dc\uac00 \ucf00\ub978 \ube14\ub7ec\ub4dc\ud6c4\ud504\uc758 \ubc31\uc131\uc774 \uc548\uc804\ud55c \uba40\uace0\uc5b4\uc5d0 \uc774\ub974\ub3c4\ub85d \ub3c4\uc654\ub2e4.","\ucf00\ub978\uc740 \ud769\uc5b4\uc838 \uc788\ub358 \uc5ec\ub7ec \ubd80\uc871\uc744 \ud1b5\ud569\ud558\uace0 \uba40\uace0\uc5b4 \ucd08\uc6d0 \uc704\ub85c \uc19f\uc740 \uac70\ub300\ud55c \uace0\uc6d0\uc5d0 \uc36c\ub354 \ube14\ub7ec\ud504\ub97c \uc138\uc6e0\uc73c\uba70, \ud0c0\uc6b0\ub80c\uc740 \uac10\uc0ac\uc640 \uc874\uacbd\uc758 \ub73b\uc73c\ub85c \ud638\ub4dc\uc5d0 \ud569\ub958\ud588\ub2e4. \uadf8\ub4e4\uc758 \ub4dc\ub8e8\uc774\ub4dc\ub294 \ub9d0\ud4e8\ub9ac\uc628 \uc2a4\ud1b0\ub808\uc774\uc9c0\uc5d0\uac8c\uc11c \uc9c1\uc811 \ubc30\uc6e0\uace0, \uc8fc\uc220\uc0ac\uc640 \uc0ac\ub0e5\uafbc\ub4e4\uc740 \uc61b \uc804\ud1b5\uc744 \uc9c0\ucf1c \uac00\uace0 \uc788\ub2e4. \uc624\ud06c\uc640\uc758 \uc720\ub300\ub97c \ubabb\ub9c8\ub545\ud558\uac8c \uc5ec\uae30\ub294 \uadf8\ub9bc\ud1a0\ud15c \uac19\uc740 \uacbd\uc7c1 \ubd80\uc871\uc740 \ub298 \uac71\uc815\uac70\ub9ac\ub2e4. \uc5b4\ub9b0 \ud0c0\uc6b0\ub80c\uc740 \uba40\uace0\uc5b4\uc758 \ub098\ub77c\uccb4 \uc57c\uc601\uc9c0\uc5d0\uc11c \ubaa8\ud5d8\uc744 \uc2dc\uc791\ud55c\ub2e4."]},"race:troll":{title:"\ud2b8\ub864",summary:"\ubab0\ub77d\ud55c \uc81c\uad6d\uc758 \ud6c4\uc608\uc778 \ud2b8\ub864\uc740 \ub300\ubd80\ubd84 \uc5ec\uc804\ud788 \ub2e4\ub978 \uc885\uc871\uc744 \uc99d\uc624\ud558\uc9c0\ub9cc, \uac80\uc740\ucc3d \ubd80\uc871\ub9cc\uc740 \uc2a4\ub784\uacfc \ud638\ub4dc\uc5d0 \ucda9\uc131\uc744 \ub9f9\uc138\ud588\ub2e4.",body:["\ud2b8\ub864\uc740 \ud55c\ub54c \uac70\ub300\ud55c \uc81c\uad6d\ub4e4\uc744 \ub2e4\uc2a4\ub838\ub2e4. \ub0a8\ucabd \ubc00\ub9bc\uc758 \uad6c\ub8e8\ubc14\uc2dc, \ubd81\ucabd \uc232\uc758 \uc544\ub9c8\ub2c8, \uadf8\ub9ac\uace0 \uc2a4\uc2a4\ub85c\ub97c \ubaa8\ub4e0 \ud2b8\ub864\uc758 \uc2dc\ucd08\ub77c \ubd80\ub974\ub294 \uc794\ub2ec\ub77c\uac00 \uadf8\ub4e4\uc774\ub2e4. \ub098\uc774\ud2b8 \uc5d8\ud504, \ud558\uc774 \uc5d8\ud504, \uc778\uac04\uacfc\uc758 \uc804\uc7c1\uc740 \uadf8 \uc81c\uad6d\ub4e4\uc744 \ubb34\ub108\ub728\ub838\uace0, \ub300\ubd80\ubd84\uc758 \ubd80\uc871\uc740 \uc5ec\uc804\ud788 \uc61b \uc99d\uc624\ub97c \ud488\uc740 \ucc44 \uc870\uc0c1\uc758 \uc815\ub839\uc2e0\uc778 \ub85c\uc544\uc5d0\uac8c \uae30\ub3c4\ud55c\ub2e4.","\uac80\uc740\ucc3d \ubd80\uc871\uc740 \ub2e4\ub974\ub2e4. \uacbd\uc7c1 \ubd80\uc871\ub4e4\uc5d0\uac8c \uac00\uc2dc\ub364\ubd88 \uace8\uc9dc\uae30\uc5d0\uc11c \ucad3\uaca8\ub09c \uac80\uc740\ucc3d \ud2b8\ub864\ub4e4\uc740 \uace0\ud5a5 \uc12c\uc744 \uc9c0\ud0a4\ub824 \uc2f8\uc6b0\uace0 \uc788\uc5c8\ub294\ub370, \uadf8\ub54c \ud3ed\ud48d\uc5d0 \ud729\uc4f8\ub9b0 \uc2a4\ub784\uc758 \ud568\ub300\uac00 \ub3c4\ucc29\ud588\ub2e4. \uc871\uc7a5 \uc13c\uc9c4\uc740 \uadf8\uacf3\uc5d0\uc11c \uc228\uc744 \uac70\ub450\uc5c8\uace0, \uadf8\uc758 \uc544\ub4e4 \ubcfc\uc9c4\uc740 \ubd80\uc871\uc744 \uc774\ub04c\uace0 \ud638\ub4dc\uc5d0 \ucda9\uc131\uc744 \ub9f9\uc138\ud588\ub2e4. \uadf8\ub4e4\uc740 \ub4c0\ub85c\ud0c0 \uc55e\ubc14\ub2e4\uc758 \uba54\uc544\ub9ac \uc12c\uc5d0 \uc815\ucc29\ud588\uc9c0\ub9cc, \ubd80\ub450\uc220\uc0ac \uc798\ub77c\uc81c\uc778\uc758 \uc5b4\ub460\uc758 \ub9c8\ubc95 \ub54c\ubb38\uc5d0 \ubcf8\ud1a0\uc758 \uc13c\uc9c4 \ub9c8\uc744\ub85c \ubc00\ub824\ub0ac\ub2e4. Forever\uc5d0\uc11c\ub294 Darkspear Raiders\uac00 \uba3c\uc9c0\uc9c4\ud759 \uc2b5\uc9c0\ub300 \uc55e\ubc14\ub2e4\uc758 Darkspear Islands\ub97c \ub450\uace0\ub3c4 \ub2e4\ud22c\uba70, \ud2b8\ub864\uc740 \ud751\ub9c8\ubc95\uc0ac\uac00 \ub420 \uc218 \uc788\ub2e4."]},"race:undead":{title:"\uc5b8\ub370\ub4dc",summary:"\ub9ac\uce58 \uc655\uc5d0\uac8c\uc11c \ubc97\uc5b4\ub09c, \uc5ed\ubcd1\uc73c\ub85c \ub418\uc0b4\uc544\ub09c \ud76c\uc0dd\uc790\ub4e4\uc778 \ud3ec\uc138\uc774\ud070\uc740 \ub85c\ub370\ub860 \ud3d0\ud5c8 \uc544\ub798\uc758 \uc5b8\ub354\uc2dc\ud2f0\ub97c \ub2e4\uc2a4\ub9ac\uba70 \ub204\uad6c\ub3c4 \ubbff\uc9c0 \uc54a\ub294\ub2e4.",body:["\ud3ec\uc138\uc774\ud070\uc740 \ud55c\ub54c \ub85c\ub370\ub860\uc758 \uc2dc\ubbfc\uc774\uc5c8\ub2e4. \uc5ed\ubcd1\uc73c\ub85c \uc8fd\uc5b4 \uc2a4\uceec\uc9c0\uc5d0 \uc758\ud574 \ub418\uc0b4\uc544\ub0ac\ub2e4\uac00, \ub9ac\uce58 \uc655\uc758 \ud798\uc774 \ud754\ub4e4\ub9ac\uc790 \uc790\uc720 \uc758\uc9c0\ub97c \ub418\ucc3e\uc740 \uc774\ub4e4\uc774\ub2e4. \ubc34\uc2dc \uc5ec\uc655 \uc2e4\ubc14\ub098\uc2a4 \uc708\ub4dc\ub7ec\ub108\uc758 \uc9c0\ud718 \uc544\ub798, \uadf8\ub4e4\uc740 \ub85c\ub370\ub860 \uc218\ub3c4\uc758 \ud3d0\ud5c8\ub97c \ucc28\uc9c0\ud558\uace0 \uadf8 \uc544\ub798 \uc5b8\ub354\uc2dc\ud2f0\ub97c \ubcf4\uae08\uc790\ub9ac\ub85c \uc0bc\uc558\ub2e4. \uadf8\ub4e4\uc758 \ub545\uc778 \ud2f0\ub9ac\uc2a4\ud314 \uc232\uacfc \uc740\ube5b\uc18c\ub098\ubb34 \uc232\uc740 \uc2a4\uceec\uc9c0\uc640 \ubd89\uc740\uc2ed\uc790\uad70\uc774 \ub178\ub9ac\ub294 \ubd84\uc7c1 \uc9c0\uc5ed\uc774\ub2e4.","\ud3ec\uc138\uc774\ud070\uc740 \uc5b4\uca54 \uc218 \uc5c6\ub294 \ub3d9\ub9f9\uc73c\ub85c \ud638\ub4dc\uc5d0 \ud569\ub958\ud588\ub2e4. \uadf8\ub4e4\uc744 \ubbff\ub294 \uc0b0 \uc790\ub294 \uac70\uc758 \uc5c6\uc73c\uba70, \uc0c8\ub85c\uc6b4 \uc5ed\ubcd1\uc744 \uc5f0\uad6c\ud558\ub294 \uc655\ub9bd \uc5f0\uae08\uc220 \ud559\ud68c\uc758 \ube44\ubc00 \uc791\uc5c5\uc740 \ub3d9\ub9f9\ub4e4\uc774 \uadf8\ub4e4\uc744 \uc758\uc2ec\ud560 \ucda9\ubd84\ud55c \uc774\uc720\uac00 \ub41c\ub2e4. \uc0c8\ub85c\uc6b4 \ud3ec\uc138\uc774\ud070\uc740 \ud2f0\ub9ac\uc2a4\ud314 \uc232\uc758 Deathknell\uc5d0\uc11c \uae68\uc5b4\ub09c\ub2e4. Forever\ub294 \ud3ec\uc138\uc774\ud070\uc774 \uc5b8\ub354\uc2dc\ud2f0 \uc704\uc758 \ubd80\uc11c\uc9c4 \ub3c4\uc2dc\ub97c \ub418\ucc3e\uc73c\ub824 \uc560\uc4f0\ub294 \ub358\uc804 Ruins of Lordaeron\uc744 \ub354\ud558\uace0, \ud3ec\uc138\uc774\ud070 \uc131\uae30\uc0ac\ub3c4 \ud5c8\uc6a9\ud55c\ub2e4. \uc774 \uc870\ud569\uc740 \uc774 \uc548\ub0b4\uc11c\uac00 \uc4f4 \uc790\ub8cc\uc5d0\uc11c \uc544\uc9c1 \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4."],unknowns:["Forever\uc5d0\uc11c \ud3ec\uc138\uc774\ud070 \uc131\uae30\uc0ac\uac00 \uc5b4\ub5bb\uac8c \uc0dd\uaca8\ub0ac\ub294\uc9c0\ub294 \uc774 \uc548\ub0b4\uc11c\uac00 \uc4f0\ub294 \uc790\ub8cc\uc5d0\uc11c \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4."]}}},1793,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"zones1",{enumerable:!0,get:function(){return o}});const o={"zone:dun-morogh":{title:"\ub358 \ubaa8\ub85c",summary:"\uc544\uc774\uc5b8\ud3ec\uc9c0\ub97c \ub458\ub7ec\uc2fc \ub208 \ub36e\uc778 \uace8\uc9dc\uae30\ub85c, \ub4dc\uc6cc\ud504\uc640 \ub3c4\uc2dc\ub97c \uc783\uc740 \ub178\uc6c0\uc758 \ubcf4\uae08\uc790\ub9ac\ub2e4.",body:["\uce74\uc988 \ubaa8\ub2e8\uc758 \ubd09\uc6b0\ub9ac\ub4e4\uc5d0 \ub458\ub7ec\uc2f8\uc778 \ub358 \ubaa8\ub85c\ub294 \ub208\ubc2d\uacfc \uc5bc\uc5b4\ubd99\uc740 \ud638\uc218, \ub4dc\uc6cc\ud504 \uac10\uc2dc\ud0d1\uc758 \ub545\uc774\ub2e4. \uadf8 \uc2ec\uc7a5\uc740 \ub9c8\uadf8\ub2c8 \uc655\uc774 \ub2e4\uc2a4\ub9ac\ub294 \ube0c\ub860\uc988\ube44\uc5b4\ub4dc \ud074\ub79c\uc758 \uc0b0\uc545 \ub3c4\uc2dc \uc544\uc774\uc5b8\ud3ec\uc9c0\uc774\uba70, \uc5b4\ub9b0 \ub4dc\uc6cc\ud504\uc640 \ub178\uc6c0\uc740 \uc544\ub291\ud55c Coldridge Valley\uc640 \uc591\uc870 \ub9c8\uc744 \uce74\ub77c\ub178\uc2a4 \uc8fc\ubcc0\uc5d0\uc11c \ucc98\uc74c \ubb34\uae30\ub97c \ub4e0\ub2e4. \uc11c\ub9ac\uac08\uae30 \ud2b8\ub864\uacfc \ub545\uc744 \ud30c\uace0\ub4dc\ub294 \ud2b8\ub85c\uadf8\uac00 \uace8\uc9dc\uae30\ub97c \uad34\ub86d\ud78c\ub2e4.","\uc11c\ucabd\uc5d0\ub294 \ub178\uc6c0 \uacf5\ud559\uc758 \uacbd\uc774\uc778 \ub188\ub9ac\uac74\uc774 \uc788\ub2e4. \ud2b8\ub85c\uadf8\uac00 \ub545\uc18d\uc5d0\uc11c \uc19f\uad6c\uce58\uace0 \uc218\ube44\ub300\uac00 \ud544\uc0ac\uc801\uc73c\ub85c \uc3df\uc544\ubd80\uc740 \ubc29\uc0ac\ub2a5\uc774 \ub3c4\uc2dc\ub97c \uc624\uc5fc\uc2dc\ud0a4\uba74\uc11c \uc783\uc5b4\ubc84\ub9b0 \uacf3\uc774\ub2e4. \uadf8 \uc0dd\uc874\uc790\ub4e4\uc740 \uc9c0\uae08 \uc544\uc774\uc5b8\ud3ec\uc9c0\uc5d0\uc11c \uc190\ub2d8\uc73c\ub85c \uc0b4\uc544\uac04\ub2e4. Forever\uc5d0\uc11c\ub294 \ub3c4\uc2dc \uc544\ub798 Hall of Thanes\uc758 \uc655\uc2e4 \ubb34\ub364\uc774 \ud138\ub838\uc73c\uba70, \uac80\uc740\ubb34\uc1e0 \uce68\uc785\uc790\ub4e4\uc774 \uc758\uc2ec\ubc1b\uace0 \uc788\ub2e4."]},"zone:durotar":{title:"\ub4c0\ub85c\ud0c0",summary:"\uc2a4\ub784\uc774 \uc544\ubc84\uc9c0\uc758 \uc774\ub984\uc744 \ubd99\uc778 \uac70\uce5c \ubd89\uc740 \ud574\uc548\uc73c\ub85c, \uc624\ud06c\ub4e4\uc774 \uc624\uadf8\ub9ac\ub9c8\ub97c \uc138\uc6b4 \uacf3\uc774\ub2e4.",body:["\uc2a4\ub784\uc740 \ud638\ub4dc\ub97c \uc774\ub04c\uace0 \uce7c\ub9bc\ub3c4\uc5b4\uc5d0 \uc654\uc744 \ub54c \ud587\ubcd5\uc5d0 \uac08\ub77c\uc9c4 \uc774 \ub3d9\ucabd \ud574\uc548 \uc9c0\ub300\ub97c \ucc28\uc9c0\ud558\uace0 \uc544\ubc84\uc9c0 \ub4c0\ub85c\ud0c4\uc758 \uc774\ub984\uc744 \ub530 \ub4c0\ub85c\ud0c0\ub77c \ubd88\ub800\ub2e4. \ubd89\uc740 \ud759\uacfc \ub3cc\ud22c\uc131\uc774 \ud611\uace1\uc740 \uc624\ud06c\ub4e4\uc5d0\uac8c \ub4dc\ub808\ub178\uc5b4\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud588\ub2e4. \uadf8\ub4e4\uc740 \uac00\uc2dc\uba67\ub3fc\uc9c0\ub97c \ubab0\uc544\ub0b4\uace0 \ubd81\ucabd\uc758 \uc0b0\uace8\uc9dc\uae30\uc5d0 \uc624\uadf8\ub9bc \ub460\ud574\uba38\uc758 \uc774\ub984\uc744 \ub534 \uc624\uadf8\ub9ac\ub9c8\ub97c \uc138\uc6e0\ub2e4.","\uc5b4\ub9b0 \uc624\ud06c\uc640 \ud2b8\ub864\uc740 \uc2dc\ud5d8\uc758 \uace8\uc9dc\uae30\uc5d0\uc11c \uc2e4\ub825\uc744 \uc99d\uba85\ud55c \ub4a4 \uce7c\ubc14\uc704 \uc5b8\ub355\uc73c\ub85c \ud5a5\ud55c\ub2e4. \ud574\uc548\uc5d0\uc11c\ub294 \ubd80\ub450\uc220\uc0ac \uc798\ub77c\uc81c\uc778\uc774 \uba54\uc544\ub9ac \uc12c\uc758 \ub3d9\uc871\uc744 \ub178\uc608\ub85c \uc0bc\uc740 \ub4a4\ub85c \uac80\uc740\ucc3d \ud2b8\ub864\uc774 \uc13c\uc9c4 \ub9c8\uc744\uc744 \uc9c0\ud0a4\uace0 \uc788\uc73c\uba70, \ucfe8 \ud2f0\ub77c\uc2a4 \ubcd1\uc0ac\ub4e4\uc740 \ud2f0\ub77c\uac00\ub4dc \uc694\uc0c8\uc5d0 \uba38\ubb3c\ub7ec \uc788\ub2e4. \ubd88\ud0c0\ub294 \uce7c\ub0a0\uc758 \uad11\uc2e0\ub3c4\ub4e4\uc774 \uc5b8\ub355\uc5d0 \uc228\uc5b4 \uc788\uace0, \uadf8 \uc790\ub9e4 \uad50\ub2e8\uc778 \uc774\uae00\uac70\ub9ac\ub294 \uce7c\ub0a0\uc740 \uc218\ub3c4 \uc544\ub798\uc758 \uc131\ub09c\ubd88\uae38 \ud611\uace1\uc5d0 \uc228\uc5b4 \uc788\ub2e4."]},"zone:elwynn-forest":{title:"\uc5d8\uc708 \uc232",summary:"\uc2a4\ud1b0\uc708\ub4dc \uc655\uad6d\uc758 \ud478\ub978 \uc2ec\uc7a5\ubd80\ub85c, \ub9ce\uc740 \uc778\uac04 \uc601\uc6c5\uc774 \uccab\uac78\uc74c\uc744 \ub0b4\ub51b\ub294 \uacf3\uc774\ub2e4.",body:["\uc5d8\uc708 \uc232\uc740 \uc2a4\ud1b0\uc708\ub4dc \uc655\uad6d\uc758 \uc628\ud654\ud55c \uc2ec\uc7a5\ubd80\ub2e4. \uc81c1\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \ud638\ub4dc\uac00 \ud30c\uad34\ud55c \ub4a4 \uc7ac\uac74\ub41c \uc2a4\ud1b0\uc708\ub4dc\uc758 \ud770 \uc131\ubcbd \ub458\ub808\ub85c \ucc38\ub098\ubb34 \uc232\uacfc \ub18d\uc7a5, \ud638\uc218\uac00 \ud3bc\uccd0\uc838 \uc788\ub2e4. \uc218\ub828\uc0dd\ub4e4\uc740 \ubd81\ub158\uace8 \uc218\ub3c4\uc6d0\uc5d0\uc11c \ud6c8\ub828\ud558\uace0, \uc5ec\ud589\uc790\ub4e4\uc740 \ud669\uae08\uace8\uc758 \uc0ac\uc790\uc655 \uc5ec\uad00\uc5d0\uc11c \uc26c\uc5b4 \uac04\ub2e4.","\ud3c9\ud654\ub294 \ubcf4\uae30\ubcf4\ub2e4 \uc587\ub2e4. \ucf54\ubcfc\ud2b8\uac00 \uad11\uc0b0\uc744 \ucc28\uc9c0\ud588\uace0, \uac15\ubc1c\ud1b1 \ub180\uc774 \uc11c\ucabd \ub18d\uc7a5\uc744 \uc57d\ud0c8\ud558\uba70, \uba40\ub85d\uc774 \ud638\uc218\uc5d0 \ub4dd\uc2dc\uae00\uac70\ub9ac\uace0, \ub370\ud53c\uc544\uc988 \ub3c4\uc801\ub4e4\uc774 \uc774\uc6c3\ud55c \uc11c\ubd80 \ubab0\ub77d\uc9c0\ub300\uc5d0\uc11c \ud37c\uc838 \ub098\uc628\ub2e4. \uc218\ub3c4 \uc548\uc5d0\uc11c\ub294 \uc2a4\ud1b0\uc708\ub4dc \uc9c0\ud558\uac10\uc625\uc774 \ub370\ud53c\uc544\uc988 \uc8c4\uc218\ub4e4\uc758 \ud3ed\ub3d9\uc5d0 \ub118\uc5b4\uac14\ub2e4."]},"zone:mulgore":{title:"\uba40\uace0\uc5b4",summary:"\uc36c\ub354 \ube14\ub7ec\ud504\uc758 \uace0\uc6d0\uc774 \uc6b0\ub69d \uc19f\uc740, \ubc14\ub78c\uc774 \ud729\uc4f0\ub294 \ud0c0\uc6b0\ub80c\uc758 \ud3c9\uc6d0.",body:["\uba40\uace0\uc5b4\ub294 \ud0c0\uc6b0\ub80c\uc758 \uc870\uc0c1 \ub300\ub300\uc758 \ucd08\uc6d0\uc73c\ub85c, \uc0b0\ub9e5\uc5d0 \ub458\ub7ec\uc2f8\uc778 \ud3c9\uc6d0\uacfc \uace0\uc6d0\uc758 \ud478\ub978 \ubd84\uc9c0\uc774\uba70 \ub3d9\ucabd \ubd88\ubaa8\uc758 \ub545\uc73c\ub85c \uac00\ub294 \uace0\uac1c\ub294 \ud558\ub098\ubfd0\uc774\ub2e4. \uc5ec\ub7ec \uc138\ub300 \ub3d9\uc548 \uc720\ubaa9\ubbfc \ud0c0\uc6b0\ub80c\uc740 \ucf04\ud0c0\uc6b0\ub85c\uc2a4\uc5d0\uac8c \ucad3\uacbc\ub294\ub370, \uc2a4\ub784\uc758 \ud638\ub4dc\uac00 \ub300\uc871\uc7a5 \ucf00\ub978 \ube14\ub7ec\ub4dc\ud6c4\ud504\ub97c \ub3c4\uc640 \uadf8\uc758 \ubc31\uc131\uc744 \uace0\ud5a5\uc73c\ub85c \uc774\ub04c\uc5c8\ub2e4. \uc774\uacf3\uc5d0\uc11c \uadf8\ub4e4\uc740 \uccab \uc601\uad6c \uc815\ucc29\uc9c0\ub97c \uc138\uc6e0\ub2e4. \ube14\ub7ec\ub4dc\ud6c4\ud504 \ub9c8\uc744, \uadf8\ub9ac\uace0 \ubc27\uc904 \ub2e4\ub9ac\ub85c \uc774\uc5b4\uc9c4 \ub192\uc740 \uace0\uc6d0 \uc704\uc5d0 \uc138\uc6b4 \uc218\ub3c4 \uc36c\ub354 \ube14\ub7ec\ud504\ub2e4.","\uc5b4\ub9b0 \ud0c0\uc6b0\ub80c\uc740 \ubd89\uc740\uad6c\ub984 \uace0\uc6d0\uc758 \ub098\ub77c\uccb4 \uc57c\uc601\uc9c0\uc5d0\uc11c \ud6c8\ub828\ud558\uace0, \ub180\uacfc \uac00\uc2dc\uba67\ub3fc\uc9c0, \ud22c\uc790\uac1c\ubc1c\ud68c\uc0ac\uc758 \ud0d0\uad11\uafbc\ub4e4\uc774 \ud3c9\uc6d0\uc744 \uc5b4\uc9c0\ub7fd\ud78c\ub2e4. Forever\uc5d0\uc11c\ub294 \ud638\ub4dc\uc758 Skyborne\uc774 Zephras Isle\uc5d0\uc11c \ube44\ud589\uc120\uc744 \ud0c0\uace0 Skywatcher Plateau\uc5d0 \ub3c4\ucc29\ud55c\ub2e4."]},"zone:teldrassil":{title:"\ud154\ub4dc\ub78f\uc2e4",summary:"\uce7c\ub9bc\ub3c4\uc5b4 \ubd81\ucabd \ud574\uc548 \uc55e\ubc14\ub2e4\uc5d0 \uc790\ub780 \ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \uc0c8 \uc138\uacc4\uc218\ub85c, \uadf8 \uac00\uc9c0 \uc704\uc5d0 \ub2e4\ub974\ub098\uc11c\uc2a4\uac00 \uc788\ub2e4.",body:["\uc81c3\ucc28 \ub300\uc804\uc7c1\uc73c\ub85c \ubd88\uba78\uc744 \uc783\uc740 \ub4a4, \ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \ub4dc\ub8e8\uc774\ub4dc\ub4e4\uc740 \uce7c\ub9bc\ub3c4\uc5b4 \ubd81\ucabd \ud574\uc548 \uc55e\ubc14\ub2e4\uc5d0 \uc0c8\ub85c\uc6b4 \uc138\uacc4\uc218\ub97c \ud0a4\uc6e0\ub2e4. \uadf8\ub4e4\uc740 \uadf8\uac83\uc744 '\ub300\uc9c0\uc758 \uc655\uad00'\uc774\ub77c\ub294 \ub73b\uc758 \ud154\ub4dc\ub78f\uc2e4\uc774\ub77c \uc774\ub984 \uc9d3\uace0, \uadf8 \uac00\uc9c0 \uc704\uc5d0 \ub2ec\ube5b\uc774 \ube44\uce58\ub294 \uc2e0\uc804\ub4e4\uc758 \ub3c4\uc2dc \ub2e4\ub974\ub098\uc11c\uc2a4\ub97c \uc138\uc6e0\ub2e4. \uadf8\uacf3\uc5d0\uc11c \ub300\uc5ec\uc0ac\uc81c \ud2f0\ub780\ub370 \uc704\uc2a4\ud37c\uc708\ub4dc\uac00 \ubc31\uc131\uc744 \uc774\ub048\ub2e4.","\uc774 \ub098\ubb34\ub294 \uc6a9\uc758 \uc704\uc0c1\ub4e4\uc758 \ucd95\ubcf5 \uc5c6\uc774 \uc2ec\uc5b4\uc84c\uace0, \uadf8 \uc131\uc7a5\uc740 \uae68\ub057\ud558\uc9c0 \uc54a\uc558\ub2e4. \ud0c0\ub77d\uc774 \uc232\uc758 \uc9d0\uc2b9\ub4e4\uc5d0\uac8c \uc2a4\uba70\ub4e4\uc5b4 Gnarlpine \ud37c\ubcfc\uadf8\ub4e4\uc744 \uc0ac\ub0a9\uac8c \ub9cc\ub4e4\uc5c8\ub2e4. \ub098\uc774\ud2b8 \uc5d8\ud504 \uc218\ub828\uc0dd\uc740 \uadf8\ub298 \uace8\uc9dc\uae30\uc5d0\uc11c \uc2dc\uc791\ud558\uba70, \ubfcc\ub9ac \uacc1\uc758 \ub8e8\ud14c\ub780 \ub9c8\uc744\uc5d0\uc11c \ucd9c\ubc1c\ud558\ub294 \ubc30\uac00 \uc12c\uacfc \uc5b4\ub460\ud574\uc548\uc744 \uc787\ub294\ub2e4."]},"zone:tirisfal-glades":{title:"\ud2f0\ub9ac\uc2a4\ud314 \uc232",summary:"\ub85c\ub370\ub860 \uc218\ub3c4\uc758 \ud3d0\ud5c8\ub97c \ub458\ub7ec\uc2fc \uc74c\uc6b8\ud55c \uc232\uc73c\ub85c, \uc9c0\uae08\uc740 \ud3ec\uc138\uc774\ud070\uc758 \uc2ec\uc7a5\ubd80\ub2e4.",body:["\ud2f0\ub9ac\uc2a4\ud314 \uc232\uc5d0\ub294 \ud55c\ub54c \ub85c\ub370\ub860\uc758 \uc218\ub3c4\uac00 \uc788\uc5c8\uace0, \uc218\ud638\uc790\ub97c \uc120\ucd9c\ud558\ub358 \ud2f0\ub9ac\uc2a4\ud314 \uc758\ud68c\ub294 \uc774 \uace0\uc694\ud55c \uc5b8\ub355\uc5d0\uc11c \uc5f4\ub9b0 \ube44\ubc00 \ud68c\ud569\uc5d0\uc11c \uc774\ub984\uc744 \ub530\uc654\ub2e4. \uc5ed\ubcd1\uacfc \uc655\uad6d\uc758 \ubab0\ub77d\uc740 \uc774 \ub545\uc744 \ubcd1\ub4e0 \ucd08\ub85d\ube5b \ud558\ub298 \uc544\ub798 \ub0a8\uaca8 \ub450\uc5c8\ub2e4. \ubb34\ub108\uc9c4 \uad81\uc804 \uc544\ub798\uc5d0\uc11c \uc2e4\ubc14\ub098\uc2a4 \uc708\ub4dc\ub7ec\ub108\uc758 \ud3ec\uc138\uc774\ud070\uc740 \uc5b8\ub354\uc2dc\ud2f0\ub97c \ubcf4\uae08\uc790\ub9ac\ub85c \uc0bc\uc558\uc73c\uba70, \uc0c8\ub85c \uc77c\uc5b4\ub09c \uadf8\ub4e4\uc758 \ub9dd\uc790\ub294 Deathknell\uc5d0\uc11c \uae68\uc5b4\ub098 \ube0c\ub9b4 \ub9c8\uc744\uc5d0 \ubaa8\uc778\ub2e4.","\uc801\ub4e4\uc740 \uc0ac\ubc29\uc5d0\uc11c \ubc00\ub824\uc628\ub2e4. \uc2a4\uceec\uc9c0\uc758 \uc794\ub2f9\uc774 \ub18d\uc7a5\uc744 \ub5a0\ub3cc\uace0, \ubd89\uc740\uc2ed\uc790\uad70\uc758 \uad11\uc2e0\ub3c4\ub4e4\uc774 \ubd81\ub3d9\ucabd\uc758 \ubd89\uc740\uc2ed\uc790\uad70 \uc218\ub3c4\uc6d0\uc744 \ucc28\uc9c0\ud558\uace0 \uc788\ub2e4. Forever\uc5d0\uc11c \ud3ec\uc138\uc774\ud070\uc740 \uba38\ub9ac \uc704\uc758 \ubd80\uc11c\uc9c4 \ub3c4\uc2dc\ub97c \ub418\ucc3e\uc73c\ub824 \ud558\ub294\ub370, Ruins of Lordaeron\uc5d0\uc11c\ub294 \ud55c \uac15\ub839\uc220\uc0ac\uac00 \ud798\uc744 \ubaa8\uc73c\uace0 \uc788\ub2e4\uace0 \ud55c\ub2e4."]},"zone:zephras-isle":{title:"Zephras Isle",summary:"\ubc14\ub78c\uc758 \uc815\ub839\uacc4 Skywall\uc5d0 \ub5a0 \uc788\ub294 \uc12c\uc73c\ub85c, Forever\uc758 Skyborne\uc774 \uc2dc\uc791\ud558\ub294 \ub545\uc774\ub2e4.",body:["Zephras Isle\uc740 \uc6d4\ub4dc \uc624\ube0c \uc6cc\ud06c\ub798\ud504\ud2b8: Forever\uc758 \uc0c8\ub85c\uc6b4 \ud50c\ub808\uc774 \uac00\ub2a5 \uc885\uc871 Skyborne\uc758 \uc2dc\uc791 \uc9c0\uc5ed\uc73c\ub85c, \uc120\ud0dd \uc0c1\ud488\uc778 Skyborne Heroic \ub610\ub294 Epic Pack\uc73c\ub85c \uc5f4\ub9b0\ub2e4. \uc12c\uc740 \ubc14\ub78c\uc758 \uc815\ub839\uacc4 Skywall\uc5d0 \ub5a0 \uc788\uc73c\uba70, \ud55c\ub54c Skyborne\uc740 \uc774\uacf3\uc744 \ubc14\ub78c \uc815\ub839\ub4e4\uacfc \ud568\uaed8 \uc37c\ub2e4. \uadf8 \uc815\ub839\ub4e4\uc740 \uc218\ubc31 \ub144 \uc804\uc5d0 \uc0ac\ub77c\uc84c\uace0, \uc12c\uc744 \ud558\ub298\uc5d0 \ub744\uc6b0\ub294 \ub9c8\ubc95\uc740 \uadf8 \ub4a4\ub85c \uacc4\uc18d \uc57d\ud574\uc9c0\uace0 \uc788\ub2e4. \uadf8\ub4e4\uacfc \ud568\uaed8 \ub2e4\ub978 Skyborne \uc12c\uc778 Anvilas, Siroccas\uc640\uc758 \uc5f0\ub77d\ub3c4 \ub04a\uacbc\ub2e4.","\uc774\uc81c \uadf8 \uc12c\ub4e4\uc740 \ubb34\ub108\uc9c0\uace0 \uc788\uace0, \ud53c\ub09c\ubbfc\ub4e4\uc740 Zephras\ub85c \ub3c4\ub9dd\uccd0 \uc624\uba70, Zephras \uc790\uccb4\ub3c4 \uac08\ub77c\uc9c0\uae30 \uc2dc\uc791\ud588\ub2e4. \ub300\uc7a5\ub85c Talaanis Shadowsong\uc740 Valanaar \ub9c8\uc744\uc5d0\uc11c \uc12c\uc744 \ub2e4\uc2a4\ub9ac\uba70, \uadf8\uacf3\uc758 \ube44\ud589\uc120 \uc120\ucc29\uc7a5\uc740 \uc5bc\ub77c\uc774\uc5b8\uc2a4\ub97c \uc704\ud574 \uc54c\ud130\ub799 \uc0b0\ub9e5\uc758 \ub2ec\ub77c\ub780\uc73c\ub85c, \ud638\ub4dc\ub97c \uc704\ud574 \uba40\uace0\uc5b4\uc758 Skywatcher Plateau\ub85c \ube44\ud589\uc120\uc744 \ubcf4\ub0b8\ub2e4."],unknowns:["\ubc14\ub78c \uc815\ub839\ub4e4\uc774 \uc65c \uc0ac\ub77c\uc84c\ub294\uc9c0\ub294 \uc774 \uc548\ub0b4\uc11c\uac00 \uc4f0\ub294 \uc790\ub8cc\uc5d0\uc11c \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4.","Skyborne\uacfc \uadf8 \ubd84\ud30c\ub4e4\uc758 \uae4a\uc740 \uae30\uc6d0\uc740 \uc544\uc9c1 \uc774 \uc548\ub0b4\uc11c\uc758 \uc790\ub8cc\uc5d0\uc11c \ub2e4\ub8e8\uc9c0 \uc54a\ub294\ub2e4.","\uc12c\uc758 \uc61b \ud1b5\uce58\uc790\uc778 Shal\u2019nan\uc740 \uc774\ub984\ub9cc \ub098\uc62c \ubfd0 \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4."]},"zone:darkshore":{title:"\uc5b4\ub460\ud574\uc548",summary:"\ub098\uc774\ud2b8 \uc5d8\ud504\uac00 \uc544\uc6b0\ubc84\ub2e4\uc778 \ud56d\uad6c\uc5d0\uc11c \uc9c0\ud0a4\ub294, \uc548\uac1c \ub080 \ud3d0\ud5c8\ud22c\uc131\uc774 \ud574\uc548.",body:["\uc5b4\ub460\ud574\uc548\uc740 \uce7c\ub9bc\ub3c4\uc5b4 \ubd81\uc11c\ucabd \ud574\uc548\uc744 \ub530\ub77c \uae38\uac8c \ubed7\uc740, \ube44\uc5d0 \uc816\uc5b4 \uc5b4\ub450\uc6b4 \ub545\uc73c\ub85c \uc138\uacc4\uc758 \ubd84\ub9ac \uc774\uc804 \uce7c\ub3c4\ub808\uc774 \ub3c4\uc2dc\ub4e4\uc758 \ubb34\ub108\uc838 \uac00\ub294 \ud3d0\ud5c8\uac00 \ud769\uc5b4\uc838 \uc788\ub2e4. \ub098\uc774\ud2b8 \uc5d8\ud504\ub294 \uc774\uacf3\uc744 \uc0c8 \uc601\ud1a0\uc758 \uc77c\ubd80\ub85c \uc5ec\uae30\uba70, \ud30c\uc218\uafbc\ub4e4\uc774 \uc544\uc6b0\ubc84\ub2e4\uc778 \ud56d\uad6c\uc5d0\uc11c \ub0a8\ucabd \uc7bf\ube5b \uace8\uc9dc\uae30\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\uc744 \uc21c\ucc30\ud55c\ub2e4.","\uae38\uc744 \ubc97\uc5b4\ub098\uba74 \uc704\ud5d8\uc774 \ub3c4\uc0ac\ub9b0\ub2e4. \uc720\ub839\ub4e4\uc774 \uc61b \ud3d0\ud5c8\ub97c \uac70\ub2d0\uace0, \ub098\uac00\uc640 \uba40\ub85d\uc774 \ud574\ubcc0\uc744 \ubc30\ud68c\ud558\uba70, \ud37c\ubcfc\uadf8\ub294 \uc232\uc5d0\uc11c \uc0ac\ub098\uc6cc\uc9c0\uace0, \ud669\ud63c\uc758 \ub9dd\uce58\uc640 Dark Strand\uc758 \uad11\uc2e0\ub3c4\ub4e4\uc774 \uc5b8\ub355\uc5d0 \uc228\uc5b4 \uc788\ub2e4. \uc544\uc6b0\ubc84\ub2e4\uc778\uc758 \ubc30\ub294 \ud154\ub4dc\ub78f\uc2e4\uacfc \uba54\ub124\uc2e4 \ud56d\uad6c, \uadf8\ub9ac\uace0 Forever\uc5d0\uc11c\ub294 \uc2a4\ud1b0\uc708\ub4dc\ub85c \ud5a5\ud558\uba70, Forever\uc758 \uc0c8 \ud56d\ub85c\uac00 \uc0ac\uc6b0\uc2a4\uc1fc\uc5b4\uc5d0\uc11c\ub3c4 \ub4e4\uc5b4\uc628\ub2e4."]},"zone:loch-modan":{title:"\ubaa8\ub2e8 \ud638\uc218",summary:"\ucee4\ub2e4\ub780 \ud638\uc218\ub97c Stonewrought Dam\uc774 \ub9c9\uace0 \uc788\ub294 \ub4dc\uc6cc\ud504\uc758 \uace0\uc6d0 \uace8\uc9dc\uae30.",body:["\ub358 \ubaa8\ub85c \ub3d9\ucabd\uc5d0\ub294 \ubaa8\ub2e8 \ud638\uc218\uac00 \uc788\ub2e4. \uc18c\ub098\ubb34\uc640 \uc790\uc791\ub098\ubb34\uac00 \uc6b0\uac70\uc9c4 \uc11c\ub298\ud55c \uace0\uc6d0 \uace8\uc9dc\uae30\ub85c, \ub4dc\uc6cc\ud504 \uacf5\ud559\uc758 \uacbd\uc774 \uc911 \ud558\ub098\uc778 Stonewrought Dam\uc774 \uac70\ub300\ud55c \ud638\uc218\ub97c \ub9c9\uace0 \uc788\ub2e4. \uadf8 \ub310\uc744 \uac80\uc740\ubb34\uc1e0 \uac74\ucd95\uac00\uac00 \uc124\uacc4\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uae30\uc5b5\ud558\ub294 \uc774\ub294 \ub4dc\ubb3c\ub2e4. \ud154\uc0ac\ub9c8 \ub9c8\uc744\uc774 \uae38\uc744 \uc9c0\ud0a4\uace0, \uc54c\uac00\uc988 \ucd08\uc18c\uac00 \ubd81\ucabd \uc800\uc2b5\uc9c0\ub85c \ud5a5\ud558\ub294 \uace0\uac1c\ub97c \uc9c0\ud0a8\ub2e4.","\uace8\uc9dc\uae30\ub294 \uc81c2\ucc28 \ub300\uc804\uc7c1\uc744 \uae30\uc5b5\ud55c\ub2e4. \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \ub4dc\uc6cc\ud504\uac00 \ubab0\uc544\ub0b4\uae30 \uc804\uae4c\uc9c0 \ud638\ub4dc\uac00 \uc774\uacf3\uc744 \ud729\uc4f8\uc5c8\ub2e4. \uc624\ub298\ub0a0 \uc704\ud5d8\uc740 \uc544\ub798\uc5d0\uc11c \uc62c\ub77c\uc628\ub2e4. Ironband\uc758 \ubc1c\uad74\uc9c0 \uac19\uc740 \uacf3\uc774 \uae4a\uc740 \uacf3\uc758 \ud2b8\ub85c\uadf8\ub97c \uae68\uc6e0\uace0, \ubaa8\uadf8\ub85c\uc26c \uc624\uc6b0\uac70\uac00 \uc5b8\ub355\uc744 \ucc28\uc9c0\ud588\uc73c\uba70, \uac80\uc740\ubb34\uc1e0 \ub4dc\uc6cc\ud504\ub294 \ub310 \uc790\uccb4\ub97c \uacf5\uaca9\ud558\uace0 \uc788\ub2e4."]},"zone:silverpine-forest":{title:"\uc740\ube5b\uc18c\ub098\ubb34 \uc232",summary:"\ub85c\ub370\ub860 \uc11c\ud574\uc548\uc758 \uc720\ub839 \uae43\ub4e0 \uc18c\ub098\ubb34 \uc232\uc73c\ub85c, \ud3ec\uc138\uc774\ud070\uacfc \ub291\ub300\uc778\uac04, \uadf8\ub9ac\uace0 \ub9c8\uc9c0\ub9c9 \uc778\uac04\ub4e4\uc774 \ub2e4\ud22c\ub294 \uacf3.",body:["\uc740\ube5b\uc18c\ub098\ubb34 \uc232\uc740 \ub85c\ub370\ub860\uc758 \ud5d8\ud55c \uc11c\ud574\uc548\uc744 \ub530\ub77c \ubed7\uc5b4 \uc788\uc73c\uba70, \uc740\ube5b \uaecd\uc9c8\uc758 \uc18c\ub098\ubb34\ub4e4\uc740 \uc774\uc81c \ubcd1\ub4e4\uc5b4 \uc548\uac1c\uc5d0 \ud729\uc2f8\uc5ec \uc788\ub2e4. \ud3ec\uc138\uc774\ud070\uc740 \uacf5\ub3d9\ubb18\uc9c0\ub97c \uac70\uc810\uc73c\ub85c \ubd81\ucabd\uc744 \uc7a5\uc545\ud558\uace0, \uc778\uac04 \uc0dd\uc874\uc790\ub4e4\uacfc \ub2ec\ub77c\ub780\uc5d0\uc11c \ubcf4\ub0b8 \ub9c8\ubc95\uc0ac\ub4e4\uc740 \uc570\ubc84\ubc00\uacfc \ub0a8\ucabd\uc5d0 \ub9e4\ub2ec\ub824 \uc788\ub2e4. \uadf8 \ub108\uba38\uc5d0\uc11c \uae38\ub2c8\uc544\uc2a4\ub294 \uadf8\ub808\uc774\uba54\uc778 \uc131\ubcbd \ub4a4\ub85c \uc2a4\uc2a4\ub85c\ub97c \ubd09\uc1c4\ud588\ub2e4.","\uc232\uc5d0\uc11c \uac00\uc7a5 \uc9d9\uc740 \uadf8\ub9bc\uc790\ub294 \ud55c\ub54c \ub0a8\uc791 \uc2e4\ubc84\ub808\uc778\uc758 \uc131\uc774\uc5c8\ub358 \uadf8\ub9bc\uc790\uc1a1\uacf3\ub2c8 \uc131\ucc44\ub2e4. \uc81c3\ucc28 \ub300\uc804\uc7c1 \ub3d9\uc548 \ub2ec\ub77c\ub780\uc758 \ub300\ub9c8\ubc95\uc0ac \uc544\ub8e8\uac08\uc740 \uc2a4\uceec\uc9c0\uc640 \uc2f8\uc6b0\ub824 \ub291\ub300\uc778\uac04\uc744 \uc18c\ud658\ud588\ub2e4\uac00 \ud1b5\uc81c\ub825\uc744 \uc783\uace0 \ubbf8\uccd0 \ubc84\ub838\uc73c\uba70, \uc774\uc81c \uadf8 \uc9d0\uc2b9\ub4e4\uc744 \uc790\uae30 \uc790\uc2dd\uc774\ub77c \ubd80\ub978\ub2e4. \uadf8\uc758 \uc800\uc8fc\ub294 \uc778\uadfc \ud30c\uc774\uc5b4\uc6b0\ub4dc \ub9c8\uc744\uc5d0\uae4c\uc9c0 \ub2ff\uc544, \uadf8\uacf3 \uc8fc\ubbfc\ub4e4\uc740 \ubc24\uc774 \ub418\uba74 \ub291\ub300\uc778\uac04\uc73c\ub85c \ubcc0\ud55c\ub2e4."]},"zone:westfall":{title:"\uc11c\ubd80 \ubab0\ub77d\uc9c0\ub300",summary:"\ubc84\ub824\uc9c4 \uc2a4\ud1b0\uc708\ub4dc\uc758 \uace1\ucc3d\uc9c0\ub300\ub85c, \uc9c0\uae08\uc740 \ub370\ud53c\uc544\uc988 \ub2e8\uc758 \uc601\uc5ed\uc774\ub2e4.",body:["\uc11c\ubd80 \ubab0\ub77d\uc9c0\ub300\ub294 \ud55c\ub54c \ud669\uae08\ube5b \ubc2d\uacfc \ud48d\ucc28\uac00 \ub298\uc5b4\uc120 \uc2a4\ud1b0\uc708\ub4dc\uc758 \uace1\ucc3d\uc9c0\ub300\uc600\ub2e4. \uc81c2\ucc28 \ub300\uc804\uc7c1 \uc774\ud6c4 \ub545\uc758 \ub300\ubd80\ubd84\uc774 \ubb35\ud600\uc84c\uace0, \uc655\uad6d\uc5d0\ub294 \uc774\uacf3\uc5d0 \uc4f8 \ub3c8\ub3c4 \ubcd1\uc0ac\ub3c4 \uc5c6\uc5c8\ub2e4. \uadf8 \ube48\uc790\ub9ac\ub97c \ub370\ud53c\uc544\uc988 \ub2e8\uc774 \ucc28\uc9c0\ud588\ub2e4. \uc2a4\ud1b0\uc708\ub4dc\ub97c \uc7ac\uac74\ud588\uc9c0\ub9cc \uadc0\uc871\ub4e4\uc774 \ub300\uac00\ub97c \uce58\ub974\uc9c0 \uc54a\uc790 \ubb34\ubc95\uc790\uac00 \ub41c \uc11d\uacf5\ub4e4\ub85c, \uc5d0\ub4dc\uc708 \ubc34\ud074\ub9ac\ud504\uac00 \uc774\ub048\ub2e4.","\ub370\ud53c\uc544\uc988\ub294 \ud3d0\ud5c8\uac00 \ub41c Moonbrook \ub9c8\uc744\uc744 \ub2e4\uc2a4\ub9ac\uba70 \uadf8 \uc544\ub798 \uc8fd\uc74c\uc758 \ud3d0\uad11\uc5d0 \uc870\uc120\uc18c\ub97c \uc228\uaca8 \ub450\uc5c8\uace0, \ub180\uacfc \uace0\uc7a5 \ub09c \uc218\ud655 \uace8\ub818\uc774 \ub0a8\uc740 \ub18d\uc7a5\uc744 \ub178\ub9b0\ub2e4. \uac10\uc2dc\uc758 \uc5b8\ub355\uc5d0\uc11c \uadf8\ub9ac\uc548 \uc2a4\ud0c0\uc6b0\ud2b8\ub9e8\ud2c0\uc774 \ubaa8\uc740 \ubbfc\ubcd1\ub300\ub9cc\uc774 \uc544\uc9c1 \uadf8\ub4e4\uc744 \ub9c9\uc544\uc11c\uace0 \uc788\ub2e4."]},"zone:barrens":{title:"\ubd88\ubaa8\uc758 \ub545",summary:"\ud669\uae08\uae38\uc774 \uac00\ub85c\uc9c0\ub974\ub294 \uce7c\ub9bc\ub3c4\uc5b4 \ud55c\uac00\uc6b4\ub370\uc758 \uad11\ud65c\ud55c \uc0ac\ubc14\ub098\ub85c, \ub300\ubd80\ubd84 \ud638\ub4dc\uac00 \uc7a5\uc545\ud558\uace0 \uc788\ub2e4.",body:["\ubd88\ubaa8\uc758 \ub545\uc740 \uce7c\ub9bc\ub3c4\uc5b4 \ud55c\uac00\uc6b4\ub370\uc5d0 \ud3bc\uccd0\uc9c4 \uac00\uc2dc\ub098\ubb34\uc640 \uc624\uc544\uc2dc\uc2a4, \ub9c8\ub978 \uac15\ubc14\ub2e5\uc758 \uad11\ud65c\ud55c \uc0ac\ubc14\ub098\ub2e4. \uc138\uacc4\uc758 \ubd84\ub9ac \uc774\uc804\uc5d0\ub294 \ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \ub3c4\uc2dc\ub4e4\uc774 \uc788\uc5c8\uc9c0\ub9cc, \uc9c0\uae08\uc740 \ud638\ub4dc\uac00 \ud06c\ub85c\uc2a4\ub85c\ub4dc\uc640 \ud0c0\uc6b0\ub77c\uc870 \uc57c\uc601\uc9c0\ub97c \uac70\uc810\uc73c\ub85c \uc774 \ub545\uc744 \uc7a5\uc545\ud558\uace0, \ud1b1\ub2c8\ud56d\uc758 \uace0\ube14\ub9b0\uc740 \ubc14\ub2f7\uae38\ub85c \ubb34\ubc95\ud56d\uacfc \uad50\uc5ed\ud558\uba70, \uc5bc\ub77c\uc774\uc5b8\uc2a4 \ubcd1\uc0ac\ub4e4\uc740 Northwatch Hold\uc5d0\uc11c \uac10\uc2dc\ud55c\ub2e4. Forever\uc5d0\uc11c\ub294 Durotar Supply and Logistics\uac00 \ud06c\ub85c\uc2a4\ub85c\ub4dc \uc11c\ucabd\uc758 \uc57c\uc601\uc9c0\uc5d0\uc11c \uad50\uc5ed\ud55c\ub2e4.","\ucf5c\uce74\ub974 \ucf04\ud0c0\uc6b0\ub85c\uc2a4\uc640 \uac00\uc2dc\uba67\ub3fc\uc9c0, \ud558\ud53c\uac00 \ud669\uae08\uae38\uc744 \uc9c0\ub098\ub294 \uc5ec\ud589\uc790\ub4e4\uc744 \uc2b5\uaca9\ud55c\ub2e4. \ub545 \uc544\ub798\uc5d0\ub294 \uc624\ub798\ub41c \uc0c1\ucc98 \uc138 \uacf3\uc774 \uc788\ub2e4. \ud55c \ub4dc\ub8e8\uc774\ub4dc\uc758 \uafc8\uc774 \uc545\ubabd\uc73c\ub85c \ubcc0\ud55c \ud1b5\uace1\uc758 \ub3d9\uad74, \uadf8\ub9ac\uace0 \uac00\uc2dc\uba67\ub3fc\uc9c0\uc5d0\uac8c \uc2e0\uc131\ud55c \uac00\uc2dc\ud22c\uc131\uc774 \uad74\uc778 \uac00\uc2dc\ub369\uad74 \uc6b0\ub9ac\uc640 \uac00\uc2dc\ub369\uad74 \uad6c\ub989\uc774\ub2e4."]},"zone:redridge-mountains":{title:"\ubd89\uc740\ub9c8\ub8e8 \uc0b0\ub9e5",summary:"\uc5d8\uc708 \ub3d9\ucabd\uc758 \ubd89\uc740 \uc5b8\ub355\uacfc \uace0\uc694\ud55c \ud638\uc218\ub85c, \ud638\uc22b\uace8\uc774 \ub180\uacfc \uac80\uc740\ubc14\uc704 \uc624\ud06c\uc5d0 \ub9de\uc11c \ubc84\ud2f0\ub294 \uacf3.",body:["\uc5d8\uc708 \ub3d9\ucabd\uc5d0 \uc19f\uc740 \ubd89\uc740\ub9c8\ub8e8 \uc0b0\ub9e5\uc740 \ubd89\uc740 \ubc14\uc704\uc640 \ud0a4 \ud070 \ub290\ub985\ub098\ubb34, \uac70\uc13c \uac15\uc758 \ub545\uc73c\ub85c, \uc2a4\ud1b0\uc708\ub4dc\uc5d0 \ubaa9\uc7ac\uc640 \uc0dd\uc120\uacfc \uace1\ubb3c\uc744 \ubcf4\ub0b8\ub2e4. \uc911\uc2ec \ub9c8\uc744\uc778 \ud638\uc22b\uace8\uc740 Lake Everstill \uae30\uc2ad\uc5d0 \uc788\uace0, Three Corners \uad50\ucc28\ub85c\uac00 \uc774\uacf3\uc744 \uc5d8\uc708\uacfc \uadf8\ub298\uc232\uc73c\ub85c \uc774\uc5b4 \uc900\ub2e4.","\uc774\uacf3\uc758 \ud3c9\ud654\ub294 \uc704\ud0dc\ub86d\ub2e4. \ubd89\uc740\ub9c8\ub8e8\uc758 \ub180\uc774 \ub18d\uc7a5\uc744 \uc57d\ud0c8\ud558\uace0, \ubd88\ud0c0\ub294 \ud3c9\uc6d0\uc5d0\uc11c \uc628 \uac80\uc740\ubc14\uc704 \uc624\ud06c\ub4e4\uc774 Stonewatch Keep\uc744 \ucc28\uc9c0\ud55c \ucc44 Render's Valley\uc5d0 \uc9c4\uc744 \ucce4\ub2e4. \uc624\ub798\uc804 \uac80\uc740\ubb34\uc1e0 \ub4dc\uc6cc\ud504\uac00 \uc774 \uc0b0\ub9e5\uc5d0 \uc655\uad6d\uc744 \uc138\uc6e0\uc9c0\ub9cc, \ud0c0\uc6b0\ub9bf\uc0b0\uc774 \ub77c\uadf8\ub098\ub85c\uc2a4\ub97c \uc18c\ud658\ud558\uba74\uc11c \ubd81\ucabd \ub545\uc774 \ubd88\ud0c0 \ubc84\ub838\ub2e4. Forever\uc5d0\uc11c\ub294 Azeroth Commerce Authority\uac00 Three Corners\uc5d0\uc11c \uad50\uc5ed\ud558\uace0, \uace0\uac1c\ub4e4\uc774 \ub3d9\ucabd Riverglades\ub85c \uc774\uc5b4\uc9c4\ub2e4."]},"zone:stonetalon-mountains":{title:"\ub3cc\ubc1c\ud1b1 \uc0b0\ub9e5",summary:"\ubd88\ubaa8\uc758 \ub545 \uc11c\ucabd\uc758 \ud5d8\uc900\ud55c \ubd09\uc6b0\ub9ac\ub4e4\ub85c, \ub098\uc774\ud2b8 \uc5d8\ud504\uc640 \ud0c0\uc6b0\ub80c\uc5d0\uac8c \uc2e0\uc131\ud558\uba70 \uace0\ube14\ub9b0\uc758 \ubc8c\ubaa9\uc73c\ub85c \uc0c1\ucc98 \uc785\uc5c8\ub2e4.",body:["\ub3cc\ubc1c\ud1b1 \uc0b0\ub9e5\uc740 \ubd88\ubaa8\uc758 \ub545 \uc11c\ucabd\uc5d0 \uc19f\uc544 \uc788\ub2e4. \ud558\ud53c\uc758 \uc624\ub79c \uace0\ud5a5\uc774\uc9c0\ub9cc, \uadf8 \ubb34\ub9ac\ub294 \uadf8 \ub4a4\ub85c \ud6e8\uc52c \uba40\ub9ac\uae4c\uc9c0 \ud37c\uc838 \ub098\uac14\ub2e4. \uac00\uc7a5 \ub192\uc740 \ub3cc\ubc1c\ud1b1 \ubd09\uc6b0\ub9ac\ub294 \ub098\uc774\ud2b8 \uc5d8\ud504\uc640 \ud0c0\uc6b0\ub80c \ubaa8\ub450\uc5d0\uac8c \uc2e0\uc131\ud558\ub2e4. \ub098\uc774\ud2b8 \uc5d8\ud504\ub294 \uc815\uc0c1 \uac00\uae4c\uc774\uc5d0 \ubb34\ub364\uacfc \uc232\uc18d \uacf5\ud130\ub97c \uc9c0\ud0a4\uace0, \ud0c0\uc6b0\ub80c\uc740 \uc911\uc559 \uace0\uc9c0\uc758 \ud0dc\uc591\ubc14\uc704 \uc57c\uc601\uc9c0\ub97c \ucc28\uc9c0\ud588\uc73c\uba70, \uac80\uc740\ucc3d \ud2b8\ub864\uc740 \ub9d0\ub77c\uce74\uc9c4\uc5d0 \uc9c4\uc744 \ucce4\ub2e4.","\uc774 \ub545\uc744 \uac00\uc7a5 \ud06c\uac8c \ub9dd\uac00\ub728\ub9b0 \uac83\uc740 \ud22c\uc790\uac1c\ubc1c\ud68c\uc0ac\ub2e4. \uadf8\ub4e4\uc758 \uace0\ube14\ub9b0\uc740 Windshear Crag\uc758 \ub098\ubb34\ub97c \uac70\uc758 \ub2e4 \ubca0\uc5b4 \ub0b4 \uacf5\uae30\ub97c \uadf8\uc744\uc74c\uc73c\ub85c \ub9c9\uace0 \ubb3c\uc744 \uae30\ub984\uc73c\ub85c \ub354\ub7fd\ud614\ub2e4. \uadf8\ub9bc\ud1a0\ud15c \ud0c0\uc6b0\ub80c\uacfc \ucf54\ubcfc\ud2b8, \uadf8\ub9ac\uace0 Charred Vale\uc758 \uc704\ud5d8\ud55c \uc9d0\uc2b9\ub4e4 \ub54c\ubb38\uc5d0 \uae38\uc740 \uc870\uae08\ub3c4 \uc548\uc804\ud558\uc9c0 \uc54a\ub2e4."]},"zone:ashenvale":{title:"\uc7bf\ube5b \uace8\uc9dc\uae30",summary:"\ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \uc870\uc0c1 \ub300\ub300\uc758 \uc232\uc73c\ub85c, \ubaa9\uc7ac\ub97c \ub458\ub7ec\uc2fc \ud638\ub4dc\uc640\uc758 \uc804\uc7c1\uc774 \uc2dc\uc791\ub41c \uacf3.",body:["\uc7bf\ube5b \uace8\uc9dc\uae30\ub294 \ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \uc870\uc0c1 \ub300\ub300\uc758 \uc232\uc73c\ub85c, \ubcf4\ub78f\ube5b \uadf8\ub298\uacfc \uace0\ubaa9\uc774 \uc6b0\uac70\uc9c4 \uae4a\uc740 \uc232\uc774 Zoram Strand\uc5d0\uc11c \ubd88\ubaa8\uc758 \ub545 \uacbd\uacc4\uae4c\uc9c0 \uc774\uc5b4\uc9c4\ub2e4. \uce7c\ub3c4\ub808\uc774\ub294 \uc544\uc2a4\ud2b8\ub77c\ub098\ub974\uc640 \uc5ec\ub7ec \uc804\ucd08\uae30\uc9c0\ub97c \uc9c0\ud0a4\uace0, \ud30c\uc218\uafbc\ub4e4\uc740 \uadf8\ub4e4\uc758 \uc232\uc744 \ub9f9\ub82c\ud788 \uc218\ud638\ud55c\ub2e4.","\uc81c3\ucc28 \ub300\uc804\uc7c1 \ub3d9\uc548 \uadf8\ub86c \ud5ec\uc2a4\ud06c\ub9bc\uc758 \uc804\uc7c1\ub178\ub798 \uc624\ud06c\ub4e4\uc774 \uc774 \uc232\uc5d0 \ub4e4\uc5b4\uc640 \ub2e4\uc2dc \uc545\ub9c8\uc758 \ud53c\ub97c \ub9c8\uc2dc\uace0 \ubc18\uc2e0 \uc138\ub098\ub9ac\uc6b0\uc2a4\ub97c \uc8fd\uc600\ub2e4. \uadf8\ub86c\uc740 \ud6d7\ub0a0 \uc9c0\uae08 Demon Fall Canyon\uc774\ub77c \ubd88\ub9ac\ub294 \uacf3\uc5d0\uc11c \uad6c\ub369\uc774 \uad70\uc8fc \ub9cc\ub178\ub85c\uc2a4\ub97c \uc8fd\uc774\uace0 \uc228\uc744 \uac70\ub450\uc5c8\ub2e4. \uc624\ud06c\ub4e4\uc740 \uc5ec\uc804\ud788 \ud1a0\ub9c9\ub098\ubb34 \uc8fc\ub454\uc9c0\uc640 \uc804\uc7c1\ub178\ub798 \uc57c\uc601\uc9c0\uc5d0\uc11c \ub3d9\ucabd \uc232\uc744 \ubca0\uc5b4 \ub0b4\uace0 \uc788\uc73c\uba70, \uc624\ub79c \ub2e4\ud23c\uc740 \uc544\uc9c1 \ubd88\uc528\uac00 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\ud2f0\ub85c\uc2a4\uac00 \ud3d0\ud5c8\ub97c \ub5a0\ub3cc\uace0, \ud574\uc548\uc5d0\ub294 \ubb3c\uc5d0 \uc7a0\uae34 \uc5d8\ub8ec\uc758 \uc2e0\uc804\uc778 \uac80\uc740\uc2ec\uc5f0\uc758 \ub098\ub77d\uc774 \uc788\ub2e4."]},"zone:duskwood":{title:"\uadf8\ub298\uc232",summary:"\ub05d\uc5c6\ub294 \ubc24\uc5d0 \uc0bc\ucf1c\uc9c4, \ud55c\ub54c \ubc1d\uc558\ub358 \uc5d8\uc708\uc758 \ud55c \uad6c\uc11d\uc73c\ub85c, \uc5b4\ub460\uace8\uc758 \uace0\uc9d1\uc2a4\ub7ec\uc6b4 \uc8fc\ubbfc\ub4e4\uc774 \uc9c0\ud0a4\uace0 \uc788\ub2e4.",body:["\uadf8\ub298\uc232\uc740 \ud55c\ub54c \uc5d8\uc708 \uc232\uc758 \ub0a8\ucabd \uc9c0\uc5ed\uc73c\ub85c, \uc9c0\uae08\uc740 \uc5b4\ub460\uace8\uacfc \uae4c\ub9c8\uadc0 \uc5b8\ub355\uc774\ub77c \ubd88\ub9ac\ub294 \ub9c8\uc744\ub4e4\uc774 \uc788\ub358 \uacf3\uc774\ub2e4. \uadf8\ub7ec\ub2e4 \ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \uc5d8\ub8ec\uc758 \ub0ab\uc758 \uc6b4\uba85\uacfc \uc5bd\ud78c \uadf8\ub9bc\uc790\uac00 \ub4dc\ub9ac\uc6e0\uace0, \uadf8 \uadf8\ub9bc\uc790\ub294 \ub05d\ub0b4 \uac77\ud788\uc9c0 \uc54a\uc558\ub2e4. \ub05d\uc5c6\ub294 \ud669\ud63c \uc544\ub798 \ub098\ubb34\ub4e4\uc740 \ub4a4\ud2c0\ub838\uace0, \ub291\ub300\uc778\uac04\uacfc \uc5b8\ub370\ub4dc, \uadf8\ub9ac\uace0 \uc8fd\uc74c\uc758 \uace0\uac1c\uc5d0\uc11c \uc628 \uc624\uc6b0\uac70\ub4e4\uc774 \ubc30\ud68c\ud558\uae30 \uc2dc\uc791\ud588\ub2e4.","\uc2a4\ud1b0\uc708\ub4dc\ub294 \uc774 \uc9c0\uc5ed\uc744 \uac70\uc758 \ub0b4\ubc84\ub824 \ub450\uc5c8\ub2e4. \uc5b4\ub460\uace8\uc758 \ubc24\uacbd\ube44\ub300\uac00 \ud070\uae38\uc744 \uc9c0\ud0a4\uace0, \uae4c\ub9c8\uadc0 \uc5b8\ub355 \ubb18\uc9c0\ub294 \uc548\uc2dd\ud558\uc9c0 \ubabb\ud55c \ub9dd\uc790\ub85c \uac00\ub4dd \ucc28\uba70, \uc232 \uae4a\uc740 \uacf3\uc758 \ud669\ud63c\uc758 \uc232\uc5d0\ub294 \uac70\ub300\ud55c \ub098\ubb34\uc640 \uc5d0\uba54\ub784\ub4dc\uc758 \uafc8\uc73c\ub85c \uac00\ub294 \ucc28\uc6d0\ubb38\uc774 \uc228\uc5b4 \uc788\ub2e4."]},"zone:wetlands":{title:"\uc800\uc2b5\uc9c0",summary:"\uce74\uc988 \ubaa8\ub2e8\uacfc \ub85c\ub370\ub860 \uc0ac\uc774\uc758 \uae38\uc744 \uc9c0\ud0a4\ub294 \uc7bf\ube5b\uc758 \ube44\uc5d0 \uc816\uc740 \uc2b5\uc9c0.",body:["\uc800\uc2b5\uc9c0\ub294 \uce74\uc988 \ubaa8\ub2e8\uc758 \uc0b0\ub9e5\uacfc \ubc14\ub2e4 \uc0ac\uc774\uc758 \ucc28\uac11\uace0 \uc548\uac1c \ub080 \uc2b5\uc9c0\ub2e4. \ud55c\ub54c \ub4dc\uc6cc\ud504\uc758 \uc694\uc0c8\ub4e4\uc774 \uc774 \uc9c0\uc5ed\uc744 \ub530\ub77c \ub298\uc5b4\uc11c \uc788\uc5c8\uc9c0\ub9cc, \uc804\uc7c1\uc774 \uadf8 \ub300\ubd80\ubd84\uc744 \ubd80\uc234 \ubc84\ub838\ub2e4. \uba54\ub124\uc2e4 \ud56d\uad6c\ub294 \uc774\uacf3\uc5d0\uc11c \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc758 \ub2fb \uc5ed\ud560\uc744 \ud558\ub294 \ud56d\uad6c\ub85c, \uadf8 \ubc30\ub4e4\uc740 \ud14c\ub77c\ubaa8\uc5b4\ub85c, \uadf8\ub9ac\uace0 Forever\uc5d0\uc11c\ub294 \uc0ac\uc6b0\uc2a4\uc1fc\uc5b4\uae4c\uc9c0 \ud56d\ud574\ud55c\ub2e4. \uc5ec\ud589\uc790\ub4e4\uc740 \ud3ec\uc704\ub41c \ub358 \uc54c\uac00\uc988\ub098 \ubd80\uc11c\uc9c4 \ud0c4\ub3cc \uad50\uac01\uc744 \uc9c0\ub098 \ub4e4\uc5b4\uc628\ub2e4.","\ub3d9\ucabd\uc5d0\ub294 \uc640\uc77c\ub4dc\ud574\uba38\uc758 \uc800\uc8fc\ubc1b\uc740 \ub3c4\uc2dc \uadf8\ub9bc \ubc14\ud1a8\uc774 \uc19f\uc544 \uc788\ub2e4. \uc81c2\ucc28 \ub300\uc804\uc7c1 \ub54c \uc6a9\uc544\uadc0 \ubd80\uc871\uc774 \ubd89\uc740 \uc6a9\ub4e4\uc744 \uac00\ub450\uc5b4 \ub450\uc5c8\ub358 \uacf3\uc774\ub2e4. \uc6a9\uc544\uadc0 \uc774\ud0c8\uc790\ub4e4\uc774 \uc544\uc9c1 \uc2b5\uc9c0\ub97c \ub5a0\ub3cc\uace0, \uac80\uc740\ubb34\uc1e0 \ub4dc\uc6cc\ud504\uac00 \ub358 \ubaa8\ub4dc\ub974\ub97c \ucc28\uc9c0\ud558\uace0 \uc788\ub2e4. Forever\uc5d0\uc11c\ub294 Whelgar's Excavation Site \uc704\uc5d0 \ub098\ud0c0\ub09c \uae30\uc774\ud55c \uc548\uac1c\uc640 \ubc88\uca4d\uc774\ub294 \ube5b\uc774 \ud2f0\ud0c4 \ud53c\uc870\ubb3c\ub4e4\ub85c \uac00\ub4dd\ud55c \ub358\uc804\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4."]},"zone:hillsbrad-foothills":{title:"\ud790\uc2a4\ube0c\ub798\ub4dc \uad6c\ub989\uc9c0",summary:"\uc0ac\uc6b0\uc2a4\uc1fc\uc5b4\uc640 \ud0c0\ub80c \ubc00\ub18d\uc7a5\uc774 \ub358\ud640\ub4dc \ud3d0\ud5c8 \uac00\uae4c\uc774\uc5d0\uc11c \uc11c\ub85c\ub97c \ub178\ub824\ubcf4\ub294 \ud478\ub978 \uc5b8\ub355.",body:["\ud790\uc2a4\ube0c\ub798\ub4dc\uc758 \ud478\ub974\uace0 \ube44\uc625\ud55c \uc5b8\ub355\uc740 \uc61b \uc54c\ud130\ub799 \uc655\uad6d \ubc14\ub85c \ub0a8\ucabd\uc5d0 \uc788\ub2e4. \uc774\uacf3\uc5d0\uc11c\ub294 \ub450 \ub9c8\uc744\uc774 \ub9c8\uc8fc \ubcf4\uace0 \uc788\ub2e4. \ud574\uc548\uc758 \uc5bc\ub77c\uc774\uc5b8\uc2a4 \ub9c8\uc744 \uc0ac\uc6b0\uc2a4\uc1fc\uc5b4\uc640 \uc5b8\ub355 \uc704 \ud3ec\uc138\uc774\ud070\uc758 \uc804\ucd08\uae30\uc9c0 \ud0c0\ub80c \ubc00\ub18d\uc7a5\uc73c\ub85c, \ub450 \ub9c8\uc744\uc758 \ubc18\ubaa9 \ub54c\ubb38\uc5d0 \ub4e4\ud310\uc740 \ud53c\ub85c \ubb3c\ub4e4\uc5b4 \uc788\ub2e4. \uba40\ub85d\uacfc \uc2e0\ub514\ucf00\uc774\ud2b8\uac00 \ubb38\uc81c\ub97c \ub354\ud55c\ub2e4.","\ub3d9\ucabd \uc5b8\ub355 \uc704\uc5d0\ub294 \ub358\ud640\ub4dc \uc694\uc0c8\uac00 \uc11c \uc788\ub2e4. \ud55c\ub54c \uc624\ud06c \uc218\uc6a9\uc18c\uc758 \ubcf8\ubd80\uc600\ub358 \uacf3\uc73c\ub85c, \uc5d0\ub378\ub77c\uc2a4 \ube14\ub799\ubb34\uc5b4 \uacbd\uc774 \uc5b4\ub9b0 \uc2a4\ub784\uc744 \uac80\ud22c\uc0ac\ub85c \uae38\ub800\uc73c\ub098 \uc2a4\ub784\uc740 \ud0c8\ucd9c\ud574 \uc790\uae30 \ubc31\uc131\uc744 \ud574\ubc29\ud588\ub2e4. \uc9c0\uae08\uc740 \uc2e0\ub514\ucf00\uc774\ud2b8\uac00 \uadf8 \ud3d0\ud5c8\ub97c \ucc28\uc9c0\ud558\uace0 \uc788\ub2e4. Forever\uc5d0\uc11c\ub294 City of Dalaran\uc73c\ub85c \uac00\ub294 \uae38\uc744 \uc5ec\ub294 \ud018\uc2a4\ud2b8\uac00 \ub450 \ub9c8\uc744 \ubaa8\ub450\uc5d0\uc11c \uc2dc\uc791\ub418\uba70, \ubc30\ub4e4\uc774 \uc0ac\uc6b0\uc2a4\uc1fc\uc5b4\uc5d0 \ub4e4\ub978\ub2e4."]},"zone:thousand-needles":{title:"\ubc84\uc12f\uad6c\ub984 \ubd09\uc6b0\ub9ac",summary:"\ub3cc\uae30\ub465\uacfc \uc18c\uae08 \ud3c9\uc6d0\uc758 \ud611\uace1\uc73c\ub85c, \ud0c0\uc6b0\ub80c\uacfc \ucf04\ud0c0\uc6b0\ub85c\uc2a4, \uacbd\uc8fc\ub97c \uc990\uae30\ub294 \uace0\ube14\ub9b0\uc774 \ubd88\uc548\ud558\uac8c \ub545\uc744 \ub098\ub204\uc5b4 \uc4f4\ub2e4.",body:["\ubc84\uc12f\uad6c\ub984 \ubd09\uc6b0\ub9ac\ub294 \uce7c\ub9bc\ub3c4\uc5b4 \ub0a8\ubd80\uc758 \uc6b0\ub69d \uc19f\uc740 \ub3cc \uace0\uc6d0\ub4e4\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uad11\ub300\ud558\uace0 \uba54\ub9c8\ub978 \ud611\uace1\uc73c\ub85c, \ubd88\ubaa8\uc758 \ub545\uc5d0\uc11c \uac70\ub300\ud55c \uc2b9\uac15\uae30\ub97c \ud0c0\uace0 \ub4e4\uc5b4\uac04\ub2e4. \ub192\uc0c8\ubc14\ub78c \ubd09\uc6b0\ub9ac\uc758 \ud0c0\uc6b0\ub80c\uc740 \uace0\uc6d0 \uaf2d\ub300\uae30\uc5d0 \uc0b4\uace0, \ucf00\ub978 \ube14\ub7ec\ub4dc\ud6c4\ud504\uc5d0\uac8c \uc801\ub300\uc801\uc778 \ud0c0\uc6b0\ub80c \ubd80\uc871\uc778 \uadf8\ub9bc\ud1a0\ud15c\uc740 Darkcloud Pinnacle\uc744 \ucc28\uc9c0\ud558\uace0 \uc788\ub2e4. \uac08\ub77c\ud06c \ucf04\ud0c0\uc6b0\ub85c\uc2a4\ub294 \ud611\uace1 \ubc14\ub2e5\uc744 \ub5a0\ub3cc\uace0, \ud558\ud53c\ub294 \ub3cc\uae30\ub465 \uc0ac\uc774\uc5d0 \ub465\uc9c0\ub97c \ud2bc\ub2e4.","\ub3d9\ucabd\uc73c\ub85c \uac00\uba74 \ud611\uace1\uc740 \ub208\ubd80\uc2e0 \uc18c\uae08 \uc0ac\ub9c9\uc778 \uc18c\uae08 \ud3c9\uc6d0\uc73c\ub85c \uc5f4\ub9ac\uba70, \uadf8\uacf3\uc5d0\uc11c \uace0\ube14\ub9b0\uacfc \ub178\uc6c0 \uae30\uc220\uc790\ub4e4\uc774 Mirage Raceway\uc5d0\uc11c \uae30\uacc4 \uacbd\uc8fc\ub97c \ubc8c\uc778\ub2e4."]},"zone:alterac-mountains":{title:"\uc54c\ud130\ub799 \uc0b0\ub9e5",summary:"\ubb34\ub108\uc9c4 \uc54c\ud130\ub799 \uc655\uad6d\uacfc \uc7a5\ubcbd\uc5d0 \uac00\ub824\uc9c4 \ub2ec\ub77c\ub780\uc758 \ud3d0\ud5c8\ub85c, \uc624\uc6b0\uac70\uc640 \uc2e0\ub514\ucf00\uc774\ud2b8\uac00 \ub2e4\ud22c\ub294 \uacf3.",body:["\uc54c\ud130\ub799 \uc0b0\ub9e5\uc740 \ud55c\ub54c \uc54c\ud130\ub799 \uc655\uad6d\uc774\uc5c8\ub2e4. \uadf8 \uad70\uc8fc \uc5d0\uc774\ub4e0 \ud398\ub808\ub180\ub4dc\ub294 \uc81c2\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \uc5bc\ub77c\uc774\uc5b8\uc2a4\ub97c \ubc30\uc2e0\ud558\uace0 \ud638\ub4dc\uc5d0 \ubd99\uc5c8\ub2e4. \uc655\uad6d\uc740 \ud574\uccb4\ub418\uc5c8\uace0, \uc9c0\uae08\uc740 Crushridge \uc624\uc6b0\uac70\ub4e4\uc774 \uc54c\ud130\ub799 \ub3c4\uc2dc\uc758 \ud3d0\ud5c8\uc5d0 \ub20c\ub7ec\uc549\uc558\uc73c\uba70, \ubd88\uba85\uc608\uc2a4\ub7ec\uc6b4 \uac00\ubb38\uc758 \ud6c4\uacc4\uc790 \uc54c\ub9ac\ub374 \ud398\ub808\ub180\ub4dc\uc758 \uc2e0\ub514\ucf00\uc774\ud2b8\uac00 \uc2a4\ud2b8\ub77c\ube0c\ub77c\ub4dc\ub97c \ub2e4\uc2a4\ub9b0\ub2e4. \ub808\uc774\ube10\ud640\ud2b8\uc758 \ub3c4\uc801\ub4e4\uc740 \uc5b8\ub355\uc5d0\uc11c \uc790\uae30\ub4e4\ub9cc\uc758 \uae38\uc744 \uac04\ub2e4.","\ub85c\ub2e4\ubbf8\uc5b4 \ud638\uc22b\uac00\uc5d0\ub294 \uc81c3\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \uc544\ud0a4\ubaac\ub4dc\uac00 \ud30c\uad34\ud55c \ub9c8\ubc95\uc0ac\ub4e4\uc758 \ub3c4\uc2dc \ub2ec\ub77c\ub780\uc758 \uc794\ud574\uac00 \uc788\ub2e4. \ud0a4\ub9b0 \ud1a0\ub294 \ub9c8\ubc95 \uc7a5\ubcbd \ub4a4\uc5d0\uc11c \ub3c4\uc2dc\ub97c \uc7ac\uac74\ud574 \uc654\ub2e4. Forever\uc5d0\uc11c\ub294 \uadf8 \uc7a5\ubcbd\uc774 \ubb34\ub108\uc838 \ub3c4\uc2dc\uc5d0 \ube44\uc804\uc758 \ud63c\ub3c8\uc774 \ub118\uccd0\ud750\ub974\uba70, \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc758 Skyborne\uc774 Zephras Isle\uc5d0\uc11c \ube44\ud589\uc120\uc744 \ud0c0\uace0 \ub3c4\ucc29\ud558\ub294 \uacf3\ub3c4 \ubc14\ub85c \uc774\uacf3\uc774\ub2e4."]},"zone:arathi-highlands":{title:"\uc544\ub77c\uc2dc \uace0\uc6d0",summary:"\uc61b \uc544\ub77c\uc18c\ub974\uc758 \uc2ec\uc7a5\ubd80\ub85c, \uc2a4\ud2b8\ub86c\uac00\ub4dc\uac00 \ud3d0\ud5c8\uac00 \ub418\uace0 \uc138 \uc138\ub825\uc774 \ub0a8\uc740 \uac83\uc744 \ub450\uace0 \uc2f8\uc6b0\ub294 \uacf3.",body:["\uc544\ub77c\uc2dc \uace0\uc6d0\uc740 \uc18c\ub77c\ub518 \uc655\uc774 \uc2a4\ud2b8\ub86c\uc744 \uc218\ub3c4\ub85c \uc138\uc6b4 \ucd5c\ucd08\uc758 \uc778\uac04 \uc81c\uad6d \uc544\ub77c\uc18c\ub974\uc758 \uc2ec\uc7a5\ubd80\uc600\ub2e4. \uadf8 \ud6c4\uacc4 \uc655\uad6d \uc2a4\ud2b8\ub86c\uac00\ub4dc\ub294 \uc9c0\uae08 \ub0a8\uc11c\ucabd\uc5d0\uc11c \ub300\ubd80\ubd84 \ud3d0\ud5c8\uac00 \ub418\uc5c8\uc73c\uba70, \uadf8\uacf3\uc5d0\uc11c \uac08\ub80c \ud2b8\ub864\ubca0\uc778 \uc655\uc790\uc758 \uc218\ube44\ub300\uac00 \uc2e0\ub514\ucf00\uc774\ud2b8\uc640 \ub3cc\uc8fc\uba39 \uc624\uc6b0\uac70\ub97c \uc0c1\ub300\ub85c \uc138 \uac08\ub798 \uac8c\ub9b4\ub77c\uc804\uc744 \ubc8c\uc774\uace0 \uc788\ub2e4. \uc18c\ub77c\ub518\uc758 \uc131\ubcbd\uc740 \uc9c0\uae08\ub3c4 \uc11c\ucabd\uc758 \uc61b \uad6d\uacbd\uc744 \ud45c\uc2dc\ud55c\ub2e4.","\uc5bc\ub77c\uc774\uc5b8\uc2a4\ub294 \ud53c\ub09c\ubbfc \uac70\uc810\uc5d0 \ubaa8\uc778\ub2e4. \ud638\ub4dc\ub294 \ud574\uba38\ud3f4\uc744 \ucc28\uc9c0\ud558\uace0 \uc788\ub294\ub370, \uc774\uacf3\uc740 \ubc31\uc131\uc744 \ud574\ubc29\ud558\ub2e4 \uc4f0\ub7ec\uc9c4 \ub300\uc871\uc7a5 \uc624\uadf8\ub9bc \ub460\ud574\uba38\ub97c \uae30\ub824 \uc774\ub984 \ubd99\uc778 \uc61b \uc218\uc6a9\uc18c\ub2e4. \ub9c8\ub978\uac00\uc9c0 \ud2b8\ub864\uc774 \uc5b8\ub355\uc744 \ub5a0\ub3cc\uace0, \ud0c4\ub3cc \uad50\uac01\uc774 \uace0\uc6d0\uacfc \uc800\uc2b5\uc9c0\ub97c \uc787\ub294\ub2e4."]},"zone:desolace":{title:"\uc78a\ud600\uc9c4 \ub545",summary:"\ucf54\ub3c4\uc758 \ubf08\uc640 \uc11c\ub85c \uc2f8\uc6b0\ub294 \ucf04\ud0c0\uc6b0\ub85c\uc2a4 \ubd80\uc871\ub4e4\ub85c \uac00\ub4dd\ud55c, \uc7ac\ub85c \ub4a4\ub36e\uc778 \uc7bf\ube5b \ud669\ubb34\uc9c0.",body:["\uc78a\ud600\uc9c4 \ub545\uc740 \uc7bf\ube5b \uc7ac\uc640 \uc8fd\uc740 \ub098\ubb34, \uadf8\ub9ac\uace0 \uc8fd\uc73c\ub7ec \ucf54\ub3c4 \ubb34\ub364\uc744 \ucc3e\uc544\uc624\ub294 \uace0\ub300 \ucf54\ub3c4\uc758 \ub450\uac1c\uace8\ub85c \uc774\ub8e8\uc5b4\uc9c4 \ud669\ub7c9\ud55c \ub545\uc774\ub2e4. \uc138\uacc4\uc758 \ubd84\ub9ac\ub85c \ubd80\uc11c\uc9c4 \uba85\uac00 \ub3c4\uc2dc\ub4e4\uc758 \ud3d0\ud5c8\uac00 \uc5b8\ub355 \uacf3\uacf3\uc5d0\uc11c \ubb34\ub108\uc838 \uac00\uace0, \uc61b \ub9c8\ubc95\uc774 \ub0a8\uc544 \uc788\ub294 \uacf3\uc5d0\ub294 \uc544\uc9c1\ub3c4 \uc545\ub9c8\uc640 \uc0ac\ud2f0\ub85c\uc2a4\uac00 \ubaa8\uc5ec\ub4e0\ub2e4.","\uc774\uacf3\uc740 \uc138\ub098\ub9ac\uc6b0\uc2a4\uc758 \uc544\ub4e4 \uc790\uc5d0\ud0c0\ub974\uc640 \ub300\uc9c0\uc758 \uacf5\uc8fc \ud14c\ub77c\ub4dc\ub77c\uc2a4\uc758 \uacb0\ud569\uc73c\ub85c \ub9c8\ub77c\uc6b0\ub3c8\uc758 \ub3d9\uad74\uc5d0\uc11c \ud0dc\uc5b4\ub09c \ucf04\ud0c0\uc6b0\ub85c\uc2a4\uc758 \uace0\ud5a5\uc774\ub2e4. \ucf5c\uce74\ub974, \uac94\ud0a4\uc2a4, \ub9c8\uadf8\ub78c, \ub9c8\ub77c\uc6b0\ub518\uc758 \ub124 \ubd80\uc871\uc740 \uc678\ubd80\uc778\uacfc \uc2f8\uc6b0\ub294 \uac83\ub9cc\ud07c\uc774\ub098 \ub9f9\ub82c\ud558\uac8c \uc11c\ub85c \uc2f8\uc6b4\ub2e4. \uc5bc\ub77c\uc774\uc5b8\uc2a4\ub294 Nijel's Point\ub97c, \ud638\ub4dc\ub294 Shadowprey Village\ub97c \ucc28\uc9c0\ud558\uace0 \uc788\ub2e4."]}}},1794,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"zones2",{enumerable:!0,get:function(){return o}});const o={"zone:stranglethorn-vale":{title:"\uac00\uc2dc\ub364\ubd88 \uace8\uc9dc\uae30",summary:"\ubb34\ub108\uc9c4 \ud2b8\ub864 \ub3c4\uc2dc\uc640 \uc0ac\ub0e5\uafbc, \ud574\uc801, \uadf8\ub9ac\uace0 \uace0\ube14\ub9b0 \ud56d\uad6c \ubb34\ubc95\ud56d\uc774 \uc788\ub294 \ucc0c\ub294 \ub4ef\ud55c \ubc00\ub9bc.",body:["\uac00\uc2dc\ub364\ubd88 \uace8\uc9dc\uae30\ub294 \uad6c\ub8e8\ubc14\uc2dc \ud2b8\ub864\uc758 \uc2ec\uc7a5\ubd80\uc600\uc73c\uba70, \uadf8\ub4e4\uc758 \uc81c\uad6d\uc740 \ud55c\ub54c \uc904\uad6c\ub8f9\uc5d0\uc11c \ubc00\ub9bc\uc744 \ub2e4\uc2a4\ub838\ub2e4. \uadf8\ub4e4\uc758 \ub3cc \ub3c4\uc2dc\ub294 \uc774\uc81c \ub369\uad74 \uc544\ub798 \ubb34\ub108\uc838 \uac00\uc9c0\ub9cc \uc5ec\uc804\ud788 \uc815\uae00 \ud2b8\ub864\uc774 \ub5a0\ub3cc\uace0, \uc624\uc6b0\uac70\uc640 \ub098\uac00, \uadf8\ub9ac\uace0 \uc774 \uace8\uc9dc\uae30\uc758 \uc545\uba85 \ub192\uc740 \ubaa9\uc870\ub974\ub294 \uac00\uc2dc\ub364\ubd88 \ub54c\ubb38\uc5d0 \ubaa8\ub4e0 \uae38\uc774 \uc704\ud5d8\ud558\ub2e4. \uc0ac\ub0e5\uafbc\ub4e4\uc740 \ub124\uc2f1\uc6cc\ub9ac \uc6d0\uc815\ub300\ub85c \ubab0\ub824\ub4e4\uace0, \ud638\ub4dc\ub294 \uadf8\ub86c\uace8 \uc8fc\ub454\uc9c0\ub97c \uc9c0\ud0a4\uba70, \uc5bc\ub77c\uc774\uc5b8\uc2a4 \ubc18\uad70\uc740 \ubd81\ucabd\uc5d0 \uc9c4\uc744 \ucce4\ub2e4.","\ub0a8\ucabd \ub05d\uc5d0\uc11c\ub294 \ubb34\ubc95\ud56d\uc758 \uace0\ube14\ub9b0\ub4e4\uc774 Blackwater Raiders \ud574\uc801\ub4e4\uacfc \ub098\ub780\ud788 \ubb34\ubc95 \ud56d\uad6c\ub97c \uc6b4\uc601\ud558\uace0, \ubaa8\ub4e0 \uc885\uc871\uc758 \ud22c\uc0ac\ub4e4\uc774 \uc624\ub798\ub41c \uad6c\ub8e8\ubc14\uc2dc \ud22c\uae30\uc7a5\uc5d0\uc11c \ub9de\ubd99\ub294\ub2e4. Forever\uc5d0\uc11c\ub294 \uadf8\ub86c\uace8 \uc11c\ucabd \ubc14\ub2e4\uc5d0\uc11c \uace0\ub300 \ud2b8\ub864 \uc720\uc801\uc774 \uc19f\uc544\uc62c\ub790\ub2e4. \uc9c0\uae08\uc740 \ud2b8\ub864\uacfc \ub098\uac00\uac00 \ub5a0\ub3c4\ub294 Drowned City\ub2e4."]},"zone:badlands":{title:"\ud669\uc57c\uc758 \ub545",summary:"\ub4dc\uc6cc\ud504\uac00 \ud2f0\ud0c4\uc758 \ube44\ubc00\uc744 \ucc3e\uc544 \ub545\uc744 \ud30c\uace0, \ud638\ub4dc\uac00 \uce74\ub974\uac00\uc2a4\uc5d0\uc11c \uc9c0\ucf1c\ubcf4\ub294 \uac08\ub77c\uc9c4 \ud611\uace1 \uc0ac\ub9c9.",body:["\ud669\uc57c\uc758 \ub545\uc740 \uce74\uc988 \ubaa8\ub2e8 \ub0a8\ubd80\uc5d0 \ud3bc\uccd0\uc9c4, \ubc14\uc704\uc640 \uad6c\ubd88\uad6c\ubd88\ud55c \ud611\uace1\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uac08\ub77c\uc9c0\uace0 \ud587\ubcd5\uc5d0 \uadf8\uc744\ub9b0 \uc0ac\ub9c9\uc774\ub2e4. \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \ud0d0\uad11\uafbc\ub4e4\uc740 \ud2f0\ud0c4\uc758 \uc720\ubb3c\uc744 \ucc3e\uc544 \uc774\uacf3\uc744 \uc0c5\uc0c5\uc774 \ub4a4\uc9c0\ub294\ub370, \uadf8\ub4e4\uc744 \ub04c\uc5b4\ub4e4\uc778 \uac83\uc740 \uc0b4\uc544 \uc788\ub294 \ub3cc\ub85c \ub41c \uc874\uc7ac\ub77c\ub294 \ub4dc\uc6cc\ud504 \uae30\uc6d0\uc758 \uccab \ub2e8\uc11c\ub97c \ub4dc\ub7ec\ub0b8 \uac70\ub300\ud55c \uc9c0\ud558 \uae08\uace0 \uc6b8\ub2e4\ub9cc\uc774\ub2e4. \uae34 \uc7a0\uc5d0\uc11c \ud480\ub824\ub09c \ud2b8\ub85c\uadf8\ub4e4\uc774 \uccab \uc6d0\uc815\ub300\ub97c \ud559\uc0b4\ud588\uace0, \uc9c0\uae08\uc740 \uadf8 \uc804\ub2f9\uc744 \uc9c0\ud0a4\uace0 \uc788\ub2e4.","\uac80\uc740\ubb34\uc1e0 \ub4dc\uc6cc\ud504\uac00 \uc559\uace0\ub974 \uc694\uc0c8\ub97c \ucc28\uc9c0\ud558\uace0, Dustbelcher \uc624\uc6b0\uac70\uac00 \ud669\ubb34\uc9c0 \uacf3\uacf3\uc5d0 \uc9c4\uc744 \ucce4\uc73c\uba70, \uac80\uc740 \uc6a9\uc871\uc774 Lethlor Ravine\uc5d0 \ub465\uc9c0\ub97c \ud2c0\uc5c8\ub2e4. \ud638\ub4dc\ub294 \uc774\uae00\uac70\ub9ac\ub294 \ud611\uace1\uc73c\ub85c \uac00\ub294 \uae38\ubaa9\uc758 \uc804\ucd08\uae30\uc9c0 \uce74\ub974\uac00\uc2a4\uc5d0\uc11c \uacbd\uacc4\ub97c \uc120\ub2e4."]},"zone:dustwallow-marsh":{title:"\uba3c\uc9c0\uc9c4\ud759 \uc2b5\uc9c0\ub300",summary:"\ud14c\ub77c\ubaa8\uc5b4\uc640 \uc624\ub2c9\uc2dc\uc544\uc758 \ub465\uc9c0, \uadf8\ub9ac\uace0 \uc624\ub7ab\ub3d9\uc548 \ubd09\uc778\ub41c \uc54c\uce74\uc988 \uc12c\uc758 \uac10\uc625\uc744 \uc228\uae34 \uae40\uc774 \ud53c\uc5b4\uc624\ub974\ub294 \ub2aa.",body:["\uba3c\uc9c0\uc9c4\ud759 \uc2b5\uc9c0\ub300\ub294 \uce7c\ub9bc\ub3c4\uc5b4 \ub3d9\ucabd \ud574\uc548\uc758 \uc624\ub798\ub418\uace0 \ub298 \ucd95\ucd95\ud55c \ub2aa\uc73c\ub85c, \uc545\uc5b4\uc640 \ub7a9\ud130\uc640 \uba40\ub85d\uc774 \uc6b0\uae00\uac70\ub9b0\ub2e4. \uc55e\ubc14\ub2e4\uc5d0\ub294 \uc81c\uc774\ub098 \ud504\ub77c\uc6b0\ub4dc\ubb34\uc5b4\uac00 \uc11c\ucabd\uae4c\uc9c0 \uc790\uc2e0\uc744 \ub530\ub77c\uc628 \uc0dd\uc874\uc790\ub4e4\uc744 \uc704\ud574 \uc138\uc6b4 \uc694\uc0c8 \ub3c4\uc2dc \ud14c\ub77c\ubaa8\uc5b4 \uc12c\uc774 \uc788\uc73c\uba70, \ud638\ub4dc\ub294 \uc2b5\uc9c0 \uac00\uc7a5\uc790\ub9ac\uc758 \uac80\uc740\uc6b8\ud0c0\ub9ac \ub9c8\uc744\uc5d0\uc11c \uc774\uc5d0 \ub9de\uc120\ub2e4. \ub0a8\ucabd\uc5d0\uc11c\ub294 \uac80\uc740 \uc6a9\ub4e4\uc774 \uc624\ub2c9\uc2dc\uc544\uc758 \ub465\uc9c0 \uc8fc\uc704\uc758 Wyrmbog\uc5d0 \ub4e4\ub053\ub294\ub2e4.","\uc54c\uce74\uc988 \uc12c\uc5d0\ub294 \uc624\ub798\uc804\ubd80\ud130 \uc18c\ubb38\uc774 \ub530\ub77c\ub2e4\ub154\ub2e4. \uadf8\uacf3 \uac10\uc625\uc5d0 \ubc14\ub9ac\uc548 \ub9b0 \uad6d\uc655\uc744 \ube44\ub86f\ud55c \uace0\uc704 \ud3ec\ub85c\ub4e4\uc774 \uac07\ud600 \uc788\ub2e4\ub294 \uac83\uc774\ub2e4. Forever\uc5d0\uc11c \uadf8 \ubb38\uc774 \ub9c8\uce68\ub0b4 \uc5f4\ub9ac\uace0, \uc548\uc5d0\uc11c \ub370\ud53c\uc544\uc988 \ub2e8\uacfc \ub098\uac00\uac00 \uc804\uc7c1\uc744 \ubc8c\uc774\uace0 \uc788\uc74c\uc774 \ub4dc\ub7ec\ub09c\ub2e4."]},"zone:riverglades":{title:"Riverglades",summary:"\uce74\uc988 \ubaa8\ub2e8 \ub0a8\ub3d9\ubd80\uc758 \ubd84\uc7c1 \uc9c0\uc5ed\uc778 \uac15\uc758 \ub545\uc73c\ub85c, Forever\uc5d0 \uc0c8\ub85c \uc0dd\uae34 \uacf3\uc774\ub2e4. Farholde\uc758 \uae30\uc0ac\ub4e4\uc740 \uc2a4\ud1b0\uc708\ub4dc\uac00 \ubc84\ub9ac\uace0 \uac04 \uc804\uc7c1\uc744 \uc544\uc9c1\ub3c4 \uce58\ub974\uace0 \uc788\ub2e4.",body:["Riverglades\ub294 \ud669\uc57c\uc758 \ub545\uacfc \ubd88\ud0c0\ub294 \ud3c9\uc6d0 \ub3d9\ucabd\uc5d0 \uc788\uc73c\uba70, \ud55c\ub54c \uc2a4\ud1b0\uc708\ub4dc \uc655\uad6d\uc758 \ub545\uc774\uc5c8\ub2e4. \uc81c1\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \ud638\ub4dc\ub294 Sunnyglade \ub9c8\uc744\uc744 \uc57d\ud0c8\ud558\uace0 \uc8fc\ubbfc\ub4e4\uc744 \ub178\uc608\ub85c \uc0bc\uc558\ub2e4. \uba87\uba87 \uac00\uc871\uc740 \ub3c4\ub9dd\uccd0 Windstead\ub97c \uc138\uc6e0\uace0, \ud3ec\ub85c\ub4e4\uc744 \uad6c\ucd9c\ud55c \uae30\uc0ac\ub4e4\uc740 Meadowsbrook\uc744 \uc138\uc6b4 \ub4a4 \ud574\uc548\uc758 \uc12c \ud558\ub098\ub97c Farholde\ub77c\ub294 \uc774\ub984\uc73c\ub85c \uc694\uc0c8\ud654\ud588\ub2e4. \uc774 \ub545\uc744 \uc783\uc5c8\ub2e4\uace0 \uc5ec\uae34 \uc2a4\ud1b0\uc708\ub4dc\ub294 \ub2e4\ub978 \uc77c\ub85c \ub208\uc744 \ub3cc\ub838\ub2e4.","\uc81c2\ucc28 \ub300\uc804\uc7c1\uc774 \ub05d\ub098\uac08 \ubb34\ub835, \uc0b4\uac8c\ub77c\uc2a4\uc758 \ubb34\ub364\uc5d0\uc11c \ub2ec\uc544\ub09c \ud669\ud63c\uc758 \ub9dd\uce58 \uc624\uc6b0\uac70\uc640 Stormreaver \uc624\ud06c\ub4e4\uc774 \uc774\uacf3\uc73c\ub85c \ud53c\uc2e0\ud588\uace0, \uc5ec\ub7ec \ud574\uc5d0 \uac78\uce5c \uc2b5\uaca9\uc740 Farholde \ud3ec\uc704\uc804\uc73c\ub85c \ub05d\ub0ac\ub2e4. 25\ub144\uc5d0\ub294 \uae30\uc0ac\ub2e8\uc7a5 Demar Brant\uc758 Brotherhood of the Horse\uac00 \uc5ec\uc804\ud788 \uc2f8\uc6b0\uace0 \uc788\uace0, \ud669\ud63c\uc758 \ub9dd\uce58\ub294 \ud3d0\ud5c8\uac00 \ub41c Sunnyglade\ub97c \ucc28\uc9c0\ud588\uc73c\uba70, Bolder'ok \uc624\uc6b0\uac70\ub294 \ud638\ub4dc\uc5d0 \ud569\ub958\ud588\ub2e4."],unknowns:["Rog'mar\uc640 Bolder'ok\uc758 \ud638\ub4dc \ubcd1\ub825\uc744 \ub204\uac00 \uc774\ub044\ub294\uc9c0\ub294 \uc790\ub8cc\uc5d0 \ub098\uc624\uc9c0 \uc54a\ub294\ub2e4.","\uc81c2\ucc28 \ub300\uc804\uc7c1 \uc774\ud6c4 \ucd08\uac08\uc774 \uc774 \uc9c0\uc5ed\uc5d0 \uc654\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \uc18c\ubb38\uc77c \ubfd0\uc774\ub2e4.","\ud574\uac00 \uc9c4 \ub4a4 Krol\u2019dok Stronghold\uc5d0\uc11c \ub4e4\ub824\uc624\ub294 \uc8fc\ubb38 \uc18c\ub9ac\uac00 \ubb34\uc5c7\uc744 \ub73b\ud558\ub294\uc9c0\ub294 \ubc1d\ud600\uc9c0\uc9c0 \uc54a\uc558\ub2e4."]},"zone:swamp-of-sorrows":{title:"\uc2ac\ud514\uc758 \ub2aa",summary:"\ub179\uc0c9\uc6a9\ub4e4\uc774 \uac00\ub77c\uc549\uc740 \uc544\ud0c8\ud559\uce74\ub974 \uc2e0\uc804\uc744 \uc9c0\ud0a4\uace0 \ud638\ub4dc\uac00 \uc2a4\ud1a0\ub098\ub4dc\ub97c \ucc28\uc9c0\ud55c \uc18c\uae08\uae30 \uc5b4\ub9b0 \ub2aa.",body:["\uc2ac\ud514\uc758 \ub2aa\uc740 \ub3d9\ubd80 \uc655\uad6d \ub0a8\ubd80\uc758 \uace0\uc778 \ub2aa\uc73c\ub85c, \ub298\uc5b4\uc9c4 \ub098\ubb34\uc640 \uc18c\uae08\uae30 \uc5b4\ub9b0 \ubb3c\ub85c \uac00\ub4dd\ud558\uba70 \uc5b4\ub460\uc758 \ubb38\uc774 \ucc98\uc74c \uc5f4\ub9b0 \uacf3\uacfc \uac00\uae5d\ub2e4. \ud638\ub4dc\ub294 \uc2a4\ud1b0\uc708\ub4dc\uc640 \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uc774\uc810\uc744 \uc798 \uc0b4\ub838\ub2e4. \uc624\ud06c \ub9c8\uc744 \uc2a4\ud1a0\ub098\ub4dc\uac00 \uc774\uacf3 \ud638\ub4dc\uc758 \uac70\uc810\uc774\ub2e4. \uc545\uc5b4\uc640 \ub2aa\uc9c0 \uad34\ubb3c, \uadf8\ub9ac\uace0 \ucd94\ubc29\ub41c \ub4dc\ub808\ub098\uc774 \ubb34\ub9ac\uac00 \ud0c1\ud55c \ubb3c\uc744 \ub098\ub204\uc5b4 \uc4f4\ub2e4.","\ub2aa \ud55c\uac00\uc6b4\ub370\uc5d0\ub294 \uc544\ud0c8\ud559\uce74\ub974 \uc2e0\uc804\uc774 \uc788\ub2e4. \uc544\ud0c8\ub77c\uc774 \uc0ac\uc81c\ub4e4\uc774 \ud55c\ub54c \ud53c\uc758 \uc2e0 \ud559\uce74\ub974\ub97c \uc18c\ud658\ud558\ub824 \ud588\ub358 \uac00\ub77c\uc549\uc740 \uc131\uc18c\ub2e4. \uc774\uc81c\ub294 \uc704\uc0c1 \uc774\uc138\ub77c\uc758 \ub179\uc0c9\uc6a9\ub4e4\uc774 \uadf8\uacf3\uc744 \uc9c0\ud0a4\uba70, \uc548\uc5d0\uc11c \uc544\uc9c1\ub3c4 \uacf5\ud3ec\uac00 \uafc8\ud2c0\uac70\ub9b0\ub2e4\uace0 \uacbd\uace0\ud55c\ub2e4."]},"zone:feralas":{title:"\ud398\ub784\ub77c\uc2a4",summary:"\uac70\ub300\ud55c \ub098\ubb34\uc640 \uc624\uc6b0\uac70\uac00 \ucc28\uc9c0\ud55c \ud3d0\ud5c8, \uadf8\ub9ac\uace0 \uace0\ub300 \uba85\uac00 \ub3c4\uc2dc \uc5d8\ub4dc\ub808\ud0c8\ub77c\uc2a4\uac00 \uc788\ub294 \ube44\uc625\ud55c \uc6b0\ub9bc.",body:["\ud398\ub784\ub77c\uc2a4\ub294 \uce7c\ub9bc\ub3c4\uc5b4 \ub0a8\uc11c\ucabd \ud574\uc548\uc758 \uac70\ub300\ud55c \ub098\ubb34\ub4e4\uc774 \uc6b0\uac70\uc9c4 \ube44\uc625\ud558\uace0 \ube44\uc5d0 \uc816\uc740 \uc232\uc73c\ub85c, \ud55c\ub54c \ub098\uc774\ud2b8 \uc5d8\ud504 \uace0\ub300 \uc655\uad6d\uc758 \uc77c\ubd80\uc600\ub2e4. \uac00\uc7a5 \ud070 \ud3d0\ud5c8\ub294 \uc9c0\uae08 \ud608\ud22c\uc758 \uc804\uc7a5\uc774\ub77c \ubd88\ub9ac\ub294 \uc5d8\ub4dc\ub808\ud0c8\ub77c\uc2a4\ub85c, \uc138\uacc4\uc758 \ubd84\ub9ac\uc5d0\uc11c \uc0b4\uc544\ub0a8\uc740 \uba85\uac00\uc778 \uc174\ub4dc\ub784\ub77c\uac00 \ub9cc \ub144 \ub3d9\uc548 \uc678\ubd80\uc640 \ub2e8\uc808\ub41c \ucc44 \uc0b4\uc544\uc628 \uacf3\uc774\ub2e4. \uace0\ub974\ub454\ub2c8 \uc624\uc6b0\uac70\uac00 \uc61b \uc5d8\ud504 \ud3d0\ud5c8\ub97c \ud729\uc4f8\uace0 \ub545 \uc804\uccb4\uc5d0 \ud0c0\ub77d\uc744 \ud37c\ub728\ub838\ub2e4.","\ud398\ub354\ubb38 \uc694\uc0c8\uc758 \ud30c\uc218\uafbc\ub4e4\uc740 \uc0ac\ub974\ub3c4\ub974 \uc12c\uc5d0\uc11c \ud574\uc548\uc744 \uac10\uc2dc\ud558\uace0, \ubaa8\uc790\ucf00 \uc57c\uc601\uc9c0\uc758 \ud0c0\uc6b0\ub80c\uc740 \ud638\ub4dc\ub97c \uc704\ud574 \uadf8\ub9bc\ud1a0\ud15c \ubcc0\uc808\uc790\ub4e4\uc744 \uc0ac\ub0e5\ud55c\ub2e4. \ub098\uac00\uac00 \uc11c\ucabd \uc12c\ub4e4\uc744 \ucc28\uc9c0\ud588\uace0, \uc2e4\ub9ac\uc2dc\ub4dc\uc758 \uad70\ub77d\uc774 \ub098\ud0c0\ub0ac\uc73c\uba70, \ub179\uc0c9\uc6a9\ub4e4\uc774 \uc5d0\uba54\ub784\ub4dc\uc758 \uafc8\uc73c\ub85c \uac00\ub294 \uad00\ubb38\uc778 Dream Bough\ub97c \uc9c0\ud0a8\ub2e4."]},"zone:hinterlands":{title:"\ub3d9\ubd80 \ub0b4\ub959\uc9c0",summary:"\uadf8\ub9ac\ud3f0 \uae30\uc218\uc640 \uc232\ud2b8\ub864\uc758 \uac70\uce5c \ubd81\ubd80 \uc5b8\ub355\uc73c\ub85c, \ub9f9\uae08\uc758 \ubd09\uc6b0\ub9ac\uc5d0 \uc0ac\ub294 \uc640\uc77c\ub4dc\ud574\uba38 \ub4dc\uc6cc\ud504\uc758 \uace0\ud5a5.",body:["\ub3d9\ubd80 \ub0b4\ub959\uc9c0\ub294 \ub85c\ub370\ub860 \ubd81\ubd80\uc758 \ud5d8\ud558\uace0 \uc232\uc774 \uc6b0\uac70\uc9c4 \uace0\uc9c0\ub300\ub2e4. \uc138 \ub9dd\uce58\uc758 \uc804\uc7c1 \uc774\ud6c4 \uc640\uc77c\ub4dc\ud574\uba38 \ub4dc\uc6cc\ud504\ub294 \uc800\uc8fc\ubc1b\uc740 \uadf8\ub9bc \ubc14\ud1a8\uc744 \ubc84\ub9ac\uace0 \uc774\uacf3 \ub9f9\uae08\uc758 \ubd09\uc6b0\ub9ac\uc5d0 \uc815\ucc29\ud588\ub2e4. \uadf8\ub4e4\uc740 \uc774 \uc9c0\uc5ed\uc758 \uc57c\uc0dd \uadf8\ub9ac\ud3f0\uc744 \uae38\ub4e4\uc774\uba70 \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc758 \uad73\uac74\ud55c \ub3d9\ub9f9\uc73c\ub85c \ub0a8\uc544 \uc788\ub2e4. \uba87\uba87 \ud558\uc774 \uc5d8\ud504\ub294 \uc544\uc9c1\ub3c4 \ucfe0\uc5d8\ub2e4\ub2d0 \uc624\ub450\ub9c9\uc744 \uc9c0\ud0a8\ub2e4.","\uc5b8\ub355\uc740 \uc232\ud2b8\ub864\uc758 \uac83\uc774\uae30\ub3c4 \ud558\ub2e4. \ub808\ubc18\ud130\uc2a4\ud06c \ubd80\uc871\uc740 \uc2a4\ub784\uc758 \ud638\ub4dc \ud3b8\uc5d0 \uc130\uace0, Vilebranch \ubd80\uc871\uc740 \uac70\ub300\ud55c \uc2e0\uc804 \ub3c4\uc2dc \uc9c4\ud0c0\uc54c\ub85c\ub97c \ub2e4\uc2a4\ub9ac\uba70, \ub9c8\ub978\uac00\uc9c0 \ubd80\uc871\uc740 \uc0e4\ub4dc\ub77c\uc54c\ub85c \uc8fc\ubcc0\uc5d0 \ub3c4\uc0ac\ub9ac\uace0 \uc788\ub2e4. \ubd81\ucabd\uc5d0\uc11c\ub294 \uace0\ub300\uc758 \ub098\ubb34 \uc138\ub77c\ub370\uc778\uc774 \uc5d0\uba54\ub784\ub4dc\uc758 \uafc8\uc73c\ub85c \uac00\ub294 \ucc28\uc6d0\ubb38\uc744 \ud488\uace0 \uc788\uc73c\uba70, \ub179\uc0c9\uc6a9\ub4e4\uc774 \uc774\ub97c \uc9c0\ud0a8\ub2e4."]},"zone:tanaris":{title:"\ud0c0\ub098\ub9ac\uc2a4",summary:"\uac00\uc82f\uc794\uc5d0\uc11c \ub2e4\uc2a4\ub9ac\ub294 \ubaa8\ub798 \uc5b8\ub355\uc758 \ubc14\ub2e4\ub85c, \uc2dc\uac04\uc758 \ub3d9\uad74\uacfc \ud2b8\ub864 \ub3c4\uc2dc \uc904\ud30c\ub77d\uc744 \uc228\uae30\uace0 \uc788\ub2e4.",body:["\ud0c0\ub098\ub9ac\uc2a4\ub294 \uce7c\ub9bc\ub3c4\uc5b4 \ub0a8\ub3d9\ubd80\uc758 \ub05d\uc5c6\ub294 \ubaa8\ub798 \uc5b8\ub355\uacfc \ubaa8\ub798 \ud3ed\ud48d\uc758 \uc0ac\ub9c9\uc774\ub2e4. \uc2a4\ud300\ud718\ub4e4 \ubb34\uc5ed\ud68c\uc0ac\uc758 \uace0\ube14\ub9b0\ub4e4\uc774 \uac00\uc82f\uc794\uacfc \uc2a4\ud300\ud718\ub4e4 \ud56d\uad6c\uc5d0\uc11c \uc774\uacf3\uc744 \uc6b4\uc601\ud558\uba70 \uc704\ud0dc\ub85c\uc6b4 \uc911\ub9bd\uc744 \uc9c0\ud0a4\uace0, \uadf8\uc0ac\uc774 Wastewander \uc0b0\uc801\uacfc \ub0a8\ucabd\ubc14\ub2e4 \ud574\uc801, Dunemaul \uc624\uc6b0\uac70\uac00 \uc5ec\ud589\uc790\ub4e4\uc744 \ub178\ub9b0\ub2e4.","\uc0ac\ub9c9\uc740 \ub354 \uc624\ub798\ub41c \ud798\ub4e4\uc744 \uc228\uae30\uace0 \uc788\ub2e4. \uc2dc\uac04\uc758 \ub3d9\uad74\uc5d0\uc11c\ub294 \ub178\uc988\ub3c4\ub974\ubb34\uc758 \uccad\ub3d9\uc6a9\uad70\ub2e8\uc774 \uc5ed\uc0ac\uc758 \ud750\ub984\uc744 \uc9c0\ucf1c\ubcf4\uace0, \uba40\ub9ac \ub0a8\ucabd\uc5d0\ub294 \uc6b8\ub460\uc758 \ud2f0\ud0c4 \uc720\uc801\uc774 \uc788\uc73c\uba70, \uc904\ud30c\ub77d\uc758 \ubaa8\ub798 \ud2b8\ub864\ub4e4\uc740 \ubd81\uc11c\ucabd\uc758 \uc131\ubcbd \ub3c4\uc2dc\ub97c \uc9c0\ud0a8\ub2e4. Forever\uc5d0\uc11c\ub294 \uc2a4\ud300\ud718\ub4e4 \ud56d\uad6c\uc5d0\uc11c \ucd9c\ubc1c\ud558\ub294 \ubc30\uac00 \uc0ac\ub9c9\uacfc Riverglades\uc758 Powderfuse Port\ub97c \uc787\ub294\ub2e4."]},"zone:searing-gorge":{title:"\uc774\uae00\uac70\ub9ac\ub294 \ud611\uace1",summary:"\uac80\uc740\ubb34\uc1e0\uc758 \uad11\uc0b0\uacfc \ub178\uc608 \ub178\ub3d9\uc758 \uadf8\uc744\ub9b0 \uad6c\ub369\uc774\ub85c, \ub77c\uadf8\ub098\ub85c\uc2a4 \uc18c\ud658\uc73c\ub85c \uc0c8\uae4c\ub9e3\uac8c \ud0d4\ub2e4.",body:["\uc774\uae00\uac70\ub9ac\ub294 \ud611\uace1\uc740 \uce74\uc988 \ubaa8\ub2e8 \ub0a8\ubd80\uc758 \uc7ac\uc640 \ub179\uc740 \ubc14\uc704\ub85c \uc0c8\uae4c\ub9e3\uac8c \ubcc0\ud55c \ub545\uc774\ub2e4. \uc774\uacf3\uc758 \uc0c1\ucc98\ub294 \ubd88\ud0c0\ub294 \ud3c9\uc6d0\uc744 \ud0dc\uc6b4 \uac83\uacfc \uac19\uc740 \uc7ac\uc559\uc5d0\uc11c \ube44\ub86f\ub418\uc5c8\ub2e4. \uc138 \ub9dd\uce58\uc758 \uc804\uc7c1\uc744 \ub05d\ub0b8 \ub9c8\ubc95\uc0ac \uc601\uc8fc \ud0c0\uc6b0\ub9bf\uc0b0\uc758 \ub77c\uadf8\ub098\ub85c\uc2a4 \uc18c\ud658\uc774\ub2e4. \uc9c0\uae08\uc740 \uac80\uc740\ubb34\uc1e0 \ub4dc\uc6cc\ud504\uac00 \uc774\uacf3\uc744 \uc9c0\ubc30\ud558\uba70, \ub178\uc608\ub4e4\uc744 \ubab0\uc544 \uac70\ub300\ud55c \uac00\ub9c8\uc1a5 \uade0\uc5f4\uc5d0\uc11c \uad11\uc11d\uc744 \uce90\uac8c \ud55c\ub2e4.","\ubaa8\ub4e0 \uac80\uc740\ubb34\uc1e0\uac00 \ubd88\uc758 \uad70\uc8fc\ub97c \uc12c\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud074\ub79c\uacfc \uac08\ub77c\uc120 \uc7a5\uc778 \ub300\uc7a5\uc7a5\uc774\ub4e4\uc778 \ud1a0\ub968 \ub300\uc7a5\uc870\ud569\uc740 \ud1a0\ub968 \uc870\ud569 \uac70\uc810\uc5d0\uc11c \uc678\ubd80\uc778\uacfc \uad50\uc5ed\ud55c\ub2e4. \ub0a8\ucabd\uc5d0\ub294 \uac80\uc740\ubc14\uc704 \uc0b0\uc774 \uc19f\uc544 \uc788\uc73c\uba70, \uadf8 \uae4a\uc740 \uacf3\uc5d0\ub294 \uac80\uc740\ubb34\uc1e0 \uc81c\uad6d\uc774, \uadf8 \uc704\uc758 \ucca8\ud0d1\uc5d0\ub294 \uc624\ud06c\uc640 \uac80\uc740 \uc6a9\ub4e4\uc774 \uc788\ub2e4."]},"zone:azshara":{title:"\uc544\uc988\uc0e4\ub77c",summary:"\uc544\uc988\uc0e4\ub77c \uc5ec\uc655\uc758 \uc218\ub3c4\uac00 \uac00\ub77c\uc549\uc740 \ud3d0\ud5c8 \uc704\ub85c \ud3bc\uccd0\uc9c4 \uc601\uc6d0\ud55c \uac00\uc744\uc758 \ud574\uc548.",body:["\uc544\uc988\uc0e4\ub77c\ub294 \uce7c\ub9bc\ub3c4\uc5b4 \ubd81\ub3d9\ubd80\uc758 \uc0b0\uc0b0\uc774 \ubd80\uc11c\uc9c4 \uc601\uc6d0\ud55c \uac00\uc744\uc758 \ud574\uc548\uc73c\ub85c, \ub098\ubb34\ub4e4\uc774 \ubd89\uc740\ube5b\uacfc \uae08\ube5b\uc73c\ub85c \ud0c0\uc624\ub978\ub2e4. \uc774\uacf3\uc5d0\ub294 \uace0\ub300 \ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \uac00\uc7a5 \uc704\ub300\ud55c \ub3c4\uc2dc \uc9c4\uc544\uc988\uc0e4\ub9ac\uac00 \uc788\uc5c8\uc9c0\ub9cc, \uc138\uacc4\uc758 \ubd84\ub9ac\uac00 \uadf8 \ub300\ubd80\ubd84\uc744 \ubc14\ub2e4\ub85c \ub0b4\ub358\uc84c\ub2e4. \ubb34\ub108\uc9c4 \uacc4\ub2e8\uc2dd \ud14c\ub77c\uc2a4\uac00 \uc544\uc9c1 \uc808\ubcbd\uc5d0 \ub9e4\ub2ec\ub824 \uc788\uace0, \uc548\uc2dd\ud558\uc9c0 \ubabb\ud55c \uba85\uac00\uc758 \uc601\ud63c\ub4e4\uc774 \uadf8\uacf3\uc744 \ub5a0\ub3c8\ub2e4. \ub098\uac00\uc640 \uc0ac\ud2f0\ub85c\uc2a4\uac00 \ud574\uc548\uc744 \ubc30\ud68c\ud558\uba70, \uc5bc\ub77c\uc774\uc5b8\uc2a4\ub294 \ud0c8\ub80c\ub4dc\ub9ac\uc2a4 \ucd08\uc18c\uc5d0, \ud638\ub4dc\ub294 \ubc1c\ub85c\ub974\ubaa8\ud06c\uc5d0 \uc791\uc740 \uc57c\uc601\uc9c0\ub97c \ub450\uace0 \uc788\ub2e4.","Forever\uc5d0\uc11c\ub294 \uc544\uc988\uc0e4\ub77c\uc758 \uc624\ub7ab\ub3d9\uc548 \ubd09\uc778\ub41c \ubb38\uc774 Blackmaw Hold\ub85c \uc5f4\ub9b0\ub2e4. \uc774\uacf3\uc740 \uac70\ub300\ud55c \ud37c\ubcfc\uadf8 \ub3c4\uc2dc\ub85c, \uadf8 \ubd80\uc871\uc740 \uc232\uacfc \uad74\uc744 \ub530\ub77c \ubc88\uc9c0\ub294 \ud0c0\ub77d\uacfc \uc2f8\uc6b0\uace0 \uc788\ub2e4. \uadf8 \uae4a\uc740 \uacf3\uc740 Barrow Deeps\uc640 \uc774\uc5b4\uc838 \uc788\uc73c\uba70 \ub354 \uc544\ub798\ub85c \ub0b4\ub824\uac04\ub2e4."]},"zone:blasted-lands":{title:"\uc800\uc8fc\ubc1b\uc740 \ub545",summary:"\uce68\ubb35\ud558\ub294 \uc5b4\ub460\uc758 \ubb38\uc744 \ub458\ub7ec\uc2fc \ubd89\uac8c \ud669\ud3d0\ud574\uc9c4 \uc0ac\ub9c9\uc73c\ub85c, \ub124\ub354\uac00\ub4dc \uc694\uc0c8\uc758 \ub9c8\ubc95\uc0ac\uc640 \uc131\uae30\uc0ac\ub4e4\uc774 \uc9c0\ucf1c\ubcf8\ub2e4.",body:["\uc800\uc8fc\ubc1b\uc740 \ub545\uc740 \ud55c\ub54c \uac80\uc740\ub2aa\uc758 \uc77c\ubd80\uc600\uc9c0\ub9cc, \uc5b4\ub460\uc758 \ubb38\uc744 \uc5f0 \ub9c8\ubc95\uc774 \uc774\uacf3\uc744 \uac08\ub77c\uc9c4 \uc810\ud1a0\uc758 \ubd89\uc740 \uc0ac\ub9c9\uc73c\ub85c \uc77c\uadf8\ub7ec\ub728\ub838\ub2e4. \ud638\ub4dc\uac00 \ucc98\uc74c \uce68\uacf5\ud574 \uc628 \uac70\ub300\ud55c \ubb38\uc740 \uc544\uc9c1 \uc774\uacf3\uc5d0 \uc11c \uc788\uc73c\uba70, \ud30c\uad34\ub41c \uc774\ud6c4 \uadf8 \ub3cc \ud2c0\uc740 \uc5b4\ub461\uace0 \uace0\uc694\ud558\ub2e4. \ub9c8\ubc95\uc0ac\uc640 \uc131\uae30\uc0ac\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc2a4\ud1b0\uc708\ub4dc\uc758 \uc694\uc0c8, \ub124\ub354\uac00\ub4dc \uc694\uc0c8\uac00 \uadf8 \ubb38\uc744 \uac10\uc2dc\ud55c\ub2e4.","\uadf8\uc744\ub9b0 \ud669\ubb34\uc9c0\uc5d0\ub294 \uc804\uac08\uacfc \ubc14\uc2e4\ub9ac\uc2a4\ud06c, Dreadmaul \uc624\uc6b0\uac70, \uadf8\ub9ac\uace0 \ucd94\ubc29\ub41c \ub4dc\ub808\ub098\uc774 \uba87\uba87 \ub9d0\uace0\ub294 \uc0b4\uc544 \uc788\ub294 \uac83\uc774 \uac70\uc758 \uc5c6\ub2e4. \uc545\ub9c8\ub4e4\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \ud30c\uba78\uc758 \uad70\uc8fc \uce74\uc790\ud06c\uac00 \ud0c0\ub77d\uc758 \ud749\ud130\uc5d0\uc11c \ubd88\ud0c0\ub294 \uad70\ub2e8\uc758 \uc794\ub2f9\uc744 \ubaa8\uc73c\uace0 \uc788\ub2e4."]},"zone:felwood":{title:"\uc545\ub839\uc758 \uc232",summary:"\uc545\ub9c8\ub4e4\uc5d0\uac8c \uc624\uc5fc\ub41c, \ud55c\ub54c \uc544\ub984\ub2e4\uc6e0\ub358 \uc232\uc73c\ub85c, \ub098\ubb34\uad6c\ub801 \ud37c\ubcfc\uadf8\uc640 \ub4dc\ub8e8\uc774\ub4dc\ub4e4\uc774 \ubd80\ud328\uc640 \uc2f8\uc6b0\uace0 \uc788\ub2e4.",body:["\uc545\ub839\uc758 \uc232\uc740 \ud55c\ub54c \ub098\uc774\ud2b8 \uc5d8\ud504\uac00 \uac00\uafb8\ub358 \uc2dc\ub0c7\ubb3c\uacfc \ucd08\uc6d0\uc758 \ub099\uc6d0\uc774\uc5c8\ub2e4. \uc81c3\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \ubd88\ud0c0\ub294 \uad70\ub2e8\uc774 \uad74\ub2e8\uc758 \ud574\uace8\uc758 \ud798\uc73c\ub85c \uc774 \uc232\uc744 \ub354\ub7fd\ud614\uace0, \ub545\uc740 \ub05d\ub0b4 \ud68c\ubcf5\ub418\uc9c0 \ubabb\ud588\ub2e4. \uac15\uc740 \ub3c5\uc73c\ub85c \ucd08\ub85d\ube5b\uc744 \ub760\uace0, \uace0\ub300\uc815\ub839\uacfc \ub098\ubb34\uc815\ub839\uc740 \uc120 \ucc44\ub85c \uc369\uc5b4 \uac00\uba70, \uc0ac\ud2f0\ub85c\uc2a4\uc640 \uc9c0\uc625\ubd88\uc815\ub839, \uadf8\ub9ac\uace0 \uc545\ub9c8\ub97c \uc22d\ubc30\ud558\ub294 \uc81c\uc774\ub370\ub098\ub974\uc758 \uc5b4\ub460\uc758 \uc758\ud68c\uac00 \uc232\uc18d \uacf5\ud130\ub97c \ub5a0\ub3c8\ub2e4.","Talonbranch Glade\uc758 \ub098\uc774\ud2b8 \uc5d8\ud504, Bloodvenom Post\uc758 \ud638\ub4dc, \uadf8\ub9ac\uace0 \uc5d0\uba54\ub784\ub4dc \uc131\uc18c\uc758 \ub4dc\ub8e8\uc774\ub4dc\ub4e4\uc774 \ud0c0\ub77d\uc744 \ubab0\uc544\ub0b4\ub824 \uc560\uc4f0\uace0 \uc788\ub2e4. \ubd81\ucabd\uc5d0\uc11c\ub294 \ub9c8\uc9c0\ub9c9 \ub0a8\uc740 \ud0c0\ub77d\ud558\uc9c0 \uc54a\uc740 \ud37c\ubcfc\uadf8 \ubd80\uc871 \uac00\uc6b4\ub370 \ud558\ub098\uc778 \ub098\ubb34\uad6c\ub801 \ubd80\uc871\uc774 \ub2ec\uc758 \uc232\uacfc \uc5ec\uba85\uc758 \uc124\uc6d0\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uad74\uc744 \uc9c0\ud0a8\ub2e4."]},"zone:un-goro-crater":{title:"\uc6b4\uace0\ub85c \ubd84\ud654\uad6c",summary:"\uacf5\ub8e1\uacfc \uc0b4\uc544 \uc788\ub294 \uc815\ub839, \uadf8\ub9ac\uace0 \uce68\ubb35\ud558\ub294 \ud2f0\ud0c4\uc758 \uae30\ub465\uc774 \uc788\ub294 \ud0dc\uace0\uc758 \ubc00\ub9bc \ubd84\ud654\uad6c.",body:["\uc6b4\uace0\ub85c \ubd84\ud654\uad6c\ub294 \uce7c\ub9bc\ub3c4\uc5b4 \ub0a8\ubd80\uc758 \uc0ac\ub9c9\ub4e4 \uc0ac\uc774\uc5d0 \uc6c0\ud479 \uaebc\uc9c4, \uae40\uc774 \ud53c\uc5b4\uc624\ub974\ub294 \ud0dc\uace0\uc758 \ubc00\ub9bc\uc774\ub2e4. \ub370\ube4c\uc0ac\uc6b0\ub8e8\uc2a4\uac00 \uc0ac\ub0e5\ud558\uace0, \uc628\ucc9c\uc5d0\uc11c \uc815\ub839\uc774 \uc19f\uc544\uc624\ub974\uba70, \ud55c\uac00\uc6b4\ub370\uc5d0\uc11c\ub294 Fire Plume Ridge\uac00 \uc5f0\uae30\ub97c \ub0b4\ubfdc\ub294 \ubcc4\ucc9c\uc9c0\ub2e4. \ud0d0\ud5d8\uac00\ub4e4\uc740 \ub9c8\uc0ec\uc758 \uc57c\uc601\uc9c0\uc5d0 \ubaa8\uc5ec \uc774\uacf3\uc758 \ubd89\uc740\uc0c9, \ud478\ub978\uc0c9, \ucd08\ub85d\uc0c9, \ub178\ub780\uc0c9 \uc218\uc815\uacfc, \ud2f0\ud0c4\uc758 \uc791\ud488\uc73c\ub85c \ubcf4\uc774\ub294 \ubd84\ud654\uad6c \ub2a5\uc120 \uc704\uc758 \uc218\uc218\uaed8\ub07c \uac19\uc740 \uae30\ub465\ub4e4\uc744 \uc5f0\uad6c\ud55c\ub2e4.","\ub0a8\ucabd\uc5d0\ub294 \uc774\uc6c3\ud55c \uc2e4\ub9ac\ub354\uc2a4\uc5d0\uc11c \ud37c\uc838 \uc628 \uc2e4\ub9ac\uc2dc\ub4dc\uac00 \ub098\ud0c0\ub0ac\ub2e4. Forever\uc5d0\uc11c\ub294 \ubd84\ud654\uad6c \ub192\uc740 \uacf3\uc5d0 \uc788\ub294 \uace0\ub300 \ud2f0\ud0c4 \uc2dc\uc124 Shaper's Terrace\uac00 \uc6b4\uace0\ub85c \uacf3\uacf3\uc5d0\uc11c \ubaa8\uc740 \ud798\uc758 \uc218\uc815\uc744 \uac00\uc838\uc628 \ubaa8\ud5d8\uac00\ub4e4\uc5d0\uac8c \uc5f4\ub9b0\ub2e4."]},"zone:burning-steppes":{title:"\ubd88\ud0c0\ub294 \ud3c9\uc6d0",summary:"\uac80\uc740\ubc14\uc704 \uc0b0 \uc544\ub798 \uc7ac\ub85c \uc228 \ub9c9\ud788\ub294 \uace0\uc6d0\uc73c\ub85c, \uac80\uc740\ubc14\uc704 \uc624\ud06c\uc640 Fire-Gut \uc624\uc6b0\uac70, \uac80\uc740 \uc6a9\ub4e4\uc774 \ucc28\uc9c0\ud558\uace0 \uc788\ub2e4.",body:["\ubd88\ud0c0\ub294 \ud3c9\uc6d0\uc740 \uc7ac\uc640 \uc6a9\uc554, \uc5f0\uae30\ub97c \ub0b4\ubfdc\ub294 \ubc14\uc704\ub85c \uc774\ub8e8\uc5b4\uc9c4 \ud669\ud3d0\ud55c \uace0\uc6d0\uc73c\ub85c, \ud0c0\uc6b0\ub9bf\uc0b0\uc758 \ub77c\uadf8\ub098\ub85c\uc2a4 \uc18c\ud658\uc774 \uc138 \ub9dd\uce58\uc758 \uc804\uc7c1\uc744 \ub05d\ub0c8\uc744 \ub54c \ubd88\ud0c0 \ubc84\ub838\ub2e4. \uc61b \uac80\uc740\ubb34\uc1e0 \ub3c4\uc2dc \ud0c0\uc6b0\ub9bf\uc0b0\uc758 \ud3d0\ud5c8\uac00 \uc544\uc9c1 \uc774\uacf3\uc5d0 \uc11c \uc788\ub2e4. \uc774 \ud3c9\uc6d0\uc740 \uc2a4\ud1b0\uc708\ub4dc\uc640 \uce74\uc988 \ubaa8\ub2e8\uc744 \uc787\ub294 \uc720\uc77c\ud55c \uc721\ub85c\uc774\uc9c0\ub9cc, \uc655\uad6d\uc740 \uc774\uacf3\uc744 \uac70\uc758 \ubc84\ub824 \ub450\uc5c8\ub2e4.","\uadf8 \uc704\ub85c \uac80\uc740\ubc14\uc704 \uc0b0\uc774 \uc19f\uc544 \uc788\ub2e4. \uc81c2\ucc28 \ub300\uc804\uc7c1 \ub54c \ud638\ub4dc\uc758 \uac70\ub300\ud55c \uc694\uc0c8\uc600\ub358 \uac80\uc740\ubc14\uc704 \ucca8\ud0d1\uc740 \ub124\ud30c\ub9ac\uc548 \ud718\ud558\uc758 \uac80\uc740\ubc14\uc704 \uc624\ud06c\uc640 \uac80\uc740 \uc6a9\ub4e4\uc774 \ucc28\uc9c0\ud558\uace0 \uc788\uc73c\uba70, \uac80\uc740\ubb34\uc1e0 \ub4dc\uc6cc\ud504\ub294 \uadf8 \uc544\ub798 \uae4a\uc740 \uacf3\uc744 \ub2e4\uc2a4\ub9b0\ub2e4. Fire-Gut \uc624\uc6b0\uac70\uac00 \ud3c9\uc6d0\uc744 \ub5a0\ub3cc\uace0, \uc5bc\ub77c\uc774\uc5b8\uc2a4 \uc804\ucd08\uae30\uc9c0\uc778 \ubaa8\uac74\uc758 \ub9dd\ub8e8\uc640 Flame Crest\uc758 \ud638\ub4dc \uc57c\uc601\uc9c0\ub9cc\uc774 \ubc84\ud2f0\uace0 \uc788\ub2e4."]},"zone:western-plaguelands":{title:"\uc11c\ubd80 \uc5ed\ubcd1\uc9c0\ub300",summary:"\uc2a4\uceec\uc9c0\uac00 \uc548\ub3c4\ud560\uc744 \ucc28\uc9c0\ud558\uace0 \uc6b0\uc11c\uc758 \ubb34\ub364\ub9cc\uc774 \ub9c8\uc9c0\ub9c9 \uc2e0\uc131\ud55c \ub545\uc73c\ub85c \ub0a8\uc740 \ub85c\ub370\ub860\uc758 \ubcd1\ub4e0 \ub18d\uacbd\uc9c0.",body:["\uc11c\ubd80 \uc5ed\ubcd1\uc9c0\ub300\ub294 \ud55c\ub54c \ub85c\ub370\ub860\uc5d0\uc11c \uac00\uc7a5 \uae30\ub984\uc9c4 \ub18d\uacbd\uc9c0\uc600\ub2e4. \uc9c0\uae08\uc740 \ubcd1\ub4e0 \ub4e4\ud310 \uc704\ub85c \uc7bf\ube5b \uc548\uac1c\uac00 \ub4dc\ub9ac\uc6b0\uace0 \uc5b8\ub370\ub4dc\uac00 \ubc84\ub824\uc9c4 \ub18d\uac00\ub97c \ub5a0\ub3c8\ub2e4. \ucf08\ud22c\uc790\ub4dc\uc758 \uad50\ub2e8\uc774 \uc5ed\ubcd1 \uace1\ubb3c\uc744 \ud37c\ub728\ub9b0 \ud3d0\ud5c8 \ub9c8\uc744 \uc548\ub3c4\ud560\uc740 \uc774\uacf3\uc5d0\uc11c \uac00\uc7a5 \ud070 \uc2a4\uceec\uc9c0\uc758 \uac70\uc810\uc774\uba70, \uc5ed\ubcd1 \uac00\ub9c8\uc1a5\uc774 \uc8fc\ubcc0 \ub4e4\ud310\uc744 \uc624\uc5fc\uc2dc\ud0a8\ub2e4. \ub300\ub85c\uc6b0\ubbf8\uc5b4 \ud638\uc218\uc758 \uc12c\uc5d0 \uc788\ub294 \ubc14\ub85c\ube0c \uac00\ubb38\uc758 \uc694\uc0c8 \uce74\uc5d8 \ub2e4\ub85c\uc6b0\ub294 \uac15\ub839\uc220 \ud559\uad50 \uc2a4\uce7c\ub85c\ub9e8\uc2a4\ub97c \uc228\uae30\uace0 \uc788\ub2e4.","\ubd89\uc740\uc2ed\uc790\uad70\uc740 \ubd81\ucabd\uc758 \ud558\uc2a4\uae00\ub80c\uc5d0\uc11c, \uc5bc\ub77c\uc774\uc5b8\uc2a4\ub294 \uc11c\ub9ac\ubc14\ub78c \uc57c\uc601\uc9c0\uc5d0\uc11c \uc2f8\uc6b0\uba70, \ud3ec\uc138\uc774\ud070\uc740 \ud2f0\ub9ac\uc2a4\ud314\uacfc\uc758 \uacbd\uacc4\uc5d0 \uc788\ub294 \ubcf4\ub8e8\ub97c \uc9c0\ud0a8\ub2e4. \ube5b\uc758 \uc218\ud638\uc790\uac00 \uc7a0\ub4e0 \uc6b0\uc11c\uc758 \ubb34\ub364\ub9cc\uc774 \ud3c9\ud654\uac00 \uae43\ub4e0 \uc720\uc77c\ud55c \uc131\uc9c0\ub2e4."]},"zone:eastern-plaguelands":{title:"\ub3d9\ubd80 \uc5ed\ubcd1\uc9c0\ub300",summary:"\ubb34\ub108\uc9c4 \ub85c\ub370\ub860\uc5d0\uc11c \uac00\uc7a5 \ud669\ud3d0\ud55c \uacf3\uc73c\ub85c, \uc2a4\uceec\uc9c0\uac00 \ubd88\ud0c0 \ubc84\ub9b0 \ub3c4\uc2dc \uc2a4\ud2b8\ub77c\uc194\ub984\uc5d0\uc11c \ub2e4\uc2a4\ub9b0\ub2e4.",body:["\ub3d9\ubd80 \uc5ed\ubcd1\uc9c0\ub300\ub294 \ub85c\ub370\ub860 \uc655\uad6d\uc5d0\uc11c \uac00\uc7a5 \ucc98\ucc38\ud558\uac8c \ud669\ud3d0\ud574\uc9c4 \ub545\uc774\ub2e4. \uac08\uc0c9\uc73c\ub85c \ubcd1\ub4e0 \ud759, \uac70\ub300\ud55c \ubc84\uc12f\ucc98\ub7fc \ubd80\ud480\uc5b4 \uc624\ub978 \ub098\ubb34\ub4e4, \uadf8\ub9ac\uace0 \uc8fc\ud669\ube5b \uc548\uac1c\ub85c \ud0c1\ud55c \uacf5\uae30\uac00 \uac00\ub4dd\ud558\ub2e4. \uadf8 \ud55c\uac00\uc6b4\ub370\uc5d0\ub294 \uc81c3\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \uc544\uc11c\uc2a4 \uc655\uc790\uac00 \uc8fc\ubbfc\ub4e4\uc744 \uce7c\ub85c \ubca0\uc5b4 \ubc84\ub9b0 \ub3c4\uc2dc \uc2a4\ud2b8\ub77c\uc194\ub984\uc774 \uc788\uc73c\uba70, \uc9c0\uae08\uc740 \uc2a4\uceec\uc9c0\uc640 \ubd89\uc740\uc2ed\uc790\uad70\uc774 \ub098\ub204\uc5b4 \ucc28\uc9c0\ud558\uace0 \uc788\ub2e4.","\uc2ed\uc790\uad70\uc758 \uc8fc\ub825 \ubd80\ub300\ub294 \ud2f0\ub974\uc758 \uc190\uc744 \ucc28\uc9c0\ud558\uace0 \ud070 \uc5f4\uc758\ub85c \uc5b8\ub370\ub4dc\uc640 \uc2f8\uc6b0\uc9c0\ub9cc \uc131\uacfc\ub294 \uc801\uc73c\uba70, \uc740\ube5b \uc5ec\uba85\ud68c\ub294 \ud76c\ub9dd\uc758 \ube5b \uc608\ubc30\ub2f9\uc5d0\uc11c \ub3c4\uc6b0\ub824\ub294 \uc774\ub77c\uba74 \ub204\uad6c\ub4e0 \ubc18\uae34\ub2e4. \ub2e4\ub85c\uc6b0\uc154\uc640 \ucf54\ub9b0\uc758 \uad50\ucc28\ub85c \uac19\uc740 \uc720\ub839 \ub9c8\uc744\ub4e4\uc774 \ud328\ubc30\ud55c \uc804\ud22c\ub97c \uc99d\uc5b8\ud558\uace0, \uc544\ub9c8\ub2c8 \ud2b8\ub864\uc740 \ubd81\ucabd\uc758 \uc904\ub9c8\uc0e4\ub974\uc5d0\uc11c \uc61b \ub545\uc744 \ub418\ucc3e\uc73c\ub824 \uacf5\uaca9\ud574 \uc628\ub2e4."]},"zone:winterspring":{title:"\uc5ec\uba85\uc758 \uc124\uc6d0",summary:"\ud558\uc774\uc798 \ube44\ud0c8\uc758 \ub208 \ub36e\uc778 \uace8\uc9dc\uae30\ub85c, \uace0\ube14\ub9b0 \uc0c1\uc778\uacfc \ub208\ud638\ub791\uc774, \ud478\ub978 \uc6a9, \uc545\ub9c8\uac00 \ud568\uaed8 \uc788\ub2e4.",body:["\uc5ec\uba85\uc758 \uc124\uc6d0\uc740 \ud558\uc774\uc798 \uc0b0 \ube44\ud0c8\uc5d0 \uc788\ub294 \uac70\uc758 \ub179\uc9c0 \uc54a\ub294 \ub208\uc758 \uace8\uc9dc\uae30\ub85c, \uc138\uacc4\uc758 \ubd84\ub9ac \uc774\ud6c4 \ub098\uc774\ud2b8 \uc5d8\ud504\uac00 \ucc98\uc74c\uc73c\ub85c \uc7ac\uac74\uc744 \uc2dc\uc791\ud55c \uacf3\uc774\ub2e4. \uace0\ube14\ub9b0 \ub9c8\uc744 \ub208\ub9dd\ub8e8 \ub9c8\uc744\uc740 \ub204\uad6c\uc640\ub3c4 \uad50\uc5ed\ud558\uace0, \ub098\uc774\ud2b8 \uc5d8\ud504\ub294 \uc544\uc9c1 \ubcc4\ub625\ubcc4 \ub9c8\uc744\uc744 \uc9c0\ud0a4\uba70, Frostsaber Rock\uc758 \uc870\ub828\uc0ac\ub4e4\uc740 \uace8\uc9dc\uae30\uc758 \ud770 \uace0\uc591\uc787\uacfc \uc9d0\uc2b9\ub4e4\uc744 \uae30\ub978\ub2e4. \ud478\ub978 \uc6a9\ub4e4\uc740 \ub9c8\uc988\uc18c\ub9b4\uc758 \ub3d9\uad74\uc5d0 \ub465\uc9c0\ub97c \ud2c0\uc5c8\ub2e4.","\uace8\uc9dc\uae30 \ub0a8\ucabd\uc740 Darkwhisper Gorge\uc5d0\uc11c \uc545\ub9c8\ub4e4\uc5d0\uac8c \ub118\uc5b4\uac14\uace0, Winterfall \ud37c\ubcfc\uadf8\ub294 \uc0ac\ub098\uc6cc\uc84c\ub2e4. Forever\uc5d0\uc11c\ub294 \uc5ec\uba85\uc758 \uc124\uc6d0\uc744 \uac70\uccd0 Barrow Deeps \uacf5\uaca9\ub300\uc758 \uc785\uad6c \uac00\uc6b4\ub370 \ud558\ub098\ub85c \uac08 \uc218 \uc788\ub2e4."]},"zone:deadwind-pass":{title:"\uc8fd\uc74c\uc758 \uace0\uac1c",summary:"\ub9c8\uc9c0\ub9c9 \uc218\ud638\uc790 \uba54\ub514\ube0c\uc758 \ud0d1 \uce74\ub77c\uc794\uc774 \uad7d\uc5b4\ubcf4\ub294, \ubc14\ub78c\uc5d0 \ucc22\uae34 \uc8fd\uc740 \uace0\uac1c.",body:["\uc8fd\uc74c\uc758 \uace0\uac1c\ub294 \uadf8\ub298\uc232\uacfc \uc2ac\ud514\uc758 \ub2aa \uc0ac\uc774\uc5d0 \uc788\ub294, \ud654\uc11d\uc774 \ub41c \uc78e \uc5c6\ub294 \ub098\ubb34\ub4e4\uc758 \ud5d8\ud55c \ud611\uace1\uc73c\ub85c, \uc6b8\ubd80\uc9d6\ub294 \ubc14\ub78c\uc774 \ub04a\uc784\uc5c6\uc774 \ubd88\uc5b4\uc628\ub2e4. \uadf8 \ud55c\uac00\uc6b4\ub370\uc5d0\ub294 \ud2f0\ub9ac\uc2a4\ud314\uc758 \ub9c8\uc9c0\ub9c9 \uc218\ud638\uc790 \uba54\ub514\ube0c\uc758 \uc0c1\uc544\ud0d1 \uce74\ub77c\uc794\uc774 \uc11c \uc788\ub2e4. \uc0b4\uac8c\ub77c\uc2a4\uc5d0\uac8c \ube59\uc758\ub41c \uba54\ub514\ube0c\uac00 \ud638\ub4dc\uc758 \uae38\uc744 \uc5f4\uc5c8\ub2e4. \uba54\ub514\ube0c\ub294 \uc624\ub798\uc804\uc5d0 \uc8fd\uc5c8\uc9c0\ub9cc, \uadf8\uc758 \ud0d1\uc5d0\uc11c\ub294 \uc5ec\uc804\ud788 \uc5b4\ub460\uc758 \ub9c8\ubc95\uc774 \ub545\uc73c\ub85c \uc0c8\uc5b4 \ub098\uc628\ub2e4.","\uc8fd\uc74c\uc758 \uace0\uac1c \uc624\uc6b0\uac70\uc640 \uc545\ub9c8, \uc548\uc2dd\ud558\uc9c0 \ubabb\ud55c \uc601\ud63c\ub4e4\uc774 \uace0\uac1c\ub97c \ub5a0\ub3cc\uace0, Morgan's Plot\uc758 \ubb34\ub364\ub4e4\uc740 \ud3b8\ud788 \uc7a0\ub4e4\uc9c0 \ubabb\ud558\uba70, \uc5ec\ud589\uc790\ub4e4\uc740 \uc0c8\ub85c\uc6b4 \ud798\uc774 \ud0d1\uc744 \ucc28\uc9c0\ud588\ub2e4\uace0 \uc218\uad70\uac70\ub9b0\ub2e4. \ub300\ubd80\ubd84\uc740 \uc11c\ub458\ub7ec \uc9c0\ub098\uac04\ub2e4."]},"zone:moonglade":{title:"\ub2ec\uc758 \uc232",summary:"\uce7c\ub9bc\ub3c4\uc5b4 \ubd81\ubd80\uc758 \ud3c9\ud654\ub85c\uc6b4 \ub4dc\ub8e8\uc774\ub4dc \uc131\uc5ed\uc73c\ub85c, \uc138\ub098\ub9ac\uc628 \uc758\ud68c\uc758 \ubcf8\uac70\uc9c0.",body:["\ub2ec\uc758 \uc232\uc740 \uce7c\ub9bc\ub3c4\uc5b4 \ubd81\ubd80\uc5d0 \uc228\uaca8\uc9c4 \uace8\uc9dc\uae30\ub85c, \uc218\ucc9c \ub144 \ub3d9\uc548 \ub4dc\ub8e8\uc774\ub4dc\uc5d0\uac8c \uc2e0\uc131\ud55c \uacf3\uc774\uc5c8\ub2e4. \ub9d0\ud4e8\ub9ac\uc628 \uc2a4\ud1b0\ub808\uc774\uc9c0\ub294 \uc774\uacf3\uc5d0 \ub4dc\ub8e8\uc774\ub4dc\ub4e4\uc744 \ubaa8\uc544 \uc138\ub098\ub9ac\uc628 \uc758\ud68c\ub97c \uc138\uc6e0\uc73c\uba70, \uc5d0\uba54\ub784\ub4dc\uc758 \uafc8\uc5d0 \ube44\uce5c \uc774 \uace8\uc9dc\uae30\uc758 \ubaa8\uc2b5\uc740 \uadf8 \uc138\uacc4\uc5d0\uc11c \uac00\uc7a5 \uc2e0\uc131\ud55c \uacf3\uc774\ub2e4. \ub098\uc774\ud2b8\ud5e4\uc774\ube10 \ub9c8\uc744\uc5d0\uc11c\ub294 \uc138\ub098\ub9ac\uc6b0\uc2a4\uc758 \uc544\ub4e4\uc778 \uc218\ud638\uc790 \ub808\ubb3c\ub85c\uc2a4\uac00 \uc758\ud68c\ub97c \ub3cc\ubcf8\ub2e4.","\uc81c3\ucc28 \ub300\uc804\uc7c1 \uc774\ud6c4 \uc758\ud68c\ub294 \ub4dc\ub8e8\uc774\ub4dc\uc758 \uae38\uc744 \uac77\ub294 \ubaa8\ub4e0 \uc774\uc5d0\uac8c \ub2ec\uc758 \uc232\uc744 \uc5f4\uc5c8\uace0, \uc774\uc81c \ud0c0\uc6b0\ub80c\uacfc \ub098\uc774\ud2b8 \uc5d8\ud504\uac00 \ud3c9\ud654\ub86d\uac8c \uadf8 \ubb3c\uac00\ub97c \ud568\uaed8 \uc4f4\ub2e4. \ub2ec\uc758 \uc232 \uac10\uc2dc\uc790\ub4e4\uc740 \uc131\uc5ed \uc548\uc5d0\uc11c\uc758 \ud3ed\ub825\uc744 \uc6a9\ub0a9\ud558\uc9c0 \uc54a\uc73c\uba70, \ud574\ub9c8\ub2e4 \ub098\uc774\ud2b8\ud5e4\uc774\ube10\uc5d0\uc11c\ub294 \ub2ec\uc758 \ucd95\uc81c\uac00 \uc5f4\ub9b0\ub2e4."]},"zone:silithus":{title:"\uc2e4\ub9ac\ub354\uc2a4",summary:"\uce7c\ub9bc\ub3c4\uc5b4 \ub0a8\uc11c\ubd80\uc758 \ud587\ubcd5\uc5d0 \ud0c0\ub294 \uace4\ucda9 \uad70\ub77d \uc0ac\ub9c9\uc73c\ub85c, \uc138\ub098\ub9ac\uc628 \uc758\ud68c\uac00 \ubd09\uc778\ub41c \uc548\ud034\ub77c\uc988\uc758 \ubb38\uc744 \uac10\uc2dc\ud55c\ub2e4.",body:["\uc2e4\ub9ac\ub354\uc2a4\ub294 \uce7c\ub9bc\ub3c4\uc5b4 \ub0a8\uc11c\ucabd \ub05d\uc758 \uc774\uae00\uac70\ub9ac\ub294 \uc0ac\ub9c9\uc73c\ub85c, \uc2e4\ub9ac\uc2dc\ub4dc\uc758 \uac70\ub300\ud55c \uad70\ub77d\ub9cc\uc774 \uadf8 \ud48d\uacbd\uc744 \ub04a\uc5b4 \ub193\ub294\ub2e4. \ud750\ub974\ub294 \ubaa8\ub798\uc758 \uc804\uc7c1 \uc774\ud6c4 \uace4\ucda9\uc744 \ub2ee\uc740 \ud034\ub77c\uc9c0\ub294 \uc6a9\uad70\ub2e8\ub4e4\uc774 \uc138\uc6b4 \uc2a4\uce74\ub77c\ubca0 \uc131\ubcbd \ub4a4\uc5d0 \ubd09\uc778\ub418\uc5b4 \uc788\uc9c0\ub9cc, \uadf8\ub4e4\uc758 \uc2e4\ub9ac\uc2dc\ub4dc \ubb34\ub9ac\ub294 \uacc4\uc18d \ubd88\uc5b4\ub098\uace0 \uc788\ub2e4.","\uc138\ub098\ub9ac\uc628 \uc758\ud68c\ub294 \uc138\ub098\ub9ac\uc628 \uc694\uc0c8\uc5d0\uc11c \uc704\ud611\uc744 \uac10\uc2dc\ud558\uace0, \ud669\ud63c\uc758 \ub9dd\uce58 \uad11\uc2e0\ub3c4\ub4e4\uc740 \uc800\ub9c8\ub2e4\uc758 \ubaa9\uc801\uc744 \uc704\ud574 \ubaa8\ub798 \uc5b8\ub355 \uacf3\uacf3\uc758 \uc57c\uc601\uc9c0\uc5d0 \ubaa8\uc5ec\ub4e0\ub2e4. \uc131\ubcbd \ub108\uba38\uc5d0\uc11c\ub294 \uc694\uc0c8 \uc2e0\uc804 \uc548\ud034\ub77c\uc988\uac00 \uae30\ub2e4\ub9ac\uace0 \uc788\ub2e4."]}}},1795,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"instances1",{enumerable:!0,get:function(){return n}});const n={"instance:hall-of-thanes":{title:"Hall of Thanes",summary:"\uce68\uc785\uc790\ub4e4\uc5d0\uac8c \ub6ab\ub9b0 \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \uc655\uc2e4 \ubb18\uc18c\ub85c, \ub4dc\uc6cc\ud504\ub4e4\uc740 \uac80\uc740\ubb34\uc1e0 \ub4dc\uc6cc\ud504\ub97c \uc758\uc2ec\ud558\uace0 \uc788\ub2e4.",body:["\uc544\uc774\uc5b8\ud3ec\uc9c0 \uc544\ub798\uc5d0\ub294 Hall of Thanes\uac00 \uc788\ub2e4. \ub4dc\uc6cc\ud504\ub4e4\uc774 \uad70\uc8fc\ub97c \uc548\uc7a5\ud558\uace0 \ubb34\ub364\uc744 \uc815\uc131\uaecf \ub3cc\ubcf4\ub294 \uacf3\uc774\ub2e4. \uc785\uad6c\ub294 \ub3c4\uc2dc \ud55c\uac00\uc6b4\ub370 High Seat\uc758 \ubb38\ud131\uc5d0 \uc788\uc5b4, \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc5d0\uac8c\ub294 \uac00\ubcbc\uc6b4 \uc0b0\ucc45\uc774\uc9c0\ub9cc \ud638\ub4dc \ud30c\ud2f0\uc5d0\uac8c\ub294 \ub300\ub2f4\ud55c \uce68\uc785\uc774\ub2e4. \uc774\uc81c \uce68\uc785\uc790\ub4e4\uc774 \uc2e0\uc131\ud55c \ubb34\ub364\uae4c\uc9c0 \uc5b5\uc9c0\ub85c \ub6ab\uace0 \ub4e4\uc5b4\uc654\ub2e4. \ub4dc\uc6cc\ud504\ub4e4\uc740 \uac80\uc740\ubb34\uc1e0 \ubd80\uc871\uc744 \uc758\uc2ec\ud558\uace0 \uc788\uc73c\uba70, \uc624\ub798\ub41c \ub3cc\uc740 \uc720\ub839\uc758 \uc18d\uc0ad\uc784\uc73c\ub85c \uac00\ub4dd\ud558\ub2e4.","\ud018\uc2a4\ud2b8\ub294 \ub300\ubd80\ubd84 \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc6a9\uc774\uba70 \uce74\ub77c\ub178\uc2a4\ub098 \uc544\uc774\uc5b8\ud3ec\uc9c0 \uc77c\ub300\uc5d0\uc11c \uc2dc\uc791\ud558\uc9c0\ub9cc, \ub0b4\ubd80 \ud018\uc2a4\ud2b8 \ud558\ub098\ub294 \uc911\ub9bd \uc720\ub839\uc774 \uc900\ub2e4. \ub124 \uba85\uc758 \uc801\uc774 \uae38\uc744 \ub9c9\ub294\ub2e4. Faldrim Anvilmar, Magmatus, Plunder, Durgen Dirgehammer\ub2e4."],unknowns:["\uce68\uc785\uc790\ub4e4\uc758 \uc9c4\uc9dc \uc815\uccb4. \uacf5\uc2dd \uc124\uba85\uc740 \ub4dc\uc6cc\ud504\ub4e4\uc774 \uac80\uc740\ubb34\uc1e0 \ubd80\uc871\uc744 \uc758\uc2ec\ud55c\ub2e4\uace0\ub9cc \ub9d0\ud55c\ub2e4.","\uc804\ub2f9 \uc548\uc5d0\uc11c \ubb34\uc5c7\uc774 \uae68\uc5b4\ub0ac\ub294\uc9c0, \uadf8\ub9ac\uace0 \ub124 \uc801 \uac01\uac01\uc5d0 \uc5bd\ud78c \uc0ac\uc5f0."]},"instance:ragefire-chasm":{title:"\uc131\ub09c\ubd88\uae38 \ud611\uace1",summary:"\uc624\uadf8\ub9ac\ub9c8 \uc544\ub798\uc758 \ud654\uc0b0 \ub3d9\uad74\ub85c, \ud2b8\ub85c\uadf8\uc640 \uc545\ub9c8\ub97c \uc12c\uae30\ub294 \uad50\ub2e8\uc774 \ud638\ub4dc\uc758 \uc0c8 \uc218\ub3c4\ub97c \uc704\ud611\ud55c\ub2e4.",body:["\uc624\uadf8\ub9ac\ub9c8 \uc544\ub798\uc5d0\ub294 \uc6a9\uc554 \ube5b\uc774 \uc77c\ub801\uc774\ub294 \ub3d9\uad74\ub4e4\uc774 \ubbf8\ub85c\ucc98\ub7fc \ubed7\uc5b4 \uc788\uc73c\uba70, \ud638\ub4dc\ub294 \uc0c8 \uc218\ub3c4\uac00 \uacb0\ucf54 \ud3b8\uc548\ud558\uc9c0 \uc54a\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uac8c \ub418\uc5c8\ub2e4. \uc131\ub09c\ubd88\uae38\uc774\ub77c \ubd88\ub9ac\ub294 \ud2b8\ub85c\uadf8\ub4e4\uc774 \uae4a\uc740 \uad74\uc5d0\uc11c \uae30\uc5b4 \uc62c\ub77c\uc654\uace0, \ud0c0\uc6b0\ub80c \uc6d0\ub85c \ub9c8\uac00\uc0ac \uadf8\ub9bc\ud1a0\ud15c\uc774 \uadf8\ub4e4\uacfc \ud654\ud574\ud558\ub824 \ud558\uc790 \ub3cc\uc544\uc628 \uac83\uc740 \ud3ed\ub825\ubfd0\uc774\uc5c8\ub2e4.","\ub354 \ub098\uc05c \uac83\uc740 \uc545\ub9c8\uc758 \uc5b4\ub460\uc758 \uc758\ud68c\uc5d0 \ucda9\uc131\ud558\ub294 \uc774\uae00\uac70\ub9ac\ub294 \uce7c\ub0a0\uc774\ub77c\ub294 \ubd84\ud30c\uac00 \ud611\uace1\uc5d0 \uc228\uc5b4, \uc2a4\ub784\uc758 \ubc31\uc131\uc774 \uc774\ub8ec \ubaa8\ub4e0 \uac83\uc744 \ubb34\ub108\ub728\ub9ac\ub824 \uc74c\ubaa8\ub97c \uafb8\ubbf8\uace0 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uc774\ub4e4\uc744 \uc774\ub044\ub294 \uac83\uc740 \uc9c0\uc625\uc218\ud638\ubcd1 Taragaman the Hungerer\uc774\uba70, \uadf8 \uacc1\uc5d0\ub294 \ud751\ub9c8\ubc95\uc0ac Jergosh the Invoker\uc640 \uc0ac\ud2f0\ub85c\uc2a4 \ubc14\uc798\ub780\uc774 \uc788\ub2e4. \ub9ce\uc740 \ud638\ub4dc \uc2e0\ucc38 \uc601\uc6c5\uc5d0\uac8c \uc774 \ub3d9\uad74\uc740 \uccab \ub358\uc804\uc774\ub2e4."]},"instance:ruins-of-lordaeron":{title:"Ruins of Lordaeron",summary:"\uc5b8\ub354\uc2dc\ud2f0 \uc704\uc758 \ubb34\ub108\uc9c4 \uc218\ub3c4\ub85c, \ud3ec\uc138\uc774\ud070\uc774 \uacfc\uac70\ub97c \ub418\ucc3e\uc73c\ub824 \ud558\ub294 \uc0ac\uc774 \ud55c \uac15\ub839\uc220\uc0ac\uac00 \ud798\uc744 \ubaa8\uc73c\uace0 \uc788\ub2e4.",body:["\ud3ec\uc138\uc774\ud070\uc740 \uc5b8\ub354\uc2dc\ud2f0 \uc704\uc5d0 \uc788\ub294 \ud3d0\ud5c8\uac00 \ub41c \uc218\ub3c4\ub97c \ub418\ucc3e\uc73c\ub824 \ud558\uace0 \uc788\ub2e4. \uc794\ud574 \uc18d\uc5d0\ub294 \uc544\uc9c1 \uc18c\uc911\ud55c \uac00\ubcf4\uc640 \ucd94\uc5b5\uc774 \ub0a8\uc544 \uc788\uc9c0\ub9cc, \uc2a4\uceec\uc9c0\uac00 \ubd80\uc11c\uc9c4 \uac70\ub9ac\ub97c \ub5a0\ub3cc\uace0, \uc131\ubcbd \uc548\uc5d0\uc11c \ud55c \uac15\ub839\uc220\uc0ac\uac00 \ud798\uc744 \ubaa8\uc73c\uace0 \uc788\ub2e4\ub294 \uc18c\ubb38\uc774 \ub3c8\ub2e4. \ub3c4\uc2dc\ub97c \uc548\uc804\ud558\uac8c \ub9cc\ub4e4\uae30 \uc704\ud574 \ubaa8\ud5d8\uac00\ub4e4\uc774 \ubd88\ub824 \uc628\ub2e4.","\ud638\ub4dc \ud30c\ud2f0\ub294 \uc5b8\ub354\uc2dc\ud2f0\uc5d0\uc11c \uc785\uad6c\uae4c\uc9c0 \uc27d\uac8c \uac08 \uc218 \uc788\uc9c0\ub9cc, \uc5bc\ub77c\uc774\uc5b8\uc2a4 \ud30c\ud2f0\ub294 \ud638\ub4dc \ub545 \uae4a\uc219\uc774 \ub4e4\uc5b4\uac00\uc57c \ud55c\ub2e4. \ub450 \uc9c4\uc601 \ubaa8\ub450 \ud018\uc2a4\ud2b8\uac00 \uc788\ub2e4. \ud638\ub4dc \ud018\uc2a4\ud2b8\ub294 \uc5b8\ub354\uc2dc\ud2f0, \uc740\ube5b\uc18c\ub098\ubb34 \uc232, \ud2f0\ub9ac\uc2a4\ud314\uc5d0\uc11c, \uc5bc\ub77c\uc774\uc5b8\uc2a4 \ud018\uc2a4\ud2b8\ub294 \ud3d0\ud5c8 \uc548\uc5d0\uc11c \uc2dc\uc791\ud55c\ub2e4. \uae38\uc740 Witherfang, The Baron, Viktor the Vile, The Abandoned, Bjork\ub97c \uac70\uccd0 \ub9c8\uc9c0\ub9c9 \uc801 Rath'mael\uc5d0\uac8c \uc774\uc5b4\uc9c4\ub2e4."],unknowns:["\uac15\ub839\uc220\uc0ac\uac00 \ub204\uad6c\uc774\uba70 \ubaa8\uc740 \ud798\uc744 \uc5b4\ub514\uc5d0 \uc4f0\ub824 \ud558\ub294\uc9c0.","\ud3ec\uc138\uc774\ud070\uc774 \uc61b \uc218\ub3c4\ub97c \uc5bc\ub9c8\ub098 \uc7ac\uac74\ud558\ub824 \ud558\ub294\uc9c0."]},"instance:deadmines":{title:"\uc8fd\uc74c\uc758 \ud3d0\uad11",summary:"\uc11c\ubd80 \ubab0\ub77d\uc9c0\ub300\uc758 \ubc84\ub824\uc9c4 \uae08\uad11\uc73c\ub85c, \uc5d0\ub4dc\uc708 \ubc34\ud074\ub9ac\ud504\uc758 \ub370\ud53c\uc544\uc988 \ub2e8\uc774 \ubab0\ub798 \uc804\ud568\uc744 \uac74\uc870\ud558\uace0 \uc788\ub2e4.",body:["\uc81c1\ucc28 \ub300\uc804\uc7c1 \uc774\uc804\uc5d0 \uc774 \uac31\ub3c4\ub4e4\uc740 \uc778\uac04 \ub545\uc5d0\uc11c \uac00\uc7a5 \ud48d\uc694\ub85c\uc6b4 \uae08\uad11\uc774\uc5c8\uc9c0\ub9cc, \uc624\ud06c\ub4e4\uc774 \uc2a4\ud1b0\uc708\ub4dc\ub97c \uc57d\ud0c8\ud55c \ub4a4\ub85c \ud145 \ube44\uac8c \ub418\uc5c8\ub2e4. \uc774\uc81c \ub370\ud53c\uc544\uc988 \ub2e8\uc774 \uc774\uacf3\uc744 \uc228\uaca8\uc9c4 \uc694\uc0c8\ub85c \uc0bc\uc558\ub2e4. \uadf8 \uc9c0\ub3c4\uc790 \uc5d0\ub4dc\uc708 \ubc34\ud074\ub9ac\ud504\ub294 \uc804\uc7c1 \ub4a4 \uc2a4\ud1b0\uc708\ub4dc \uc7ac\uac74\uc744 \ub3c4\uc6b4 \uc11d\uacf5 \uc7a5\uc778\uc774\uc5c8\uc73c\ub098, \ub3c4\uc2dc\uc758 \uadc0\uc871\ub4e4\uc774 \uadf8\uc758 \uc870\ud569\uc5d0 \ub300\uac00\ub97c \uce58\ub974\uc9c0 \uc54a\uc558\ub2e4. \ubc30\uc2e0\ub2f9\ud55c \uc77c\uafbc\ub4e4\uc740 \ubb34\ubc95\uc790\uac00 \ub418\uc5b4 \uc11c\ubd80 \ubab0\ub77d\uc9c0\ub300 \uacf3\uacf3\uc73c\ub85c \ud37c\uc838 \ub098\uac14\ub2e4.","\ub4e4\uc5b4\uac00\ub294 \uae38\uc740 \ud3d0\ud5c8\uac00 \ub41c \ub9c8\uc744 Moonbrook\uc5d0\uc11c \uc2dc\uc791\ud55c\ub2e4. \uae4a\uc740 \uc544\ub798\uc5d0\uc11c\ub294 \uc2a4\ub2c8\ub4dc\uc640 \uae38\ub2c8\ub4dc \uac19\uc740 \uace0\ube14\ub9b0\ub4e4\uc774 \ub370\ud53c\uc544\uc988\ub97c \ub3c4\uc640 \uc228\uaca8\uc9c4 \ub9cc\uc5d0\uc11c \uac70\ub300\ud55c \ubc30\ub97c \uc644\uc131\ud558\uace0 \uc788\uc73c\uba70, \uadf8\uacf3\uc740 \ubbf8\uc2a4\ud130 \uc2a4\ub9c8\uc774\ud2b8\uc640 \uc120\uc7a5 \uadf8\ub9b0\uc2a4\ud0a8\uc774 \uc9c0\ud0a4\uace0 \uc788\ub2e4."]},"instance:wailing-caverns":{title:"\ud1b5\uace1\uc758 \ub3d9\uad74",summary:"\ubd88\ubaa8\uc758 \ub545 \uc544\ub798 \ub3d9\uad74\ub85c, \ub4dc\ub8e8\uc774\ub4dc \ub098\ub784\ub809\uc2a4\uac00 \uafc8\uafbc \uc7ac\uc0dd\uc774 \uc545\ubabd\uc73c\ub85c \ubcc0\ud55c \uacf3\uc774\ub2e4.",body:["\ud1b5\uace1\uc758 \ub3d9\uad74\uc774\ub77c\ub294 \uc774\ub984\uc740 \ubc14\uc704\ud2c8\uc73c\ub85c \uc0c8\uc5b4 \ub098\uc624\ub294 \ubc14\ub78c\uacfc \uc99d\uae30\uc758 \uc2e0\uc74c \uc18c\ub9ac\uc5d0\uc11c \uc654\ub2e4. \ub098\uc774\ud2b8 \uc5d8\ud504 \ub4dc\ub8e8\uc774\ub4dc \ub098\ub784\ub809\uc2a4\ub294 \uc774 \ub3d9\uad74\uc744 \ubc1c\uacac\ud558\uace0, \uadf8 \uc9c0\ud558 \uc0d8\uc744 \uc5d0\uba54\ub784\ub4dc\uc758 \uafc8\uacfc \uc774\uc5b4 \uba54\ub9c8\ub978 \ubd88\ubaa8\uc758 \ub545\uc5d0 \ub2e4\uc2dc \ud478\ub978 \uc0dd\uba85\uc774 \ud37c\uc9c0\uae30\ub97c \ubc14\ub790\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uac00 \uba85\uc0c1\ud558\ub294 \ub3d9\uc548 \uc624\ud788\ub824 \uc5d0\uba54\ub784\ub4dc\uc758 \uc545\ubabd\uc774 \uadf8\ub97c \uc9d1\uc5b4\uc0bc\ucf30\ub2e4.","\uc7a0\uc5d0 \uac07\ud78c \ub098\ub784\ub809\uc2a4\ub294 \uc774\uc81c \uadf8 \ud0c0\ub77d\uc744 \ub3d9\uad74\uc5d0 \uc3df\uc544\ubd93\uace0 \uc788\ub2e4. \ub3d9\uad74\uc758 \uc0dd\ubb3c\ub4e4\uc740 \ub4a4\ud2c0\ub9b0 \ub3cc\uc5f0\ubcc0\uc774 \uc9d0\uc2b9\uc774 \ub418\uc5c8\uace0, \uadf8\uc758 \uc81c\uc790 \ub300\ubd80\ubd84\uc740 \ubbf8\uccd0 \uc1a1\uacf3\ub2c8 \ub4dc\ub8e8\uc774\ub4dc\uac00 \ub418\uc5c8\ub2e4. \uadf8\uc911\uc5d0\ub294 \uc5ec\uad70\uc8fc \uc544\ub098\ucf58\ub4dc\ub77c\uc640 \ucf54\ube0c\ub780, \ud53c\ud0c0\uc2a4, \uc11c\ud39c\ud2f0\uc2a4 \uad70\uc8fc\uac00 \uc788\ub2e4. \ub098\ub784\ub809\uc2a4\ub97c \uae68\uc6b0\ub824\uba74 \uac8c\uac78\uc2a4\ub7ec\uc6b4 \ubb34\ud0c0\ub204\uc2a4\uc640 \ub9de\uc11c\uc57c \ud55c\ub2e4."]},"instance:shadowfang-keep":{title:"\uadf8\ub9bc\uc790\uc1a1\uacf3\ub2c8 \uc131\ucc44",summary:"\uc740\ube5b\uc18c\ub098\ubb34 \uc232\uc758 \uc720\ub839 \uae43\ub4e0 \uc131\ucc44\ub85c, \ubbf8\uce5c \ub300\ub9c8\ubc95\uc0ac \uc544\ub8e8\uac08\uc774 \uc790\uc2e0\uc774 \ud480\uc5b4\ub193\uc740 \ub291\ub300\uc778\uac04\ub4e4\uc744 \ud488\uace0 \uc788\ub2e4.",body:["\uc81c3\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \ud0a4\ub9b0 \ud1a0\ub294 \uc2a4\uceec\uc9c0\uc640\uc758 \uc2f8\uc6c0\uc5d0\uc11c \ubc00\ub9ac\uace0 \uc788\uc5c8\uace0, \uc4f0\ub7ec\uc9c4 \ub9c8\ubc95\uc0ac\ub294 \uace7 \uc801\uc758 \ud3b8\uc5d0\uc11c \ub2e4\uc2dc \uc77c\uc5b4\uc130\ub2e4. \ub300\ub9c8\ubc95\uc0ac \uc544\ub8e8\uac08\uc740 \ub3d9\ub8cc\ub4e4\uc758 \uacbd\uace0\ub97c \ubb34\uc2dc\ud558\uace0 \uc138\uacc4 \ub108\uba38\ub85c \ub3c4\uc6c0\uc744 \uad6c\ud574 \uc0ac\ub098\uc6b4 \ub291\ub300\uc778\uac04\ub4e4\uc744 \ubd88\ub7ec\ub0c8\ub2e4. \ub291\ub300\uc778\uac04\ub4e4\uc740 \uc5b8\ub370\ub4dc\ub97c \uac08\uac00\ub9ac \ucc22\uc5c8\uace0, \uc774\uc5b4 \ub2ec\ub77c\ub780\uc758 \ubcd1\ub825\uae4c\uc9c0 \ucc22\uc5b4\ubc1c\uae34 \ub4a4, \ud30c\uc774\uc5b4\uc6b0\ub4dc \ub9c8\uc744\uc774 \ub0b4\ub824\ub2e4\ubcf4\uc774\ub294 \uc5b8\ub355 \uc704 \uc2e4\ubc84\ub808\uc778 \ub0a8\uc791\uc758 \uc131\ucc44\ub97c \ud729\uc4f8\uc5c8\ub2e4.","\uc8c4\ucc45\uac10\uc774 \uc544\ub8e8\uac08\uc758 \uc815\uc2e0\uc744 \ubb34\ub108\ub728\ub838\ub2e4. \uadf8\ub294 \uc774\uc81c \ub291\ub300\uc778\uac04\ub4e4\uc744 \uc790\uae30 \uc790\uc2dd\uc774\ub77c \ubd80\ub974\uba70, \uadf8\ub9bc\uc790\uc1a1\uacf3\ub2c8\ub85c \uc774\ub984\uc774 \ubc14\ub010 \uc131\ucc44\uc5d0 \uadf8\ub4e4\uacfc \ud568\uaed8 \uc228\uc5b4 \uc788\uace0, \uac70\ub300\ud55c \ub291\ub300 \ud39c\ub8e8\uc2a4\uac00 \uadf8\uacf3\uc744 \uc9c0\ud0a8\ub2e4. \ub0a8\uc791\uc758 \uc720\ub839\uc740 \ub05d\ub0b4 \uadf8\uacf3\uc744 \ub5a0\ub098\uc9c0 \uc54a\uc558\uace0, \uc740\ube5b\uc18c\ub098\ubb34 \uc232\uc758 \ud3ec\uc138\uc774\ud070\uc740 \ub300\ub9c8\ubc95\uc0ac\uc758 \uc8fd\uc74c\uc744 \ubc14\ub780\ub2e4."]},"instance:excavation-site-wetlands":{title:"Excavation Site: Wetlands",summary:"Whelgar's Excavation Site \uc704\uc758 \ubc1c\uad74 \ud604\uc7a5\uc774 \uc2dc\uac04\uc774 \uc190\ub300\uc9c0 \uc54a\uc740 \uc7a5\uc18c\ub85c \uc5f4\ub838\uace0, \uc8fc\uc778 \uc783\uc740 \ud2f0\ud0c4 \ud53c\uc870\ubb3c\ub4e4\uc774 \uadf8\uacf3\uc744 \uc9c0\ud0a8\ub2e4.",body:["\uc800\uc2b5\uc9c0\uc758 \uc5b8\ub355, Thelgen Rock\uacfc \ub358 \uc54c\uac00\uc988 \uadfc\ucc98\uc5d0\uc11c \ubb34\uc5b8\uac00\uac00 \uae68\uc5b4\ub0ac\ub2e4. Whelgar's Excavation Site \uc704 \ube44\ud0c8\ub85c \uc548\uac1c\uac00 \ud758\ub7ec\ub0b4\ub9ac\uace0, \uc9c0\ud3c9\uc120\uc5d0\uc11c\ub294 \ube5b\uc774 \uae5c\ube61\uc778\ub2e4. \ubc1c\uad74 \ud604\uc7a5 \ub108\uba38\uc758 \ub545\uc740 \uc138\uc6d4\uc774 \ud750\ub974\uc9c0 \uc54a\uc740 \ub4ef \uadf8\ub300\ub85c\uc774\uba70, \uc8fc\uc778 \uc783\uc740 \ud2f0\ud0c4 \uae30\uacc4\uc640 \uc0ac\ub098\uc6b4 \uc57c\uc0dd \ub3d9\ubb3c\ub4e4\uc774 \ud0d0\ud5d8\uac00 \uc5f0\ub9f9\uc774 \ubc1d\ud600\ub0b4\uace0 \uc2f6\uc5b4 \ud558\ub294 \ube44\ubc00\uc744 \uc9c0\ud0a4\uace0 \uc788\ub2e4.","\uc5bc\ub77c\uc774\uc5b8\uc2a4 \ud018\uc2a4\ud2b8\ub294 \uba54\ub124\uc2e4 \ud56d\uad6c, Greenwarden's Grove, \ud638\uc22b\uace8\uc5d0\uc11c, \ud638\ub4dc \ud018\uc2a4\ud2b8\ub294 \uc624\uadf8\ub9ac\ub9c8\uc640 \ud574\uba38\ud3f4\uc5d0\uc11c \uc2dc\uc791\ud55c\ub2e4. Saltspine\uacfc Shadetooth\uac00 Relic Guardian\uc5d0\uac8c \uac00\ub294 \uae38\uc744 \ub9c9\uace0 \uc788\uc73c\uba70, Relic Guardian\uc744 \uc4f0\ub7ec\ub728\ub9ac\uba74 \ub450 \uc9c4\uc601 \ubaa8\ub450\uc758 \ud018\uc2a4\ud2b8\ub97c \uc2dc\uc791\ud558\ub294 \ud2f0\ud0c4 \uc720\ubb3c\uc744 \uc5bb\ub294\ub2e4."],unknowns:["\ubc1c\uad74 \ud604\uc7a5 \ub108\uba38\uc5d0\uc11c \ubb34\uc5c7\uc774 \uae68\uc5b4\ub0ac\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc548\uac1c\uc640 \ube5b\uc758 \uc6d0\uc778.","\uc774\uacf3\uc744 \ub204\uac00 \uc9c0\uc5c8\uc73c\uba70 \ud2f0\ud0c4 \uc720\ubb3c\uc774 \ubb34\uc5c7\uc744 \uc704\ud55c \uac83\uc778\uc9c0."]},"instance:stormwind-stockade":{title:"\uc2a4\ud1b0\uc708\ub4dc \uc9c0\ud558\uac10\uc625",summary:"\ub370\ud53c\uc544\uc988\uac00 \uc774\ub048 \ud3ed\ub3d9\uc73c\ub85c \uc218\uac10\uc790\ub4e4 \uc190\uc5d0 \ub118\uc5b4\uac04 \uc2a4\ud1b0\uc708\ub4dc\uc758 \uac10\uc625.",body:["\uc9c0\ud558\uac10\uc625\uc740 \uc2a4\ud1b0\uc708\ub4dc \uc2dc \ud55c\uac00\uc6b4\ub370\uc5d0 \uc788\uc73c\uba70 \ub3c4\ub451, \uc0b4\uc778\uc790, \uc815\uce58\ubc94\uc744 \uac00\ub454\ub2e4. \uc5bc\ub9c8 \uc804 \uc218\uac10\uc790\ub4e4\uc774 \ub4e4\uace0\uc77c\uc5b4\ub098 \ub370\ud53c\uc544\uc988 \ub2e8\uc5d0 \ub300\ud55c \ucda9\uc131\uc744 \ub4dc\ub7ec\ub0b4\uace0 \uac04\uc218\ub4e4\uc744 \ubab0\uc544\ub0c8\uc73c\uba70, \uc774\uc81c\ub294 \uadf8\ub4e4\uc774 \uc9c1\uc811 \uac10\ubc29 \uad6c\uc5ed\uc744 \uc6b4\uc601\ud558\uace0 \uc788\ub2e4.","\uc8fc\ub3d9\uc790\ub294 \ub370\ud53c\uc544\uc988 \uc694\uc6d0 \ubc14\uc9c8 \uc2a4\ub808\ub4dc\ub2e4. \uc218\uac10\uc790 \uc911\uc5d0\ub294 \uac80\uc740\ubc14\uc704 \uc624\ud06c \uacf5\ud3ec\uc758 \ud0c0\uace0\ub974, \uac80\uc740\ubb34\uc1e0 \ub4dc\uc6cc\ud504 \uce84 \ub525\ud4e8\ub9ac, \ub3c4\uad74\uafbc \ub371\uc2a4\ud2b8\ub80c \uc640\ub4dc\uac00 \uc788\ub2e4. \uc5ec\ub7ff\uc774 \uc0ac\ud615\uc744 \uc120\uace0\ubc1b\uc558\uc9c0\ub9cc \uadc0\uc871\ub4e4\uc758 \ubc88\uac70\ub85c\uc6b4 \uc808\ucc28 \ud0d3\uc5d0 \ud615 \uc9d1\ud589\uc774 \uacc4\uc18d \ubbf8\ub904\uc84c\uace0, \uadf8\ub798\uc11c \ud638\uc22b\uace8\uacfc \uc5b4\ub460\uace8, \uc2ec\uc9c0\uc5b4 \uc544\uc774\uc5b8\ud3ec\uc9c0\uae4c\uc9c0 \uc77c\uc744 \ub9e4\ub4ed\uc9d3\uae30 \uc704\ud574 \uc870\uc6a9\ud788 \ubaa8\ud5d8\uac00\ub4e4\uc744 \ub4e4\uc5ec\ubcf4\ub0b8\ub2e4."]},"instance:city-of-dalaran":{title:"City of Dalaran",summary:"\uc54c\ud130\ub799 \uc0b0\ub9e5\uc5d0 \uc788\ub294 \ud0a4\ub9b0 \ud1a0\uc758 \ub3c4\uc2dc\ub85c, \ubcf5\uad6c \uc791\uc5c5\uc744 \uac00\ub9ac\ub358 \uc7a5\ubcbd\uc774 \ubb34\ub108\uc9c0\uace0 \ub9c8\ubc95\uc774 \ub0a0\ub6f0\uace0 \uc788\ub2e4.",body:["\ud55c\ub3d9\uc548 \ub9c8\ubc95 \uc7a5\ubcbd\uc774 \ub2ec\ub77c\ub780\uc758 \ubcf5\uad6c \uc791\uc5c5\uc744 \uac00\ub9ac\uace0 \uc788\uc5c8\ub2e4. \uc774\uc81c \uadf8 \ubcf4\ud638\ub9c9\uc774 \ubb34\ub108\uc838 \ub3c4\uc2dc\ub294 \ube44\uc804\uc758 \ud63c\ub3c8 \uc18d\uc5d0 \ubaa8\uc2b5\uc744 \ub4dc\ub7ec\ub0c8\ub2e4. \uc8fc\ubb38\uc774 \uc5c7\ub098\uac00\uace0, \ud53c\uc870\ubb3c\ub4e4\uc774 \ud480\ub824 \ub2e4\ub2c8\uba70, \ub0a0\uac83\uc758 \ub9c8\ubc95\uc774 \uac70\ub9ac\ub85c \ud758\ub7ec\ub118\uce5c\ub2e4. \ud0a4\ub9b0 \ud1a0\ub294 \ub3c4\uc6c0\uc774 \ud544\uc694\ud558\uc9c0\ub9cc, \ubbff\uc744 \uc218 \uc788\ub294 \uc774\ub4e4\uc758 \ub3c4\uc6c0\ub9cc \ubc1b\uc73c\ub824 \ud55c\ub2e4.","\uc5bc\ub77c\uc774\uc5b8\uc2a4 \uc601\uc6c5\uc740 \uc0ac\uc6b0\uc2a4\uc1fc\uc5b4\uc758 Emissary Jacques\uc5d0\uac8c\uc11c, \ud638\ub4dc \uc601\uc6c5\uc740 \ud0c0\ub80c \ubc00\ub18d\uc7a5\uc758 Magus Wordeen Voidglare\uc5d0\uac8c\uc11c \uadf8 \uc2e0\ub8b0\ub97c \uc5bb\uae30 \uc2dc\uc791\ud55c\ub2e4. \ub450 \uae38 \ubaa8\ub450 \ub85c\ub2e4\ubbf8\uc5b4 \ud638\uc218 \ub0a8\ucabd \uae30\uc2ad\uc5d0 \uc788\ub294 \ub300\ub9c8\ubc95\uc0ac \ubaa8\ub370\ub77c\uc758 \ud658\uc601\uc5d0\uac8c \uc774\uc5b4\uc9c0\uba70, \uadf8\ub140\uac00 Dalaran Sewer Key\ub97c \uac74\ub128\ub2e4. \ud558\uc218\ub3c4\uc5d0\uc11c\ubd80\ud130 \ud30c\ud2f0\ub294 \uac01\uc790 \uacbd\ub85c\ub97c \uace8\ub77c \ub3c4\uc2dc\ub97c \uc9c0\ub098 \ud63c\ub780\uc758 \uadfc\uc6d0\uc73c\ub85c \ud5a5\ud558\uba70, \ub9c8\uc9c0\ub9c9 \uc801\uc740 Shade of the Archmage\ub2e4."],unknowns:["\ud63c\ub780\uc744 \uc77c\uc73c\ud0a8 \uc6d0\uc778\uacfc \ub9c8\uc9c0\ub9c9 \uc801\uc774 \ub204\uad6c\uc758 \ub9dd\ub839\uc778\uc9c0.","\ub2ec\ub77c\ub780 \ubcf5\uad6c\uac00 \uc5b4\ub514\uae4c\uc9c0 \uc9c4\ud589\ub418\uc5c8\ub294\uc9c0."]},"instance:blackfathom-deeps":{title:"\uac80\uc740\uc2ec\uc5f0\uc758 \ub098\ub77d",summary:"\uc7bf\ube5b \uace8\uc9dc\uae30 \ud574\uc548\uc5d0 \uac00\ub77c\uc549\uc740 \uc5d8\ub8ec\uc758 \uc2e0\uc804\uc73c\ub85c, \uc9c0\uae08\uc740 \uad11\uc2e0\ub3c4\ub4e4\uc774 \uace0\ub300 \uc2e0\uc758 \uad34\uc218\ub97c \ub3cc\ubcf4\ub294 \uc131\uc18c\uac00 \ub418\uc5c8\ub2e4.",body:["\uc7bf\ube5b \uace8\uc9dc\uae30\uc758 Zoram Strand\uc5d0 \uc788\ub294, \uacc4\ub2e8\uc73c\ub85c \ub458\ub7ec\uc2f8\uc778 \uad6c\ub369\uc774\ub294 \ud55c\ub54c \ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \ub2ec\uc758 \uc5ec\uc2e0 \uc5d8\ub8ec\uc758 \uc2e0\uc804\uc774\uc5c8\ub358 \ubb3c\uc5d0 \uc7a0\uae34 \uc804\ub2f9\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc138\uacc4\uc758 \ubd84\ub9ac\ub294 \uc131\uc18c\ub97c \ubd80\uc234 \ubc14\ub2f7\uc18d\uc73c\ub85c \ub04c\uc5b4\ub0b4\ub838\uace0, \uc131\uc18c\ub294 \uc624\ub79c \uc138\uc6d4 \uc7a0\ub4e4\uc5b4 \uc788\ub2e4\uac00 \uadf8\uacf3\uc5d0 \uc544\uc9c1 \ub0a8\uc740 \ud798\uc744 \ud0d0\ub0b8 \ub098\uac00\uc640 \uc0ac\ud2f0\ub85c\uc2a4\uac00 \ucc3e\uc544\uc640 \ud0d0\uc0ac\ud558\uae30 \uc2dc\uc791\ud588\ub2e4.","\uc624\ub298\ub0a0 \ud669\ud63c\uc758 \ub9dd\uce58 \uad50\ub2e8\uc740 \ud669\ud63c\uc758 \uad70\uc8fc \ucf08\ub9ac\uc2a4 \uc544\ub798 \uac00\uc7a5 \uae4a\uc740 \uc6c5\ub369\uc774\uc5d0\uc11c \uc608\ubc30\ud558\uba70, \uace0\ub300 \uc2e0\ub4e4\uc774 \uc544\ub07c\ub294 \uad34\uc218 \uc544\ucfe0\ub9c8\uc774\ub97c \ub3cc\ubcf8\ub2e4. \ub300\uc9c0 \uace0\ub9ac\ud68c\uc758 \uc8fc\uc220\uc0ac\ub4e4\uc774 \uadf8\ub4e4\uc744 \ub9c9\uc73c\ub7ec \uc654\ub2e4. \uace0\ub300 \uc2e0\uc744 \ubd80\ub974\ub294 \uc77c\uc740 \ubb34\uc5c7\uc774\ub4e0 \uc628 \uc138\uc0c1\uc744 \uc704\ud5d8\uc5d0 \ube60\ub728\ub9b0\ub2e4\ub294 \uac83\uc744 \uc54c\uae30 \ub54c\ubb38\uc774\ub2e4."]},"instance:razorfen-kraul":{title:"\uac00\uc2dc\ub369\uad74 \uc6b0\ub9ac",summary:"\uc4f0\ub7ec\uc9c4 \ubc18\uc2e0\uc758 \ud53c\uc5d0\uc11c \uc19f\uc544\ub09c \uac00\uc2dc\ub369\uad74\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uac00\uc2dc\uba67\ub3fc\uc9c0\uc758 \uc870\uc0c1 \ub300\ub300\uc758 \uad74.",body:["\uac00\uc2dc\uba67\ub3fc\uc9c0\ub294 \uace0\ub300\uc758 \uc804\uc7c1\uc5d0\uc11c \uc8fd\uc740 \uc704\ub300\ud55c \uba67\ub3fc\uc9c0 \ubc18\uc2e0 \uc544\uac00\ub9c8\uac04\uc744 \uc22d\ubc30\ud55c\ub2e4. \uadf8\uc758 \ud53c\uac00 \ub5a8\uc5b4\uc9c4 \uacf3\ub9c8\ub2e4 \uac70\ub300\ud55c \uac00\uc2dc\ub369\uad74\uc774 \ub545\uc744 \ub6ab\uace0 \uc19f\uc544\ub0ac\uace0, \ubd88\ubaa8\uc758 \ub545 \ub0a8\ucabd \ub05d\uc5d0 \uc788\ub294 \uac00\uc7a5 \ud070 \ub369\uad74 \ubb34\ub354\uae30\uac00 \ubc14\ub85c Razorfen\uc774\ub2e4. \uac00\uc2dc\uba67\ub3fc\uc9c0\ub294 \uc774\uacf3\uc744 \uadf8\uc758 \ubb34\ub364\uc73c\ub85c \ubc1b\ub4e0\ub2e4.","\uac00\uc2dc\ub369\uad74 \uc6b0\ub9ac\ub294 \uadf8\ub4e4\uc758 \uc870\uc0c1 \ub300\ub300\uc758 \ubcf4\uae08\uc790\ub9ac\ub85c, \uac00\uc2dc\ub364\ubd88 \uc9c0\ubd95\uc744 \uc778 \uad74\uacfc \ud1b5\ub85c\uac00 \ubbf8\ub85c\ucc98\ub7fc \uc5bd\ud78c \uacf3\uc774\uba70 \ub178\ud30c \uc0ec\uac00 \ub808\uc774\uc800\ud50c\ub7ad\ud06c\uac00 \ub2e4\uc2a4\ub9b0\ub2e4. Death's Head \ubd80\uc871\uc758 \uc0ac\uc81c\ub4e4\uc774 \ubc8c\uc368 \uc774\uacf3 \ud1b5\ub85c\ub97c \uc624\uac00\uace0 \uc788\uace0, \uc815\ucc30\ubcd1\ub4e4\uc740 \uc774 \uc9c0\uc5ed\uc5d0 \uc5b8\ub370\ub4dc\uac00 \ubaa8\uc5ec\ub4e0\ub2e4\uace0 \ubcf4\uace0\ud55c\ub2e4. \uc2a4\uceec\uc9c0\uac00 \uce7c\ub9bc\ub3c4\uc5b4\ub97c \ub178\ub9ac\uace0 \uc788\ub2e4\ub294 \ub450\ub824\uc6c0\uc774 \ucee4\uc9c0\ub294 \uac83\uc774\ub2e4."]},"instance:gnomeregan":{title:"\ub188\ub9ac\uac74",summary:"\ud2b8\ub85c\uadf8\uc758 \uce68\uacf5\uacfc \ubc30\uc2e0\uc790\uc758 \uc870\uc5b8 \ub4a4\uc5d0 \ubc29\uc0ac\ub2a5 \uc815\ud654\ub85c \uc624\uc5fc\ub41c, \ub358 \ubaa8\ub85c\uc5d0 \uc788\ub294 \ub178\uc6c0\uc758 \uc783\uc5b4\ubc84\ub9b0 \uc218\ub3c4.",body:["\ub358 \ubaa8\ub85c\uc758 \uc0b0\ub9e5 \uae4a\uc219\uc774 \uc9c0\uc5b4\uc9c4 \ub188\ub9ac\uac74\uc740 \ub178\uc6c0 \uacf5\ud559 \ucd5c\uace0\uc758 \uacbd\uc774\uc600\ub2e4. \uadf8\ub7ec\ub2e4 \ud2b8\ub85c\uadf8\uac00 \ub545\uc18d\uc5d0\uc11c \ub4e4\ub053\uc5b4 \uc62c\ub77c \ub3c4\uc2dc\ub97c \ud729\uc4f8\uc5c8\ub2e4. \ub55c\uc7a5\uc774\uc655 \uba55\uce74\ud1a0\ud06c\ub294 \uc870\uc5b8\uc790 \uc2dc\ucf54 \ud154\ub9c8\ud50c\ub7ec\uadf8\uc758 \ub9d0\uc744 \ub530\ub77c \uce68\ub7b5\uc790\ub4e4\uc744 \uc8fd\uc774\ub824 \ub3c4\uc2dc\uc5d0 \ubc29\uc0ac\ub2a5\uc744 \uc3df\uc544\ubd80\uc5c8\uc9c0\ub9cc, \uadf8 \uc815\ud654\ub294 \ub178\uc6c0 \ub300\ubd80\ubd84\uae4c\uc9c0 \uc8fd\uc774\uace0 \ub9d0\uc558\ub2e4. \uc0dd\uc874\uc790\ub4e4\uc740 \uc544\uc774\uc5b8\ud3ec\uc9c0\ub85c \ud53c\uc2e0\ud588\ub2e4.","\uadf8\uac83\uc740 \ubc30\uc2e0\uc774\uc5c8\ub2e4. \ud154\ub9c8\ud50c\ub7ec\uadf8\ub294 \ub0a8\uc544\uc11c \uc2a4\uc2a4\ub85c \ud3d0\ud5c8\uc758 \uad70\uc8fc\ub85c \uc989\uc704\ud588\uace0, \uc774\uc81c \uc624\uc5fc\ub41c \ub178\uc6c0\uacfc \ud2b8\ub85c\uadf8, \uadf8\ub9ac\uace0 \uac10\uc804\ub85c\ubd07 6000\uacfc Crowd Pummeler 9-60 \uac19\uc740 \ubbf8\uccd0 \ubc84\ub9b0 \uae30\uacc4\ub4e4\uc744 \uc9c0\ud718\ud55c\ub2e4. \ub9dd\uba85\uc790\ub4e4\uc740 \uace0\ud5a5\uc744 \ub418\ucc3e\uaca0\ub2e4\uace0 \ub9f9\uc138\ud588\ub2e4."]},"instance:scarlet-monastery-graveyard":{title:"\ubd89\uc740\uc2ed\uc790\uad70 \uc218\ub3c4\uc6d0: \ubb18\uc9c0",summary:"\ubd89\uc740\uc2ed\uc790\uad70 \uc218\ub3c4\uc6d0\uc758 \uc9c0\ud558 \ubb18\uc9c0\ub85c, \uc2ec\ubb38\uad00\uc774 \uc77c\ud558\uace0 \uc8fd\uc740 \uc790\ub4e4\uc774 \uc548\uc2dd\uc744 \uac70\ubd80\ud558\ub294 \uacf3.",body:["\ud2f0\ub9ac\uc2a4\ud314 \uc232 \ubd81\ucabd\uc758 \uc218\ub3c4\uc6d0\uc740 \ub85c\ub370\ub860 \uc0ac\uc81c\ub4e4\uc744 \uc704\ud55c \ud559\ubb38\uc758 \uc804\ub2f9\uc73c\ub85c \uc9c0\uc5b4\uc84c\ub2e4. \uc81c3\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \uc2a4\uceec\uc9c0\uac00 \uc655\uad6d\uc744 \ud729\uc4f4 \ub4a4, \ubd89\uc740\uc2ed\uc790\uad70\uc758 \uad11\uc2e0\ub3c4\ub4e4\uc774 \uc774\uacf3\uc744 \ucc28\uc9c0\ud574 \uac70\uc810\uc73c\ub85c \uc0bc\uc558\ub2e4. \uadf8\ub4e4\uc740 \uc778\uac04\uc774 \uc544\ub2cc \ubaa8\ub4e0 \uc774\uac00 \uc5ed\ubcd1\uc744 \uc9c0\ub154\ub2e4\uace0 \uc758\uc2ec\ud558\uba70, \ub0af\uc120 \uc774\ub97c \uc9c8\ubb38 \ub300\uc2e0 \uce7c\ub0a0\ub85c \ub9de\ub294\ub2e4.","\ubb18\uc9c0\ub294 \ub300\ubd80\ubd84\uc758 \ud30c\ud2f0\uac00 \ucc98\uc74c \ucc3e\ub294 \uad6c\uc5ed\uc774\ub2e4. \uac10\ubc29\uc740 \uc2ec\ubb38\uad00 \ube44\uc0e4\uc2a4\uc758 \uac83\uc774\uace0, \ud608\ubc95\uc0ac \ud0c8\ub178\uc2a4\uac00 \ubb34\ub364 \uc0ac\uc774\uc5d0 \ub3c4\uc0ac\ub9ac\uba70, \uc7a0\ub4e4\uc9c0 \uc54a\ub294 \uc544\uc988\uc2dc\ub974, Ironspine, \ud0c0\ub77d\ud55c \uc6a9\uc0ac \uac19\uc740 \uc548\uc2dd\ud558\uc9c0 \ubabb\ud55c \ub9dd\uc790\ub4e4\uc774 \uc9c0\ud558 \ubb18\uc9c0\ub97c \ubc30\ud68c\ud55c\ub2e4."]},"instance:scarlet-monastery-library":{title:"\ubd89\uc740\uc2ed\uc790\uad70 \uc218\ub3c4\uc6d0: \ub3c4\uc11c\uad00",summary:"\uc0ac\ub0e5\uac1c\uc870\ub828\uc0ac\uc640 \uc2e0\ube44\uc220\uc0ac\uac00 \uad50\ub2e8\uc758 \ucc45\uc744 \uc9c0\ud0a4\ub294 \ubd89\uc740\uc2ed\uc790\uad70\uc758 \uc11c\uace0.",body:["\ub85c\ub370\ub860\uc758 \uc0ac\uc81c\ub4e4\uc740 \ud55c\ub54c \uacf5\ubd80\ud558\ub7ec \ud2f0\ub9ac\uc2a4\ud314\uc758 \uc774 \uc218\ub3c4\uc6d0\uc744 \ucc3e\uc558\ub2e4. \uc81c3\ucc28 \ub300\uc804\uc7c1 \ub4a4 \uc774\uacf3\uc744 \ucc28\uc9c0\ud55c \ubd89\uc740\uc2ed\uc790\uad70\uc740 \ucc45\uc740 \uc9c0\ucf30\uc9c0\ub9cc \uc628\ud654\ud568\uc740 \uc783\uc5c8\ub2e4. \uad11\uc2e0\ub3c4\ub4e4\uc740 \uc778\uac04\uc774 \uc544\ub2cc \uc790\ub77c\uba74 \ub204\uad6c\ub4e0 \uc5ed\ubcd1\uc744 \ud37c\ub728\ub9b4 \uc218 \uc788\ub2e4\uace0 \ubbff\uc73c\uba70, \uc131\ubcbd\ub9cc\ud07c\uc774\ub098 \uc0ac\ub0a9\uac8c \uc11c\uace0\ub97c \uc9c0\ud0a8\ub2e4.","\uc0ac\ub0e5\uac1c\uc870\ub828\uc0ac \ub85d\uc2dc\uc640 \uadf8\uc758 \uac1c\ub4e4\uc774 \ubc14\uae65 \uc804\ub2f9\uc5d0\uc11c \uce68\uc785\uc790\ub97c \uc0ac\ub0e5\ud558\uace0, \uc2e0\ube44\uc220\uc0ac \ub3c4\uc548\uc774 \uc548\ucabd \uc11c\uac00\ub97c \uc9c0\ud0a8\ub2e4. \ub9ce\uc740 \uc774\uac00 \ucc45 \uc790\uccb4\ub97c \ub178\ub9ac\uace0 \uc628\ub2e4. \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \ud559\uc790\ub4e4\uc740 \ud2f0\ud0c4 \uc2e0\ud654\uc5d0 \uad00\ud55c \ucc45 \ud55c \uad8c\uc744 \uc6d0\ud558\uace0, \ud3ec\uc138\uc774\ud070\uc740 \uc2ed\uc790\uad70\uc774 \uc9c1\uc811 \ub0a8\uae34 \uc8fd\uc740 \uc790\ub4e4\uc758 \uc5f0\ub300\uae30\ub97c \ucc3e\ub294\ub2e4."]},"instance:drowned-city":{title:"Drowned City",summary:"\uac00\uc2dc\ub364\ubd88 \uace8\uc9dc\uae30 \uc55e\ubc14\ub2e4\uc5d0\uc11c \uc19f\uc544\uc624\ub978 \uace0\ub300 \ud2b8\ub864 \uc720\uc801\uc73c\ub85c, \uc9c0\uae08\uc740 \ud2b8\ub864\uacfc \ub098\uac00\uac00 \ub5a0\ub3c8\ub2e4.",body:["\uac00\uc2dc\ub364\ubd88 \uace8\uc9dc\uae30 \uc55e\ubc14\ub2e4, \uadf8\ub86c\uace8 \uc11c\ucabd\uc5d0\uc11c \ubc14\ub2e4\uc5d0 \uc0bc\ucf1c\uc84c\ub358 \ud2b8\ub864 \ub3c4\uc2dc\uac00 \ub2e4\uc2dc \uc19f\uc544\uc62c\ub790\ub2e4. \uc624\ub79c \uc138\uc6d4 \uc544\ubb34\ub3c4 \ubc1f\uc9c0 \uc54a\uc740 \uac70\ub9ac\uac00 \uc774\uc81c \ud558\ub298 \uc544\ub798 \ub4dc\ub7ec\ub0ac\uace0, \ud2b8\ub864\uacfc \ub098\uac00\uac00 \ubc8c\uc368 \uc790\ub9ac\ub97c \uc7a1\uc558\uc73c\uba70, \uadfc\ucc98\uc758 \ud574\uc801\uc120 \ud55c \ucc99\uc740 \uc544\uc8fc \ub054\ucc0d\ud55c \ucd5c\ud6c4\ub97c \ub9de\uc740 \ub4ef\ud558\ub2e4.","\uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub824\uba74 \ud30c\ud2f0\ub294 \uc7a0\uc218\ud574 \uc218\uba74 \uc544\ub798\uc758 \uae38\uc744 \ucc3e\uc544\uc57c \ud55c\ub2e4. \uc77c\ub2e8 \ub4e4\uc5b4\uac00\uba74 \ud0c1 \ud2b8\uc778 \ud558\ub298 \uc544\ub798\uc5d0\uc11c \uc2f8\uc6b0\uac8c \ub418\ub294\ub370, \ub0a0\uc528\uac00 \uc810\uc810 \ub098\ube60\uc838 \uc548\uac1c\ub294 \ube44\ub85c, \ube44\ub294 \ub9c8\uc9c0\ub9c9 \uc804\ud22c\uc5d0 \uc774\ub974\uba74 \uac70\uc13c \ud3ed\ud48d\uc73c\ub85c \ubc14\ub010\ub2e4."],unknowns:["\ub3c4\uc2dc\uac00 \uc65c \uc9c0\uae08 \uc19f\uc544\uc62c\ub790\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub290 \ud2b8\ub864 \uc885\uc871\uc774 \uc138\uc6e0\ub294\uc9c0.","\uc548\uc5d0\uc11c \ud2b8\ub864\uacfc \ub098\uac00\ub97c \ub204\uac00 \uc774\ub044\ub294\uc9c0. \uc774 \uc548\ub0b4\uc11c\uc758 \uc790\ub8cc\uc5d0\ub294 \uc544\uc9c1 \uc6b0\ub450\uba38\ub9ac\uac00 \uc5c6\ub2e4.","\ud574\uc801\uc120\uc5d0 \ubb34\uc2a8 \uc77c\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0."]},"instance:scarlet-monastery-armory":{title:"\ubd89\uc740\uc2ed\uc790\uad70 \uc218\ub3c4\uc6d0: \ubb34\uae30\uace0",summary:"\uc6a9\uc0ac \ud5e4\ub85c\ub4dc\uac00 \ub2e4\uc2a4\ub9ac\ub294 \ubd89\uc740\uc2ed\uc790\uad70\uc758 \ud6c8\ub828\uc7a5\uc774\uc790 \ubb34\uae30\uace0.",body:["\ud2f0\ub9ac\uc2a4\ud314 \uc232\uc758 \uc218\ub3c4\uc6d0 \ub2f4\uc7a5 \ub108\uba38\uc5d0\uc11c \ubd89\uc740\uc2ed\uc790\uad70\uc740 \ubcd1\uc0ac\ub4e4\uc744 \ud6c8\ub828\uc2dc\ud0a8\ub2e4. \uc774 \uad50\ub2e8\uc740 \uc81c3\ucc28 \ub300\uc804\uc7c1\uc758 \ub85c\ub370\ub860 \ubab0\ub77d\uc5d0\uc11c \ud0dc\uc5b4\ub0ac\uc73c\uba70, \uc778\uac04\uc774 \uc544\ub2cc \uc790\ub294 \ub204\uad6c\ub4e0 \uc5ed\ubcd1\uc744 \uc9c0\ub154\uc744 \uc218 \uc788\ub2e4\uace0 \ubbff\uae30\uc5d0 \uc2e0\ubcd1\ub4e4\uc5d0\uac8c \uba3c\uc800 \uacf5\uaca9\ud558\ub77c\uace0 \uac00\ub974\uce5c\ub2e4.","\ubb34\uae30\uace0\uc5d0\ub294 \ud6c8\ub828\uc7a5\uacfc \ubcd1\uc601, \ubb34\uae30 \ucc3d\uace0\uac00 \uc788\uc73c\uba70, \uadf8 \uc8fc\uc778\uc740 \ubd89\uc740\uc2ed\uc790\uad70 \uc6a9\uc0ac \ud5e4\ub85c\ub4dc\ub2e4. \uadf8\ub294 \uac70\ub300\ud55c \ub3c4\ub07c\ub97c \ud718\ub450\ub974\uba70 \uacf5\uaca9\uc790\ub4e4 \uc0ac\uc774\ub97c \ud68c\uc624\ub9ac\ucc98\ub7fc \ud729\uc4f0\ub294 \uc6b0\ub78c\ud55c \uac70\ud55c\uc774\ub2e4. \uadf8\ub97c \uc4f0\ub7ec\ub728\ub9ac\uba74 \ud30c\ud2f0\uac00 \uc218\ub3c4\uc6d0 \ud55c\uac00\uc6b4\ub370\uc758 \ub300\uc131\ub2f9\uc5d0 \ub4e4\uc5b4\uac08 \uc900\ube44\uac00 \ub418\uc5c8\uc74c\uc774 \uc99d\uba85\ub41c\ub2e4."]},"instance:razorfen-downs":{title:"\uac00\uc2dc\ub369\uad74 \uad6c\ub989",summary:"\ub9ac\uce58 \ub0c9\uae30\uc758 \uc554\ub124\ub098\ub974\uac00 \uc774\ub044\ub294 \uc2a4\uceec\uc9c0\uc5d0\uac8c \ub118\uc5b4\uac04 \uac00\uc2dc\uba67\ub3fc\uc9c0\uc758 \uc624\ub798\ub41c \ub9e4\uc7a5\uc9c0.",body:["\uac00\uc2dc\ub369\uad74 \uad6c\ub989\uc740 \uac00\uc2dc\ub369\uad74 \uc6b0\ub9ac\uc640 \uac19\uc740 \uac70\ub300\ud55c \uac00\uc2dc\uc5d0\uc11c \uc790\ub77c\ub0ac\uc73c\uba70, \uac00\uc2dc\uba67\ub3fc\uc9c0\uac00 \uc8fd\uc740 \uc790\ub97c \ubb3b\ub294 \uacf3\uc774\ub2e4. \ud55c\ub54c\ub294 \uadf8\ub4e4\uc758 \ub300\uc0ac\uc81c\uc778 Death's Head\uac00 \uc774 \ub545\uc758 \uc2e0\uc131\ud568\uc744 \uc9c0\ucf30\ub2e4. \uadf8\ub7ec\ub098 \uc2a4\uceec\uc9c0\uac00 \uce7c\ub9bc\ub3c4\uc5b4\uc5d0 \uc774\ub974\uc790 \ubaa8\ub4e0 \uac83\uc774 \ubc14\ub00c\uc5c8\ub2e4. \ub9ac\uce58 \ub0c9\uae30\uc758 \uc554\ub124\ub098\ub974\uac00 \ubd80\uc871\uc758 \uc0ac\uc81c\ub4e4\uc744 \uc790\uae30 \uc218\ud558\ub85c \uc0bc\uace0 \uac00\uc2dc\ub364\ubd88\uc744 \ub418\uc0b4\uc544\ub09c \ub9dd\uc790\ub4e4\ub85c \uac00\ub4dd \ucc44\uc6b4 \uac83\uc774\ub2e4.","\uc790\uc720\ub85c\uc6b4 \uac00\uc2dc\uba67\ub3fc\uc9c0\ub4e4\uc740 \ub9ac\uce58\uc758 \ud798\uc774 \ubd88\ubaa8\uc758 \ub545 \ub098\uba38\uc9c0 \uc9c0\uc5ed\uc73c\ub85c \ubc88\uc9c0\uae30 \uc804\uc5d0 \ub9e4\uc7a5 \ub3c4\uc2dc\ub97c \ub418\ucc3e\uc73c\ub824 \uc2f8\uc6b0\uace0 \uc788\ub2e4. \ud30c\ud2f0\ub294 \ud22c\ud150\uce74\uc26c, \ubd88\uaf43\ub208 \ubaa8\ub4dc\ub808\uc26c, \uba39\ubcf4, \uc369\uc5b4\uac00\ub294 \uc5ed\ubcd1\uc544\uadc0\ub97c \ub6ab\uace0 \ub098\uc544\uac00\uc57c \uc554\ub124\ub098\ub974\uc5d0\uac8c \uc774\ub97c \uc218 \uc788\ub2e4."]},"instance:scarlet-monastery-cathedral":{title:"\ubd89\uc740\uc2ed\uc790\uad70 \uc218\ub3c4\uc6d0: \ub300\uc131\ub2f9",summary:"\ubd89\uc740\uc2ed\uc790\uad70 \uc218\ub3c4\uc6d0\uc758 \uc2ec\uc7a5\ubd80\ub85c, \uc0ac\ub839\uad00 \ubaa8\uadf8\ub808\uc778\uc774 \uc2e0\ub3c4\ub4e4\uc744 \uc774\ub04c\uace0 \uc885\uad50\uc7ac\ud310\uad00 \ud654\uc774\ud2b8\uba54\uc778\uc774 \uc4f0\ub7ec\uc9c4 \uc790\ub97c \uc77c\uc73c\ud0a8\ub2e4.",body:["\ub300\uc131\ub2f9\uc740 \ud2f0\ub9ac\uc2a4\ud314 \uc232\uc5d0 \uc788\ub294 \ubd89\uc740\uc2ed\uc790\uad70 \uc218\ub3c4\uc6d0\uc758 \uc2ec\uc7a5\ubd80\uc774\uc790 \uadf8\uacf3 \uc9c0\ub3c4\uc790\ub4e4\uc758 \uac70\ucc98\ub2e4. \ubd89\uc740\uc2ed\uc790\uad70 \uc0ac\ub839\uad00 \ubaa8\uadf8\ub808\uc778\uc774 \uad11\uc2e0\uc801\uc778 \uc218\ube44\ub300\ub97c \uc9c0\ud718\ud558\uc9c0\ub9cc, \uc2e4\uc81c \uad8c\ud55c\uc740 \uc4f0\ub7ec\uc9c4 \uc6a9\uc0ac\ub97c \ub2e4\uc2dc \uc2f8\uc6b0\ub3c4\ub85d \ubd88\ub7ec\ub0bc \uc218 \uc788\ub294 \uc0ac\uc81c, \uc885\uad50\uc7ac\ud310\uad00 \ud654\uc774\ud2b8\uba54\uc778\uc5d0\uac8c \uc788\ub2e4.","\uc2ed\uc790\uad70\uc740 \ub85c\ub370\ub860\uc758 \ubab0\ub77d\uc5d0\uc11c \ud0dc\uc5b4\ub098 \uc9c0\uae08\ub3c4 \ubaa8\ub4e0 \uc774\ubc29\uc778\uc5d0\uac8c\uc11c \uc5ed\ubcd1\uc744 \ubcf8\ub2e4. \uadf8 \uc2e0\ub150\uc774 \uac00\uc7a5 \ub728\uac81\uac8c \ud0c0\uc624\ub974\ub294 \uacf3\uc774 \ubc14\ub85c \uc5ec\uae30\ub2e4. \uc0ac\ub839\uad00\uc740 \ub05d\uae4c\uc9c0 \uc2f8\uc6b0\uace0, \uadf8\uac00 \uc4f0\ub7ec\uc9c0\uba74 \ud654\uc774\ud2b8\uba54\uc778\uc774 \uc131\ub2e8\uc5d0\uc11c \ub0b4\ub824\uc640 \uc2f8\uc6c0\uc744 \uc774\uc5b4 \uac00\uba70 \uadf8\ub97c \ub2e4\uc2dc \uc77c\uc73c\ud0a8\ub2e4."]}}},1796,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"instances2",{enumerable:!0,get:function(){return o}});const o={"instance:kroldok-stronghold":{title:"Krol'dok Stronghold",summary:"\uc57d\ud0c8\uc790\ub4e4\uc774 \uc5ec\ud589\uc790\ub97c \ub0a9\uce58\ud558\uace0 \ud574\uac00 \uc9c0\uba74 \uc8fc\ubb38 \uc18c\ub9ac\uac00 \uc6b8\ub824 \ud37c\uc9c0\ub294 Riverglades\uc758 \uc624\uc6b0\uac70 \uc694\uc0c8.",body:["Krol'dok\uc740 Riverglades\uc758 \uc624\uc6b0\uac70 \uc694\uc0c8\uc774\uba70, \uadf8 \uc5ed\uc0ac\ub294 \uc81c2\ucc28 \ub300\uc804\uc7c1 \uc9c1\ud6c4\ub85c \uac70\uc2ac\ub7ec \uc62c\ub77c\uac04\ub2e4. \uc774 \uc9c0\uc5ed\uc758 \uc61b \ud638\ub4dc \ubcd1\ub825\uc774 Farholde Keep\uc744 \ud3ec\uc704\ud588\uc744 \ub54c, Fern Crimsonleaf\uac00 \uadf8\ub4e4\uc758 \uc9c4\uc601\uc5d0 \uc228\uc5b4\ub4e4\uc5b4 \uc9c0\ud718\uad00\ub4e4\uc744 \uc8fd\uc600\ub2e4. \uc9c0\ud718\uad00\uc744 \uc783\uc740 \ub300\uad70\uc740 Brotherhood of the Horse\uc5d0\uac8c \ub9c9\ub300\ud55c \ub300\uac00\ub97c \uce58\ub974\uba70 \ud328\ud558\uace0 Krol'dok\uc73c\ub85c \ub2ec\uc544\ub0ac\ub2e4.","\uc774\uc81c \uadf8\uacf3\uc758 \uc624\uc6b0\uac70 \ucc99\ud6c4\ubcd1\ub4e4\uc774 Riverglades \uacf3\uacf3\uc744 \uc2b5\uaca9\ud574 \uc5ec\ud589\uc790\ub97c \ub04c\uace0 \uac00\uace0 \uc815\ucc29\uc9c0\ub97c \uc57d\ud0c8\ud55c\ub2e4. \uadf8\ub4e4\uc758 \uc790\ucde8\ub294 \uc791\uc5c5\uc7a5\uacfc \uc57c\uc601\uc9c0, \uc0bc\uc5c4\ud558\uac8c \uac10\uc2dc\ub418\ub294 \ud1b5\ub85c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uac70\ub300\ud55c \uc694\uc0c8\uc5d0\uc11c \ub05d\ub09c\ub2e4. \ud30c\ud2f0\ub294 \uc2b5\uaca9\uc744 \uba48\ucd94\uace0, \ud574\uac00 \uc9c0\uba74 \uc694\uc0c8\uc5d0\uc11c \uc6b8\ub824 \ub098\uc624\ub294 \uae30\ubb18\ud55c \uc8fc\ubb38 \uc18c\ub9ac\uc758 \uc758\ubbf8\ub97c \uc54c\uc544\ub0b4\uae30 \uc704\ud574 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac04\ub2e4."],unknowns:["\uc9c0\uae08 \uc694\uc0c8\ub97c \ub204\uac00 \uc9c0\ud718\ud558\ub294\uc9c0. \uc774 \uc548\ub0b4\uc11c\uc758 \uc790\ub8cc\uc5d0\ub294 \uc544\uc9c1 \uc6b0\ub450\uba38\ub9ac\uac00 \uc5c6\ub2e4.","\uc8fc\ubb38 \uc18c\ub9ac\uac00 \ubb34\uc5c7\uc774\uba70 \ub204\uac00 \uc774\ub044\ub294\uc9c0.","\uc774 \uc624\uc6b0\uac70\ub4e4\uc774 \ud669\ud63c\uc758 \ub9dd\uce58, \uadf8\ub9ac\uace0 Riverglades \ub2e4\ub978 \uacf3\uc758 Bolder'ok \uc624\uc6b0\uac70\uc640 \uc5b4\ub5a4 \uad00\uacc4\uc778\uc9c0."]},"instance:uldaman":{title:"\uc6b8\ub2e4\ub9cc",summary:"\ub4dc\uc6cc\ud504 \ubc1c\uad74\uafbc\ub4e4\uc774 \ud2b8\ub85c\uadf8\ub97c \uae68\uc6b0\uace0 \uc790\uc2e0\ub4e4\uc758 \uae30\uc6d0\uc5d0 \uad00\ud55c \ub2e8\uc11c\ub97c \ucc3e\uc544\ub0b8, \ud669\uc57c\uc758 \ub545\uc758 \ud2f0\ud0c4 \uae08\uace0.",body:["\uc6b8\ub2e4\ub9cc\uc740 \ud2f0\ud0c4\uc758 \uad00\ub9ac\uc790\ub4e4\uc774 \uc9c0\uae08\uc758 \ud669\uc57c\uc758 \ub545, \uce74\uc988 \ubaa8\ub2e8\uc758 \uc0b0\ub9e5 \uae4a\uc219\uc774 \ubd09\uc778\ud55c \uae08\uace0\ub2e4. \ud2f0\ud0c4\uc774 \uc2e4\ud328\uc791\uc73c\ub85c \ud310\ub2e8\ud55c \ucd08\uae30 \ud53c\uc870\ubb3c\uc778 \ud2b8\ub85c\uadf8\ub97c \uac00\ub450\uae30 \uc704\ud55c \uacf3\uc774\uc5c8\ub2e4. \uc81c3\ucc28 \ub300\uc804\uc7c1 \uc774\uc804\uc5d0 \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \ubc1c\uad74\uafbc\ub4e4\uc774 \uc774\uacf3\uc744 \ub6ab\uace0 \ub4e4\uc5b4\uac14\uace0, \uadf8\ub4e4\uc774 \uae68\uc6b4 \ud2b8\ub85c\uadf8\ub4e4\uc740 \uc6d0\uc815\ub300 \ub300\ubd80\ubd84\uc744 \ud559\uc0b4\ud588\ub2e4.","\uc774\uc81c \ud0d0\ud5d8\uac00 \uc5f0\ub9f9\uacfc \uac80\uc740\ubb34\uc1e0 \uc57d\ud0c8\uc790, \ud2b8\ub85c\uadf8 \ubd80\uc871\ub4e4\uc774 \uadf8 \uc804\ub2f9\uc744 \ub450\uace0 \ub2e4\ud230\ub2e4. \uac00\uc7a5 \uae4a\uc740 \uacf3\uc5d0\ub294 \ub4dc\uc6cc\ud504\uac00 \ub3cc \ud53c\ubd80\uc758 \ub300\uc9c0\uc778\uc5d0\uac8c\uc11c \uc720\ub798\ud588\uc74c\uc744 \ubc1d\ud600 \uc8fc\ub294 \ud2f0\ud0c4\uc758 \uae30\ub85d, \ub178\ub974\uac04\ub17c\uc758 \uc6d0\ubc18\uc774 \uc788\uc73c\uba70, \ud2f0\ud0c4\uc774 \ubcbc\ub824 \ub0b8 \uc544\uce74\uc5d0\ub2e4\uc2a4\uac00 \uc774\ub97c \uc9c0\ud0a8\ub2e4. \uadf8\ub294 \uc9c0\uae08\ub3c4 \uc790\uc2e0\uc758 \uae08\uace0\ub97c \uc5b4\uc9c0\ub7fd\ud788\ub294 \uc790\uc5d0\uac8c \ub9de\uc11c \uc77c\uc5b4\ub09c\ub2e4."]},"instance:zulfarrak":{title:"\uc904\ud30c\ub77d",summary:"\ud0c0\ub098\ub9ac\uc2a4\uc5d0 \uc788\ub294, \ud587\ubcd5\uc5d0 \uadf8\uc744\ub9b0 \ubaa8\ub798\ud3ed\ud48d \ud2b8\ub864\uc758 \ub3c4\uc2dc\ub85c, \uc2e0\uc131\ud55c \uc6c5\ub369\uc774\uc5d0\uc11c \ud788\ub4dc\ub77c \uc2e0\uc774 \uc7a0\ub4e4\uc5b4 \uc788\ub2e4.",body:["\ud0c0\ub098\ub9ac\uc2a4\ub294 \ud55c\ub54c \uc815\uae00\uc774\uc5c8\uace0 \uad6c\ub8e8\ubc14\uc2dc \ud2b8\ub864\uc758 \ub545\uc5d0 \uc18d\ud588\uc73c\uba70, \uc904\ud30c\ub77d\uc740 \uadf8\ub4e4\uc758 \ub3c4\uc2dc \uac00\uc6b4\ub370 \ud558\ub098\uc600\ub2e4. \uc138\uacc4\uc758 \ubd84\ub9ac\ub85c \uc774 \uc9c0\uc5ed\uc774 \uc0ac\ub9c9\uc73c\ub85c \ubcc0\ud558\uc790 \uadf8\uacf3\uc5d0 \ub0a8\uc740 \ud30c\ub77c\ud0a4 \ud2b8\ub864\uc740 \ud658\uacbd\uc5d0 \uc801\uc751\ud574 \ubaa8\ub798 \ud2b8\ub864\uc774 \ub418\uc5c8\ub2e4. \uc624\ub298\ub0a0 \ub3c4\uc2dc\ub294 \uc794\ud639\ud568\uacfc \uc5b4\ub460\uc758 \ub9c8\ubc95\uc73c\ub85c \uc545\uba85 \ub192\uc740 \ubaa8\ub798\ud3ed\ud48d \ubd80\uc871\uc758 \uac83\uc774\ub2e4.","\ubaa8\ud5d8\uac00\ub4e4\uc740 \uc5ec\ub7ec \uc774\uc720\ub85c \uc774\uacf3\uc744 \ucc3e\ub294\ub2e4. \uc18c\ubb38\uc5d0 \ub530\ub974\uba74 \ubd80\ub7ec\uc9c4 \ud2b8\ub864 \uac80 Sul'thraze the Lasher\uc758 \ub450 \uc870\uac01\uc774 \ubaa8\ub450 \uc131\ubcbd \uc548\uc5d0 \uc788\ub2e4\uace0 \ud558\uba70, \uac00\uc82f\uc794\uc5d0\uc11c \ub3c4\ub9dd\uce58\ub358 \uc6a9\ubcd1\ub2e8\uc774 \uc798\ubabb \ub4e4\uc5b4\uc654\ub2e4\uac00 \ud3ec\ub85c\ub85c \uc7a1\ud614\ub2e4. \ub3c4\uc2dc \ud55c\uac00\uc6b4\ub370\uc758 \uc2e0\uc131\ud55c \uc6c5\ub369\uc774\uc5d0\ub294 \ud788\ub4dc\ub77c \uac00\uc988\ub9b4\ub77c\uac00 \uc7a0\ub4e4\uc5b4 \uc788\ub294\ub370, \ubaa8\ub798\ud3ed\ud48d \ubd80\uc871\uc740 \uadf8\ub97c \ubc18\uc2e0\uc73c\ub85c \uc22d\ubc30\ud558\uba70 \ubc14\uce60 \uc81c\ubb3c\uc774 \uc788\uc744 \ub54c\ub9cc \uae68\uc6b4\ub2e4."]},"instance:alcaz-prison":{title:"Alcaz Prison",summary:"\uc624\ub7ab\ub3d9\uc548 \uc18c\ubb38\ub9cc \ubb34\uc131\ud588\ub358 \uba3c\uc9c0\uc9c4\ud759 \uc2b5\uc9c0\ub300 \uc54c\uce74\uc988 \uc12c\uc758 \uac10\uc625\uc774 \ub9c8\uce68\ub0b4 \uc5f4\ub838\uace0, \uc548\uc5d0\uc11c\ub294 \ub370\ud53c\uc544\uc988\uc640 \ub098\uac00\uac00 \uc804\uc7c1 \uc911\uc774\ub2e4.",body:["\uba3c\uc9c0\uc9c4\ud759 \uc2b5\uc9c0\ub300\uc5d0\uc11c\ub294 \uc624\ub798\uc804\ubd80\ud130 \uc54c\uce74\uc988 \uc12c\uacfc \uadf8\uacf3\uc5d0 \uac07\ud600 \uc788\ub2e4\ub294 \uace0\uc704 \ud3ec\ub85c\ub4e4\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uac00 \ubb34\uc131\ud588\ub2e4. \uc5b4\ub5a4 \uc18c\ubb38\uc740 \uc2a4\ud1b0\uc708\ub4dc\uc758 \ubc14\ub9ac\uc548 \ub9b0 \uad6d\uc655\uae4c\uc9c0 \uac70\ub860\ud588\ub2e4. \uc9c4\uc2e4\uc744 \uc54c\uc544\ub0b4\ub824 \ud574\ub3c4 \uc544\ubb34\ub3c4 \uac10\uc625\uc5d0 \ub2ff\uc744 \uc218 \uc5c6\uc5c8\ub2e4. \uc774\uc81c \uadf8 \ubb38\uc774 \uc5f4\ub838\ub2e4.","\uc548\uc5d0\uc11c\ub294 \ub370\ud53c\uc544\uc988 \ub2e8\uacfc \ub098\uac00\uac00 \uc11c\ub85c \uc2f8\uc6b0\uace0 \uc788\ub2e4. \ud30c\ud2f0\ub294 \uadf8 \ud63c\ub780\uc744 \ud2c8\ud0c0 \uac10\ubc29\uc744 \ub4a4\uc9c0\uace0, \uac10\uc625\uc744 \uc7a5\uc545\ud55c \uc790\ub4e4\uacfc \ub9de\uc11c\uba70, \uc5ec\ub7ec \uc655\uad6d\uc774 \uc774\ubbf8 \uc798 \uc54c\uace0 \uc788\ub294 \uc218\uc218\uaed8\ub07c\uc5d0 \uad00\ud55c \uc0c8 \ub2e8\uc11c\ub97c \ubaa8\uc740\ub2e4."],unknowns:["\ubc14\ub9ac\uc548 \ub9b0 \uad6d\uc655\uc774 \uc774\uacf3\uc5d0 \uac07\ud600 \uc788\uac70\ub098 \uac07\ud600 \uc788\uc5c8\ub294\uc9c0. \uacf5\uc2dd \uc124\uba85\uc740 \uc18c\ubb38\ub9cc \uc804\ud55c\ub2e4.","\uac10\uc625\uc744 \ub204\uac00 \uc6b4\uc601\ud558\uba70 \ub370\ud53c\uc544\uc988\uc640 \ub098\uac00\uac00 \uc65c \uc2f8\uc6b0\ub294\uc9c0.","\uc548\uc5d0\uc11c \uc5b4\ub5a4 \uc6b0\ub450\uba38\ub9ac\uac00 \uae30\ub2e4\ub9ac\ub294\uc9c0. \uc774 \uc548\ub0b4\uc11c\uc758 \uc790\ub8cc\uc5d0\ub294 \uc544\uc9c1 \uc5c6\ub2e4."]},"instance:maraudon":{title:"\ub9c8\ub77c\uc6b0\ub3c8",summary:"\ub300\uc9c0\uc758 \uacf5\uc8fc \ud14c\ub77c\ub4dc\ub77c\uc2a4\uc758 \uc2ac\ud514\uc73c\ub85c \uc624\uc5fc\ub41c, \uc78a\ud600\uc9c4 \ub545\uc5d0 \uc788\ub294 \ucf04\ud0c0\uc6b0\ub85c\uc2a4\uc758 \uc2e0\uc131\ud55c \ub3d9\uad74.",body:["\uc804\uc124\uc740 \ucf04\ud0c0\uc6b0\ub85c\uc2a4\uc758 \ud0c4\uc0dd\uc5d0 \uad00\ud55c \uc74c\uc6b8\ud55c \uc774\uc57c\uae30\ub97c \ub4e4\ub824\uc900\ub2e4. \uadf8\ub4e4\uc758 \uc544\ubc84\uc9c0\ub294 \ubc18\uc2e0 \uc138\ub098\ub9ac\uc6b0\uc2a4\uc758 \uc544\ub4e4 \uc790\uc5d0\ud0c0\ub974\uc600\uace0, \uc5b4\uba38\ub2c8\ub294 \ub300\uc9c0\uc758 \uc815\ub839 \uad70\uc8fc\uc758 \ub538 \ud14c\ub77c\ub4dc\ub77c\uc2a4 \uacf5\uc8fc\uc600\ub2e4. \ucd5c\ucd08\uc758 \ucf04\ud0c0\uc6b0\ub85c\uc2a4\ub4e4\uc740 \uc790\uc5d0\ud0c0\ub974\uc5d0\uac8c \ub4f1\uc744 \ub3cc\ub824 \uadf8\ub97c \uc8fd\uc600\uace0, \uc2ac\ud514\uc5d0 \uc7a0\uae34 \ud14c\ub77c\ub4dc\ub77c\uc2a4\ub294 \uadf8\uc758 \uc601\ud63c\uc744 \ub9c8\ub77c\uc6b0\ub3c8 \uc548\uc5d0 \ubb36\uc5b4 \ub450\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uadf8 \ud589\uc704\uac00 \ub0a8\uae34 \ud0c0\ub77d\uc740 \uc9c0\uae08\ub3c4 \ub3d9\uad74\uc744 \uc624\uc5fc\uc2dc\ud0a4\uace0 \uc788\ub2e4.","\ucf04\ud0c0\uc6b0\ub85c\uc2a4 \ubd80\uc871\ub4e4\uc740 \ub9c8\ub77c\uc6b0\ub3c8\uc744 \uc2e0\uc131\ud55c \ub9e4\uc7a5\uc9c0\ub85c \uc5ec\uae30\uc9c0\ub9cc, \uc774\uc81c Wicked Grotto\uc640 Foulspore Cavern, Earth Song Falls\uc5d0\ub294 \uc548\uc2dd\ud558\uc9c0 \ubabb\ud55c \ucf04\ud0c0\uc6b0\ub85c\uc2a4 \uc720\ub839\uacfc \ub4a4\ud2c0\ub9b0 \uc815\ub839, \ub3c5\uc744 \ud488\uc740 \uc2dd\ubb3c \uc0dd\ubb3c\ub4e4\uc774 \uac00\ub4dd\ud558\ub2e4. \uc790\uc5d0\ud0c0\ub974\uc758 \uc870\uce74 \uc140\ub808\ube0c\ub77c\uc2a4\ub294 \uc219\ubd80\uc758 \uc601\ud63c\uc744 \ud480\uc5b4 \uc8fc\ub7ec \uc654\ub2e4\uac00 \uc790\uc2e0\ub3c4 \ud0c0\ub77d\uc5d0 \ubb34\ub108\uc84c\ub2e4. \ub9e8 \ubc11\ubc14\ub2e5\uc5d0\uc11c\ub294 \ud14c\ub77c\ub4dc\ub77c\uc2a4\uac00 \uae30\ub2e4\ub9b0\ub2e4."]},"instance:temple-of-atalhakkar":{title:"\uc544\ud0c8\ud559\uce74\ub974 \uc2e0\uc804",summary:"\uc544\ud0c8\ub77c\uc774 \uc0ac\uc81c\ub4e4\uc774 \uc544\uc9c1\ub3c4 \ud53c\uc758 \uc2e0 \ud559\uce74\ub974\ub97c \ubd80\ub974\ub824 \ud558\ub294 \uc2ac\ud514\uc758 \ub2aa\uc758 \uac00\ub77c\uc549\uc740 \uc0ac\uc6d0.",body:["\uc544\ud0c8\ub77c\uc774\ub294 \ud53c\uc758 \uc2e0\uc778 \uc601\ud63c\uc57d\ud0c8\uc790 \ud559\uce74\ub974\ub97c \uc138\uc0c1\uc5d0 \ubd88\ub7ec\ub4e4\uc774\ub824 \ud55c \ud2b8\ub864 \uc0ac\uc81c\ub4e4\uc774\uc5c8\uc73c\uba70, \uadf8\ub4e4\uc744 \ub9c9\uc73c\ub824\ub294 \uc2f8\uc6c0\uc774 \ucc9c\uc5ec \ub144 \uc804 \uad6c\ub8e8\ubc14\uc2dc \uc81c\uad6d\uc744 \uac08\uac00\ub9ac \ucc22\uc5b4 \ub193\uc558\ub2e4. \ud328\ubc30\ud558\uace0 \ucad3\uaca8\ub09c \uadf8\ub4e4\uc740 \ud559\uce74\ub974\uc758 \uadc0\ud658\uc744 \uc900\ube44\ud558\ub824\uace0 \uc2ac\ud514\uc758 \ub2aa\uc5d0 \uc2e0\uc804\uc744 \uc138\uc6e0\uc9c0\ub9cc, \uc704\uc0c1 \uc774\uc138\ub77c\uac00 \uadf8 \uacc4\ud68d\uc744 \uc54c\uc544\ucc44\uace0 \uc2e0\uc804\uc744 \uc9c4\ud759 \uc18d\uc5d0 \uac00\ub77c\uc549\ud614\ub2e4.","\uadf8 \ub4a4\ub85c \ub179\uc0c9\uc6a9\ub4e4\uc774 \uac00\ub77c\uc549\uc740 \ud3d0\ud5c8\ub97c \uc9c0\ucf1c \uc654\uc9c0\ub9cc, \uc544\ud0c8\ub77c\uc774\ub294 \uc0b4\uc544\ub0a8\uc544 \uc608\uc5b8\uc790 \uc7a0\ub9d0\ub780 \uc544\ub798\uc5d0\uc11c \uc9c0\uae08\ub3c4 \ud559\uce74\ub974\uc5d0\uac8c \uae30\ub3c4\ud55c\ub2e4. \ub354 \uae4a\uc740 \uacf3\uc5d0\ub294 \uc774\uc138\ub77c\uc758 \ubc30\uc6b0\uc790\ub85c\uc11c \uc5d0\uba54\ub784\ub4dc\uc758 \uc545\ubabd\uc5d0 \uc815\uc2e0\uc774 \uc5b4\ub450\uc6cc\uc9c4 \uc5d0\ub77c\ub2c8\ucfe0\uc2a4\uc758 \uc0ac\ub839\uc774 \uba38\ubb3c\ub7ec \uc788\ub2e4."]},"instance:blackrock-depths":{title:"\uac80\uc740\ubc14\uc704 \ub098\ub77d",summary:"\uac80\uc740\ubc14\uc704 \uc0b0 \uae4a\uc740 \uacf3\uc5d0 \uc788\ub294 \uac80\uc740\ubb34\uc1e0 \ub4dc\uc6cc\ud504\uc758 \uc218\ub3c4 \uc5b4\ub460\uad34\ucca0\ub85c\ub85c, \ud669\uc81c \ub2e4\uadf8\ub780 \ud0c0\uc6b0\ub9bf\uc0b0\uc774 \ub77c\uadf8\ub098\ub85c\uc2a4\uc758 \uadf8\ub298 \uc544\ub798 \ub2e4\uc2a4\ub9b0\ub2e4.",body:["\ub450 \uc138\uae30\ub3c4 \ub354 \uc804\uc5d0, \uac80\uc740\ubb34\uc1e0\uc758 \ub9c8\ubc95\uc0ac \uc601\uc8fc \ud0c0\uc6b0\ub9bf\uc0b0\uc740 \uc808\ubc15\ud55c \uc18c\ud658\uc73c\ub85c \uc774\ubbf8 \uc9c4 \uc804\uc7c1\uc744 \ub4a4\uc9d1\uc73c\ub824\ub2e4 \uc624\ud788\ub824 \ubd88\uc758 \uad70\uc8fc \ub77c\uadf8\ub098\ub85c\uc2a4\ub97c \ubd88\ub7ec\ub0c8\ub2e4. \uadf8 \ud3ed\ubc1c\ub85c \uac80\uc740\ubc14\uc704 \uc0b0\uc774 \uc19f\uc544\uc62c\ub790\uace0, \uadf8\uc758 \ubd80\uc871\uc740 \ubd88\uc758 \uad70\uc8fc\uc758 \ub73b\uc5d0 \ubb36\uc774\uac8c \ub418\uc5c8\ub2e4. \uadf8 \ud6c4\uc190\ub4e4\uc740 \uc9c0\uae08\ub3c4 \uc0b0 \uc544\ub798 \ubd88\ud0c0\ub294 \uad74\uc5d0\uc11c \ub77c\uadf8\ub098\ub85c\uc2a4\ub97c \uc704\ud574 \uace0\uc5ed\uc744 \uce58\ub978\ub2e4.","\uac80\uc740\ubc14\uc704 \ub098\ub77d\uc740 \uadf8\ub4e4\uc758 \uc601\uc5ed\uc774\ub2e4. \uac10\uc625, \ubc95\uc758 \uc2ec\ud310\uc7a5\uc774\ub77c \ubd88\ub9ac\ub294 \ud22c\uae30\uc7a5, Grim Guzzler \uc120\uc220\uc9d1, \uac80\uc740 \ub300\uc7a5\uac04, \uadf8\ub9ac\uace0 \uc5b4\ub460\uad34\ucca0\ub85c \uadf8 \uc790\uccb4\uac00 \uc788\ub2e4. \uadf8\uacf3\uc5d0\uc11c \ud669\uc81c \ub2e4\uadf8\ub780 \ud0c0\uc6b0\ub9bf\uc0b0\uc774 \uc625\uc88c\uc5d0 \uc549\uc544 \uc788\uc73c\uba70, \uadf8 \uacc1\uc5d0\ub294 \ubaa8\uc774\ub77c \ube0c\ub860\uc988\ube44\uc5b4\ub4dc \uacf5\uc8fc\uac00 \uc788\ub2e4. \uadf8\ub140\uc758 \uc544\ubc84\uc9c0\uc778 \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \ub9c8\uadf8\ub2c8 \uc655\uc740 \ub538\uc774 \uc8fc\ubb38\uc5d0 \uac78\ub824 \ubd99\uc7a1\ud600 \uc788\ub2e4\uace0 \ubbff\ub294\ub2e4."]},"instance:warpwood-quarter":{title:"Warpwood Quarter",summary:"\ud3d0\ud5c8\uac00 \ub41c \uc5d8\ub4dc\ub808\ud0c8\ub77c\uc2a4\uc758 \ub3d9\ucabd \uad6c\uc5ed\uc73c\ub85c, \uc0ac\ud2f0\ub85c\uc2a4 Alzzin the Wildshaper \uc544\ub798\uc5d0\uc11c \ud0c0\ub77d\ud55c \uc2dd\ubb3c\ub4e4\uc774 \ub4a4\ub36e\uc5c8\ub2e4.",body:["\ud398\ub784\ub77c\uc2a4\uc758 \ud608\ud22c\uc758 \uc804\uc7a5\uc740 \ud55c\ub54c \uc544\uc988\uc0e4\ub77c \uc5ec\uc655\uc758 \uac00\uc7a5 \uc740\ubc00\ud55c \ube44\uc804\uc220\uc0ac\ub4e4\uc774 \uc5ec\uc655\uc758 \uadc0\ud55c \uc9c0\uc2dd\uc744 \uc9c0\ud0a4\ub358 \ub3c4\uc2dc \uc5d8\ub4dc\ub808\ud0c8\ub77c\uc2a4\uc600\ub2e4. \uc138\uacc4\uc758 \ubd84\ub9ac\ub294 \ub3c4\uc2dc\ub97c \ubd80\uc234 \ub193\uc558\uace0, \uc138\uc6d4\uc774 \ud750\ub974\uba70 \uc624\uc6b0\uac70\uc640 \uc0ac\ud2f0\ub85c\uc2a4, \uadf8\ub9ac\uace0 \ub354 \uae30\uc774\ud55c \uc874\uc7ac\ub4e4\uc774 \uadf8 \uad6c\uc5ed\ub4e4\uc5d0 \uc790\ub9ac \uc7a1\uc558\ub2e4.","\ub3d9\ucabd\uc758 Warpwood Quarter\ub294 \ud48d\uc694\uc758 \uc5f4\ub9e4\ub97c \ud0c0\ub77d\uc2dc\ucf1c \uc774\uc81c \uc5ed\uaca8\uc6b4 \uc9c0\uc625\ub369\uad74\ub9cc \ub9fa\uac8c \ub9cc\ub4e0 \uc0ac\ud2f0\ub85c\uc2a4 Alzzin the Wildshaper\uc758 \uc190\uc5d0 \ub118\uc5b4\uac14\ub2e4. \ub4a4\ud2c0\ub9b0 \uace0\ub300\uc815\ub839, \ucc44\ucc0d\ub369\uad74, \uc545\ub9c8, \uc0ac\ud2f0\ub85c\uc2a4\uac00 \uadf8\uc5d0\uac8c \ubcf5\uc885\ud558\uba70, \uad6c\uc5ed \uc804\uccb4\uac00 \uc57c\uc0dd\uc73c\ub85c \ub3cc\uc544\uac14\ub2e4. \uc7a5\ub09c\uafb8\ub7ec\uae30 \uc784\ud504 \ud478\uc2e4\ub9b0\uc870\ucc28 \uce68\uc785\uc790\ub4e4\uc744 \ub370\ub9ac\uace0 \uc804\ub2f9 \uacf3\uacf3\uc5d0\uc11c \uc2e0\ub098\ub294 \ucd94\uaca9\uc804\uc744 \ubc8c\uc778\ub2e4."]},"instance:blackmaw-hold":{title:"Blackmaw Hold",summary:"\uc544\uc988\uc0e4\ub77c\uc5d0\uc11c \uc624\ub7ab\ub3d9\uc548 \ubd09\uc778\ub418\uc5b4 \uc788\ub358 \ubb38 \ub108\uba38\uc758 \uac70\ub300\ud55c \ud37c\ubcfc\uadf8 \ub3c4\uc2dc\ub85c, Blackmaw \ubd80\uc871\uc774 \ubc88\uc838 \uac00\ub294 \ud0c0\ub77d\uacfc \uc2f8\uc6b0\uace0 \uc788\ub2e4.",body:["\uc544\uc988\uc0e4\ub77c\uc5d0\uc11c \uc544\uc8fc \uc624\ub7ab\ub3d9\uc548 \ub2eb\ud600 \uc788\ub358 \ubb38 \ub108\uba38\uc5d0 \ud37c\ubcfc\uadf8\uc758 \uac70\ub300\ud55c \ub3c4\uc2dc\uac00 \uc788\ub2e4. \uadf8\uacf3\uc5d0 \uc0ac\ub294 Blackmaw \ubd80\uc871\uc740 \uc232\uacfc \uc0b0 \uc544\ub798 \uad6c\ubd88\uad6c\ubd88\ud55c \uad74\uc744 \ub530\ub77c \uc2a4\uba70\ub4dc\ub294 \ud0c0\ub77d\uacfc \uc2f8\uc6b0\uace0 \uc788\ub2e4.","\uc774 \uc694\uc0c8\ub294 \ucd5c\uace0 \ub808\ubca8 \ud30c\ud2f0\ub97c \uc704\ud55c \uae34 \ubaa8\ud5d8\uc73c\ub85c, \uc5ec\ub7ec \uacbd\ub85c\uc640 \ub9ce\uc740 \uc6b0\ub450\uba38\ub9ac\uac00 \uc788\ub2e4. \uac00\uc7a5 \uae4a\uc740 \uacf3\uc5d0\ub294 \uc544\uc81c\ub85c\uc2a4 \uc544\ub798\ub85c \ub354 \uae4a\uc774 \ub0b4\ub824\uac00\ub294 \uae38\uc774 \uc228\uc5b4 \uc788\ub2e4\uace0 \ud558\uba70, \ube14\ub9ac\uc790\ub4dc\uc758 \uacf5\uaca9\ub300 \uac1c\uc694\ub294 Blackmaw Hold\ub97c Barrow Deeps\ub85c \ub4e4\uc5b4\uac00\ub294 \uae38 \uac00\uc6b4\ub370 \ud558\ub098\ub85c \uaf3d\ub294\ub2e4."],unknowns:["\ud0c0\ub77d\uc774 \ubb34\uc5c7\uc774\uba70 \uc5b4\ub514\uc11c \uc624\ub294\uc9c0.","\ub204\uac00 \uc65c \ubb38\uc744 \ubd09\uc778\ud588\ub294\uc9c0.","\uc548\uc5d0\uc11c \uc5b4\ub5a4 \uc6b0\ub450\uba38\ub9ac\uac00 \uae30\ub2e4\ub9ac\ub294\uc9c0. \uc774 \uc548\ub0b4\uc11c\uc758 \uc790\ub8cc\uc5d0\ub294 \uc544\uc9c1 \uc5c6\ub2e4."]},"instance:lower-blackrock-spire":{title:"\uac80\uc740\ubc14\uc704 \ucca8\ud0d1 \ud558\uce35",summary:"\uac80\uc740\ubc14\uc704 \uc0b0 \uaf2d\ub300\uae30 \ucca8\ud0d1\uc758 \uc544\ub798\uce35 \uc804\ub2f9\uc73c\ub85c, \ub80c\ub4dc \ube14\ub799\ud578\ub4dc\uac00 \uc774\ub044\ub294 \uc5b4\ub460\uc758 \ud638\ub4dc\uc758 \ubcd1\uc601\uc774\ub2e4.",body:["\uc218 \uc138\uae30 \ub3d9\uc548 \uac80\uc740\ubc14\uc704 \uc0b0\uc744 \uc655\uad00\ucc98\ub7fc \ub450\ub978 \ucca8\ud0d1\uc740 \uac80\uc740\ubb34\uc1e0 \ubd80\uc871\uc758 \uc694\uc0c8\uc600\ub2e4. \uadf8\ub7ec\ub098 \ub370\uc2a4\uc719\uc758 \uc544\ub4e4 \ub124\ud30c\ub9ac\uc548\uc774 \uc6a9\uc871 \uc218\ud558\ub4e4\uc744 \uc774\ub04c\uace0 \uc704\uce35\uc744 \ucc28\uc9c0\ud574 \ub4dc\uc6cc\ud504\ub4e4\uc5d0\uac8c \ub4f1\uc744 \ub3cc\ub9ac\uba74\uc11c \uadf8 \uc2dc\ub300\ub294 \ub05d\ub0ac\ub2e4. \uadf8\ub294 \uc2a4\ub784\uc744 \ub530\ub974\uc9c0 \uc54a\ub294 \uc5b4\ub460\uc758 \ud638\ub4dc\uc758 \ub300\uc871\uc7a5\uc744 \uc790\ucc98\ud558\ub294 \uc624\ud06c \ub80c\ub4dc \ube14\ub799\ud578\ub4dc\ub97c \ub3d9\ub9f9\uc73c\ub85c \uc0bc\uc558\ub2e4.","\uac80\uc740\ubc14\uc704 \ucca8\ud0d1 \ud558\uce35\uc740 \uadf8 \uc5b4\ub460\uc758 \ud638\ub4dc\uc758 \ubcd1\uc601\uc774\ub2e4. \uac80\uc740\ubc14\uc704 \uc624\ud06c \uad70\ub2e8, \ub300\uad70\uc8fc \uc624\ubaa8\ud06c \ud718\ud558\uc758 Spirestone \uc624\uc6b0\uac70, \uc5b4\ub460\uc0ac\ub0e5\uafbc \ubcf4\uc26c\uac00\uc9c4\uc758 Smolderthorn \ud2b8\ub864, \uadf8\ub9ac\uace0 Mother Smolderweb \uc8fc\ubcc0\uc758 \uac70\ubbf8\ub4e4\uc774 \ub300\uad70\uc8fc \uc6dc\ud0c0\ub77c\ud06c\uc758 \uc9c0\ud718 \uc544\ub798 \ubb34\ub108\uc9c4 \uc804\ub2f9\uc744 \ud568\uaed8 \uc4f4\ub2e4. \uc815\uc608\ubcd1\uacfc \uc6a9\ub4e4\uc740 \ub354 \ub192\uc740 \uacf3, \uac80\uc740\ubc14\uc704 \ucca8\ud0d1 \uc0c1\uce35\uc5d0\uc11c \uae30\ub2e4\ub9b0\ub2e4."]},"instance:capital-gardens":{title:"Capital Gardens",summary:"\uc5d8\ub4dc\ub808\ud0c8\ub77c\uc2a4\uc758 \uc11c\ucabd \uad6c\uc5ed\uc73c\ub85c, \uc174\ub4dc\ub784\ub77c\uc758 \ub9c8\uc9c0\ub9c9 \uba85\uac00 \uc5d8\ud504\ub4e4\uc774 \uac07\ud78c \uc545\ub9c8\uc758 \ud798\uc73c\ub85c \uc5f0\uba85\ud558\ub294 \uacf3.",body:["\uc9c0\uae08\uc740 \ud608\ud22c\uc758 \uc804\uc7a5\uc774\ub77c \ubd88\ub9ac\ub294 \uc5d8\ub4dc\ub808\ud0c8\ub77c\uc2a4\ub294 \uc544\uc988\uc0e4\ub77c \uc5ec\uc655\uc758 \ube44\uc804 \ube44\ubc00\uc744 \uc9c0\ud0a4\uae30 \uc704\ud574 \uc9c0\uc5b4\uc84c\uc73c\uba70, \uadf8 \uc218\ud638\uc790\uc778 \uc174\ub4dc\ub784\ub77c\ub294 \uc138\uacc4\uc758 \ubd84\ub9ac\uc5d0\uc11c \uc0b4\uc544\ub0a8\uc558\ub2e4. \uc601\uc6d0\uc758 \uc0d8\uc758 \ud798\uc744 \uc783\uc740 \uadf8\ub4e4\uc758 \uc9c0\ub3c4\uc790 \ud1a0\ub974\ud154\ub4dc\ub9b0 \uc655\uc790\ub294 \ub2e4\uc12f \uac1c\uc758 \uc218\uc815\ud0d1\uc744 \uc138\uc6cc \uc545\ub9c8 \uc774\ubab0\ud0c0\ub974\ub97c \uac00\ub450\uc5c8\uace0, \uadf8\uc758 \ubc31\uc131\uc740 \ubd88\uba78\uc744 \uc720\uc9c0\ud558\ub824\uace0 \uadf8 \uc545\ub9c8\uc758 \uae30\uc6b4\uc744 \ube68\uc544\ub4e4\uc600\ub2e4.","\uc218 \uc138\uae30\uac00 \ud750\ub974\uba70 \uac10\uc625\uc740 \uc57d\ud574\uc84c\ub2e4. \uc790\uc2e0\uc758 \ud798\uc744 \uc9c0\ud0a4\ub824\uace0 \ud1a0\ub974\ud154\ub4dc\ub9b0\uc740 \ub3d9\ub8cc \uc174\ub4dc\ub784\ub77c\uc5d0\uac8c \ub4f1\uc744 \ub3cc\ub824 \uadf8\ub4e4\uc758 \ud798\uc744 \ube7c\uc557\uc558\ub2e4. \ud55c\ub54c \uba85\uac00\uc758 \uc815\uc6d0\uc774\uc790 \uad81\uc815\uc774\uc5c8\ub358 Capital Gardens\uc5d0\ub294 \uc774\uc81c \uadf8\uc758 \ub9c8\uc9c0\ub9c9 \ucda9\uc2e0\ub4e4\uacfc \uc2dc\ub4e0 \ub098\ubb34, \uc131\ub09c \uace0\ub300\uc815\ub839, \uadf8\ub9ac\uace0 \uac07\ud78c \uc545\ub9c8 \uc790\uc2e0\uc774 \uc788\ub2e4."]},"instance:scholomance":{title:"\uc2a4\uce7c\ub85c\ub9e8\uc2a4",summary:"\ubc14\ub85c\ube0c \uac00\ubb38\uc774 \uc2a4\uceec\uc9c0\uc5d0\uac8c \ub118\uaca8\uc900, \uce74\uc5d8 \ub2e4\ub85c\uc6b0 \uc544\ub798 \uc9c0\ud558 \ubb18\uc9c0\uc5d0 \uc788\ub294 \ucf08\ud22c\uc790\ub4dc\uc758 \uac15\ub839\uc220 \ud559\uad50.",body:["\uc11c\ubd80 \uc5ed\ubcd1\uc9c0\ub300\uc758 \ub300\ub85c\uc6b0\ubbf8\uc5b4 \ud638\uc218\uc5d0 \uc788\ub294 \uc12c\uc5d0\ub294 \ud55c\ub54c \uadc0\uc871 \ubc14\ub85c\ube0c \uac00\ubb38\uc758 \uc694\uc0c8\uc600\ub358 \uce74\uc5d8 \ub2e4\ub85c\uc6b0\uac00 \uc11c \uc788\ub2e4. \ub9c8\ubc95\uc0ac \ucf08\ud22c\uc790\ub4dc\uac00 \uc800\uc8fc\ubc1b\uc740 \uc790\uc758 \uad50\ub2e8 \ucd94\uc885\uc790\ub4e4\uc744 \ubaa8\uc744 \ub54c, \uadf8\ub294 \ub9ac\uce58 \uc655\uc758 \uc774\ub984\uc73c\ub85c \ubd88\uba78\uc744 \uc57d\uc18d\ud588\uace0, \ubc14\ub85c\ube0c \uac00\ubb38\uc740 \uc694\uc0c8\uc640 \uc9c0\ud558 \ubb18\uc9c0\ub97c \uadf8\uc5d0\uac8c \ub0b4\uc8fc\uc5c8\ub2e4. \uad50\ub2e8\uc740 \uadf8 \uc9c0\ud558 \ubb18\uc9c0\ub97c \uac15\ub839\uc220\uc0ac\ub4e4\uc774 \uc5ed\ubcd1\uc744 \ud37c\ub728\ub9ac\ub3c4\ub85d \ud6c8\ub828\ubc1b\ub294 \ud559\uad50, \uc2a4\uce7c\ub85c\ub9e8\uc2a4\ub85c \ubc14\uafb8\uc5c8\ub2e4.","\ubc14\ub85c\ube0c \uac00\ubb38\uc740 \uac00\uc7a5 \ub054\ucc0d\ud55c \ubc29\uc2dd\uc73c\ub85c \uc18c\uc6d0\uc744 \uc774\ub8e8\uc5b4 \uc774\uc81c \uc5b8\ub370\ub4dc\uac00 \ub418\uc5b4 \uc804\ub2f9\uc744 \ub5a0\ub3c8\ub2e4. \ub9ac\uce58 \ub77c\uc2a4 \ud504\ub85c\uc2a4\ud2b8\uc704\uc2a4\ud37c\uac00 \uc2a4\uceec\uc9c0\ub97c \uc704\ud574 \ud559\uad50\ub97c \ub2e4\uc2a4\ub9ac\uace0, \uc554\ud751\uc2a4\uc2b9 \uac04\ub4e4\ub9c1\uc774 \uad50\uc7a5\uc744 \ub9e1\uace0 \uc788\uc73c\uba70, \uc544\ub798\uc5d0\uc11c\ub294 \ub77c\ubca4\ub2c8\uc548\uc774 \uc57d\ud55c \ud559\uc0dd\ub4e4\uc744 \uc9d1\uc5b4\uc0bc\ud0a4\ub824 \ub3c4\uc0ac\ub9ac\uace0 \uc788\ub2e4."]},"instance:shapers-terrace":{title:"Shaper's Terrace",summary:"\uc6b4\uace0\ub85c \ubd84\ud654\uad6c \uacf3\uacf3\uc5d0\uc11c \ubaa8\uc740 \ud798\uc758 \uc218\uc815\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294, \ubd84\ud654\uad6c \ubd81\ucabd \uc5b8\ub355\uc758 \uace0\ub300 \ud2f0\ud0c4 \uc2dc\uc124.",body:["\uc6b4\uace0\ub85c \ubd84\ud654\uad6c \ubd81\ucabd \uace0\uc9c0\ub300\uc5d0\uc11c, \uace0\ub300 \ud2f0\ud0c4 \uc2dc\uc124 \ud558\ub098\uac00 \uc138\uc6d4\uc774 \ube44\ucf1c \uac04 \ub4ef\ud55c \ub545\uc744 \ub0b4\ub824\ub2e4\ubcf8\ub2e4. \uacf5\ub8e1, \ud0c0\ub974 \uad6c\ub369\uc774, \ud2f0\ud0c4 \uac74\ucd95\ubb3c, \ube5b\ub098\ub294 \uc218\uc815\uc774 \ubaa8\ub450 \uc774 \uc6d0\uc815\uc758 \uc77c\ubd80\uc774\uba70, \ucd5c\uace0 \ub808\ubca8\uc5d0 \uac00\uae4c\uc6b4 \ud30c\ud2f0\ub97c \uc704\ud55c \uacf3\uc774\ub2e4.","\uc774\uacf3\uc758 \uc218\uc218\uaed8\ub07c\ub294 \uc131\ubcbd \ubc16\uae4c\uc9c0 \uc774\uc5b4\uc9c4\ub2e4. \ud30c\ud2f0\ub294 \ubd84\ud654\uad6c \uacf3\uacf3\uc5d0\uc11c \ud798\uc758 \uc218\uc815\uc744 \ubaa8\uc544 \ud14c\ub77c\uc2a4 \uc548\uc758 \uc81c\uc5b4\ubc18\uc5d0 \uc0ac\uc6a9\ud558\ubbc0\ub85c, \ubc14\uae65\uc5d0\uc11c \ubb34\uc5c7\uc744 \ucc3e\uc544\uc624\ub290\ub0d0\uc5d0 \ub530\ub77c \uc548\uc758 \ub3c4\uc804\uc774 \ub2ec\ub77c\uc9c4\ub2e4."],unknowns:["\ud14c\ub77c\uc2a4\ub97c \ub204\uac00 \uc9c0\uc5c8\uc73c\uba70 \ubb34\uc5c7\uc5d0 \uc4f0\uc600\ub294\uc9c0.","\uc81c\uc5b4\ubc18\uc774 \ubb34\uc2a8 \uc77c\uc744 \ud558\uba70 \uc548\uc5d0\uc11c \uc5b4\ub5a4 \uc6b0\ub450\uba38\ub9ac\uac00 \uae30\ub2e4\ub9ac\ub294\uc9c0. \uc774 \uc548\ub0b4\uc11c\uc758 \uc790\ub8cc\uc5d0\ub294 \uc544\uc9c1 \uc5c6\ub2e4."]},"instance:stratholme":{title:"\uc2a4\ud2b8\ub77c\uc194\ub984",summary:"\ub9ac\ube10\ub370\uc5b4 \ub0a8\uc791\uc758 \uc2a4\uceec\uc9c0\uc640 \ubd89\uc740\uc2ed\uc790\uad70\uc774 \ub098\ub204\uc5b4 \ucc28\uc9c0\ud55c, \ubd88\ud0c0\ub294 \ub85c\ub370\ub860 \ubd81\ubd80 \ub300\ub3c4\uc2dc\uc758 \ud3d0\ud5c8.",body:["\uc2a4\ud2b8\ub77c\uc194\ub984\uc740 \ub85c\ub370\ub860 \ubd81\ubd80\uc5d0\uc11c \uac00\uc7a5 \uc790\ub791\uc2a4\ub7ec\uc6b4 \ub3c4\uc2dc\uc774\uc790 \ubc31\uc740\uc758 \uc190 \uae30\uc0ac\ub2e8\uc774 \ud0dc\uc5b4\ub09c \uacf3\uc774\uc5c8\ub2e4. \uc81c3\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \uc544\uc11c\uc2a4 \uc655\uc790\ub294 \uc5ed\ubcd1\uc5d0 \ubb3c\ub4e0 \uc8fc\ubbfc\ub4e4\uc774 \uc5b8\ub370\ub4dc\ub85c \uc77c\uc5b4\uc11c\uac8c \ub450\ub290\ub2c8 \ucc28\ub77c\ub9ac \ub3c4\uc2dc\ub97c \uce7c\ub85c \ubca0\uc5b4 \ubc84\ub838\uace0, \uadf8\ub85c\uc368 \uc2a4\uc2b9 \uc6b0\uc11c\uc640 \uac08\ub77c\uc130\ub2e4. \uace7\uc774\uc5b4 \uc2a4\uceec\uc9c0\uac00 \ub4e4\uc5b4\uc654\uace0, \ub3c4\uc2dc\ub294 \uadf8 \ub4a4\ub85c \uc904\uace7 \ubd88\ud0c0\uace0 \uc788\ub2e4.","\uc624\ub298\ub0a0 \ub450 \uc801\uc774 \ub3c4\uc2dc\ub97c \ub098\ub204\uc5b4 \ucc28\uc9c0\ud55c\ub2e4. \ubd89\uc740\uc2ed\uc790\uad70\uc740 \ub300\uc131\uc804\uae30\uc0ac \ub2e4\uc2a4\ub85c\ud55c \uc544\ub798 \ud55c\ucabd\uc744 \uc9c0\ud0a4\ub294\ub370, \uadf8\uac00 \uc0ac\uc2e4\uc740 \ubcc0\uc7a5\ud55c \uacf5\ud3ec\uc758 \uad70\uc8fc \ubc1c\ub098\uc790\ub974\ub77c\ub294 \uac83\uc744 \uafc8\uc5d0\ub3c4 \ubaa8\ub978\ub2e4. \ub2e4\ub978 \ucabd\uc740 \uc2a4\uceec\uc9c0\uc640 \uc8fd\uc74c\uc758 \uae30\uc0ac \ub9ac\ube10\ub370\uc5b4 \ub0a8\uc791\uc758 \uac83\uc774\ub2e4. \uadf8\ub294 \uc800\uc8fc\ubc1b\uc740 \uc790\uc758 \uad50\ub2e8\uc5d0 \ub4e4\uc5b4\uac00\uae30 \uc804 \uc2a4\ud2b8\ub77c\uc194\ub984\uc758 \ubd80\uc720\ud55c \uc9c0\uc8fc\uc774\uc790 \ucf08\ud22c\uc790\ub4dc\uc758 \uce5c\uad6c\uc600\ub2e4."]},"instance:gordok-commons":{title:"Gordok Commons",summary:"\uace0\ub974\ub3c5 \uc655\uacfc \uadf8\uc758 \uc624\uc6b0\uac70\ub4e4\uc774 \uc790\ub9ac \uc7a1\uc740 \ud608\ud22c\uc758 \uc804\uc7a5 \ubd81\ucabd \uad6c\uc5ed\uc73c\ub85c, \uc655\uc744 \uc8fd\uc778 \uc790\uac00 \uc655\uad00\uc744 \ucc28\uc9c0\ud55c\ub2e4.",body:["\uace0\ub974\ub454\ub2c8 \ubd80\uc871 \uc624\uc6b0\uac70\ub4e4\uc774 \uc9c0\uae08\uc740 \ud608\ud22c\uc758 \uc804\uc7a5\uc774\ub77c \ubd88\ub9ac\ub294 \ud3d0\ud5c8\uac00 \ub41c \uba85\uac00\uc758 \ub3c4\uc2dc, \uc61b \uc5d8\ub4dc\ub808\ud0c8\ub77c\uc2a4\uc758 \ubd81\ucabd \uad6c\uc5ed\uc744 \ucc28\uc9c0\ud588\ub2e4. \uadf8\ub4e4 \uac00\uc6b4\ub370 \uac00\uc7a5 \uac15\ud55c \uc804\uc0ac\uc778 \uace0\ub974\ub3c5\uc774 Commons\uc5d0\uc11c \ub2e4\uc2a4\ub9ac\uba70, \uadf8\ub4e4\uc758 \uc655\uc740 \uace0\ub974\ub3c5 \uc655\uc774\ub77c\ub294 \uc774\ub984\uc744 \uc4f4\ub2e4.","\uc774\uacf3 \uc624\uc6b0\uac70\uc758 \uad00\uc2b5\uc740 \ub2e8\uc21c\ud558\ub2e4. \uc655\uc744 \uc8fd\uc778 \uc790\uac00 \uc0c8\ub85c\uc6b4 \uace0\ub974\ub3c5 \uc655\uc774 \ub41c\ub2e4. \uc601\ub9ac\ud55c \ud30c\ud2f0\ub294 \uacbd\ube44\ubcd1 \ubab0\ub2e4\ub974, \ud3ad\uad6c\uc2a4, \uc2ac\ub9bd\ud0a5\uacfc \ucff5\ucf85 \ud06c\ub9ac\uadf8, \ub300\uc7a5 \ud06c\ub86c\ud06c\ub7ec\uc26c \uc0ac\uc774\ub97c \ubab0\ub798 \ube60\uc838\ub098\uac00 \uc655\ub9cc \ub178\ub9ac\uba70, \uc0b4\uc544\ub0a8\uc740 \uc624\uc6b0\uac70\ub4e4\uc740 \uc2b9\uc790\ub97c \uc0c8 \ud1b5\uce58\uc790\ub85c \ubaa8\uc2dc\uace0 \uacf5\ubb3c\uc744 \ubc14\uce5c\ub2e4. \uad00\ucc30\uc790 \ucd08\ub8e8\uc26c\uac00 \uc655 \uacc1\uc744 \uc9c0\ud0a8\ub2e4."]},"instance:barrow-deeps":{title:"Barrow Deeps",summary:"\uc77c\ub9ac\ub2e8 \uc2a4\ud1b0\ub808\uc774\uc9c0\ub97c \ub9cc \ub144 \ub3d9\uc548 \uac00\ub450\uc5c8\ub358 \uce7c\ub9bc\ub3c4\uc5b4 \uc544\ub798 \uac10\uc625\uc73c\ub85c \ud5a5\ud558\ub294 10\uc778 \uacf5\uaca9\ub300.",body:["\uce7c\ub9bc\ub3c4\uc5b4 \uae4a\uc740 \uacf3 \uc544\ub798, Barrow Deeps\ub294 \uc77c\ub9ac\ub2e8 \uc2a4\ud1b0\ub808\uc774\uc9c0\ub97c \ub9cc \ub144 \ub3d9\uc548 \uac00\ub450\uc5b4 \ub450\uc5c8\ub2e4. \uc774\uc81c \uadf8 \uad74\ub85c \uac00\ub294 \uae38\uc774 \uc5f4\ub838\uace0, \uacf5\uaca9\ub300\ub294 \uc5b4\ub460 \uc18d\uc5d0 \ub0a8\uaca8\uc9c4 \uc774\ub4e4\uc5d0\uac8c \ubb34\uc2a8 \uc77c\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0, \uadf8\ub9ac\uace0 \uac10\uc2dc\uc790\ub4e4\uc774 \uc544\ub798\uc5d0\uc11c \uafc8\ud2c0\ub300\ub294 \uc704\ud611\uc5d0 \uc5b4\ub5bb\uac8c \ub300\ucc98\ud558\ub824 \ud558\ub294\uc9c0 \uc54c\uc544\ub0b4\ub7ec \ub0b4\ub824\uac04\ub2e4.","\ud558\uc774\uc798 \uc0b0, \uc5ec\uba85\uc758 \uc124\uc6d0, Blackmaw Hold\uc640 \uc774\uc5b4\uc9c4 \uc138 \uac08\ub798 \uae38\uc774 \uc548\uc73c\ub85c \ud1b5\ud55c\ub2e4. 10\uba85\uc758 \ud50c\ub808\uc774\uc5b4\uac00 \ub0b4\ub824\uac00\ub294 \ub3d9\uc548 \uc5ec\ub35f \uc6b0\ub450\uba38\ub9ac\uc640 \ub9de\uc11c\uba70, Deepscar Matriarch\uc640 Khalith the Dreadspinner\ubd80\ud130 Del'lynar Songwood\ub97c \uac70\uccd0 \ub9c8\uc9c0\ub9c9\uc73c\ub85c Sonya Darkhallow\uc5d0 \uc774\ub978\ub2e4."],unknowns:["\ub204\uac00 \ud1b5\ub85c\ub97c \uc5f4\uc5c8\uc73c\uba70 \uc544\ub798\uc758 \uc704\ud5d8\uc774 \ubb34\uc5c7\uc778\uc9c0.","\uac10\uc2dc\uc790\ub4e4\uc774 \ub204\uad6c\uc774\uba70 \uc5ec\ub35f \uc6b0\ub450\uba38\ub9ac\uc5d0\uac8c \uc5b4\ub5a4 \uc0ac\uc5f0\uc774 \uc788\ub294\uc9c0."]},"instance:hyjal-summit":{title:"Hyjal Summit",summary:"\uc138\uacc4\uc218 \ub180\ub4dc\ub78f\uc2e4 \uadfc\ucc98 \ud558\uc774\uc798 \uc0b0 \uc815\uc0c1\uc5d0\uc11c \uc5f4\ub9ac\ub294 20\uc778 \uacf5\uaca9\ub300\ub85c, \uc6b0\ub450\uba38\ub9ac \uc5f4\uc14b\uacfc \uc5ec\ub7ec \uac08\ub798 \uae38\uc774 \uc788\ub2e4.",body:["Hyjal Summit\uc740 \ud558\uc774\uc798 \uc0b0 \uaf2d\ub300\uae30, \uc138\uacc4\uc218 \ub180\ub4dc\ub78f\uc2e4 \uadfc\ucc98\uc5d0 \uc788\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uace0\ub300\uc758 \uc218\ud638\uc790\uac00 \uae38\uc744 \ub9c9\uace0, \uadf8 \ub4a4\ub85c\ub294 \uacf5\uaca9\ub300\uac00 \uc0b0\uc744 \ub118\ub294 \uacbd\ub85c\ub97c \uc2a4\uc2a4\ub85c \uace8\ub77c \uc9c0\uc0c1\uacfc \uc9c0\ud558\uc758 \ud3d0\ud5c8\ub97c \uc9c0\ub098\uba70 \ud558\uc774\uc798\uc744 \uc704\ud611\ud558\ub294 \ubaa8\ub4e0 \uac83\uacfc \uc2f8\uc6b0\ub2e4\uac00, \ub9c8\uce68\ub0b4 \ub9c8\uc9c0\ub9c9 \uc804\ud22c\ub85c \uac00\ub294 \uae38\uc774 \uc5f4\ub9b0\ub2e4.","20\uba85\uc758 \ud50c\ub808\uc774\uc5b4\uac00 \uc6b0\ub450\uba38\ub9ac \uc5f4\uc14b\uacfc \ub9de\uc120\ub2e4. \uadf8 \uac00\uc6b4\ub370\uc5d0\ub294 Bandalar, Time-Lost Battalion, Council of Thorns, Wild King, Ancient of Decay\uac00 \uc788\ub2e4. \uac00\uc7a5 \ub9c8\uc9c0\ub9c9\uc740 Nythus the Dreambound\ub2e4."],unknowns:["\ud558\uc774\uc798\uc744 \uc704\ud611\ud558\ub294 \uc138\ub825\uc774 \ubb34\uc5c7\uc778\uc9c0. \uacf5\uc2dd \uac1c\uc694\ub294 \uc774\ub984\uc744 \ubc1d\ud788\uc9c0 \uc54a\ub294\ub2e4.","\uace0\ub300\uc758 \uc218\ud638\uc790\uac00 \ub204\uad6c\uc774\uba70 Nythus the Dreambound\uac00 \ub204\uad6c\uc778\uc9c0."]},"instance:onyxias-lair":{title:"\uc624\ub2c9\uc2dc\uc544\uc758 \ub465\uc9c0",summary:"\uba3c\uc9c0\uc9c4\ud759 \uc2b5\uc9c0\ub300\uc5d0 \uc788\ub294 \uac80\uc740\uc6a9\uad70\ub2e8\uc758 \uc5b4\ubbf8 \uc6a9 \uc624\ub2c9\uc2dc\uc544\uc758 \ub465\uc9c0\ub85c, \uc6a9\uc758 \ubd88\uaf43 \ubd80\uc801\uc744 \uc9c0\ub2cc \uc790\ub9cc \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4.",body:["\uba3c\uc9c0\uc9c4\ud759 \uc2b5\uc9c0\ub300\uc758 Wyrmbog\uc5d0\uc11c, \ub370\uc2a4\uc719\uc758 \ub538\uc774\uc790 \ub124\ud30c\ub9ac\uc548\uc758 \ub204\uc774\uc778 \uc624\ub2c9\uc2dc\uc544\uac00 \ubd88\uaf43\uc758 \ub3d9\uad74\uc5d0\uc11c \uc0c8\ub07c\ub4e4\uc744 \uc9c0\ud0a8\ub2e4. \uadf8\ub140\uc758 \ub354 \ud070 \ubb34\uae30\ub294 \uae30\ub9cc\uc774\ub2e4. \uc778\uac04\uc758 \ubaa8\uc2b5\uc744 \ud55c \uce74\ud2b8\ub77c\ub098 \ud504\ub808\uc2a4\ud130 \ubd80\uc778\uc73c\ub85c\uc11c, \uadf8\ub140\ub294 \uc2a4\ud1b0\uc708\ub4dc \uad81\uc815\uc5d0\uc11c \uc18d\uc0ad\uc774\uba70 \ud544\uba78\uc790\uc758 \uc655\uad6d\ub4e4\uc744 \uc11c\ub85c \uc2f8\uc6b0\uac8c \ub9cc\ub4e4\ub824 \ud55c\ub2e4.","40\uba85\uc758 \ud50c\ub808\uc774\uc5b4\uac00 \uc138 \ub2e8\uacc4\ub85c \uc774\ub8e8\uc5b4\uc9c4 \ud654\uc5fc\uc758 \uc804\ud22c\uc5d0\uc11c \uadf8\ub140\uc640 \ub9de\uc11c\ubbc0\ub85c, \uacf5\uaca9\ub300\ub294 \uba3c\uc800 \ud654\uc5fc \uc800\ud56d\uc744 \uac16\ucd98\ub2e4. \ub610\ud55c \ubaa8\ub4e0 \uad6c\uc131\uc6d0\uc740 \uae34 \uc5f0\uacc4 \ud018\uc2a4\ud2b8\ub85c \uc5bb\ub294 \uc6a9\uc758 \ubd88\uaf43 \ubd80\uc801\uc744 \uc9c0\ub140\uc57c \ud55c\ub2e4. \uc5bc\ub77c\uc774\uc5b8\uc2a4\ub294 \uac80\uc740\ubc14\uc704 \ub098\ub77d\uc5d0\uc11c \uc708\uc800 \uc0ac\ub839\uad00\uc758 \ud0c8\ucd9c\uacfc \uc2a4\ud1b0\uc708\ub4dc\uc5d0\uc11c\uc758 \uc815\uccb4 \ud3ed\ub85c\ub97c \uac70\uce58\uace0, \ud638\ub4dc\ub294 \ub809\uc0ac\ub974\uc640 \ube44\ub8e1 \uc5e0\ubc84\uc2a4\ud2b8\ub77c\uc774\ud504\ub97c \uac70\uce5c\ub2e4. \ub450 \uac08\ub798 \ubaa8\ub450 \uac80\uc740\ubc14\uc704 \ucca8\ud0d1 \uc0c1\uce35\uc758 \ub4dc\ub77c\ud0a4\uc0ac\uc2a4 \uc7a5\uad70\uc5d0\uac8c\uc11c \ub05d\ub09c\ub2e4."]}}},1797,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"items",{enumerable:!0,get:function(){return t}});const t={"item:demon-soul":{title:"\uc6a9\uc758 \uc601\ud63c (\uc545\ub9c8\uc758 \uc601\ud63c)",summary:"\ubaa8\ub4e0 \uc6a9\uc744 \uc9c0\ubc30\ud558\ub824\uace0 \ub12c\ud0c0\ub9ac\uc628\uc774 \ub9cc\ub4e0 \ud669\uae08 \uc6d0\ubc18. \ub370\uc2a4\uc719\uc744 \ud0c4\uc0dd\uc2dc\ucf30\uace0, \uc624\ub79c \uc138\uc6d4\uc774 \ud750\ub978 \ub4a4\uc5d0\ub294 \ubd89\uc740\uc6a9\uad70\ub2e8\uc744 \ud638\ub4dc\uc5d0 \ubb36\uc5b4 \ub450\uc5c8\ub2e4.",body:["\uace0\ub300\uc758 \uc804\uc7c1 \uc774\uc804\uc5d0 \ub300\uc9c0\uc758 \uc218\ud638\uc790 \ub12c\ud0c0\ub9ac\uc628\uc740 \uace0\ube14\ub9b0 \ud558\uc218\uc778\ub4e4\uc744 \uc2dc\ucf1c \ud3c9\ubc94\ud574 \ubcf4\uc774\ub294 \ud669\uae08 \uc6d0\ubc18\uc744 \ub9cc\ub4e4\uac8c \ud588\ub294\ub370, \uadf8 \uc6d0\ubc18\uc5d0\ub294 \uace0\ub300 \uc2e0\uc758 \ud0c0\ub77d\uc774 \uc740\ubc00\ud788 \uc2a4\uba70 \uc788\uc5c8\ub2e4. \uadf8\ub294 \ubd88\ud0c0\ub294 \uad70\ub2e8\uacfc \uc2f8\uc6b0\uae30 \uc704\ud574 \ub2e4\ub978 \uc704\uc0c1\ub4e4\uc744 \uc124\ub4dd\ud574 \uadf8\ub4e4\uc758 \ud798 \uc77c\ubd80\ub97c \uc6d0\ubc18\uc5d0 \uc3df\uc544\ubd93\uac8c \ud55c \ub4a4, \uadf8\uac83\uc744 \uc545\ub9c8\uc640 \ub3d9\ub9f9 \ubaa8\ub450\uc5d0\uac8c \uaca8\ub204\uc5c8\ub2e4. \uc6a9\uc758 \uc601\ud63c\uc758 \ud798\uc740 \uadf8\uc758 \ubab8\uc744 \uac08\uac00\ub9ac \ucc22\uc5c8\uace0, \ub12c\ud0c0\ub9ac\uc628\uc740 \ub370\uc2a4\uc719\uc774 \ub418\uc5c8\ub2e4.","\uc138\uacc4\uc758 \ubd84\ub9ac \uc774\ud6c4 \uc704\uc0c1\ub4e4\uc740 \uc6d0\ubc18\uc744 \uc9c0\uae08\uc758 \ubd89\uc740\ub9c8\ub8e8 \uc0b0\ub9e5 \uae4a\uc740 \uacf3\uc5d0 \uc228\uacbc\ub2e4. \ub370\uc2a4\uc719\uc758 \ud658\uc601\uc744 \ub530\ub77c \uc6a9\uc544\uadc0 \ubd80\uc871\uc774 \uc6d0\ubc18\uc744 \ub418\ucc3e\uc544 \uc545\ub9c8\uc758 \uc601\ud63c\uc774\ub77c \uc774\ub984 \ubd99\uc774\uace0, \uadf8\ub9bc \ubc14\ud1a8\uc5d0\uc11c \uc54c\ub809\uc2a4\ud2b8\ub77c\uc790\ub97c \ub178\uc608\ub85c \uc0bc\ub294 \ub370 \uc37c\ub2e4. \uc6d0\ubc18\uc740 \uacb0\uad6d \uadf8\uacf3\uc5d0\uc11c \uc0b0\uc0b0\uc774 \ubd80\uc11c\uc84c\uace0, \ubd89\uc740 \uc6a9\ub4e4\uc740 \uc790\uc720\ub97c \ub418\ucc3e\uc558\ub2e4."]},"item:atiesh":{title:"Atiesh, Greatstaff of the Guardian",summary:"\ud2f0\ub9ac\uc2a4\ud314 \uc218\ud638\uc790\ub4e4\uc758 \uc9c0\ud321\uc774\ub85c, \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uba54\ub514\ube0c\uac00 \uc9c0\ub154\uc73c\uba70 \uc774\ud6c4 \ubd80\uc11c\uc838 \ucf08\ud22c\uc790\ub4dc\uac00 \uadf8 \uc870\uac01\uc744 \ucc3e\uc544 \ub098\uc130\ub2e4.",body:["\uc544\ud2f0\uc26c\ub294 \uc5ec\ub7ec \uc138\ub300\uc5d0 \uac78\uccd0 \uc218\ud638\uc790\uc5d0\uc11c \uc218\ud638\uc790\ub85c \uc804\ud574\uc84c\uace0, \ub9c8\uc9c0\ub9c9 \uc218\ud638\uc790 \uba54\ub514\ube0c\uc5d0\uac8c\uc11c \uadf8 \uc5ec\uc815\uc744 \ub05d\ub0c8\ub2e4. \uc804\uc124\uc5d0 \ub530\ub974\uba74 \uc774 \uc9c0\ud321\uc774\ub294 '\uc99d\uc624\uc758 \uc528\uc557'\uc5d0\uc11c \uc790\ub77c\ub0ac\uc73c\uba70 \uc18c\uc720\uc790\uc5d0\uac8c \ub05d\uc5c6\ub294 \ud798\uc744 \uc900\ub2e4\uace0 \ud55c\ub2e4. \uc9c0\ud321\uc774 \uc8fc\uc704\uc5d0\ub294 \uae4c\ub9c8\uadc0\ub4e4\uc774 \ubaa8\uc5ec\ub4e4\uace0, \uce74\ub77c\uc794\uc73c\ub85c \uac00\ub294 \uae38\uc744 \uc5f4 \uc218\ub3c4 \uc788\ub2e4. \uba54\ub514\ube0c\uac00 \ubab0\ub77d\ud55c \ub4a4 \ud0a4\ub9b0 \ud1a0\ub294 \uc9c0\ud321\uc774\ub97c \ub2ec\ub77c\ub780\uc5d0 \ubd09\uc778\ud588\ub294\ub370, \uadf8\uac83\uc744 \ub9cc\uc9c4 \ub9c8\ubc95\uc0ac\ub4e4\uc740 \ud558\ub098\uac19\uc774 \ube44\ucc38\ud55c \ucd5c\ud6c4\ub97c \ub9de\uc558\ub2e4.","\uc544\ud0a4\ubaac\ub4dc\uac00 \ub2ec\ub77c\ub780\uc744 \ud30c\uad34\ud588\uc744 \ub54c \uc544\ud2f0\uc26c\ub294 \uc218\uc2ed \uc870\uac01\uc73c\ub85c \ubd80\uc11c\uc838 \uc544\uc81c\ub85c\uc2a4 \uacf3\uacf3\uc73c\ub85c \ud769\uc5b4\uc84c\uace0, \ucf08\ud22c\uc790\ub4dc\uac00 \uadf8 \uc870\uac01\ub4e4\uc744 \ubaa8\uc73c\uae30 \uc2dc\uc791\ud588\ub2e4. \uc624\ub9ac\uc9c0\ub110 \uac8c\uc784\uc5d0\uc11c \uacf5\uaca9\ub300\ub294 \uadf8\uc758 \ub124\ud06c\ub85c\ud3f4\ub9ac\uc2a4 \ub099\uc2a4\ub77c\ub9c8\uc2a4\uc5d0\uc11c \uc870\uac01\ub4e4\uc744 \ube7c\uc557\uace0, \uccad\ub3d9\uc6a9 \uc544\ub098\ud06c\ub85c\ub178\uc2a4\uc758 \ub3c4\uc6c0\uc73c\ub85c \uc9c0\ud321\uc774\uc758 \ud2c0\uc744 \ubcf5\uc6d0\ud55c \ub4a4, \uc2a4\ud2b8\ub77c\uc194\ub984\uc5d0\uc11c \uc9c0\ud321\uc774 \uc548\uc5d0 \uac07\ud78c \uc545\ub9c8\ub97c \ubb3c\ub9ac\uccd0 \uc9c0\ud321\uc774\ub97c \uc815\ud654\ud574\uc57c \ud588\ub2e4."]},"item:scepter-of-the-shifting-sands":{title:"\ud750\ub974\ub294 \ubaa8\ub798\uc758 \ud640",summary:"\uc548\ud034\ub77c\uc988\ub97c \ubd09\uc778\ud55c \uc2a4\uce74\ub77c\ubca0 \uc131\ubcbd\uc758 \uc5f4\uc1e0\ub85c, \uc2ac\ud514\uc5d0 \uc7a0\uae34 \ud310\ub4dc\ub784 \uc2a4\ud0dc\uadf8\ud5ec\ub984\uc774 \ubd80\uc234 \ubc84\ub838\ub2e4.",body:["\uc81c1\ucc28 \ub300\uc804\uc7c1\ubcf4\ub2e4 \uac70\uc758 \ucc9c \ub144 \uc804, \uace4\ucda9\uc744 \ub2ee\uc740 \ud034\ub77c\uc9c0\uac00 \uace0\ub300 \uc2e0 \ud06c\ud230\uc758 \ubd80\ucd94\uae40\uc744 \ubc1b\uc544 \uc548\ud034\ub77c\uc988\uc5d0\uc11c \uc3df\uc544\uc838 \ub098\uc654\ub2e4. \ub300\ub4dc\ub8e8\uc774\ub4dc \ud310\ub4dc\ub784 \uc2a4\ud0dc\uadf8\ud5ec\ub984\uc774 \ub098\uc774\ud2b8 \uc5d8\ud504\ub97c \uc774\ub04c\uace0 \ub9de\uc130\uc9c0\ub9cc, \uadf8\uc758 \uc544\ub4e4 \ubc1c\uc2a4\ud0c4\uc774 \ub208\uc55e\uc5d0\uc11c \uc4f0\ub7ec\uc9c0\uc790 \uc804\uc138\uac00 \ub4a4\uc9d1\ud614\ub2e4. \ub124 \uc6a9\uad70\ub2e8\uc758 \ub3c4\uc6c0\uc744 \ubc1b\uace0\uc11c\uc57c \ube44\ub85c\uc18c \ubc8c\ub808 \ub5bc\ub97c \ubab0\uc544\ub0b4 \uc2a4\uce74\ub77c\ubca0 \uc131\ubcbd \ub4a4\uc5d0 \uac00\ub458 \uc218 \uc788\uc5c8\ub2e4.","\uc131\ubcbd\uc740 \uc774 \ud640\ub85c \uc2a4\uce74\ub77c\ubca0 \uc9d5\uc744 \uc6b8\ub824\uc57c\ub9cc \uc5f4 \uc218 \uc788\uc5c8\ub2e4. \ud310\ub4dc\ub784\uc740 \uc2ac\ud514\uc5d0\uc11c \ube44\ub86f\ub41c \ubd84\ub178\ub85c \ud640\uc744 \ubd80\uc234 \ubc84\ub838\uace0, \uadf8 \uc870\uac01\ub4e4\uc740 \ud769\uc5b4\uc84c\ub2e4. \uc624\ub9ac\uc9c0\ub110 \uac8c\uc784\uc5d0\uc11c \ubaa8\ud5d8\uac00\ub4e4\uc740 \ud640\uc744 \ub2e4\uc2dc \ub9de\ucd94\uace0 \uc9d5\uc744 \uc6b8\ub824 \uc548\ud034\ub77c\uc988\ub97c \ub2e4\uc2dc \uc5f4\uc5c8\ub2e4."]},"item:doomhammer":{title:"\ud30c\uba78\uc758 \ub9dd\uce58",summary:"\ub460\ud574\uba38 \uac00\ubb38\uc5d0 \ub300\ub300\ub85c \uc804\ud574\uc9c4 \uc804\ud22c \ub9dd\uce58\ub85c, \uc624\uadf8\ub9bc\uc774 \ub450 \ubc88\uc758 \uc804\uc7c1 \ub0b4\ub0b4 \ud718\ub450\ub974\ub2e4 \uc2a4\ub784\uc5d0\uac8c \ubb3c\ub824\uc8fc\uc5c8\ub2e4.",body:["\uc624\ub798\uc804 \ub4dc\ub808\ub178\uc5b4\uc5d0\uc11c \ubcbc\ub824\uc9c4 \uac80\uc740 \ub3cc\uc758 \uac70\ub300\ud55c \ub9dd\uce58\ub294 \ud55c \uc624\ud06c \uac00\ubb38 \uc548\uc5d0\uc11c \uc544\ubc84\uc9c0\uc5d0\uac8c\uc11c \uc544\ub4e4\ub85c \uc804\ud574\uc84c\uace0, \uadf8 \uc704\uc5d0\ub294 \uac80\uc740\ubc14\uc704\uc758 \uc624\ub79c \uc608\uc5b8\uc774 \ub4dc\ub9ac\uc6cc \uc788\uc5c8\ub2e4. \uac00\ubb38\uc758 \ub9c8\uc9c0\ub9c9 \ud6c4\uc190\uc774 \uc624\ud06c\ub4e4\uc5d0\uac8c \uba3c\uc800 \uad6c\uc6d0\uc744, \uadf8\ub2e4\uc74c\uc5d0\ub294 \ud30c\uba78\uc744 \uac00\uc838\uc62c \uac83\uc774\uba70, \uadf8 \ub4a4\uc5d0 \ud55c \uc774\ubc29\uc778\uc774 \uc815\uc758\ub97c \uc704\ud574 \ub9dd\uce58\ub97c \ub4e4\uc5b4 \uc62c\ub9ac\ub9ac\ub77c\ub294 \uac83\uc774\uc5c8\ub2e4. \uc624\uadf8\ub9bc \ub460\ud574\uba38\ub294 \uc81c1\ucc28\uc640 \uc81c2\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \uc774 \ub9dd\uce58\ub97c \ud718\ub458\ub800\uace0, \uadf8\uac83\uc73c\ub85c \uc548\ub450\uc778 \ub85c\uc11c\ub97c \uc4f0\ub7ec\ub728\ub9ac\uba70 \uae30\uc0ac\uc758 \ub8ec\uac80\uc744 \ubd80\uc234 \ubc84\ub838\ub2e4.","\ud638\ub4dc\uac00 \ud328\ubc30\ud55c \ub4a4 \uc624\uadf8\ub9bc\uc740 \ud3ec\ub85c \uc0dd\ud65c\uc5d0\uc11c \ud0c8\ucd9c\ud574 \uc218\uc6a9\uc18c\uc5d0 \uac07\ud78c \ub3d9\uc871\uc744 \ud574\ubc29\ud558\ub824\uace0 \uc2f8\uc6e0\ub2e4. \uadf8 \uc804\ud22c \uac00\uc6b4\ub370 \ud558\ub098\uc5d0\uc11c \uce58\uba85\uc0c1\uc744 \uc785\uc740 \uadf8\ub294 \uc790\uc2e0\uc758 \ubd80\uc871\ub3c4 \ud608\ud1b5\ub3c4 \uc544\ub2cc \uc2a4\ub784\uc5d0\uac8c \ub9dd\uce58\ub97c \uac74\ub138\ub2e4. \uc2a4\ub784\uc740 \ub2e4\uc2dc \ud0dc\uc5b4\ub09c \ud638\ub4dc\uc758 \uc0c1\uc9d5\uc73c\ub85c \uadf8 \ub9dd\uce58\ub97c \uc9c0\ub154\uace0, \uc608\uc5b8\uc740 \uadf8\ub807\uac8c \uc774\ubc29\uc778\uc744 \ucc3e\uc544\ub0c8\ub2e4."]},"item:book-of-medivh":{title:"\uba54\ub514\ube0c\uc758 \ucc45",summary:"\uba54\ub514\ube0c\uac00 \ub0a8\uae34 \ub9c8\uc9c0\ub9c9 \uc8fc\ubb38\uc11c\ub85c, \ub450 \ubc88\uc774\ub098 \uc138\uacc4\uc640 \uc138\uacc4 \uc0ac\uc774\uc758 \uae38\uc744 \ucc22\uc5b4 \uc5ec\ub294 \ub370 \uc4f0\uc600\ub2e4.",body:["\uba54\ub514\ube0c\uac00 \uc8fd\uc740 \ub4a4 \uadf8\uc758 \uc8fc\ubb38\uc11c\ub294 \uc7ac\uac74\ub41c \uc2a4\ud1b0\uc708\ub4dc\uc758 \uc655\uc2e4 \ub3c4\uc11c\uad00\uc5d0 \ubcf4\uad00\ub418\uc5c8\uc73c\ub098, \uc54c\ud130\ub799\uc758 \ucca9\uc790\ub4e4\uc774 \uadf8\uac83\uc744 \ud6d4\uccd0 \uac14\ub2e4. \uc54c\ud130\ub799 \uad6d\uc655\uacfc \ud638\ub4dc\uc758 \uc8fd\uc74c\uc758 \uae30\uc0ac \ud14c\ub860 \uace0\uc5b4\ud540\ub4dc \uc0ac\uc774\uc758 \uac70\ub798\ub85c \ucc45\uc740 \uc624\ud06c\ub4e4\uc5d0\uac8c \ub118\uc5b4\uac14\uace0, \ub4dc\ub808\ub178\uc5b4\uc5d0\uc11c \ub12c\uc974\uc740 \ub2e4\ub978 \uc720\ubb3c\ub4e4\uacfc \ud568\uaed8 \uc774 \ucc45\uc73c\ub85c \uc0c8\ub85c\uc6b4 \ucc28\uc6d0\ubb38\uc744 \uc5f4\uc5c8\ub2e4. \uadf8 \uade0\uc5f4\uc740 \uadf8\uc758 \uc138\uacc4\ub97c \uac08\uac00\ub9ac \ucc22\uc5b4 \ub193\uc558\ub2e4. \uc5b4\ub460\uc758 \ubb38\uc774 \ubb34\ub108\uc9c0\uae30 \uc804\uc5d0 \uce74\ub4dc\uac00\uac00 \ucc45\uc744 \ub418\ucc3e\uc544 \uadf8\ub9ac\ud3f0\uc5d0 \uc2e4\uc5b4 \uace0\ud5a5\uc73c\ub85c \ubcf4\ub0c8\ub2e4.","\ud0a4\ub9b0 \ud1a0\ub294 \ucc45\uc744 \ub2ec\ub77c\ub780\uc758 \uae08\uace0\uc5d0 \ubd09\uc778\ud588\ub2e4. \uc81c3\ucc28 \ub300\uc804\uc7c1 \uc911 \ucf08\ud22c\uc790\ub4dc\ub294 \uadf8 \uae08\uace0\ub97c \ubd80\uc218\uace0, \ucc45\uc758 \ud798\uc73c\ub85c \uc544\ud0a4\ubaac\ub4dc\uc640 \ubd88\ud0c0\ub294 \uad70\ub2e8\uc774 \uc544\uc81c\ub85c\uc2a4\ub85c \ub4e4\uc5b4\uc62c \uade0\uc5f4\uc744 \uc5f4\uc5c8\ub2e4. \uadf8 \ub4a4\ub85c \ucc45\uc740 \ub9ac\uce58\uc758 \uc190\uc5d0 \ub0a8\uc558\ub2e4."]},"item:frostmourne":{title:"\uc11c\ub9ac\ud55c",summary:"\ub178\uc2a4\ub80c\ub4dc\uc758 \uc5bc\uc74c \uc18d\uc5d0\uc11c \uc544\uc11c\uc2a4 \uba54\ub124\uc2e4\uc758 \uc601\ud63c\uc744 \uc557\uc544 \uac04 \ub9ac\uce58 \uc655\uc758 \ub8ec\uac80.",body:["\uc11c\ub9ac\ud55c\uc740 \uc5bc\uc74c\uc655\uad00\uc5d0 \uc788\ub294 \ub9ac\uce58 \uc655\uc758 \uac10\uc625\uacfc \ubb36\uc5ec \uc788\uc5c8\uace0, \ub12c\uc974\uc740 \uc6a9\uc0ac\ub97c \uaf80\uc5b4\ub0b4\ub824\uace0 \uc774 \uac80\uc744 \uc5bc\uc5b4\ubd99\uc740 \uc655\uc88c \ubc16\uc73c\ub85c \ubc00\uc5b4\ub0c8\ub2e4. \uac80\uc740 \ub178\uc2a4\ub80c\ub4dc\uc758 \uc5bc\uc5b4\ubd99\uc740 \ub3d9\uad74\uc5d0\uc11c \uc218\ud638\ub97c \ubc1b\uc73c\uba70 \uae30\ub2e4\ub9ac\uace0 \uc788\uc5c8\uace0, \uadf8\uac83\uc744 \uc9d1\uc5b4 \ub4dc\ub294 \uc790\uc758 \uc601\ud63c\uc5d0 \uc0c1\ucc98\ub97c \ub0a8\uae30\ub9ac\ub77c\ub294 \uacbd\uace0\uac00 \uc0c8\uaca8\uc838 \uc788\uc5c8\ub2e4. \uc5ed\ubcd1\uc744 \ub9c9\uc73c\ub824 \uc808\ubc15\ud588\ub358 \uc544\uc11c\uc2a4 \uc655\uc790\ub294 \uacbd\uace0\ub97c \ubb34\uc2dc\ud558\uace0, \uc5bc\uc74c \ud30c\ud3b8\uc5d0 \ub9de\uc544 \uc4f0\ub7ec\uc9c4 \ubb34\ub77c\ub518 \ube0c\ub860\uc988\ube44\uc5b4\ub4dc\ub97c \ub4a4\ub85c\ud55c \ucc44 \uac80\uc744 \uc6c0\ucf1c\uc950\uc5c8\ub2e4.","\uc774 \uac80\uc740 \uc790\uc2e0\uc774 \ubca4 \uc790\ub4e4\uc758 \uc601\ud63c\uc744 \uc9d1\uc5b4\uc0bc\ud0a8\ub2e4. \uc544\uc11c\uc2a4\ub294 \uc774 \uac80\uc73c\ub85c \uacf5\ud3ec\uc758 \uad70\uc8fc \ub9d0\uac00\ub2c8\uc2a4\ub97c \uc8fd\uc774\uace0, \uc774\uc5b4 \uc544\ubc84\uc9c0 \ud14c\ub808\ub098\uc2a4 \uad6d\uc655\uacfc \uc61b \uc2a4\uc2b9 \uc6b0\uc11c\uae4c\uc9c0 \uc8fd\uc600\ub2e4. 25\ub144\uc5d0 \uac80\uc740 \ub9ac\uce58 \uc655 \ubc14\ub85c \uacc1\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ud074\ub798\uc2dd \uc774\ud6c4\uc758 \uc774\uc57c\uae30\uc5d0\uc11c\ub294 \ud2f0\ub9ac\uc628 \ud3f4\ub4dc\ub9c1\uc774 \ud30c\uba78\uc758 \uc778\ub3c4\uc790\ub85c \uc774 \uac80\uc744 \ubd80\uc21c\ub2e4."]},"item:ashbringer":{title:"\ud30c\uba78\uc758 \uc778\ub3c4\uc790",summary:"\uc5b8\ub370\ub4dc\ub97c \uc7ac\ub85c \ub9cc\ub4e4\ub824\uace0 \uc544\uc774\uc5b8\ud3ec\uc9c0\uc5d0\uc11c \ubcbc\ub9b0 \uc131\uac80\uc73c\ub85c, \uc774\ud6c4 \ubc30\uc2e0\ub2f9\ud574 \uc5ed\ubcd1\uc9c0\ub300\uc5d0\uc11c \ud0c0\ub77d\ud588\ub2e4.",body:["\uc81c2\ucc28 \ub300\uc804\uc7c1 \uc911 \ubc31\uc740\uc758 \uc190\uc758 \ub300\uc601\uc8fc \uc54c\ub809\uc0b0\ub4dc\ub85c\uc2a4 \ubaa8\uadf8\ub808\uc778\uc740 \uc4f0\ub7ec\uc9c4 \uc624\ud06c \ud751\ub9c8\ubc95\uc0ac\uc5d0\uac8c\uc11c \uac80\uc740 \uc218\uc815\uc744 \ubc1c\uacac\ud588\ub2e4. \uc2a4\uceec\uc9c0\uac00 \ub85c\ub370\ub860\uc744 \uc704\ud611\ud558\uc790 \uae30\uc0ac\ub2e8 \uc9c0\ub3c4\uc790\ub4e4\uc740 \uc2e0\uc131\ud55c \ub9c8\ubc95\uc73c\ub85c \uc218\uc815\uc744 \ud30c\uad34\ud558\ub824 \ud588\uc9c0\ub9cc, \uc218\uc815\uc740 \uc624\ud788\ub824 \ube5b\uc744 \ube68\uc544\ub4e4\uc5ec \ucc2c\ub780\ud558\uac8c \ube5b\ub098\uae30 \uc2dc\uc791\ud588\ub2e4. \ub9c8\uadf8\ub2c8 \ube0c\ub860\uc988\ube44\uc5b4\ub4dc \uc655\uc740 \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \uac70\ub300\ud55c \ubaa8\ub8e8\uc5d0\uc11c \uadf8 \uc218\uc815\uc744 \uac80\uc73c\ub85c \ubcbc\ub838\uace0, \ubaa8\uadf8\ub808\uc778\uc758 \uc190\uc5d0\uc11c \ud30c\uba78\uc758 \uc778\ub3c4\uc790\ub294 \uc5b8\ub370\ub4dc\ub97c \uc7ac\ub85c \ub9cc\ub4e4\uc5c8\ub2e4.","\uacf5\ud3ec\uc758 \uad70\uc8fc \ubc1c\ub098\uc790\ub974\uc640 \ucf08\ud22c\uc790\ub4dc\ub294 \uadf8\uc758 \ubab0\ub77d\uc744 \uafb8\uba84\ub2e4. \ubaa8\uadf8\ub808\uc778\uc758 \uc544\ub4e4 \ub974\ub178\ub294 \uadf8\ub97c \uc2a4\ud2b8\ub77c\uc194\ub984\uc758 \uc2a4\uceec\uc9c0 \ub9e4\ubcf5\uc73c\ub85c \uc774\ub04c\uc5b4 \uadf8\uc758 \uac80\uc73c\ub85c \uadf8\ub97c \uc8fd\uc600\uace0, \uadf8\ub85c \uc778\ud574 \uac80\uc740 \ud0c0\ub77d\ud588\ub2e4. 25\ub144\uc5d0 \uc54c\ub809\uc0b0\ub4dc\ub85c\uc2a4\ub294 \uc8fd\uc74c\uc758 \uae30\uc0ac\ub85c\uc11c \ucf08\ud22c\uc790\ub4dc\ub97c \uc12c\uae30\uace0, \ub974\ub178\ub294 \ubd89\uc740\uc2ed\uc790\uad70 \uc218\ub3c4\uc6d0\uc744 \uc9c0\ud718\ud55c\ub2e4. \uac80\uc740 \ud6d7\ub0a0\uc758 \uc774\uc57c\uae30\uc5d0\uc11c\uc57c \uc815\ud654\ub41c\ub2e4."]},"item:skull-of-guldan":{title:"\uad74\ub2e8\uc758 \ud574\uace8",summary:"\ucc28\uc6d0\ubb38\uc744 \uc5f4\uace0, \uc7bf\ube5b \uace8\uc9dc\uae30\ub97c \uc624\uc5fc\uc2dc\ud0a4\uace0, \uc77c\ub9ac\ub2e8\uc744 \ud0c8\ubc14\uafc8\uc2dc\ud0a8 \ud751\ub9c8\ubc95\uc0ac\uc758 \ud574\uace8\uc774\uc790 \uc545\ub9c8\uc758 \uc720\ubb3c.",body:["\uad74\ub2e8\uc740 \uc0b4\uac8c\ub77c\uc2a4\uc758 \ubb34\ub364\uc5d0\uc11c \uc545\ub9c8\ub4e4\uc5d0\uac8c \uac08\uac00\ub9ac \ucc22\uacbc\uc9c0\ub9cc, \uadf8\uc758 \ud574\uace8\uc5d0\ub294 \uadf8\uc758 \uc545\uc758\uac00 \ud55c \uc870\uac01 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \ud574\uace8\uc740 \uc5ec\ub7ec \uc624\ud06c\uc758 \uc190\uc744 \uac70\uccd0 \uadf8\ub86c \ud5ec\uc2a4\ud06c\ub9bc\uc774 \ub12c\uc974\uc5d0\uac8c \uac00\uc838\uac14\uace0, \ub12c\uc974\uc740 \uadf8 \ud798\uc73c\ub85c \uc5b4\ub460\uc758 \ubb38\uc744 \ub2e4\uc2dc \uc5ec\ub294 \ub370 \ub3c4\uc6c0\uc744 \ubc1b\uc558\ub2e4. \ud6d7\ub0a0 \uce74\ub4dc\uac00\ub294 \uba54\ub514\ube0c\uc758 \ucc45\uacfc \ud568\uaed8 \ud574\uace8\uc744 \ub2ec\ub77c\ub780\uc73c\ub85c \ubcf4\ub0c8\uace0, \ud0a4\ub9b0 \ud1a0\uac00 \ub458\uc744 \uc9c0\ucf30\ub2e4.","\uc81c3\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \ub2ec\ub77c\ub780\uc774 \ud568\ub77d\ub418\uc790 \uacf5\ud3ec\uc758 \uad70\uc8fc \ud2f0\ucf58\ub4dc\ub9ac\uc6b0\uc2a4\uac00 \ud574\uace8\uc744 \ud6d4\ucce4\uace0, \uadf8 \ud798\uc774 \uc7bf\ube5b \uace8\uc9dc\uae30\uc640 \uc545\ub839\uc758 \uc232\uc744 \ub354\ub7fd\ud614\ub2e4. \uc77c\ub9ac\ub2e8 \uc2a4\ud1b0\ub808\uc774\uc9c0\ub294 \ud574\uace8\uc758 \ub9c8\ub825\uc744 \uc9d1\uc5b4\uc0bc\ucf1c \ubc18\uc740 \uc545\ub9c8\uac00 \ub418\uc5c8\uace0, \uadf8 \ud798\uc73c\ub85c \ud2f0\ucf58\ub4dc\ub9ac\uc6b0\uc2a4\ub97c \uc8fd\uc600\ub2e4. \ud574\uace8\uc758 \uaecd\ub370\uae30\ub294 \uc77c\ub9ac\ub2e8\uc5d0\uac8c \ub0a8\uc558\ub2e4."]},"item:gorehowl":{title:"\ud53c\uc6b8\uc74c",summary:"\uc138\ub098\ub9ac\uc6b0\uc2a4\uc640 \ub9cc\ub178\ub85c\uc2a4\ub97c \ubaa8\ub450 \uc4f0\ub7ec\ub728\ub9b0 \ud5ec\uc2a4\ud06c\ub9bc \uac00\ubb38\uc758 \uc6b8\ubd80\uc9d6\ub294 \ub3c4\ub07c.",body:["\ud53c\uc6b8\uc74c\uc740 \uadf8\ub86c \ud5ec\uc2a4\ud06c\ub9bc\uc774 \ubb3c\ub824\ubc1b\uae30 \uc5ec\ub7ec \uc138\ub300 \uc804\uc5d0 \ubcbc\ub824\uc84c\uc73c\uba70, \uc804\uc7c1\ub178\ub798\uc758 \uc804\uc124\uc5d0 \ub530\ub974\uba74 \uac15\ub825\ud55c \uadf8\ub860\ub4e4\uc758 \uc2ec\uc7a5\uc73c\ub85c \ub2f4\uae08\uc9c8\ud588\ub2e4\uace0 \ud55c\ub2e4. \uc804\uc7c1\ub178\ub798 \ubd80\uc871\uc758 \uc871\uc7a5 \uadf8\ub86c\uc740 \uad6c\ub369\uc774 \uad70\uc8fc \ub9cc\ub178\ub85c\uc2a4\uc758 \ud53c\ub97c \uac00\uc7a5 \uba3c\uc800 \ub9c8\uc154 \uc624\ud06c\ub4e4\uc744 \ubd88\ud0c0\ub294 \uad70\ub2e8\uc5d0 \ubb36\uc5b4 \ubc84\ub838\ub2e4. \uc7bf\ube5b \uace8\uc9dc\uae30\uc5d0\uc11c \uadf8\ub294 \ub2e4\uc2dc \uadf8 \ud53c\ub97c \ub9c8\uc168\uace0, \ud53c\uc6b8\uc74c\uc73c\ub85c \ubc18\uc2e0 \uc138\ub098\ub9ac\uc6b0\uc2a4\ub97c \uc8fd\uc600\ub2e4.","\uc2a4\ub784\uc774 \uadf8\ub97c \uc545\ub9c8\uc758 \uc190\uc544\uadc0\uc5d0\uc11c \ud480\uc5b4 \uc8fc\uc5c8\uace0, \ub450 \uc0ac\ub78c\uc740 \ud568\uaed8 \ub9cc\ub178\ub85c\uc2a4\uc5d0\uac8c \ub9de\uc130\ub2e4. \uadf8\ub86c\uc740 \uad6c\ub369\uc774 \uad70\uc8fc\uc758 \ubb34\uae30\ub97c \ucabc\uac1c\uace0 \ub2e8 \ud55c \ubc88\uc758 \uc77c\uaca9\uc73c\ub85c \uadf8\ub97c \uc8fd\uc5ec, \uc790\uc2e0\uc758 \ubaa9\uc228\uc744 \ub300\uac00\ub85c \ub3d9\uc871\uc5d0\uac8c \ub0b4\ub9b0 \uc800\uc8fc\ub97c \ub04a\uc5c8\ub2e4. \uadf8 \ub4a4 \uc2a4\ub784\uc740 \ub3c4\ub07c\ub97c \uc624\uadf8\ub9ac\ub9c8\uc5d0 \uac04\uc9c1\ud588\ub2e4."]},"item:horn-of-cenarius":{title:"\uc138\ub098\ub9ac\uc6b0\uc2a4\uc758 \ubfd4\ud53c\ub9ac",summary:"\ub4dc\ub8e8\uc774\ub4dc\ub4e4\uc744 \uae34 \uc7a0\uc5d0\uc11c \uae68\uc6b0\uace0 \ud558\uc774\uc798\uc5d0\uc11c \ub098\uc774\ud2b8 \uc5d8\ud504 \uc870\uc0c1\ub4e4\uc744 \ubd88\ub7ec\ub0b8 \ubc18\uc2e0\uc758 \ubfd4\ud53c\ub9ac.",body:["\uc138\ub098\ub9ac\uc6b0\uc2a4\uac00 \uc4f0\ub7ec\uc9c4 \ub4a4 \uadf8\uc758 \ubfd4\ud53c\ub9ac\ub294 \uace0\ub300 \uc218\ud638\uc790\ub4e4\uc758 \uac10\uc2dc \uc544\ub798 \ub2ec\uc758 \uc232\uc5d0 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uc81c3\ucc28 \ub300\uc804\uc7c1\uc5d0\uc11c \ubd88\ud0c0\ub294 \uad70\ub2e8\uc774 \ub3cc\uc544\uc624\uc790, \uc5ec\uc0ac\uc81c \ud2f0\ub780\ub370 \uc704\uc2a4\ud37c\uc708\ub4dc\uac00 \ubfd4\ud53c\ub9ac\ub97c \ub418\ucc3e\uc544 \uae34 \uafc8\uc5d0 \ube60\uc9c4 \ub9d0\ud4e8\ub9ac\uc628 \uc2a4\ud1b0\ub808\uc774\uc9c0\ub97c \uae68\uc6e0\ub2e4. \ub9d0\ud4e8\ub9ac\uc628\uc740 \uc774\uc5b4\uc11c \ubfd4\ud53c\ub9ac\ub97c \ubd88\uc5b4 \uc7a0\ub4e4\uc5b4 \uc788\ub358 \uac08\ud034\ubc1c\ud1b1\uacfc \ubc1c\ud1b1\uc758 \ub4dc\ub8e8\uc774\ub4dc\ub4e4\uc744 \uae68\uc6e0\ub2e4.","\ud558\uc774\uc798 \uc0b0 \uc804\ud22c\uac00 \uc808\uc815\uc5d0 \uc774\ub974\ub800\uc744 \ub54c, \ub9d0\ud4e8\ub9ac\uc628\uc740 \ub2e4\uc2dc \ud55c\ubc88 \ubfd4\ud53c\ub9ac\ub97c \ubd88\uc5c8\ub2e4. \uc218\ucc9c\uc758 \uc870\uc0c1 \uc601\ud63c\uc774 \uc751\ub2f5\ud574 \uc544\ud0a4\ubaac\ub4dc\uc5d0\uac8c \ubab0\ub824\ub4e4\uc5c8\uace0, \uc138\uacc4\uc218 \ubc1c\uce58\uc5d0\uc11c \uc545\ub9c8 \uad70\uc8fc\ub97c \uc18c\uba78\uc2dc\ucf30\ub2e4. \ub2e4\ub9cc \uadf8\ub54c \ud480\ub824\ub09c \ud798\uc740 \ub180\ub4dc\ub78f\uc2e4\uc5d0 \uc0c1\ucc98\ub97c \ub0a8\uacbc\ub2e4."]},"item:sulfuras":{title:"\uc124\ud37c\ub77c\uc2a4 - \ub77c\uadf8\ub098\ub85c\uc2a4\uc758 \uc190",summary:"\ubd88\uc758 \uad70\uc8fc\uc758 \ubd88\ud0c0\ub294 \ub9dd\uce58, \uadf8\ub9ac\uace0 \uc7a5\uc778 \ub300\uc7a5\uc7a5\uc774\ub4e4\uc774 \uadf8 \ubaa8\uc2b5\uc744 \ubcf8\ub5a0 \ubcbc\ub9ac\ub294 \ubc95\uc744 \uc775\ud78c \uc791\uc740 \ubcf5\uc81c\ud488.",body:["\uc124\ud37c\ub77c\uc2a4\ub294 \ub77c\uadf8\ub098\ub85c\uc2a4\uc758 \uac70\ub300\ud55c \ub9dd\uce58\ub85c, \ubd88\uc758 \uad70\uc8fc\uac00 \uacb0\ucf54 \uc190\uc5d0\uc11c \ub193\uc9c0 \uc54a\ub294 \ubd88\ud0c0\ub294 \ubd89\uc740 \uc5d8\ub808\uba58\ud2f0\uc6c0 \ub369\uc5b4\ub9ac\ub2e4. \uc544\ub4dd\ud55c \uc61b\ub0a0 \uc815\ub839\ub4e4\uc758 \uc804\uc7c1\uc5d0\uc11c \uadf8\ub294 \uc774 \ub9dd\uce58\ub85c \ubc14\ub78c\uc758 \uc655\uc790 \uc36c\ub354\ub780\uc744 \uc4f0\ub7ec\ub728\ub838\ub2e4. \ud0c0\uc6b0\ub9bf\uc0b0\uc758 \uc18c\ud658 \uc774\ud6c4 \ub77c\uadf8\ub098\ub85c\uc2a4\ub294 \ub9dd\uce58\ub97c \uc190\uc5d0 \uc950\uace0 \uac80\uc740\ubc14\uc704 \uc0b0 \uc544\ub798 \ud654\uc0b0 \uc2ec\uc7a5\ubd80\ub97c \ub2e4\uc2a4\ub9ac\uace0 \uc788\ub2e4.","\uc9c4\uc9dc \ubb34\uae30\ub294 \ud544\uba78\uc790\uc758 \uc190\uc5d0\ub294 \ub108\ubb34\ub098 \uac70\ub300\ud558\uc9c0\ub9cc, \uadf8 \ubaa8\uc870\ud488\uc740 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc624\ub9ac\uc9c0\ub110 \uac8c\uc784\uc5d0\uc11c \uc7a5\uc778 \ub300\uc7a5\uc7a5\uc774\ub294 \uac80\uc740\ubc14\uc704 \ub098\ub77d\uc5d0\uc11c \ud1a0\ub968 \ub300\uc7a5\uc870\ud569\uc758 \ub85c\ud06c\ud1a0\uc2a4 \ub2e4\ud06c\ubc14\uac8c\uc774\ub108\uc5d0\uac8c \uc124\ud37c\ub860 \ub9dd\uce58\uc758 \ub3c4\uba74\uc744 \uc5bb\uc740 \ub4a4, \ub77c\uadf8\ub098\ub85c\uc2a4\uc5d0\uac8c\uc11c \uc9c1\uc811 \ube7c\uc557\uc740 \ud76c\uadc0\ud55c \uc124\ud37c\ub77c\uc2a4\uc758 \ub208\uacfc \ud569\uccd0 \ud544\uba78\uc790\uc5d0\uac8c \ub9de\ub294 \ud06c\uae30\uc758 \ub77c\uadf8\ub098\ub85c\uc2a4\uc758 \uc190\uc744 \ub9cc\ub4e4\uc5b4 \ub0c8\ub2e4."]},"item:thunderfury":{title:"\uc6b0\ub808\ud3ed\ud48d - \ubc14\ub78c\ucd94\uc801\uc790\uc758 \uc131\uac80",summary:"\ub77c\uadf8\ub098\ub85c\uc2a4\uac00 \uac00\ub450\uc5c8\ub358 \ubc14\ub78c\uc758 \uc655\uc790 \uc36c\ub354\ub780\uc758 \ub9c8\uc9c0\ub9c9 \uc815\uc218\ub97c \ub2f4\uc544 \ubcbc\ub9b0 \uac80.",body:["\ubd88\uacfc \ubc14\ub78c \uc0ac\uc774\uc758 \uace0\ub300 \uc804\uc7c1\uc5d0\uc11c \ub77c\uadf8\ub098\ub85c\uc2a4\uc640 \uadf8\uc758 \ubd80\uad00 \uac00\ub974\uc640 \ub0a8\uc791 \uac8c\ub3c8\uc740 \ubc14\ub78c\uc758 \uc655\uc790 \uc36c\ub354\ub780\uc744 \ubb3c\ub9ac\ucce4\ub2e4. \ubd88\uc758 \uad70\uc8fc\ub294 \uadf8\uc758 \uc815\uc218\ub97c \uba39\uc5b4 \uce58\uc6e0\uc9c0\ub9cc \uc804\ubd80 \uc0bc\ud0a4\uc9c0\ub294 \ubabb\ud588\uace0, \uadf8\ub798\uc11c \ub0a8\uc740 \uc815\uc218\ub97c \ubd80\uc801\uc5d0 \ubd09\uc778\ud55c \ub4a4 \ub458\ub85c \ucabc\uac1c \ubd80\uad00\ub4e4\uc5d0\uac8c \ud558\ub098\uc529 \uc8fc\uc5c8\ub2e4. \uadf8\uac83\uc774 \ubc14\ub78c\ucd94\uc801\uc790\uc758 \uad74\ub808\ub2e4.","\uc624\ub9ac\uc9c0\ub110 \uac8c\uc784\uc5d0\uc11c \uacf5\uaca9\ub300\ub294 \ud654\uc0b0 \uc2ec\uc7a5\ubd80\uc5d0\uc11c \uac00\ub974\uc640 \uac8c\ub3c8\uc5d0\uac8c\uc11c \ub450 \uc870\uac01\uc744 \ube7c\uc557\uc544 \uc2e4\ub9ac\ub354\uc2a4\uc758 \ub300\uc601\uc8fc \ub370\ubbf8\ud2b8\ub9ac\uc548\uc5d0\uac8c \uac00\uc838\uac14\ub2e4. \ubd88\uc758 \uad70\uc8fc \uc790\uc2e0\uc758 \uc815\uc218\uc640 \ub9c8\ubc95\uc774 \uae43\ub4e0 \uc5d8\ub808\uba58\ud2f0\uc6c0 \uc8fc\uad34\ub97c \ub354\ud558\uc790 \uad74\ub808\ub294 \uc57d\ud574\uc9c4 \uc655\uc790\ub97c \ubd88\ub7ec\ub0c8\uace0, \uadf8\uac00 \uc4f0\ub7ec\uc9c0\uc790 \ub370\ubbf8\ud2b8\ub9ac\uc548\uc740 \ub0a8\uc740 \ud798\uc744 \ubcbc\ub824 \uc0b4\uc544 \uc788\ub294 \ud3ed\ud48d\uc774 \ud0c0\ub2e5\uac70\ub9ac\ub294 \uac80, \uc6b0\ub808\ud3ed\ud48d\uc744 \ub9cc\ub4e4\uc5c8\ub2e4."]},"item:seal-of-ascension":{title:"\uc2b9\ucc9c\uc758 \uc778\uc7a5",summary:"\uac80\uc740\uc6a9\uc758 \ubd88\uaf43\uc73c\ub85c \ubcbc\ub824 \uac80\uc740\ubc14\uc704 \ucca8\ud0d1\uc758 \uc0c1\uce35 \uc131\ucc44\ub97c \uc5f4\uc5c8\ub358 \ubc18\uc9c0.",body:["\ub80c\ub4dc \ube14\ub799\ud578\ub4dc\uc640 \uac80\uc740\uc6a9\uad70\ub2e8\uc774 \uad81\uc815\uc744 \ucc28\ub9b0 \uac80\uc740\ubc14\uc704 \ucca8\ud0d1\uc758 \uc704\uce35 \uc804\ub2f9\uc740 \uce68\uc785\uc790\ub97c \ub9c9\uae30 \uc704\ud574 \ubd09\uc778\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ucca8\ud0d1 \ud558\uce35\uc5d0\uc11c\ub294 \ubc38\ub780\uc774\ub77c\ub294 \ubcc0\uc7a5\ud55c \uc774\ubc29\uc778, \uc2e4\uc740 \ub124\ud30c\ub9ac\uc548\uc744 \ucad3\uae30\ub85c \ub9f9\uc138\ud55c \ubd89\uc740 \uc6a9 \ubc38\ub77c\uc2a4\ud2b8\ub77c\uc988\uac00 \ubaa8\ud5d8\uac00\ub4e4\uc5d0\uac8c \uc5f4\uc1e0 \ub9cc\ub4dc\ub294 \ubc95\uc744 \uac00\ub974\uccd0 \uc8fc\uc5c8\ub2e4. \ucca8\ud0d1\uc758 Smolderthorn, Spirestone, \ud53c\ub3c4\ub07c \uc9c0\ud718\uad00\ub4e4\uc5d0\uac8c\uc11c \ube7c\uc557\uc740 \ubcf4\uc11d \uc138 \uac1c\ub97c \ubc15\uc740 \uc7a5\uc2dd \uc5c6\ub294 \uc778\uc7a5\uc774\uc5c8\ub2e4.","\uadf8\ub2e4\uc74c \uc778\uc7a5\uc740 \uac80\uc740\uc6a9\uc758 \ubd88\uaf43\uc73c\ub85c \ubcbc\ub824\uc57c \ud588\ub2e4. \uc601\uc6c5\ub4e4\uc740 \uba3c\uc9c0\uc9c4\ud759 \uc2b5\uc9c0\ub300\uc758 Wyrmbog\ub85c \uac00\uc11c \ube44\ub8e1 \uc5e0\ubc84\uc2a4\ud2b8\ub77c\uc774\ud504\uc5d0\uac8c \uc5b5\uc9c0\ub85c \ubd88\uc744 \ubfdc\uac8c \ud588\ub2e4. \uc644\uc131\ub41c \ubc18\uc9c0\ub294 \uc0c1\uce35 \uc131\ucc44\ub97c \uc5f4\uc5c8\uace0, \ub80c\ub4dc\uc640 \uc2f8\uc6b8 \ub54c \ubc38\ub77c\uc2a4\ud2b8\ub77c\uc988\uc758 \ud22c\uc601\uccb4\ub97c \ubd88\ub7ec\ub0b4 \uc601\uc6c5\ub4e4 \uacc1\uc5d0 \uc138\uc6b8 \uc218 \uc788\uc5c8\ub2e4."]},"item:drakefire-amulet":{title:"\uc6a9\uc758 \ubd88\uaf43 \ubd80\uc801",summary:"\uac80\uc740 \uc6a9\uc758 \ud53c\ub85c \ub2e4\uc2dc \ub9cc\ub4e4\uc5b4 \uc624\ub2c9\uc2dc\uc544 \uc790\uc2e0\uc758 \ub465\uc9c0\ub85c \ub4e4\uc5b4\uac00\ub294 \uc5f4\uc1e0\uac00 \ub41c, \uadf8\ub140\uc758 \ubd80\uc11c\uc9c4 \ubd80\uc801.",body:["\uce74\ud2b8\ub77c\ub098 \ud504\ub808\uc2a4\ud130 \ubd80\uc778\uc73c\ub85c \ubcc0\uc7a5\ud55c \uc624\ub2c9\uc2dc\uc544\ub294 \uc6a9\uc758 \ub208\uc774\ub77c \ubd88\ub9ac\ub294 \ud39c\ub358\ud2b8\ub85c \uc2a4\ud1b0\uc708\ub4dc \uad81\uc815\uc5d0 \ud30c\uace0\ub4e4\uc5c8\ub2e4. \uadf8\uac83\uc740 \uc815\uc2e0\uc744 \uace7\ubc14\ub85c \uc9c0\ubc30\ud558\uc9c0\ub294 \uc54a\uc558\uc9c0\ub9cc, \uc228\uc740 \uc695\ub9dd\uc744 \ubd80\ucd94\uae30\uace0 \uadf8\ub140\uc5d0\uac8c \ud5a5\ud560 \uc758\uc2ec\uc744 \ub2e4\ub978 \ub370\ub85c \ub3cc\ub838\ub2e4. \uc708\uc800 \uc0ac\ub839\uad00\uc774 \uadf8 \uac00\uba74\uadf9\uc744 \ud3ed\ub85c\ud558\uc790 \ud39c\ub358\ud2b8\ub294 \ubd80\uc11c\uc84c\uace0, \ud478\ub978 \uc6a9 \ud560\ub808\uac00 \ub4dc\ub77c\ud0a4\uc0ac\uc2a4 \uc7a5\uad70\uc758 \ud53c\ub85c \uadf8 \uc870\uac01\ub4e4\uc744 \ub2e4\uc2dc \uc5ee\uc5b4 \uc6a9\uc758 \ubd88\uaf43 \ubd80\uc801\uc744 \ub9cc\ub4e4\uc5c8\ub2e4.","\ud638\ub4dc \uc601\uc6c5\ub4e4\uc740 \ub2e4\ub978 \uae38, \uace7 \ub809\uc0ac\ub974\uc640 \uace0\ub300 \ube44\ub8e1 \uc5e0\ubc84\uc2a4\ud2b8\ub77c\uc774\ud504\uc758 \uc2dc\ud5d8\uc744 \uac70\uccd0 \uac19\uc740 \ubd80\uc801\uc744 \uc5bb\ub294\ub2e4. \uc624\ub2c9\uc2dc\uc544\uc758 \ub465\uc9c0\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uacf5\uaca9\ub300\uc6d0\uc740 \ub204\uad6c\ub098 \uc774 \ubd80\uc801\uc744 \uc9c0\ub140\uc57c \ud558\uba70, Forever\ub294 \uc774 \uc870\uc728 \uacfc\uc815\uc744 \uc9c4\uc601\ub9c8\ub2e4 \ubcc4\ub3c4\uc758 \uc5f0\uacc4 \ud018\uc2a4\ud2b8\ub85c \uc720\uc9c0\ud55c\ub2e4."]},"item:head-of-onyxia":{title:"\uc624\ub2c9\uc2dc\uc544\uc758 \uba38\ub9ac",summary:"\uc5b4\ubbf8 \uc6a9\uc758 \uc8fd\uc74c\uc744 \uc99d\uba85\ud558\ub294 \uc804\ub9ac\ud488\uc73c\ub85c, \uc2a4\ud1b0\uc708\ub4dc\ub098 \uc624\uadf8\ub9ac\ub9c8\uc758 \uc131\ubb38 \uc704\uc5d0 \ub0b4\uac78\ub824 \uc0ac\uae30\ub97c \ubd81\ub3cb\uc6b4\ub2e4.",body:["\ub370\uc2a4\uc719\uc758 \ub538\uc774\uc790 \ub124\ud30c\ub9ac\uc548\uc758 \uc5ec\ub3d9\uc0dd\uc778 \uc624\ub2c9\uc2dc\uc544\ub294 \uba3c\uc9c0\uc9c4\ud759 \uc2b5\uc9c0\ub300\uc758 \ub3d9\uad74\uc5d0\uc11c \uc0c8\ub07c\ub4e4\uc744 \uc9c0\ud0a4\uba70, \uc544\uc81c\ub85c\uc2a4 \ud544\uba78\uc790\uc758 \uc655\uad6d\ub4e4\uc744 \uc790\uc2e0\uc758 \ub73b\ub300\ub85c \uad74\ubcf5\uc2dc\ud0a4\ub824\ub294 \uc74c\ubaa8\ub97c \uafb8\ubbfc\ub2e4. \uadf8\ub140\ub97c \uc4f0\ub7ec\ub728\ub9ac\uc790 \uac80\uc740\uc6a9\uad70\ub2e8\uc758 \uac00\uc7a5 \uc624\ub79c \uae30\ub9cc \uac00\uc6b4\ub370 \ud558\ub098\uac00 \ub05d\ub0ac\ub2e4.","\uc624\ub9ac\uc9c0\ub110 \uac8c\uc784\uc5d0\uc11c \uadf8\ub140\uc758 \uba38\ub9ac\ub294 \uc804\ub9ac\ud488\uc73c\ub85c \uace0\ud5a5\uc5d0 \uac00\uc838\uac14\ub2e4. \uc5bc\ub77c\uc774\uc5b8\uc2a4 \uc6a9\uc0ac\ub4e4\uc740 \uc2a4\ud1b0\uc708\ub4dc\uc5d0, \ud638\ub4dc \uc6a9\uc0ac\ub4e4\uc740 \uc624\uadf8\ub9ac\ub9c8\uc758 \uc2a4\ub784\uc5d0\uac8c \ubc14\ucce4\ub2e4. \uc131\ubb38 \uc704\uc5d0 \ub0b4\uac78\ub9b0 \uba38\ub9ac\ub294 \ub3c4\uc2dc\uc5d0 \uc788\ub294 \ubaa8\ub450\uc5d0\uac8c \uc6a9\uc0ac\ub0e5\uafbc\uc758 \uaca9\ub824\uc758 \ud568\uc131\uc744 \ub0b4\ub838\uace0, \uc218\ub3c4 \uc804\uccb4\uac00 \uc2b9\ub9ac\ub97c \ucd95\ud558\ud588\ub2e4."]},"item:quel-serrar":{title:"\ucf08\uc138\ub77c\ub974",summary:"\uc174\ub4dc\ub784\ub77c\uac00 \uc9c0\ucf1c \uc628 \uace0\ub300 \ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \uac80\uc73c\ub85c, \uc6a9\uc758 \uc228\uacb0 \uc18d\uc5d0\uc11c\ub9cc \uc644\uc131\ub41c\ub2e4.",body:["\ucf08\uc138\ub77c\ub974\ub294 \uc624\ub798\uc804 \ub098\uc774\ud2b8 \uc5d8\ud504 \ub300\uc7a5\uc7a5\uc774\ub4e4\uc774 \uc6a9\uad70\ub2e8\uc758 \ub3c4\uc6c0\uc744 \ubc1b\uc544 \ubcbc\ub9b0 \ud504\ub9ac\uc998 \uac80 \uac00\uc6b4\ub370 \ud558\ub098\uc774\uba70, \uadf8 \uc30d\ub465\uc774 \uac80\uc778 \ucf08\ub378\ub77c\ub974\ub294 \ud558\uc774 \uc5d8\ud504\uc5d0\uac8c \uc8fc\uc5b4\uc84c\ub2e4. \uc218\ucc9c \ub144 \ub3d9\uc548 \uc5d8\ub4dc\ub808\ud0c8\ub77c\uc2a4\uc758 \uc174\ub4dc\ub784\ub77c\ub294 \uc774 \uac80\uc744 \uae68\uc6b8 \ub9cc\ud07c \uac15\ud55c \uc8fc\uc778\uc744 \uae30\ub2e4\ub9ac\uba70 \uac04\uc9c1\ud574 \uc654\ub2e4.","\uc624\ub9ac\uc9c0\ub110 \uac8c\uc784\uc5d0\uc11c \uc6a9 \uc0ac\ub0e5\uc5d0 \uad00\ud55c \ub0a1\uc740 \uac1c\ub860\uc11c\ub97c \ucc3e\uc740 \uc804\uc0ac\ub098 \uc131\uae30\uc0ac\ub294 \uadf8\uac83\uc744 \ud608\ud22c\uc758 \uc804\uc7a5 \ub3c4\uc11c\uad00\uc758 \uc804\uc2b9\uc9c0\uae30 \ub9ac\ub4dc\ub85c\uc2a4\uc5d0\uac8c \uac00\uc838\uac00 \uc544\uc9c1 \ub2f4\uae08\uc9c8\ub418\uc9c0 \uc54a\uc740 \uac80\uc744 \ubc1b\uc558\ub2e4. \uc624\ub2c9\uc2dc\uc544\uc758 \uae4a\uc740 \uc228\uacb0\ub85c \ub2ec\uad70 \ub4a4 \uc4f0\ub7ec\uc9c4 \uc6a9\uc5d0\uac8c \uaf42\uc740 \uadf8 \uac15\ucca0\uc740, \ub9ac\ub4dc\ub85c\uc2a4\uc5d0\uac8c \ub3cc\ub824\uc8fc\uba74 \ucf08\uc138\ub77c\ub974\uac00 \ub418\uc5c8\ub2e4."]},"item:rhokdelar":{title:"\ub85c\ud06c\ub378\ub77c\ub974\uc640 \ub85d\ub378\ub77c\ub974",summary:"\uc545\ub839\uc758 \uc232\uc758 \ud0c0\ub77d\ud55c \uace0\ub300\uc815\ub839\ub4e4\uc774 \uc790\uc2e0\ub4e4\uc758 \uc6d0\uc218\ub97c \uac1a\uc544 \uc900 \uc0ac\ub0e5\uafbc\uc744 \uc704\ud574 \ube5a\uc5b4\ub0b8 \uc0b4\uc544 \uc788\ub294 \uc7a5\uad81\uacfc \uc9c0\ud321\uc774.",body:["\ubd88\ud0c0\ub294 \uad70\ub2e8\uc774 \uce7c\ub9bc\ub3c4\uc5b4\ub97c \ud729\uc4f8\uc5c8\uc744 \ub54c, \uadf8\ub4e4\uc740 \ud6d7\ub0a0 \uc545\ub839\uc758 \uc232\uc774 \ub420 \uace8\uc9dc\uae30\ub97c \uc624\uc5fc\uc2dc\ucf30\ub2e4. \uadf8\uacf3\uc758 \uac00\uc7a5 \uac15\ub825\ud55c \uace0\ub300\uc815\ub839\ub4e4\uc740 \ub9d0\ub77c\ube44\ud2c0\uc5b4\uc838 \ub3cc\ucc98\ub7fc \uad73\uc740 \uaecd\ub370\uae30\uac00 \ub418\uc5c8\uc9c0\ub9cc, \uadf8 \uc601\ud63c\uc740 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uadf8\uc911 \ud558\ub098\uc778 \ubc14\ub974\ud2b8\ub8e8\uc2a4\uc758 \uc78e\uc0ac\uadc0 \ud558\ub098\uac00 \ud654\uc0b0 \uc2ec\uc7a5\ubd80\uc5d0 \uc788\ub294 \ubd88\uc758 \uad70\uc8fc\uc758 \ubcf4\ubb3c \ub354\ubbf8\uc5d0 \ud758\ub7ec\ub4e4\uc5c8\ub2e4.","\uc624\ub9ac\uc9c0\ub110 \uac8c\uc784\uc5d0\uc11c \uadf8 \uc78e\uc0ac\uadc0\ub97c \ubc14\ub974\ud2b8\ub8e8\uc2a4\uc5d0\uac8c \ub3cc\ub824\uc900 \uc0ac\ub0e5\uafbc\uc740 \uc18c\ud658\uc218\uc870\ucc28 \uc5c6\uc774 \ud640\ub85c \uad70\ub2e8\uc758 \ud558\uc218\uc778 \ub137\uc744 \uc0ac\ub0e5\ud558\ub77c\ub294 \uc784\ubb34\ub97c \ubc1b\uc558\ub2e4. \uadf8 \ubcf4\ub2f5\uc73c\ub85c \uace0\ub300\uc815\ub839\ub4e4\uc740 \uc800\uc808\ub85c \uaf43\uc744 \ud53c\uc6b0\ub294 \uc7a5\uad81 \ub85c\ud06c\ub378\ub77c\ub974\uc640, \uc790\uc5f0\uc758 \ud798\uc73c\ub85c \ube5b\ub098\ub294 \uc9dd \uc9c0\ud321\uc774 \ub85d\ub378\ub77c\ub974\ub97c \ub9cc\ub4e4\uc5b4 \uc8fc\uc5c8\ub2e4."]},"item:taelans-hammer":{title:"\ud0e4\ub780\uc758 \ub9dd\uce58",summary:"\ubd89\uc740\uc2ed\uc790\uad70\uc5d0\uac8c \ube7c\uc557\uae34 \uc544\ub4e4\uc5d0\uac8c \ud2f0\ub9ac\uc628 \ud3f4\ub4dc\ub9c1\uc774 \ub2e4\uac00\uac08 \uc218 \uc788\uac8c \ub3c4\uc6b4 \uc544\uc774\uc758 \uc7a5\ub09c\uac10 \ub9dd\uce58.",body:["\uc77c\uacf1 \ubc88\uc9f8 \uc0dd\uc77c\uc5d0 \uc5b4\ub9b0 \ud0e4\ub780\uc740 \uc544\ubc84\uc9c0 \ud2f0\ub9ac\uc628 \ud3f4\ub4dc\ub9c1\uc5d0\uac8c\uc11c \uc791\uc740 \uc804\ud22c \ub9dd\uce58\ub97c \ubc1b\uc558\ub2e4. \ud2f0\ub9ac\uc628 \uc790\uc2e0\uc758 \ub9dd\uce58\ub97c \ubcf8\ub72c \uac83\uc774\uc5c8\ub2e4. \ud2f0\ub9ac\uc628\uc774 \uc624\ud06c \uc5d0\uc774\ud2b8\ub9ac\uadf8\ub97c \ubcc0\ud638\ud55c \uc8c4\ub85c \ucd94\ubc29\ub41c \ub4a4, \ud0e4\ub780\uc758 \uc5b4\uba38\ub2c8\ub294 \uc544\uc774\uc5d0\uac8c \uc544\ubc84\uc9c0\uac00 \uc8fd\uc5c8\ub2e4\uace0 \ub9d0\ud558\uace0 \uadf8\ub97c \ub3d9\ubd80 \uc5ed\ubcd1\uc9c0\ub300 Undercroft\uc758 \uac00\uc9dc \ubb34\ub364\uc73c\ub85c \ub370\ub824\uac14\ub2e4. \uc544\uc774\ub294 \uadf8\uacf3\uc5d0 \ub9dd\uce58\ub97c \ubb3b\uc5c8\uace0, \uadf8 \uae30\uc5b5\ub3c4 \ud568\uaed8 \ubb3b\uc5c8\ub2e4.","\uc5ec\ub7ec \ud574\uac00 \uc9c0\ub098 \ud0e4\ub780\uc740 \ud558\uc2a4\uae00\ub80c\uc5d0\uc11c \ubd89\uc740\uc2ed\uc790\uad70\uc758 \ub300\uc601\uc8fc\uc5d0 \uc62c\ub790\ub2e4. \uc624\ub9ac\uc9c0\ub110 \uac8c\uc784\uc5d0\uc11c \ubaa8\ud5d8\uac00\ub4e4\uc740 \ub098\uc774 \ub4e0 \ud2f0\ub9ac\uc628\uc744 \uc704\ud574 \ub9dd\uce58\ub97c \ub418\ucc3e\uc544 \uc8fc\uace0, \ud0e4\ub780\uc774 \uc2ed\uc790\uad70\uc774 \ubb34\uc5c7\uc73c\ub85c \ubcc0\ud588\ub294\uc9c0 \uae68\ub2eb\ub3c4\ub85d \ub3c4\uc654\ub2e4. \ud0e4\ub780\uc774 \ud558\uc2a4\uae00\ub80c\uc5d0\uc11c \ub2ec\uc544\ub0a0 \ub54c \ub300\uc2ec\ubb38\uad00 \uc774\uc2e4\ub9ac\uc5d4\uc774 \uc544\ubc84\uc9c0\uac00 \ubcf4\ub294 \uc55e\uc5d0\uc11c \uadf8\ub97c \ubca0\uc5c8\uace0, \ud2f0\ub9ac\uc628\uc740 \uc774\uc2e4\ub9ac\uc5d4\uc744 \uc8fd\uc778 \ub4a4 \ubc31\uc740\uc758 \uc190\uc744 \ub2e4\uc2dc \uc138\uc6b0\uaca0\ub2e4\uace0 \ub9f9\uc138\ud588\ub2e4."]},"item:heart-of-hakkar":{title:"\ud559\uce74\ub974\uc758 \uc2ec\uc7a5",summary:"\ud559\uce74\ub974\uac00 \uc904\uad6c\ub8f9\uc5d0\uc11c \uc4f0\ub7ec\uc9c4 \ub4a4 \uc794\ub2ec\ub77c\uc5d0\uac8c \uc804\ud574\uc9c4, \uc544\uc9c1\ub3c4 \ud0c0\uc624\ub974\ub294 \ud53c\uc758 \uc2e0\uc758 \uc2ec\uc7a5.",body:["\uc5b4\ub460\uc758 \ubb38\uc774 \uc5f4\ub9ac\uae30 \uc57d 1,500\ub144 \uc804, \uad76\uc8fc\ub9b0 \uad6c\ub8e8\ubc14\uc2dc \ud2b8\ub864\ub4e4\uc740 \ud53c\uc758 \ub85c\uc544\uc778 \uc601\ud63c\uc57d\ud0c8\uc790 \ud559\uce74\ub974\uc5d0\uac8c \uc758\uc9c0\ud588\ub2e4. \uadf8\ub294 \uadf8\ub4e4\uc5d0\uac8c \ud798\uacfc \uc81c\uad6d\uc744 \uc8fc\uc5c8\uc9c0\ub9cc, \uc810\uc810 \ub354 \ub9ce\uc740 \ubaa9\uc228\uc744 \uc694\uad6c\ud588\uace0, \uacb0\uad6d \ubd80\uc871\ub4e4\uc740 \uadf8\uc5d0\uac8c \ubc18\uae30\ub97c \ub4e4\uc5b4 \uadf8\uc758 \uc544\ud0c8\ub77c\uc774 \uc0ac\uc81c\ub4e4\uc744 \ucd94\ubc29\ud588\ub2e4. \uc0ac\uc81c\ub4e4\uc774 \uadf8\ub97c \ub418\uc0b4\ub9ac\ub824 \uc2e0\uc804\uc744 \uc138\uc6b0\uc790, \uc774\uc138\ub77c\ub294 \uc2e0\uc804\uc744 \ubd80\uc234 \uc2ac\ud514\uc758 \ub2aa \uc544\ub798\ub85c \uac00\ub77c\uc549\ud614\ub2e4.","\uc624\ub9ac\uc9c0\ub110 \uac8c\uc784\uc5d0\uc11c \ud559\uce74\ub9ac \uc0ac\uc81c\ub4e4\uc740 \ub9c8\uce68\ub0b4 \uc601\ud63c\uc57d\ud0c8\uc790\ub97c \uc904\uad6c\ub8f9\uc73c\ub85c \ubd88\ub7ec\ub4e4\uc600\ub2e4. \uc794\ub2ec\ub77c \ubd80\uc871\uc774 \ubaa8\uc740 \uc601\uc6c5\ub4e4\uc740 \uadf8\uacf3\uc5d0\uc11c \uadf8\ub97c \uc4f0\ub7ec\ub728\ub9ac\uace0, \uc544\uc9c1\ub3c4 \ube5b\ub098\ub294 \uadf8\uc758 \uc2ec\uc7a5\uc744 \uc694\uc7a0\ubc14 \uc12c\uc758 \ubab0\ud1a0\ub974\uc5d0\uac8c \uac00\uc838\uac14\ub2e4. \ubab0\ud1a0\ub974\uc758 \uc758\uc2dd\uc740 \uc12c\uacfc \ubb34\ubc95\ud56d\uc5d0 \uc788\ub294 \ubaa8\ub450\uc5d0\uac8c \uc794\ub2ec\ub77c\uc758 \ud63c\uc744 \ub0b4\ub824 \uc8fc\uc5c8\ub2e4."]},"item:phylactery-of-kelthuzad":{title:"\ucf08\ud22c\uc790\ub4dc\uc758 \uc131\ubb3c\ud568",summary:"\ub300\ub9ac\uce58\uc758 \uc601\ud63c\uc744 \ub2f4\uc740 \uadf8\ub987\uc73c\ub85c, \uadf8\uac00 \ud328\ubc30\ud55c \ub4a4 \ub099\uc2a4\ub77c\ub9c8\uc2a4\uc5d0\uc11c \ud68c\uc218\ub418\uc5c8\ub2e4.",body:["\ud55c\ub54c \ud0a4\ub9b0 \ud1a0\uc758 \ub300\ub9c8\ubc95\uc0ac\uc600\ub358 \ucf08\ud22c\uc790\ub4dc\ub294 \uc800\uc8fc\ubc1b\uc740 \uc790\uc758 \uad50\ub2e8\uc744 \uc138\uc6b0\uace0 \ub9ac\uce58 \uc655\uc744 \uc704\ud574 \uc5ed\ubcd1\uc744 \ud37c\ub728\ub838\ub2e4. \uc544\uc11c\uc2a4\uc5d0\uac8c \uc8fd\uc784\uc744 \ub2f9\ud55c \ub4a4 \ub9ac\uce58\ub85c \ub418\uc0b4\uc544\ub098\uae30 \uc704\ud574 \ud0dc\uc591\uc0d8\uc73c\ub85c \uc62e\uaca8\uc9c4 \uadf8\ub294, \ub5a0\ub2e4\ub2c8\ub294 \ub124\ud06c\ub85c\ud3f4\ub9ac\uc2a4 \ub099\uc2a4\ub77c\ub9c8\uc2a4\uc5d0\uc11c \ub85c\ub370\ub860\uc758 \uc2a4\uceec\uc9c0\ub97c \ub2e4\uc2a4\ub9ac\uac8c \ub418\uc5c8\ub2e4.","\ub9ac\uce58\ub294 \uc790\uc2e0\uc758 \uc601\ud63c\uc744 \ub2f4\uc740 \uadf8\ub987\uc774 \ub0a8\uc544 \uc788\ub294 \ud55c \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc624\ub9ac\uc9c0\ub110 \uac8c\uc784\uc5d0\uc11c \ucf08\ud22c\uc790\ub4dc\ub97c \ubb3c\ub9ac\uce5c \uacf5\uaca9\ub300\ub294 \uadf8\uc758 \uc131\ubb3c\ud568\uc744 \ub418\ucc3e\uc544 \uc740\ube5b \uc5ec\uba85\ud68c\uc5d0 \ub9e1\uaca8 \uc9c0\ud0a4\uac8c \ud588\ub2e4. \ud6d7\ub0a0\uc758 \uc774\uc57c\uae30\uc5d0\uc11c \uc740\ube5b \uc5ec\uba85\ud68c\uc758 \uc0ac\uc81c \uc774\ub2c8\uace0 \ubaac\ud1a0\uc774 \uc2e0\ubd80\uac00 \uadf8 \ubbff\uc74c\uc744 \uc800\ubc84\ub9ac\uace0 \uc131\ubb3c\ud568\uc744 \ub178\uc2a4\ub80c\ub4dc\ub85c \uac00\uc838\uac00, \ub300\ub9ac\uce58\uc5d0\uac8c \uadc0\ud658\ud560 \uc2dc\uac04\uc744 \ubc8c\uc5b4 \uc8fc\uc5c8\uc74c\uc774 \ub4dc\ub7ec\ub0ac\ub2e4."]}}},1798,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"terms",{enumerable:!0,get:function(){return t}});const t={"term:argent-dawn":{title:"\uc740\ube5b \uc5ec\uba85\ud68c",summary:"\ubd89\uc740\uc2ed\uc790\uad70\uc758 \ub9f9\ubaa9\uc801\uc778 \uc99d\uc624\uc5d0 \ud729\uc4f8\ub9ac\uc9c0 \uc54a\uace0 \uc2a4\uceec\uc9c0\ub85c\ubd80\ud130 \uc544\uc81c\ub85c\uc2a4\ub97c \uc9c0\ud0a4\uae30\ub85c \ub9f9\uc138\ud55c \uae30\uc0ac\ub2e8.",body:["\ub85c\ub370\ub860\uc5d0 \ub0a8\uc740 \ubc31\uc740\uc758 \uc190 \uc0dd\uc874\uc790\ub4e4\uc774 \uad11\uc2e0\uc801\uc778 \ubd89\uc740\uc2ed\uc790\uad70\uc73c\ub85c \uad73\uc5b4 \uac08 \ub54c, \uadf8 \uae38\uc744 \ub530\ub974\uc9c0 \uc54a\uc740 \uc774\ub4e4\uc774 \uc788\uc5c8\ub2e4. \ub9e5\uc2a4\uc6f0 \ud2f0\ub85c\uc11c\uc2a4 \uacbd \uac19\uc740 \uc778\ubb3c\ub4e4\uc774 \uc774\ub048 \uadf8\ub4e4\uc740 \uc740\ube5b \uc5ec\uba85\ud68c\ub97c \uc138\uc6e0\uace0, \uc774 \uae30\uc0ac\ub2e8\uc740 \uc5b8\ub370\ub4dc\uc640 \uc2f8\uc6b8 \ub73b\uc774 \uc788\ub294 \uc790\ub77c\uba74 \ub204\uad6c\ub4e0 \ubc1b\uc544\ub4e4\uc778\ub2e4. \uae30\uc0ac\ub2e8\uc740 \ub3d9\ubd80 \uc5ed\ubcd1\uc9c0\ub300\uc758 \ud76c\ub9dd\uc758 \ube5b \uc608\ubc30\ub2f9\uc5d0\uc11c \uc2a4\uceec\uc9c0\ub97c \uac10\uc2dc\ud558\uba70, \uc804\uc120\uc744 \uc9c0\ud0a4\ub294 \ub370 \ud798\uc744 \ubcf4\ud0e0 \uc774\ub4e4\uc5d0\uac8c \ubcf4\uc0c1\uc744 \ub0b4\ub9b0\ub2e4."]},"term:burning-legion":{title:"\ubd88\ud0c0\ub294 \uad70\ub2e8",summary:"\ubab0\ub77d\ud55c \ud2f0\ud0c4 \uc0b4\uac8c\ub77c\uc2a4\uac00 \uac70\ub290\ub9b0 \ub05d\uc5c6\ub294 \uc545\ub9c8 \uad70\ub300\ub85c, \ubaa8\ub4e0 \ucc3d\uc870\ubb3c\uc744 \ubd88\ud0dc\uc6b0\uae30\ub85c \ub9f9\uc138\ud588\ub2e4.",body:["\ud55c\ub54c \ud2f0\ud0c4 \ud310\ud14c\uc628\uc758 \uc218\ud638\uc790\uc600\ub358 \uc0b4\uac8c\ub77c\uc2a4\ub294 \uacf5\ud5c8\uc758 \uc138\ub825\uc774 \uc138\uacc4\ud63c\uc744 \ud0c0\ub77d\uc2dc\ud0a4\ub824 \ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uac8c \ub418\uc5c8\uace0, \uc808\ub9dd\uc5d0 \ube60\uc838 \ucc3d\uc870\ubb3c\uc774 \uadf8\ub4e4\uc758 \uc190\uc5d0 \ub118\uc5b4\uac00\ub290\ub2c8 \ucc28\ub77c\ub9ac \ubaa8\ub450 \ubd88\ud0dc\uc6b0\uae30\ub85c \uacb0\uc2ec\ud588\ub2e4. \uadf8\ub294 \uc790\uc2e0\uc774 \uac00\ub450\uc5c8\ub358 \uc545\ub9c8\ub4e4\uc744 \ud480\uc5b4 \uc8fc\uace0, \uc5d0\ub808\ub2e4\ub974\uc758 \uad70\uc8fc \ud0ac\uc81c\ub374\uacfc \uc544\ud0a4\ubaac\ub4dc\ub97c \ub04c\uc5b4\ub4e4\uc5ec \uadf8\ub4e4\uc744 \uc9c0\ud718\ud558\uac8c \ud588\ub2e4. \uad70\ub2e8\uc740 \uace0\ub300\uc758 \uc804\uc7c1 \ub54c \uc544\uc81c\ub85c\uc2a4\ub97c \uce68\uacf5\ud588\uace0 \uc81c3\ucc28 \ub300\uc804\uc7c1 \ub54c \ub2e4\uc2dc \uccd0\ub4e4\uc5b4\uc654\uc73c\uba70, \uadf8 \ud558\uc218\uc778\ub4e4\uc740 \uc9c0\uae08\ub3c4 \uc545\ub839\uc758 \uc232\uacfc \uc800\uc8fc\ubc1b\uc740 \ub545 \uac19\uc740 \uacf3\uc5d0 \uc228\uc5b4 \uc788\ub2e4."]},"term:cenarion-circle":{title:"\uc138\ub098\ub9ac\uc628 \uc758\ud68c",summary:"\ub2ec\uc758 \uc232\uc5d0\uc11c \uc790\uc5f0\uc758 \uade0\ud615\uc744 \uc9c0\ud0a4\ub294 \ub098\uc774\ud2b8 \uc5d8\ud504\uc640 \ud0c0\uc6b0\ub80c \ub4dc\ub8e8\uc774\ub4dc\ub4e4\uc758 \uacb0\uc0ac.",body:["\ucd5c\ucd08\uc758 \ub4dc\ub8e8\uc774\ub4dc\ub4e4\uc744 \uac00\ub974\uce5c \ubc18\uc2e0 \uc138\ub098\ub9ac\uc6b0\uc2a4\uc758 \uc774\ub984\uc744 \ub534 \uc774 \uc758\ud68c\ub294 \ub098\uc774\ud2b8 \uc5d8\ud504\uc640 \ud0c0\uc6b0\ub80c \ub4dc\ub8e8\uc774\ub4dc\ub97c \ud558\ub098\uc758 \uacb0\uc0ac\ub85c \ubb36\ub294\ub2e4. \uc758\ud68c\uc758 \uc911\uc2ec\uc740 \uc2f8\uc6c0\uc774 \uae08\uc9c0\ub41c \uc131\uc5ed\uc778 \ub2ec\uc758 \uc232\uc758 \ub098\uc774\ud2b8\ud5e4\uc774\ube10 \ub9c8\uc744\uc774\uba70, \ud68c\uc6d0\ub4e4\uc740 \uc138\ub098\ub9ac\uc628 \uc694\uc0c8\uc5d0\uc11c \uc2e4\ub9ac\ub354\uc2a4\uc758 \uc704\ud611\ub3c4 \uc9c0\ucf1c\ubcf8\ub2e4."]},"term:cult-of-the-damned":{title:"\uc800\uc8fc\ubc1b\uc740 \uc790\uc758 \uad50\ub2e8",summary:"\ucf08\ud22c\uc790\ub4dc\uac00 \uc138\uc6b4 \ub9ac\uce58 \uc655\uc758 \uad50\ub2e8\uc73c\ub85c, \uc601\uc0dd\uc744 \uc57d\uc18d\ud588\uc9c0\ub9cc \uc5ed\ubcd1\uc744 \uac00\uc838\uc654\ub2e4.",body:["\ub300\ub9c8\ubc95\uc0ac \ucf08\ud22c\uc790\ub4dc\ub294 \uac15\ub839\uc220\uc744 \uc5f0\uad6c\ud558\ub824\uace0 \ud0a4\ub9b0 \ud1a0\uc5d0 \ub4f1\uc744 \ub3cc\ub838\uace0, \uc8fd\uc74c \uc5c6\ub294 \ub354 \ub098\uc740 \uc0b6\uc744 \uc57d\uc18d\ud558\uba70 \ub85c\ub370\ub860\uc758 \uac00\ub09c\ud558\uace0 \uc808\ubc15\ud55c \uc0ac\ub78c\ub4e4\uc744 \ub04c\uc5b4\ubaa8\uc558\ub2e4. \uad50\ub2e8\uc740 \ub9ac\uce58 \uc655\uc758 \uc5ed\ubcd1\uc744 \uace1\ubb3c \uc218\uc1a1\ud488 \uc18d\uc5d0 \uc228\uaca8 \ub9c8\uc744 \uc804\uccb4\ub97c \uc2a4\uceec\uc9c0\ub85c \ubc14\uafb8\uc5b4 \ub193\uc558\ub2e4. \uad50\ub2e8\uc758 \uac15\ub839\uc220\uc0ac\ub4e4\uc740 \uc9c0\uae08\ub3c4 \ubc14\ub85c\ube0c \uac00\ubb38\uc758 \uc61b \uc131\ucc44\uc778 \uce74\uc5d8 \ub2e4\ub85c\uc6b0\uc758 \uc2a4\uce7c\ub85c\ub9e8\uc2a4\uc5d0\uc11c \uac00\ub974\uce68\uc744 \uc774\uc5b4 \uac00\uace0 \uc788\ub2e4."]},"term:dark-portal":{title:"\uc5b4\ub460\uc758 \ubb38",summary:"\uc624\ud06c \ud638\ub4dc\uac00 \uc544\uc81c\ub85c\uc2a4\ub97c \uce68\uacf5\ud560 \ub54c \uc9c0\ub098\uc628 \ub4dc\ub808\ub178\uc5b4\uc640 \uc544\uc81c\ub85c\uc2a4 \uc0ac\uc774\uc758 \uad00\ubb38.",body:["\uc624\ud06c \ud751\ub9c8\ubc95\uc0ac \uad74\ub2e8\uacfc \ube59\uc758\ub41c \uc218\ud638\uc790 \uba54\ub514\ube0c\uac00 \uc5b4\ub460\uc758 \ubb38\uc744 \uc5f4\uc5b4 \ub4dc\ub808\ub178\uc5b4\uc640 \uc544\uc81c\ub85c\uc2a4\uc758 \uac80\uc740\ub2aa\uc744 \uc774\uc5c8\ub2e4. \ubb38\uc774 \uc5f4\ub9ac\uba74\uc11c \uc81c1\ucc28 \ub300\uc804\uc7c1\uc774 \uc2dc\uc791\ub418\uc5c8\uace0, \uc6cc\ud06c\ub798\ud504\ud2b8 \uc5ed\uc0ac\uc758 \uc5f0\ub3c4\ub294 \uc9c0\uae08\ub3c4 \uc774\ub54c\ub97c \uae30\uc900\uc73c\ub85c \uc13c\ub2e4. \uc81c2\ucc28 \ub300\uc804\uc7c1\uc774 \ub05d\ub09c \ub4a4 \uc5bc\ub77c\uc774\uc5b8\uc2a4\uac00 \ubb38\uc744 \ud30c\uad34\ud588\uc9c0\ub9cc, \ub12c\uc974\uc774 \uc774\ub97c \ub2e4\uc2dc \ucc22\uc5b4 \uc5f4\uc5c8\uace0, \uce74\ub4dc\uac00\uac00 \ub4dc\ub808\ub178\uc5b4 \ucabd\uc5d0\uc11c \ubb38\uc744 \ubb34\ub108\ub728\ub838\ub2e4. \uc7a0\ub4e0 \ubb38\uc758 \uace8\uaca9\uc740 \uc9c0\uae08\ub3c4 \uc800\uc8fc\ubc1b\uc740 \ub545 \uc704\uc5d0 \uc6b0\ub69d \uc19f\uc544 \uc788\ub2e4."]},"term:defias-brotherhood":{title:"\ub370\ud53c\uc544\uc988 \ub2e8",summary:"\ubcf4\uc218\ub97c \ubc1b\uc9c0 \ubabb\ud574 \uc5d0\ub4dc\uc708 \ubc34\ud074\ub9ac\ud504 \uc544\ub798\uc5d0\uc11c \ub3c4\uc801\uc774 \ub41c \uc2a4\ud1b0\uc708\ub4dc\uc758 \uc11d\uacf5\ub4e4.",body:["\uc11d\uacf5 \uae38\ub4dc\ub294 \uc81c2\ucc28 \ub300\uc804\uc7c1 \ud6c4 \uc2a4\ud1b0\uc708\ub4dc\ub97c \uc7ac\uac74\ud588\uc9c0\ub9cc, \uadc0\uc871\ub4e4\uc740 \uadf8\ub4e4\uc5d0\uac8c \ub300\uac00\ub97c \uce58\ub974\uae30\ub97c \uac70\ubd80\ud588\ub2e4. \uc9c0\ub3c4\uc790 \uc5d0\ub4dc\uc708 \ubc34\ud074\ub9ac\ud504\ub294 \ubd84\ub178\ud55c \uc11d\uacf5\ub4e4\uc744 \uc774\ub04c\uace0 \uc11c\ubd80 \ubab0\ub77d\uc9c0\ub300\ub85c \ub5a0\ub098, \uadf8\ub4e4\uc744 \uc8fd\uc74c\uc758 \ud3d0\uad11\uc5d0 \uc228\uc740 \ub3c4\ub451\uacfc \ud30c\uad34 \uacf5\uc791\uc6d0 \ubb34\ub9ac\uc778 \ub370\ud53c\uc544\uc988 \ub2e8\uc73c\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. Forever\uc5d0\uc11c\ub294 \ub2e8\uc6d0\ub4e4\uc774 Alcaz Prison \uc548\uc5d0\uc11c\ub3c4 \ub098\ud0c0\ub098 \ub098\uac00\uc640 \ub2e4\ud23c\uc744 \ubc8c\uc778\ub2e4."]},"term:dragon-aspects":{title:"\uc704\uc0c1",summary:"\uc544\uc81c\ub85c\uc2a4\ub97c \uc9c0\ud0a4\ub3c4\ub85d \ud2f0\ud0c4\uc5d0\uac8c \ud798\uc744 \ubc1b\uc740 \ub2e4\uc12f \uac70\ub300\ud55c \uc6a9\uc73c\ub85c, \uc800\ub9c8\ub2e4 \uc6a9\uad70\ub2e8 \ud558\ub098\ub97c \uc774\ub048\ub2e4.",body:["\ud2f0\ud0c4\uc740 \ub2e4\uc12f \uc6a9\uc744 \uace8\ub77c \uac01\uc790\uc5d0\uac8c \uc790\uc2e0\ub4e4\uc758 \ud798 \uc77c\ubd80\ub97c \ub098\ub204\uc5b4 \uc8fc\uc5c8\ub2e4. \ubd89\uc740\uc6a9\uad70\ub2e8\uc758 \uc0dd\uba85\uc758 \uc5b4\uba38\ub2c8 \uc54c\ub809\uc2a4\ud2b8\ub77c\uc790, \ub179\uc0c9\uc6a9\uad70\ub2e8\uc758 \uafc8\uc758 \uc218\ud638\uc790 \uc774\uc138\ub77c, \uccad\ub3d9\uc6a9\uad70\ub2e8\uc758 \uc2dc\uac04\uc758 \uc218\ud638\uc790 \ub178\uc988\ub3c4\ub974\ubb34, \ud478\ub978\uc6a9\uad70\ub2e8\uc758 \ub9c8\ubc95\uc758 \uc218\ud638\uc790 \ub9d0\ub9ac\uace0\uc2a4, \uadf8\ub9ac\uace0 \uac80\uc740\uc6a9\uad70\ub2e8\uc758 \ub300\uc9c0\uc758 \uc218\ud638\uc790 \ub12c\ud0c0\ub9ac\uc628\uc774\ub2e4. \ub12c\ud0c0\ub9ac\uc628\uc740 \ubc30\uc2e0\uc73c\ub85c \ub370\uc2a4\uc719\uc774 \ub418\uc5c8\uace0, \uadf8\uc758 \uc790\uc2dd \uc624\ub2c9\uc2dc\uc544\uc640 \ub124\ud30c\ub9ac\uc548\uc740 \uc9c0\uae08\ub3c4 \uc544\uc81c\ub85c\uc2a4\uc5d0\uc11c \uc74c\ubaa8\ub97c \uafb8\ubbf8\uace0 \uc788\ub2e4."]},"term:elemental-lords":{title:"\uc815\ub839\uc758 \uad70\uc8fc",summary:"\ubd88, \ub300\uc9c0, \ubc14\ub78c, \ubb3c\uc744 \ub2e4\uc2a4\ub9ac\ub294 \ub124 \uad70\uc8fc\ub85c, \ud55c\ub54c \uace0\ub300 \uc2e0\uc758 \uc885\uc774\uc5c8\ub2e4.",body:["\ubd88\uc758 \ub77c\uadf8\ub098\ub85c\uc2a4, \ub300\uc9c0\uc758 \ud14c\ub77c\uc81c\uc778, \ubc14\ub78c\uc758 \uc54c\uc544\ud0a4\ub974, \ubb3c\uc758 \ub135\ud2a4\ub860\uc740 \ud2f0\ud0c4\uc758 \uc885\ub4e4\uc5d0 \ub9de\uc120 \uace0\ub300 \uc2e0\uc758 \uc804\uc7c1\uc5d0\uc11c \uc815\ub839\ub4e4\uc744 \uc774\ub04c\uc5c8\ub2e4. \uac80\uc740 \uc81c\uad6d\uc774 \ubb34\ub108\uc9c0\uc790 \uad00\ub9ac\uc790\ub4e4\uc740 \uadf8\ub4e4\uc744 \uc815\ub839\uacc4\uc5d0 \uac00\ub450\uc5c8\ub2e4. \uc8fc\uc220\uc0ac\ub4e4\uc740 \uc815\ub839\uc758 \uade0\ud615\uc744 \uc9c0\ud0a4\ub824 \uc560\uc4f0\uc9c0\ub9cc, \uac80\uc740\ubb34\uc1e0 \ub9c8\ubc95\uc0ac \ud0c0\uc6b0\ub9bf\uc0b0\uc758 \uc2e4\uc218\ub85c \ub77c\uadf8\ub098\ub85c\uc2a4\ub294 \uac80\uc740\ubc14\uc704 \uc0b0 \uc544\ub798\uc5d0\uc11c \ub2e4\uc2dc \uc138\uc0c1\uc73c\ub85c \ub3cc\uc544\uc654\ub2e4."]},"term:elune":{title:"\uc5d8\ub8ec",summary:"\ub098\uc774\ud2b8 \uc5d8\ud504\uc758 \ub2ec\uc758 \uc5ec\uc2e0\uc73c\ub85c, \uadf8\ub140\uc758 \uc5ec\uc0ac\uc81c\ub4e4\uc774 \ub098\uc774\ud2b8 \uc5d8\ud504\ub97c \uc774\ub048\ub2e4.",body:["\ub098\uc774\ud2b8 \uc5d8\ud504\ub294 \ubb38\uba85\uc758 \uc0c8\ubcbd\ubd80\ud130 \uc5d8\ub8ec\uc744 \uc12c\uae30\uba70 \ub2ec\ube5b \uc18d\uc5d0\uc11c \uae38\uc7a1\uc774\ub97c \ucc3e\uc544 \uc654\ub2e4. \ub300\uc5ec\uc0ac\uc81c \ud2f0\ub780\ub370 \uc704\uc2a4\ud37c\uc708\ub4dc\uac00 \uc774\ub044\ub294 \uc5d8\ub8ec\uc758 \uc790\ub9e4\ud68c\ub294 \ub2e4\ub974\ub098\uc11c\uc2a4\uc5d0\uc11c \uc131\uc9c1\uc790\uc774\uc790 \uc9c0\ub3c4\uce35\uc758 \uc5ed\ud560\uc744 \ud568\uaed8 \ub9e1\uace0 \uc788\uc73c\uba70, \ub098\uc774\ud2b8 \uc5d8\ud504 \uc0ac\uc81c\ub4e4\uc740 \uc5ec\uc2e0\uc5d0\uac8c\uc11c \uce58\uc720\uc758 \ud798\uc744 \uc5bb\ub294\ub2e4."]},"term:emerald-dream":{title:"\uc5d0\uba54\ub784\ub4dc\uc758 \uafc8",summary:"\uc190\ub300\uc9c0 \uc54a\uc740 \uc544\uc81c\ub85c\uc2a4\uc758 \uc57c\uc0dd\uc744 \ube44\ucd94\ub294 \uafc8\uc758 \uc138\uacc4\ub85c, \uc774\uc138\ub77c\uac00 \uc9c0\ud0a4\uace0 \ub4dc\ub8e8\uc774\ub4dc\uac00 \uac70\ub2cc\ub2e4.",body:["\uc5d0\uba54\ub784\ub4dc\uc758 \uafc8\uc740 \ud544\uba78\uc790\uc758 \uc190\uae38\uc774 \ub2ff\uc9c0 \uc54a\uc558\ub2e4\uba74 \uc138\uc0c1\uc774 \uc5b4\ub5a4 \ubaa8\uc2b5\uc774\uc5c8\uc744\uc9c0\ub97c \ube44\ucd98\ub2e4. \uc774\uc138\ub77c\uc640 \ub179\uc0c9\uc6a9\uad70\ub2e8\uc774 \uc774\uacf3\uc744 \uc9c0\ud0a4\uba70, \ub4dc\ub8e8\uc774\ub4dc\ub294 \uc601\ud63c\uc73c\ub85c \uc774\uacf3\uc5d0 \ub4e4\uc5b4\uac00 \ub54c\ub85c\ub294 \uc218\ubc31 \ub144 \ub3d9\uc548 \uc7a0\ub4e4\uae30\ub3c4 \ud55c\ub2e4. \uc9c0\uae08\uc758 \uc544\uc81c\ub85c\uc2a4\uc5d0\uc11c\ub294 \ubb34\uc5b8\uac00\uac00 \uafc8\uc744 \uc369\uac8c \ud558\uace0 \uc788\ub2e4. \uc11c\uc11c\ud788 \ubc88\uc9c0\ub294 \uc545\ubabd\uc774 \ud1b5\uace1\uc758 \ub3d9\uad74\uc5d0\uc11c \ub098\ub784\ub809\uc2a4\uc758 \uafc8\uc744 \ube44\ud2c0\uace0, \uac00\ub77c\uc549\uc740 \uc0ac\uc6d0\uc758 \ub179\uc0c9 \uc6a9\ub4e4\uc744 \ubbf8\uce58\uac8c \ub9cc\ub4e4\uc5c8\ub2e4."]},"term:explorers-league":{title:"\ud0d0\ud5d8\uac00 \uc5f0\ub9f9",summary:"\ud2f0\ud0c4\uc758 \ube44\ubc00\uc744 \ucc3e\uc544 \ub545\uc744 \ud30c\ub294 \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \ub4dc\uc6cc\ud504 \uace0\uace0\ud559\uc790 \ubaa8\uc784.",body:["\uc5f0\ub9f9\uc740 \uc544\uc774\uc5b8\ud3ec\uc9c0\uc758 \ud0d0\ud5d8\uac00\uc758 \uc804\ub2f9\uc5d0\uc11c \ub4dc\uc6cc\ud504\ub4e4\uc744 \uc138\uacc4 \uacf3\uacf3\uc73c\ub85c \ubcf4\ub0b4, \uc790\uae30 \uc885\uc871\uc758 \uae30\uc6d0\uc744 \ubc1d\ud600 \uc904\uc9c0\ub3c4 \ubaa8\ub97c \uc720\ubb3c\uc744 \ucc3e\uac8c \ud55c\ub2e4. \uac00\uc7a5 \uc720\uba85\ud55c \ud68c\uc6d0\uc740 \uc655\uc758 \ubc29\ub791\ubcbd \uc788\ub294 \ub3d9\uc0dd \ube0c\ub780 \ube0c\ub860\uc988\ube44\uc5b4\ub4dc\ub2e4. \uc5f0\ub9f9\uc758 \ubc1c\uad74\ub2e8\uc740 \uc6b8\ub2e4\ub9cc\uc758 \ud2f0\ud0c4 \uae08\uace0\ub97c \ucc3e\uc544\ub0c8\uace0, Forever\uc5d0\uc11c \uc800\uc2b5\uc9c0\uc758 Whelgar's Excavation Site \ub108\uba38\uc5d0 \uc788\ub294, \uc2dc\uac04\uc774 \uba48\ucd98 \ub4ef\ud55c \uae30\ubb18\ud55c \ud3d0\ud5c8\ub294 \ubc14\ub85c \uc5f0\ub9f9\uc774 \ucad3\ub294 \uc885\ub958\uc758 \uc218\uc218\uaed8\ub07c\ub2e4."]},"term:fel":{title:"\uc9c0\uc625 \ub9c8\ubc95",summary:"\ubd88\ud0c0\ub294 \uad70\ub2e8\uc758 \ud0c0\uc624\ub974\uba70 \ud0c0\ub77d\uc2dc\ud0a4\ub294 \ub9c8\ubc95.",body:["\uc9c0\uc625 \ub9c8\ubc95\uc740 \uc545\ub9c8\uc758 \ub9c8\ubc95\uc774\ub2e4. \uac15\ub825\ud558\uace0 \uc911\ub3c5\uc131\uc774 \uc788\uc73c\uba70, \ub2ff\ub294 \ubaa8\ub4e0 \uac83\uc744 \ud30c\uba78\uc2dc\ud0a8\ub2e4. \uad74\ub2e8\uc758 \ud751\ub9c8\ubc95\uc0ac\ub4e4\uc740 \uc774 \ub9c8\ubc95\uc73c\ub85c \ub4dc\ub808\ub178\uc5b4\uc758 \uc0dd\uba85\ub825\uc744 \ube68\uc544\ub4e4\uc774\uace0 \uc624\ud06c\ub4e4\uc744 \uad70\ub2e8\uc5d0 \ubb36\uc5c8\uc73c\uba70, \uadf8 \uc624\uc5fc \ub54c\ubb38\uc5d0 \uc624\ud06c\uc758 \ud53c\ubd80\ub294 \ucd08\ub85d\uc0c9\uc73c\ub85c \ubcc0\ud588\ub2e4. \ud751\ub9c8\ubc95\uc0ac\ub4e4\uc740 \uc9c0\uae08\ub3c4 \uc774 \ub9c8\ubc95\uc744 \ub2e4\ub8e8\uba70, \uadf8 \uc0c1\ucc98\ub294 \uc545\ub9c8\uc758 \ud0c0\ub77d\uc774 \uace0\ub300\uc758 \uc232\uc744 \uc911\ub3c5\uc2dc\ud0a8 \uc545\ub839\uc758 \uc232\uc5d0 \ub0a8\uc544 \uc788\ub2e4."]},"term:guardian-of-tirisfal":{title:"\ud2f0\ub9ac\uc2a4\ud314\uc758 \uc218\ud638\uc790",summary:"\ud640\ub85c \ubd88\ud0c0\ub294 \uad70\ub2e8\uacfc \uc2f8\uc6b0\ub3c4\ub85d \ube44\ubc00 \uc758\ud68c\uc758 \ud798\uc744 \ubaa8\ub450 \ubc1b\uc740 \ub9c8\ubc95\uc0ac.",body:["\ud558\uc774 \uc5d8\ud504\uc640 \uc778\uac04 \ub9c8\ubc95\uc0ac\ub4e4\uc740 \uacbd\uc194\ud55c \ub9c8\ubc95\uc744 \ud2c8\ud0c0 \uc545\ub9c8\uac00 \uc138\uc0c1\uc5d0 \uc2a4\uba70\ub4dc\ub294 \uac83\uc744 \ub9c9\uc73c\ub824\uace0 \ube44\ubc00 \uacb0\uc0ac\uc778 \ud2f0\ub9ac\uc2a4\ud314 \uc758\ud68c\ub97c \uc138\uc6e0\ub2e4. \uc758\ud68c\ub294 \uc2dc\ub300\ub9c8\ub2e4 \ud55c \uba85\uc758 \uc218\ud638\uc790\uc5d0\uac8c \uc790\uc2e0\ub4e4\uc758 \ud798\uc744 \uc3df\uc544\ubd80\uc5c8\ub2e4. \uc5d0\uc774\uadf8\uc708\uc740 \uc218\ubc31 \ub144 \ub3d9\uc548 \uadf8 \uc5ed\ud560\uc744 \ub9e1\uc558\uace0, \uadf8\ub140\uc758 \uc544\ub4e4\uc774\uc790 \ub9c8\uc9c0\ub9c9 \uc218\ud638\uc790\uc778 \uba54\ub514\ube0c\ub294 \ub0a8\ubab0\ub798 \uc0b4\uac8c\ub77c\uc2a4\uc5d0\uac8c \ube59\uc758\ub418\uc5b4 \uc624\ud06c\ub4e4\uc5d0\uac8c \uae38\uc744 \uc5f4\uc5b4 \uc8fc\uc5c8\ub2e4."]},"term:highborne":{title:"\uba85\uac00",summary:"\uace0\ub300 \ub098\uc774\ud2b8 \uc5d8\ud504 \uc81c\uad6d\uc758 \ube44\uc804 \uadc0\uc871\uc73c\ub85c, \ub9c8\ubc95\uc5d0 \ub300\ud55c \uac08\ub9dd\uc774 \uad70\ub2e8\uc744 \ubd88\ub7ec\ub4e4\uc600\ub2e4.",body:["\uba85\uac00\ub294 \uc5ec\uc655 \uc544\uc988\uc0e4\ub77c\uc758 \uad81\uc815\uc774\uc790 \ub9c8\ubc95\uc0ac\ub85c\uc11c \uadf8\ub140\ub97c \uc12c\uacbc\uace0, \uc601\uc6d0\uc758 \uc0d8\uc758 \ud798\uc744 \uc810\uc810 \ub354 \uae4a\uc774 \ub04c\uc5b4 \uc4f0\ub2e4\uac00 \uacb0\uad6d \uadf8\ub4e4\uc758 \uc8fc\ubb38\uc774 \uc0b4\uac8c\ub77c\uc2a4\uc758 \ub208\uc5d0 \ub744\uace0 \ub9d0\uc558\ub2e4. \uc138\uacc4\uc758 \ubd84\ub9ac \uc774\ud6c4 \uc0b4\uc544\ub0a8\uc740 \ub300\ubd80\ubd84\uc740 \ucd94\ubc29\ub418\uc5b4 \ud558\uc774 \uc5d8\ud504\ub85c\uc11c \ucfe0\uc5d8\ud0c8\ub77c\uc2a4\ub97c \uc138\uc6e0\ub2e4. \ub2e4\ub978 \uc774\ub4e4, \uace7 \uc174\ub4dc\ub784\ub77c\ub294 \uc9c0\uae08 \ud608\ud22c\uc758 \uc804\uc7a5\uc774\ub77c \ubd88\ub9ac\ub294 \ub3c4\uc2dc \uc5d8\ub4dc\ub808\ud0c8\ub77c\uc2a4\uc5d0 \uc228\uc5b4 \uc9c0\ub0c8\ub2e4."]},"term:holy-light":{title:"\uc131\uc2a4\ub7ec\uc6b4 \ube5b",summary:"\uc131\uae30\uc0ac\uc640 \uc0ac\uc81c\uac00 \ub2e4\ub8e8\ub294 \ud76c\ub9dd\uacfc \ubbf8\ub355\uc758 \ud798.",body:["\uc778\uac04\uc740 \uc131\uc2a4\ub7ec\uc6b4 \ube5b\uc758 \uad50\ud68c\ub97c \ud1b5\ud574 \ube5b\uc744 \uc22d\ubc30\ud55c\ub2e4. \uad50\ud68c\uc758 \uc131\uc9c1\uc790\ub4e4\uc740 \ubd80\uc0c1\uc790\ub97c \uce58\uc720\ud558\uba70, \uadf8 \ub300\uc131\ub2f9\uc740 \uc2a4\ud1b0\uc708\ub4dc\uc5d0 \uc19f\uc544 \uc788\uace0 \ud55c\ub54c \ub85c\ub370\ub860\uc5d0\ub3c4 \uc11c \uc788\uc5c8\ub2e4. \ub4dc\uc6cc\ud504 \uc5ed\uc2dc \ube5b\uc744 \ubc1b\uc544\ub4e4\uc600\ub2e4. \uc81c2\ucc28 \ub300\uc804\uc7c1 \ub3d9\uc548 \ub300\uc8fc\uad50 \uc54c\ub860\uc11c\uc2a4 \ud30c\uc62c\uc740 \ubc31\uc740\uc758 \uc190 \uc131\uae30\uc0ac\ub2e8\uc744 \uc138\uc6cc \uc2e0\uc559\uacfc \uac15\ucca0\uc744 \ud558\ub098\ub85c \ubb36\uc5c8\uc73c\uba70, \ube5b\uc740 \uc9c0\uae08\ub3c4 \uc5b8\ub370\ub4dc\uc758 \ucc9c\uc801\uc73c\ub85c \ub0a8\uc544 \uc788\ub2e4."]},"term:kaldorei":{title:"\uce7c\ub3c4\ub808\uc774",summary:"\u2018\ubcc4\uc758 \uc790\uc190\u2019\uc774\ub77c \ubd88\ub9ac\ub294 \ub098\uc774\ud2b8 \uc5d8\ud504\ub85c, \uce7c\ub9bc\ub3c4\uc5b4\uc5d0\uc11c \uac00\uc7a5 \uc624\ub798\ub41c \ubb38\uba85 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4.",body:["\uc601\uc6d0\uc758 \uc0d8\uc73c\ub85c \ubcc0\ud55c \ud2b8\ub864\uc758 \ud6c4\uc190\uc778 \ub098\uc774\ud2b8 \uc5d8\ud504\ub294 \uc5ec\uc655 \uc544\uc988\uc0e4\ub77c \uc544\ub798\uc5d0\uc11c \ub208\ubd80\uc2e0 \uc81c\uad6d\uc744 \uc138\uc6e0\uc9c0\ub9cc, \uadf8 \uc81c\uad6d\uc740 \uc138\uacc4\uc758 \ubd84\ub9ac \ub54c \ubc14\ub2e4\uc5d0 \uc7a0\uacbc\ub2e4. \uadf8 \ub4a4 \ub9cc \ub144 \ub3d9\uc548 \uadf8\ub4e4\uc740 \ub180\ub4dc\ub78f\uc2e4 \ub355\ubd84\uc5d0 \ub299\uc9c0 \uc54a\uc740 \ucc44 \ub4dc\ub8e8\uc774\ub4dc\uc640 \ud30c\uc218\uafbc\uc73c\ub85c \uc0b4\uc558\uc73c\ub098, \uc81c3\ucc28 \ub300\uc804\uc7c1\uc73c\ub85c \ubd88\uba78\uc744 \uc783\uc5c8\ub2e4. \uc624\ub298\ub0a0 \uadf8\ub4e4\uc740 \ud154\ub4dc\ub78f\uc2e4 \uc704\uc758 \ub2e4\ub974\ub098\uc11c\uc2a4\uc5d0\uc11c \ub098\ub77c\ub97c \ub2e4\uc2a4\ub9ac\uba70 \uc5bc\ub77c\uc774\uc5b8\uc2a4\uc640 \ud568\uaed8\ud55c\ub2e4."]},"term:kirin-tor":{title:"\ud0a4\ub9b0 \ud1a0",summary:"\ub2ec\ub77c\ub780\uc744 \ub2e4\uc2a4\ub9ac\uace0 \uc704\ud5d8\ud55c \ub9c8\ubc95\uc744 \uc9c0\ud0a4\ub294 \ub9c8\ubc95\uc0ac\ub4e4\uc758 \ud1b5\uce58 \uc758\ud68c.",body:["\ub9c8\ubc95\uc0ac\uc758 \ub3c4\uc2dc \ub2ec\ub77c\ub780\uc5d0\uc11c \uc138\uc6cc\uc9c4 \ud0a4\ub9b0 \ud1a0\ub294 \ube44\uc804 \ub9c8\ubc95 \uc5f0\uad6c\ub97c \uac10\ub3c5\ud558\uace0, \uc138\uc0c1\uc5d0 \ub0b4\ub193\uae30\uc5d4 \ub108\ubb34 \uc704\ud5d8\ud55c \uc720\ubb3c\uc744 \ubd09\uc778\ud55c\ub2e4. \uc81c3\ucc28 \ub300\uc804\uc7c1 \ub54c \uc544\ud0a4\ubaac\ub4dc\ub294 \ub2ec\ub77c\ub780\uc744 \ud3d0\ud5c8\ub85c \ub9cc\ub4e4\uc5c8\uace0, \uc624\ub9ac\uc9c0\ub110 \uac8c\uc784\uc5d0\uc11c \ub3c4\uc2dc\ub294 \ubcf4\ub78f\ube5b \ub3d4 \uc544\ub798 \uc228\uaca8\uc838 \uc788\uc5c8\ub2e4. Forever\uc5d0\uc11c\ub294 \uadf8 \uc7a5\ubcbd\uc774 \ubb34\ub108\uc838, \uc81c\uba4b\ub300\ub85c \ud130\uc9c0\ub294 \ube44\uc804\uc758 \ud63c\ub3c8\uc5d0 \ub4a4\ub36e\uc778 \uc7ac\uac74 \ud604\uc7a5\uc774 \ub4dc\ub7ec\ub0ac\ub2e4."]},"term:ley-lines":{title:"\uc9c0\ub9e5",summary:"\ud608\uad00\ucc98\ub7fc \uc544\uc81c\ub85c\uc2a4\ub97c \uac00\ub85c\uc9c8\ub7ec \ud750\ub974\ub294 \ube44\uc804 \uc5d0\ub108\uc9c0\uc758 \ubb3c\uc904\uae30.",body:["\uc9c0\ub9e5\uc740 \uc21c\uc218\ud55c \ube44\uc804\uc758 \ud798\uc744 \uc628 \uc138\uc0c1\uc73c\ub85c \uc2e4\uc5b4 \ub098\ub974\uba70, \uc9c0\ub9e5\uc774 \uad50\ucc28\ud558\ub294 \uacf3\uc5d0\uc11c\ub294 \ub9c8\ubc95\uc774 \ub354 \uac15\ud558\uac8c \ubaa8\uc778\ub2e4. \ud558\uc774 \uc5d8\ud504\ub294 \uadf8\ub7f0 \uad50\ucc28\uc810\uc5d0 \ud0dc\uc591\uc0d8\uc744 \uc138\uc6e0\uace0, \ub9c8\ubc95\uc0ac\ub4e4\uc740 \uc624\ub798\uc804\ubd80\ud130 \uc774 \ud750\ub984\uc744 \ucc3e\uc544\ub2e4\ub154\ub2e4. Forever\uc5d0\uc11c High Order\uc758 Skyborne\uc740 \uc885\uc871 \ud2b9\uc131 Read Ley Line\uc73c\ub85c \uc9c0\ub9e5\uc758 \ud798\uc744 \ub04c\uc5b4 \uc4f8 \uc218 \uc788\uc73c\uba70, \uc9c0\ub9e5 \uac00\uae4c\uc774\uc5d0\uc11c \uc4f0\uba74 \ud6a8\uacfc\uac00 \ud6e8\uc52c \uc624\ub798\uac04\ub2e4."]},"term:lich-king":{title:"\ub9ac\uce58 \uc655",summary:"\ub178\uc2a4\ub80c\ub4dc\uc758 \uc5bc\uc74c \uc18d \uc655\uc88c\uc5d0 \uc549\uc740, \uc8fd\uc9c0 \uc54a\ub294 \uc2a4\uceec\uc9c0\uc758 \uc8fc\uc778.",body:["\ud0ac\uc81c\ub374\uc740 \uad70\ub2e8\uc744 \uc704\ud574 \uc544\uc81c\ub85c\uc2a4\ub97c \uc900\ube44\uc2dc\ud0a4\ub824\uace0 \uc624\ud06c \uc8fc\uc220\uc0ac \ub12c\uc974\uc758 \uc601\ud63c\uc744 \uc721\uccb4\uc5d0\uc11c \ub5bc\uc5b4 \ub0b4 \uc5bc\uc74c\uc655\uad00 \uaf2d\ub300\uae30\uc758 \uc5bc\uc74c\ub369\uc5b4\ub9ac, \uace7 \uc5bc\uc5b4\ubd99\uc740 \uc655\uc88c\uc5d0 \ubd09\uc778\ud588\ub2e4. \ub9ac\uce58 \uc655\uc740 \uadf8\uacf3\uc5d0\uc11c \uc2a4\uceec\uc9c0\ub97c \uc77c\uc73c\ud0a4\uace0 \uc5ed\ubcd1\uc744 \ud37c\ub728\ub838\ub2e4. \uc81c3\ucc28 \ub300\uc804\uc7c1 \uc774\ud6c4 \uc544\uc11c\uc2a4 \uc655\uc790\uac00 \uc655\uc88c\uc5d0 \uc62c\ub77c \uadf8\uc640 \ud558\ub098\uac00 \ub418\uc5c8\uace0, \ud558\ub098\ub85c \ud569\uccd0\uc9c4 \ub9ac\uce58 \uc655\uc740 \uc9c0\uae08 \ub178\uc2a4\ub80c\ub4dc\uc5d0\uc11c \ub54c\ub97c \uae30\ub2e4\ub9ac\uace0 \uc788\ub2e4."]},"term:loa":{title:"\ub85c\uc544",summary:"\ud2b8\ub864\uc774 \uc22d\ubc30\ud558\ub294 \uac15\ub825\ud55c \ub3d9\ubb3c \uc815\ub839\uc774\uc790 \uc2e0.",body:["\ubaa8\ub4e0 \ud2b8\ub864 \ubd80\uc871\uc740 \ud754\ud788 \uac70\ub300\ud55c \uc9d0\uc2b9\uc758 \ubaa8\uc2b5\uc744 \ud55c \uace0\ub300 \uc815\ub839\uc778 \ub85c\uc544\ub97c \uc12c\uae30\uba70, \ud798\uc744 \uc5bb\uae30 \uc704\ud574 \uadf8\ub4e4\uacfc \uac70\ub798\ud55c\ub2e4. \ubcc0\ub355\uc2a4\ub7fd\uc9c0\ub9cc \uacf5\uc815\ud55c \ub85c\uc544\ub3c4 \uc788\uace0, \uc794\ud639\ud55c \ub85c\uc544\ub3c4 \uc788\ub2e4. \ud53c\uc758 \ub85c\uc544\uc778 \uc601\ud63c\uc57d\ud0c8\uc790 \ud559\uce74\ub974\ub294 \uad6c\ub8e8\ubc14\uc2dc \uc81c\uad6d\uc744 \uac70\uc758 \uc9d1\uc5b4\uc0bc\ud0ac \ubed4\ud588\uc73c\uba70, \uadf8\uc758 \ucd94\uc885\uc790\ub4e4\uc740 \uc9c0\uae08\ub3c4 \uac00\uc2dc\ub364\ubd88 \uace8\uc9dc\uae30\uc640 \uc2ac\ud514\uc758 \ub2aa\uc5d0\uc11c \uafc8\ud2c0\uac70\ub9ac\uace0 \uc788\ub2e4."]},"term:nathrezim":{title:"\ub098\uc2a4\ub808\uc9d0",summary:"\uae30\ub9cc\uc73c\ub85c \uad70\ub2e8\uc744 \uc12c\uae30\ub294 \uad50\ud65c\ud55c \ud761\ud608 \uc545\ub9c8, \uacf5\ud3ec\uc758 \uad70\uc8fc.",body:["\ub098\uc2a4\ub808\uc9d0\uc740 \uacf5\uacf5\uc5f0\ud55c \uc804\uc7c1\ubcf4\ub2e4 \uc18d\uc0ad\uc784\uc744 \uc990\uae34\ub2e4. \uad70\ub2e8\uc740 \ub9d0\uac00\ub2c8\uc2a4, \ud2f0\ucf58\ub4dc\ub9ac\uc6b0\uc2a4, \ubc1c\ub098\uc790\ub974 \uac19\uc740 \uacf5\ud3ec\uc758 \uad70\uc8fc\ub4e4\uc5d0\uac8c \ub9ac\uce58 \uc655\uc744 \uac10\uc2dc\ud558\uace0 \uc2a4\uceec\uc9c0\uc758 \ub85c\ub370\ub860 \uc815\ubcf5\uc744 \uc774\ub04c\uac8c \ud588\ub2e4. \ub9ac\uce58 \uc655\uc774 \uadf8\ub4e4\uc758 \uc190\uc544\uadc0\uc5d0\uc11c \ubc97\uc5b4\ub098\uc790 \uadf8\ub4e4\uc740 \ud769\uc5b4\uc84c\uc9c0\ub9cc, \uc77c\ubd80\ub294 \uc5ec\uc804\ud788 \ubc84\uc813\uc774 \ubaa8\uc2b5\uc744 \uc228\uae30\uace0 \uc788\ub2e4. \ubc1c\ub098\uc790\ub974\ub294 \ubd89\uc740\uc2ed\uc790\uad70 \ub300\uc131\uc804\uae30\uc0ac\uc758 \uc5bc\uad74\uc744 \ud558\uace0 \uc788\ub2e4."]},"term:nordrassil":{title:"\ub180\ub4dc\ub78f\uc2e4",summary:"\ub450 \ubc88\uc9f8 \uc601\uc6d0\uc758 \uc0d8\uc744 \ubd09\uc778\ud558\ub824\uace0 \uc704\uc0c1\ub4e4\uc774 \ud558\uc774\uc798 \uc0b0\uc5d0 \ud0a4\uc6b4 \uc138\uacc4\uc218.",body:["\uc138\uacc4\uc758 \ubd84\ub9ac \uc774\ud6c4 \uc77c\ub9ac\ub2e8\uc740 \uc601\uc6d0\uc758 \uc0d8\uc5d0\uc11c \ud6d4\uce5c \ubb3c\uc744 \ubab0\ub798 \ud558\uc774\uc798 \uc0b0\uc758 \ud638\uc218\uc5d0 \ubd80\uc5c8\ub2e4. \uc774 \uc0c8\ub85c\uc6b4 \uc0d8\uc744 \ubd09\uc778\ud558\ub824\uace0 \uc704\uc0c1\ub4e4\uc740 \ub9c8\ubc95\uc774 \uae43\ub4e0 \uc528\uc557\uc744 \uc2ec\uc5c8\uace0, \uc528\uc557\uc740 \ub180\ub4dc\ub78f\uc2e4\ub85c \uc790\ub77c\ub0ac\uc73c\uba70, \uadf8 \ucd95\ubcf5\uc73c\ub85c \ub098\uc774\ud2b8 \uc5d8\ud504\ub294 \ub299\uc9c0 \uc54a\uac8c \ub418\uc5c8\ub2e4. \uc544\ud0a4\ubaac\ub4dc\uac00 \uadf8 \ubfcc\ub9ac\uc5d0\uc11c \uc4f0\ub7ec\uc9c0\uba70 \ub098\ubb34\ub294 \uc0c1\ucc98\ub97c \uc785\uc5c8\uace0, Forever\uc758 Hyjal Summit \uacf5\uaca9\ub300\ub294 \uadf8 \uacc1\uc758 \uc815\uc0c1\uae4c\uc9c0 \uc62c\ub77c\uac04\ub2e4."]},"term:old-gods":{title:"\uace0\ub300 \uc2e0",summary:"\uc544\uc81c\ub85c\uc2a4\uc758 \uc138\uacc4\ud63c\uc744 \ud0c0\ub77d\uc2dc\ud0a4\ub824\uace0 \ub545\uc18d\uc5d0 \uc790\uc2e0\uc744 \ubb3b\uc740 \uacf5\ud5c8\uc758 \uace0\ub300 \uc874\uc7ac\ub4e4.",body:["\ud544\uba78\uc790\uac00 \uc138\uc0c1\uc744 \uac77\uae30 \ud6e8\uc52c \uc804, \ud06c\ud230, \uc694\uadf8\uc0ac\ub860, \ub290\uc870\uc2a4, \uc774\uc0e4\ub77c\uc988\ub97c \ube44\ub86f\ud55c \uace0\ub300 \uc2e0\ub4e4\uc774 \uc544\uc81c\ub85c\uc2a4\uc5d0 \ub5a8\uc5b4\uc838 \uac80\uc740 \uc81c\uad6d\uc744 \uc77c\uc73c\ucf30\ub2e4. \uc774\uc0e4\ub77c\uc988\ub97c \ub72f\uc5b4\ub0b4\uc790 \uc138\uacc4 \uc790\uccb4\uac00 \uc0c1\ucc98\ub97c \uc785\uc5c8\uae30\uc5d0, \ud2f0\ud0c4\uc740 \ub098\uba38\uc9c0\ub97c \ub545\uc18d\uc5d0 \uac00\ub450\ub294 \uae38\uc744 \ud0dd\ud588\ub2e4. \uadf8\ub4e4\uc758 \uc18d\uc0ad\uc784\uc740 \uc9c0\uae08\ub3c4 \ud669\ud63c\uc758 \ub9dd\uce58 \uac19\uc740 \uad50\ub2e8\uc744 \uc6c0\uc9c1\uc774\uba70, \ud06c\ud230\uc740 \uc2e4\ub9ac\ub354\uc2a4\uc758 \uc548\ud034\ub77c\uc988 \uc544\ub798\uc5d0\uc11c \uafc8\ud2c0\uac70\ub9ac\uace0 \uc788\ub2e4."]},"term:silver-hand":{title:"\ubc31\uc740\uc758 \uc190 \uae30\uc0ac\ub2e8",summary:"\uc81c2\ucc28 \ub300\uc804\uc7c1 \uc911 \ub85c\ub370\ub860\uc5d0\uc11c \uc138\uc6cc\uc9c4 \ucd5c\ucd08\uc758 \uc131\uae30\uc0ac\ub2e8.",body:["\ub300\uc8fc\uad50 \uc54c\ub860\uc11c\uc2a4 \ud30c\uc62c\uc740 \uc131\uc9c1\uc790\ub9cc\uc73c\ub85c\ub294 \ud638\ub4dc\ub97c \ubc84\ud2f8 \uc218 \uc5c6\ub2e4\uace0 \ubcf4\uace0, \uc804\uc0ac\ub4e4\uc5d0\uac8c \ube5b\uc758 \uae38\uc744 \uac00\ub974\ucce4\ub2e4. \ube5b\uc758 \uc218\ud638\uc790 \uc6b0\uc11c\uac00 \ubc31\uc740\uc758 \uc190\uc758 \uccab \uae30\uc0ac\uac00 \ub418\uc5c8\ub2e4. \uae30\uc0ac\ub2e8\uc740 \uc81c2\ucc28 \ub300\uc804\uc7c1\uc744 \ub05d\uae4c\uc9c0 \uc2f8\uc6cc \ub0c8\uc9c0\ub9cc, \uc544\uc11c\uc2a4\uc758 \ud0c0\ub77d\uc73c\ub85c \ubb34\ub108\uc84c\ub2e4. \uc6b0\uc11c\ub294 \uc61b \uc81c\uc790\uc758 \uc190\uc5d0 \uc8fd\uc5c8\uace0, \uc0b4\uc544\ub0a8\uc740 \uc774\ub4e4 \ub2e4\uc218\ub294 \ubd89\uc740\uc2ed\uc790\uad70\uc73c\ub85c \ud758\ub7ec\ub4e4\uc5c8\ub2e4."]},"term:queldorei":{title:"\ucfe0\uc5d8\ub3c4\ub808\uc774",summary:"\ucd94\ubc29\ub41c \uba85\uac00\uc758 \ud6c4\uc608\uc778 \ucfe0\uc5d8\ud0c8\ub77c\uc2a4\uc758 \ud558\uc774 \uc5d8\ud504.",body:["\uc5b4\ub460\uc758 \ubb38\uc774 \uc5f4\ub9ac\uae30 \uc57d \uce60\ucc9c \ub144 \uc804, \ucd94\ubc29\ub41c \uba85\uac00\ub294 \ubc14\ub2e4\ub97c \uac74\ub108 \ucfe0\uc5d8\ud0c8\ub77c\uc2a4\ub97c \uc138\uc6b0\uace0 \ud0dc\uc591\uc0d8\uc5d0 \ubd88\uc744 \ubc1d\ud614\ub2e4. \uadf8\ub4e4\uc740 \ud2b8\ub864 \uc804\uc7c1\uc5d0\uc11c \uc544\ub77c\uc18c\ub974\uc758 \uc778\uac04\ub4e4\uacfc \ub3d9\ub9f9\uc744 \ub9fa\uace0 \uadf8\ub4e4\uc5d0\uac8c \ub9c8\ubc95\uc744 \uac00\ub974\ucce4\ub2e4. \uc544\uc11c\uc2a4\uc758 \uc2a4\uceec\uc9c0\uac00 \uc655\uad6d\uc744 \uc9d3\ubc1f\uace0 \ud0dc\uc591\uc0d8\uc744 \ub354\ub7fd\ud788\uc790, \uc0b4\uc544\ub0a8\uc740 \ub300\ubd80\ubd84\uc740 \uc8fd\uc740 \uc774\ub4e4\uc744 \uae30\ub9ac\uba70 \uc0c8 \uc774\ub984\uc744 \ubc1b\uc544\ub4e4\uc600\ub2e4. \ubc14\ub85c \uc2e0\ub3c4\ub808\uc774, \uace7 \ube14\ub7ec\ub4dc \uc5d8\ud504\ub2e4."]},"term:scarlet-crusade":{title:"\ubd89\uc740\uc2ed\uc790\uad70",summary:"\uc5b8\ub370\ub4dc\uc640 \uc5ed\ubcd1\uc774 \uc758\uc2ec\ub418\ub294 \uc790\ub294 \ub204\uad6c\ub4e0 \uc0ac\ub0e5\ud558\ub294 \uad11\uc2e0\uc790\ub4e4\ub85c, \ub0a8\ubab0\ub798 \uacf5\ud3ec\uc758 \uad70\uc8fc\uac00 \uc774\ub048\ub2e4.",body:["\ub85c\ub370\ub860\uc758 \uc131\uae30\uc0ac\uc640 \ubcd1\uc0ac \uc0dd\uc874\uc790\ub4e4\uc5d0\uac8c\uc11c \ud0dc\uc5b4\ub09c \uc2ed\uc790\uad70\uc740 \uc2a4\uceec\uc9c0\ub97c \uc4f8\uc5b4\ubc84\ub9ac\uaca0\ub2e4\uace0 \ub9f9\uc138\ud588\uc9c0\ub9cc, \ub108\ubb34\ub3c4 \uad11\uc2e0\uc801\uc73c\ub85c \ubcc0\ud55c \ub098\uba38\uc9c0 \ud3ec\uc138\uc774\ud070\uacfc \uc0b4\uc544 \uc788\ub294 \uc5ec\ud589\uc790\ub97c \uac00\ub9ac\uc9c0 \uc54a\uace0 \uacf5\uaca9\ud55c\ub2e4. \uc2ed\uc790\uad70\uc758 \ub300\uc131\uc804\uae30\uc0ac\ub294 \uc0ac\uc2e4 \uacf5\ud3ec\uc758 \uad70\uc8fc \ubc1c\ub098\uc790\ub974\ub2e4. \uc8fc\uc694 \uac70\uc810\uc73c\ub85c\ub294 \ud2f0\ub9ac\uc2a4\ud314 \uc232\uc758 \ubd89\uc740\uc2ed\uc790\uad70 \uc218\ub3c4\uc6d0, \ud558\uc2a4\uae00\ub80c, \ud2f0\ub974\uc758 \uc190\uc774 \uc788\ub2e4."]},"term:scourge":{title:"\uc2a4\uceec\uc9c0",summary:"\uc5ed\ubcd1\uacfc \uac15\ub839\uc220\ub85c \ud37c\uc9c0\ub294 \ub9ac\uce58 \uc655\uc758 \uc5b8\ub370\ub4dc \uad70\ub300.",body:["\uc2a4\uceec\uc9c0\ub294 \ub9ac\uce58 \uc655\uc758 \uc758\uc9c0\uc5d0 \ubb36\uc5ec \uc788\ub2e4. \uc4f0\ub7ec\uc9c4 \uc790\ub4e4\uc5d0\uac8c\uc11c \uc77c\uc73c\ucf1c\uc9c4 \uad6c\uc6b8, \ub204\ub354\uae30\uace8\ub818, \ub9ac\uce58, \uc8fd\uc74c\uc758 \uae30\uc0ac\uac00 \uadf8\ub4e4\uc774\ub2e4. \uadf8\ub4e4\uc744 \ub9cc\ub4e4\uc5b4 \ub0b8 \uc5ed\ubcd1\uc740 \uc81c3\ucc28 \ub300\uc804\uc7c1 \ub54c \ub85c\ub370\ub860\uc744 \ud729\uc4f8\uace0 \uc5ed\ubcd1\uc9c0\ub300\ub97c \ub0a8\uacbc\ub2e4. \ucf08\ud22c\uc790\ub4dc \ud718\ud558\uc758 \uc2a4\uceec\uc9c0\ub294 \uc9c0\uae08\ub3c4 \uc2a4\ud2b8\ub77c\uc194\ub984\uacfc \uc2a4\uce7c\ub85c\ub9e8\uc2a4\ub97c \uc7a5\uc545\ud558\uace0 \uc788\uc73c\uba70, \uadf8 \uc190\uae38\uc740 \ubd88\ubaa8\uc758 \ub545\uc5d0 \uc788\ub294 \uac00\uc2dc\ub369\uad74 \uad6c\ub989\uae4c\uc9c0 \ubed7\uc5b4 \uc788\ub2e4."]},"term:skywall":{title:"Skywall",summary:"\ubc14\ub78c\uc758 \uad70\uc8fc \uc54c\uc544\ud0a4\ub974\uac00 \ub2e4\uc2a4\ub9ac\ub294 \ubc14\ub78c\uc758 \uc815\ub839\uacc4.",body:["\ud2f0\ud0c4\uc758 \uc885\ub4e4\uc774 \uc815\ub839\ub4e4\uc744 \uac00\ub450\uc5c8\uc744 \ub54c, \ubc14\ub78c\uc758 \uad70\uc8fc\ub4e4\uc740 \uc54c\uc544\ud0a4\ub974\uac00 \ub2e4\uc2a4\ub9ac\ub294 \ub05d\uc5c6\ub294 \ud558\ub298\uc758 \uc601\uc5ed Skywall\uc5d0 \uac07\ud614\ub2e4. Forever\uc5d0\uc11c Skywall\uc740 Skyborne\uc758 \ub5a0\ub2e4\ub2c8\ub294 \uc2dc\uc791 \uc9c0\uc5ed\uc778 Zephras Isle\uc758 \uace0\ud5a5\uc774\uae30\ub3c4 \ud558\ub2e4. \uc12c\uc758 \ubc14\ub78c \uc815\ub839\ub4e4\uc740 \uc218\ubc31 \ub144 \uc804\uc5d0 \uc0ac\ub77c\uc84c\uace0, \uc12c\uc744 \ud558\ub298\uc5d0 \ub744\uc6cc \ub454 \ub9c8\ubc95\uc740 \uc11c\uc11c\ud788 \uc57d\ud574\uc9c0\uace0 \uc788\ub2e4."]},"term:sunwell":{title:"\ud0dc\uc591\uc0d8",summary:"\ucfe0\uc5d8\ud0c8\ub77c\uc2a4\uc758 \uc2ec\uc7a5\ubd80\uc5d0 \uc790\ub9ac\ud55c \ube44\uc804\uc758 \uc6d0\ucc9c.",body:["\ub2e4\uc2a4\ub808\ub9c8\ub974 \uc120\uc2a4\ud2b8\ub77c\uc774\ub354\ub294 \uc601\uc6d0\uc758 \uc0d8\uc5d0\uc11c \ud6d4\uce5c \ubb3c\ubcd1 \ud558\ub098\ub97c \uc9c0\ub9e5\uc774 \ub9cc\ub098\ub294 \ud638\uc218\uc5d0 \ubd80\uc5c8\uace0, \ud0dc\uc591\uc0d8\uc774 \ud658\ud558\uac8c \ud0c0\uc624\ub974\uba70 \uc0dd\uaca8\ub0ac\ub2e4. \uc218\ucc9c \ub144 \ub3d9\uc548 \ud0dc\uc591\uc0d8\uc740 \ud558\uc774 \uc5d8\ud504\uc758 \ub9c8\ubc95\uacfc \ubb38\ud654\ub97c \uae38\ub7ec \ub0c8\ub2e4. \uc81c3\ucc28 \ub300\uc804\uc7c1 \ub54c \uc544\uc11c\uc2a4\ub294 \uadf8 \ubb3c\ub85c \ucf08\ud22c\uc790\ub4dc\ub97c \ub9ac\uce58\ub85c \ub418\uc0b4\ub9ac\uba74\uc11c \uc6d0\ucc9c\uc744 \ub354\ub7fd\ud614\uace0, \ud0dc\uc591\uc0d8\uc744 \uc783\uc740 \uc0dd\uc874\uc790\ub4e4\uc5d0\uac8c\ub294 \ub9c8\ubc95\uc5d0 \ub300\ud55c \ub05d\uc5c6\ub294 \uad76\uc8fc\ub9bc\uc774 \ub0a8\uc558\ub2e4."]},"term:titan-forged":{title:"\ud2f0\ud0c4 \ud53c\uc870\ubb3c",summary:"\uc544\uc81c\ub85c\uc2a4\uc5d0 \uc9c8\uc11c\ub97c \uc138\uc6b0\ub824\uace0 \ud2f0\ud0c4\uc774 \ub9cc\ub4e0 \uad00\ub9ac\uc790\uc640 \uadf8 \ubc16\uc758 \uc885\ub4e4.",body:["\ud2f0\ud0c4\uc740 \uc790\uc2e0\ub4e4\uc758 \uc77c\uc744 \ub9c8\ubb34\ub9ac\ud560 \uc885\ub4e4\uc744 \ube5a\uc5b4\ub0c8\ub2e4. \uc6b0\ub69d \uc19f\uc740 \uad00\ub9ac\uc790\ub4e4, \uadf8\ub9ac\uace0 \ub300\uc9c0\uc778\uacfc \uae30\uacc4\ub178\uc6c0\ucc98\ub7fc \ub3cc\uacfc \uae08\uc18d\uc73c\ub85c \ub41c \uc885\uc871\ub4e4\uc774\ub2e4. \uc624\ub79c \uc138\uc6d4 \ub3d9\uc548 \uace0\ub300 \uc2e0\uc758 \uc721\uc2e0\uc758 \uc800\uc8fc\uac00 \uadf8\ub4e4 \uc911 \ub9ce\uc740 \uc218\ub97c \ud544\uba78\uc790\ub85c \ubc14\uafb8\uc5c8\uace0, \ub4dc\uc6cc\ud504\uc640 \ub178\uc6c0\uc740 \uadf8\ub4e4\uc758 \ud6c4\uc190\uc774\ub2e4. \ud2f0\ud0c4 \ud53c\uc870\ubb3c \uc218\ud638\uc790\ub4e4\uc740 \uc9c0\uae08\ub3c4 \uc6b8\ub2e4\ub9cc \uac19\uc740 \uae08\uace0\ub97c \uc9c0\ud0a4\uba70, Forever\ub294 \uc800\uc2b5\uc9c0\uc758 \ubc1c\uad74\uc9c0\ubd80\ud130 \uc6b4\uace0\ub85c \ubd84\ud654\uad6c\uc758 Shaper's Terrace\uae4c\uc9c0 \ud2f0\ud0c4 \uc720\uc801\uc744 \ub354\ud55c\ub2e4."]},"term:titans":{title:"\ud2f0\ud0c4",summary:"\uc6b0\uc8fc\uc5d0 \uc9c8\uc11c\ub97c \uac00\uc838\uc624\ub824 \ud588\uace0 \uc544\uc81c\ub85c\uc2a4\ub97c \ube5a\uc5b4\ub0b8 \uac70\ub300\ud55c \uc138\uacc4\ud63c\ub4e4.",body:["\ud2f0\ud0c4\uc740 \uc2e0\uacfc \uac19\uc740 \uc874\uc7ac\ub85c \uae68\uc5b4\ub09c \uc138\uacc4\ud63c\uc774\ub2e4. \uc544\ub9cc\ud234\uc774 \uc774\ub044\ub294 \ud310\ud14c\uc628\uc740 \uc7a0\ub4e0 \uc138\uacc4\ud63c\uc744 \ucc3e\uc544 \uc6b0\uc8fc\ub97c \ub204\ubcd0\uace0, \uc544\uc81c\ub85c\uc2a4 \uc548\uc5d0\uc11c \ud070 \uac00\ub2a5\uc131\uc744 \uc9c0\ub2cc \ud558\ub098\ub97c \ubc1c\uacac\ud588\ub2e4. \uadf8\ub4e4\uc740 \uace0\ub300 \uc2e0 \uc774\uc0e4\ub77c\uc988\ub97c \uc138\uacc4\uc5d0\uc11c \ub72f\uc5b4\ub0b4\uace0 \ub098\uba38\uc9c0\ub97c \uac00\ub454 \ub4a4, \ub545\uc744 \ube5a\ub294 \uc77c\uc744 \uc790\uc2e0\ub4e4\uc758 \uc885\uc5d0\uac8c \ub9e1\uacbc\ub2e4. \uadf8\ub4e4\uc758 \uac00\uc7a5 \uac15\ub825\ud55c \uc218\ud638\uc790 \uc0b4\uac8c\ub77c\uc2a4\ub294 \ud6d7\ub0a0 \ud0c0\ub77d\ud558\uc5ec \ubd88\ud0c0\ub294 \uad70\ub2e8\uc744 \uc138\uc6e0\ub2e4."]},"term:twilights-hammer":{title:"\ud669\ud63c\uc758 \ub9dd\uce58",summary:"\ud55c\ub54c \uc624\ud06c \ubd80\uc871\uc774\uc5c8\uc73c\ub098 \uc9c0\uae08\uc740 \uace0\ub300 \uc2e0\uc744 \uc12c\uae30\ub294 \uc885\ub9d0 \uad50\ub2e8.",body:["\uba38\ub9ac \ub458 \ub2ec\ub9b0 \uc624\uc6b0\uac70 \ub9c8\ubc95\uc0ac \ucd08\uac08\uc774 \uc774\ub048 \ud669\ud63c\uc758 \ub9dd\uce58\ub294 \uc81c2\ucc28 \ub300\uc804\uc7c1 \ub54c \uc624\ud06c \ubd80\uc871\uc73c\ub85c \uc2f8\uc6e0\uace0, \uadf8 \ub4a4 \uc138\uc0c1\uc758 \uc885\ub9d0\uc744 \uac08\ub9dd\ud558\ub294 \uad50\ub2e8\uc73c\ub85c \ubcc0\ud588\ub2e4. \ubaa8\ub4e0 \uc885\uc871\uc5d0\uc11c \ubaa8\uc5ec\ub4e0 \uc2e0\ub3c4\ub4e4\uc740 \uac80\uc740\uc2ec\uc5f0\uc758 \ub098\ub77d\uacfc \uc2e4\ub9ac\ub354\uc2a4 \uac19\uc740 \uacf3\uc5d0 \ubaa8\uc778\ub2e4. Forever\uc5d0\uc11c \uad50\ub2e8\uc740 Riverglades\uc758 Sunnyglade \ud3d0\ud5c8\ub3c4 \ucc28\uc9c0\ud558\uace0 \uc788\ub2e4."]},"term:well-of-eternity":{title:"\uc601\uc6d0\uc758 \uc0d8",summary:"\uace0\ub300 \uce7c\ub9bc\ub3c4\uc5b4\uc758 \uc2ec\uc7a5\ubd80\uc5d0 \uc788\ub358 \uc21c\uc218\ud55c \ube44\uc804\uc758 \ud638\uc218\ub85c, \uadf8 \ubd95\uad34\uac00 \uc138\uacc4\ub97c \uac08\ub77c\ub193\uc558\ub2e4.",body:["\uc0d8\uc740 \ud2f0\ud0c4\uc774 \uc774\uc0e4\ub77c\uc988\ub97c \uc138\uacc4\uc5d0\uc11c \ub72f\uc5b4\ub0b8 \uc790\ub9ac\uc5d0 \uc0dd\uaca8\ub0ac\uace0, \uad00\ub9ac\uc790\ub4e4\uc774 \ud53c \ud758\ub9ac\ub294 \uc0c1\ucc98\ub97c \uac00\ub77c\uc549\ud600 \uc21c\uc218\ud55c \ud798\uc758 \ud638\uc218\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. \ub098\uc774\ud2b8 \uc5d8\ud504\ub294 \uadf8 \uae30\uc2ad\uc5d0 \uc81c\uad6d\uc744 \uc138\uc6e0\uace0, \uba85\uac00\uc758 \ubb34\ubaa8\ud55c \uc8fc\ubb38\uc740 \uadf8 \uc0d8\uc744 \ud1b5\ud574 \uad70\ub2e8\uc744 \ubd88\ub7ec\ub4e4\uc600\ub2e4. \uace0\ub300\uc758 \uc804\uc7c1 \ub54c \uc0d8\uc774 \ubb34\ub108\uc9c0\uba74\uc11c \uc138\uacc4\uc758 \ubd84\ub9ac\uac00 \uc77c\uc5b4\ub0ac\uace0, \uc0d8\uc774 \uc788\ub358 \uc790\ub9ac\uc5d0\ub294 \uc9c0\uae08 \ud070 \uc18c\uc6a9\ub3cc\uc774\uac00 \ubab0\uc544\uce5c\ub2e4."]}}},1799,[]);